// Initialize Sentry
initSentry(app);

// Sentry Request Handler - must be the first middleware on the app
app.use(sentryRequestHandler());

// Security & Middleware
app.use(helmet());
app.use(cors({ origin: config.corsOrigins, credentials: true }));
app.use(compression());
app.use(cookieParser());
app.use(express.json({ limit: '10mb' }));
