// Unified Customization System - for ALL modules (restaurant, chalets, pool, snack bar, future modules)
apiRouter.use('/customizations', customizationRoutes);

// Integration Routes - DISABLED: Uses PrismaClient
// apiRouter.use('/integrations/quickbooks', quickbooksRoutes);

// POS Hardware Routes
apiRouter.use('/pos', posHardwareRoutes);

// Platform-aware payment routes (Apple Pay, Google Pay, mobile SDK)
apiRouter.use('/payments/platform', paymentPlatformRoutes);

// GDPR Routes - FIXED
apiRouter.use('/gdpr', gdprRoutes);

// Channel Management Routes - FIXED
apiRouter.use('/channels', channelRoutes);

// Rate Parity Routes - FIXED
apiRouter.use('/rate-parity', parityRoutes);

// Multi-Property Routes - FIXED
apiRouter.use('/multi-property', multiPropertyRoutes);

// Phase 3: Operations Routes - FIXED: Converted to Supabase
apiRouter.use('/reporting', reportingRoutes);
apiRouter.use('/revenue', revenueRoutes);
apiRouter.use('/groups', groupsRoutes);
apiRouter.use('/marketing', marketingRoutes);

// Phase 4: Guest Experience Routes - FIXED: Converted to Supabase
apiRouter.use('/mobile-checkin', mobileCheckinRoutes);
apiRouter.use('/kiosk', kioskRoutes);
apiRouter.use('/messaging', messagingRoutes);
apiRouter.use('/i18n', i18nRoutes);

// Channel Webhooks - FIXED
app.use('/webhooks/channels', channelWebhookRoutes);

app.use('/api/v1', apiRouter);

// Documentation routes (Public)
app.use('/api/docs', docsRoutes);

// Basic 404
app.use((req, res) => {
  res.status(404).json({ success: false, error: 'Route not found' });
});

// Sentry Error Handler - must be before any other error middleware
app.use(sentryErrorHandler());

// Structured Error Handler
app.use((err: Error & { statusCode?: number; code?: string; isOperational?: boolean; errors?: unknown[]; details?: Record<string, unknown> }, req: express.Request, res: express.Response, _next: express.NextFunction) => {
  // Log non-operational (unexpected) errors with full stack trace
  if (!err.isOperational) {
    logger.error('Unexpected error:', {
      error: err.message,
      stack: err.stack,
      path: req.path,
      method: req.method,
      requestId: req.requestId,
    });
  } else {
    logger.warn('Operational error:', {
      code: err.code,
      message: err.message,
      path: req.path,
      method: req.method,
      requestId: req.requestId,
    });
  }

  const status = err.statusCode || 500;
  const isProd = config.env === 'production';

  const response: Record<string, unknown> = {
    success: false,
    error: status === 500 && isProd ? 'Internal Server Error' : err.message,
    code: err.code || 'INTERNAL_ERROR',
  };

  // Include validation errors if present
  if (err.errors) {
    response.errors = err.errors;
  }

  // Include details in non-production
  if (!isProd && err.details) {
    response.details = err.details;
  }

  res.status(status).json(response);
});

export default app;

import { getSupabase } from './database/connection.js';
import { logger } from './utils/logger.js';

async function fixWaitlistSchema() {
    const supabase = getSupabase();
    logger.info('Fixing waitlist_entries schema...');

    // Use rpc to execute raw SQL if available, otherwise try direct operations
    // Supabase JS client doesn't support raw SQL directly, so we'll use a workaround:
    // Create the columns via insert/update operations or rely on the table already existing

    // Actually, the best approach is to check if we can query with these columns
    // The standalone_repair.sql was executed, so table exists.
    // The controller expects: customer_name, phone, party_size, type, quoted_wait_time, status
    // Let's verify what columns exist by doing a select

    try {
        const { data, error } = await supabase
            .from('waitlist_entries')
            .select('id, customer_name, phone, party_size, type, status')
            .limit(1);

        if (error) {
            // Column doesn't exist error means we need to add them
            // But Supabase JS can't run DDL. We need to use the Supabase Management API or Dashboard.
            // For now, let's just log what's missing
            logger.error('Waitlist query error:', error.message);

            // Check if error is about missing columns
            if (error.message.includes('type') || error.message.includes('phone')) {
                logger.info('Missing columns detected. Please run the following SQL in Supabase Dashboard:');
                logger.info(`
ALTER TABLE waitlist_entries ADD COLUMN IF NOT EXISTS type TEXT DEFAULT 'restaurant';
ALTER TABLE waitlist_entries ADD COLUMN IF NOT EXISTS phone TEXT;
ALTER TABLE waitlist_entries ADD COLUMN IF NOT EXISTS quoted_wait_time INTEGER;
ALTER TABLE waitlist_entries ADD COLUMN IF NOT EXISTS notified_at TIMESTAMPTZ;
        `);
            }
        } else {
            logger.info('Waitlist schema looks correct!');
            logger.info('Sample data:', data);
        }
    } catch (e: any) {
        logger.error('Error:', e.message);
    }

    process.exit(0);
}

fixWaitlistSchema();

import { getSupabase } from './database/connection.js';
import { logger } from './utils/logger.js';

async function clearRateLimit() {
    const supabase = getSupabase();
    logger.info('Clearing rate limit for admin user...');

    try {
        // Clear login attempts for admin user
        const { error } = await supabase
            .from('login_attempts')
            .delete()
            .eq('email', 'admin@v2resort.com');

        if (error) {
            logger.warn('Could not clear login_attempts:', error.message);
            // Table might not exist or have different structure
        } else {
            logger.info('✅ Rate limit cleared!');
        }
    } catch (e: any) {
        logger.warn('Error:', e.message);
    }

    // Also try rate_limits table if it exists
    try {
        const { error } = await supabase
            .from('rate_limits')
            .delete()
            .ilike('key', '%admin@v2resort.com%');

        if (!error) {
            logger.info('✅ rate_limits cleared!');
        }
    } catch (e) {
        // ignore
    }

    process.exit(0);
}

clearRateLimit();

import dotenv from 'dotenv';
import crypto from 'crypto';
dotenv.config();

const isProduction = process.env.NODE_ENV === 'production';
const isDevelopment = process.env.NODE_ENV === 'development' || !process.env.NODE_ENV;
const isTest = process.env.NODE_ENV === 'test';

/**
 * Validate that required environment variables are set.
 * Called at application startup, NOT at import time.
 * This allows tests to import modules without env validation.
 */
export function validateEnvironment(): void {
  const requiredEnvVars = isProduction
    ? ['JWT_SECRET', 'JWT_REFRESH_SECRET', 'SUPABASE_URL', 'SUPABASE_SERVICE_KEY', 'DATABASE_URL']
    : ['SUPABASE_URL', 'SUPABASE_SERVICE_KEY'];

  const missing = requiredEnvVars.filter(v => !process.env[v]);
  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}. Check your .env file.`);
  }

  if (isProduction && process.env.JWT_SECRET && process.env.JWT_SECRET.length < 32) {
    throw new Error('JWT_SECRET must be at least 32 characters in production');
  }
}

// Only validate at import time in non-test environments
// Tests can call validateEnvironment() explicitly if needed
if (!isTest) {
  const requiredEnvVars = isProduction
    ? ['JWT_SECRET', 'JWT_REFRESH_SECRET', 'SUPABASE_URL', 'SUPABASE_SERVICE_KEY', 'DATABASE_URL']
    : ['SUPABASE_URL', 'SUPABASE_SERVICE_KEY'];

  const missing = requiredEnvVars.filter(v => !process.env[v]);
  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}. Check your .env file.`);
  }

  if (isProduction && process.env.JWT_SECRET && process.env.JWT_SECRET.length < 32) {
    throw new Error('JWT_SECRET must be at least 32 characters in production');
  }
}

// Generate secure development-only secrets (never used in production)
// These are randomly generated per-process so they're different each restart
const generateDevSecret = (prefix: string) => {
  if (isProduction) return ''; // Force failure if not set
  console.warn(`⚠️  WARNING: Using auto-generated ${prefix} - set in .env for persistence`);
  return `dev-only-${prefix}-${crypto.randomBytes(32).toString('hex')}`;
};

