export type Config = typeof config;

/**
 * V2 Resort - Secrets Management
 * Secure secrets loading and rotation
 */

import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';

export interface SecretConfig {
  name: string;
  required: boolean;
  default?: string;
  validator?: (value: string) => boolean;
  description?: string;
}

// Define all secrets used by the application
const SECRET_DEFINITIONS: SecretConfig[] = [
  // Database
  { name: 'DATABASE_URL', required: true, description: 'PostgreSQL connection string' },
  { name: 'SUPABASE_URL', required: true, description: 'Supabase project URL' },
  { name: 'SUPABASE_ANON_KEY', required: true, description: 'Supabase anonymous key' },
  { name: 'SUPABASE_SERVICE_ROLE_KEY', required: true, description: 'Supabase service role key' },
  
  // Authentication
  { name: 'JWT_SECRET', required: true, validator: (v) => v.length >= 32, description: 'JWT signing secret (min 32 chars)' },
  { name: 'JWT_REFRESH_SECRET', required: true, validator: (v) => v.length >= 32, description: 'JWT refresh token secret' },
  { name: 'SESSION_SECRET', required: true, validator: (v) => v.length >= 32, description: 'Session cookie secret' },
  
  // Stripe
  { name: 'STRIPE_SECRET_KEY', required: true, validator: (v) => v.startsWith('sk_'), description: 'Stripe secret API key' },
  { name: 'STRIPE_WEBHOOK_SECRET', required: true, validator: (v) => v.startsWith('whsec_'), description: 'Stripe webhook signing secret' },
  
  // Email
  { name: 'SENDGRID_API_KEY', required: false, validator: (v) => v.startsWith('SG.'), description: 'SendGrid API key' },
  
  // SMS
  { name: 'TWILIO_ACCOUNT_SID', required: false, validator: (v) => v.startsWith('AC'), description: 'Twilio account SID' },
  { name: 'TWILIO_AUTH_TOKEN', required: false, description: 'Twilio auth token' },
  
  // Redis
  { name: 'REDIS_URL', required: false, default: 'redis://localhost:6379', description: 'Redis connection URL' },
  
  // Encryption
  { name: 'ENCRYPTION_KEY', required: true, validator: (v) => v.length === 64, description: 'AES-256 encryption key (64 hex chars)' },
  
  // External APIs
  { name: 'WEATHER_API_KEY', required: false, description: 'Weather API key' },
  { name: 'GOOGLE_MAPS_API_KEY', required: false, description: 'Google Maps API key' },
  
  // Sentry
  { name: 'SENTRY_DSN', required: false, description: 'Sentry error tracking DSN' },
  
  // Unsubscribe
  { name: 'UNSUBSCRIBE_SECRET', required: false, description: 'Secret for email unsubscribe tokens' },
];

class SecretsManager {
  private secrets: Map<string, string> = new Map();
  private rotationCallbacks: Map<string, Array<(newValue: string) => void>> = new Map();
  private lastRotation: Map<string, Date> = new Map();

  constructor() {
    this.loadSecrets();
  }

  /**
   * Load secrets from environment and optionally from secrets file
   */
  private loadSecrets(): void {
    // First, load from environment variables
    for (const def of SECRET_DEFINITIONS) {
      const value = process.env[def.name];
      
      if (value) {
        this.secrets.set(def.name, value);
      } else if (def.default) {
        this.secrets.set(def.name, def.default);
      }
    }

    // Check for secrets file (for Docker secrets or mounted files)
    const secretsPath = process.env.SECRETS_FILE_PATH || '/run/secrets';
    if (fs.existsSync(secretsPath)) {
      this.loadFromSecretsDirectory(secretsPath);
    }

    // Validate all secrets
    this.validateSecrets();
  }

  /**
   * Load secrets from a directory (Docker secrets pattern)
   */
  private loadFromSecretsDirectory(dirPath: string): void {
    try {
      const files = fs.readdirSync(dirPath);
      
      for (const file of files) {
        const secretName = file.toUpperCase().replace(/-/g, '_');
        const filePath = path.join(dirPath, file);
        
        try {
          const value = fs.readFileSync(filePath, 'utf8').trim();
          this.secrets.set(secretName, value);
        } catch (err) {
          console.warn(`[Secrets] Could not read secret file: ${file}`);
        }
      }
    } catch (err) {
      // Directory doesn't exist or isn't readable - that's OK
    }
  }

  /**
   * Validate all required secrets
   */
  private validateSecrets(): void {
    const missing: string[] = [];
    const invalid: string[] = [];

    for (const def of SECRET_DEFINITIONS) {
      const value = this.secrets.get(def.name);

      if (def.required && !value) {
        missing.push(def.name);
        continue;
      }

      if (value && def.validator && !def.validator(value)) {
        invalid.push(`${def.name} (${def.description})`);
      }
    }

    if (missing.length > 0) {
      console.error('[Secrets] Missing required secrets:', missing.join(', '));
      if (process.env.NODE_ENV === 'production') {
        throw new Error(`Missing required secrets: ${missing.join(', ')}`);
      }
    }

    if (invalid.length > 0) {
      console.warn('[Secrets] Invalid secret values:', invalid.join(', '));
    }

    console.log(`[Secrets] Loaded ${this.secrets.size} secrets`);
  }

  /**
   * Get a secret value
   */
  get(name: string): string | undefined {
    return this.secrets.get(name);
  }

  /**
   * Get a secret value (throws if not found)
   */
  getRequired(name: string): string {
    const value = this.secrets.get(name);
    if (!value) {
      throw new Error(`Required secret not found: ${name}`);
    }
    return value;
  }

  /**
   * Check if a secret exists
   */
  has(name: string): boolean {
    return this.secrets.has(name);
  }

  /**
   * Rotate a secret (for key rotation)
   */
  async rotate(name: string, newValue: string): Promise<void> {
    const oldValue = this.secrets.get(name);
    
    // Validate the new value
    const def = SECRET_DEFINITIONS.find((d) => d.name === name);
    if (def?.validator && !def.validator(newValue)) {
      throw new Error(`Invalid value for secret: ${name}`);
    }

    // Update the secret
    this.secrets.set(name, newValue);
    this.lastRotation.set(name, new Date());

    // Notify all registered callbacks
    const callbacks = this.rotationCallbacks.get(name) || [];
    for (const callback of callbacks) {
      try {
        callback(newValue);
      } catch (err) {
        console.error(`[Secrets] Rotation callback error for ${name}:`, err);
      }
    }

    // Log the rotation (without values)
    console.log(`[Secrets] Rotated secret: ${name}`);
  }

  /**
   * Register callback for secret rotation
   */
  onRotation(name: string, callback: (newValue: string) => void): void {
    if (!this.rotationCallbacks.has(name)) {
      this.rotationCallbacks.set(name, []);
    }
    this.rotationCallbacks.get(name)!.push(callback);
  }

  /**
   * Get rotation history
   */
  getRotationHistory(): Map<string, Date> {
    return new Map(this.lastRotation);
  }

  /**
   * Generate a secure random secret
   */
  static generateSecret(length: number = 32, encoding: BufferEncoding = 'hex'): string {
    return crypto.randomBytes(length).toString(encoding);
  }

  /**
   * Generate an encryption key
   */
  static generateEncryptionKey(): string {
    return crypto.randomBytes(32).toString('hex'); // 256 bits
  }

  /**
   * Encrypt a value using the app's encryption key
   */
  encrypt(plaintext: string): string {
    const key = this.getRequired('ENCRYPTION_KEY');
    const keyBuffer = Buffer.from(key, 'hex');
    const iv = crypto.randomBytes(16);
    
    const cipher = crypto.createCipheriv('aes-256-gcm', keyBuffer, iv);
    const encrypted = Buffer.concat([
      cipher.update(plaintext, 'utf8'),
      cipher.final(),
    ]);
    const authTag = cipher.getAuthTag();

    // Return IV + AuthTag + Encrypted as base64
    const combined = Buffer.concat([iv, authTag, encrypted]);
    return combined.toString('base64');
  }

  /**
   * Decrypt a value using the app's encryption key
   */
  decrypt(ciphertext: string): string {
    const key = this.getRequired('ENCRYPTION_KEY');
    const keyBuffer = Buffer.from(key, 'hex');
    
    const combined = Buffer.from(ciphertext, 'base64');
    const iv = combined.subarray(0, 16);
    const authTag = combined.subarray(16, 32);
    const encrypted = combined.subarray(32);

    const decipher = crypto.createDecipheriv('aes-256-gcm', keyBuffer, iv);
    decipher.setAuthTag(authTag);

    const decrypted = Buffer.concat([
      decipher.update(encrypted),
      decipher.final(),
    ]);

    return decrypted.toString('utf8');
  }

  /**
   * Hash a value (one-way)
   */
  hash(value: string, salt?: string): string {
    const actualSalt = salt || crypto.randomBytes(16).toString('hex');
    const hash = crypto.pbkdf2Sync(value, actualSalt, 100000, 64, 'sha512');
    return `${actualSalt}:${hash.toString('hex')}`;
  }

  /**
   * Verify a hashed value
   */
  verifyHash(value: string, storedHash: string): boolean {
    const [salt, originalHash] = storedHash.split(':');
    const hash = crypto.pbkdf2Sync(value, salt, 100000, 64, 'sha512');
    return crypto.timingSafeEqual(
      Buffer.from(hash.toString('hex')),
      Buffer.from(originalHash)
    );
  }

  /**
   * Audit secrets configuration
   */
  audit(): {
    total: number;
    configured: number;
    missing: string[];
    optional_missing: string[];
    warnings: string[];
  } {
    const missing: string[] = [];
    const optionalMissing: string[] = [];
    const warnings: string[] = [];

    for (const def of SECRET_DEFINITIONS) {
      const value = this.secrets.get(def.name);

      if (!value) {
        if (def.required) {
          missing.push(def.name);
        } else {
          optionalMissing.push(def.name);
        }
      } else if (def.validator && !def.validator(value)) {
        warnings.push(`${def.name}: Invalid format`);
      }
    }

    // Check for weak secrets in development
    if (process.env.NODE_ENV !== 'production') {
      const jwtSecret = this.secrets.get('JWT_SECRET');
      if (jwtSecret && jwtSecret.length < 64) {
        warnings.push('JWT_SECRET: Consider using a longer secret in production');
      }
    }

    return {
      total: SECRET_DEFINITIONS.length,
      configured: this.secrets.size,
      missing,
      optional_missing: optionalMissing,
      warnings,
    };
  }

  /**
   * Get list of all secret names (not values!)
   */
  listSecretNames(): string[] {
    return Array.from(this.secrets.keys());
  }

  /**
   * Mask a secret value for logging
   */
  static mask(value: string | undefined): string {
    if (!value) return '[not set]';
    if (value.length <= 8) return '****';
    return `${value.substring(0, 4)}...${value.substring(value.length - 4)}`;
  }
}

// Singleton instance
export const secretsManager = new SecretsManager();

// Convenience exports
export const getSecret = (name: string) => secretsManager.get(name);
export const getRequiredSecret = (name: string) => secretsManager.getRequired(name);
export const encryptValue = (value: string) => secretsManager.encrypt(value);
export const decryptValue = (value: string) => secretsManager.decrypt(value);

/**
 * V2 Resort - Horizontal Scaling Session Store Configuration
 * Enables stateless backend instances with Redis-backed sessions
 */

import Redis from 'ioredis';
import session from 'express-session';
import { RedisStore } from 'connect-redis';

// Environment configuration
const REDIS_URL = process.env.REDIS_URL || 'redis://localhost:6379';
const REDIS_CLUSTER_NODES = process.env.REDIS_CLUSTER_NODES?.split(',') || [];
const REDIS_ENABLED = process.env.REDIS_ENABLED === 'true';
const SESSION_SECRET = process.env.SESSION_SECRET;
const NODE_ENV = process.env.NODE_ENV || 'development';

if (!SESSION_SECRET && NODE_ENV === 'production') {
  console.warn(
    'WARN: SESSION_SECRET is not set in production. Using a generated secret. ' +
    'Sessions will be invalidated on restart.'
  );
}

// Generate a random secret if one isn't provided (for fallback)
const FALLBACK_SECRET = require('crypto').randomBytes(32).toString('hex');
const FINAL_SESSION_SECRET = SESSION_SECRET || FALLBACK_SECRET;

// Redis connection options
const redisOptions = {
  maxRetriesPerRequest: 3,
  enableReadyCheck: true,
  retryDelayOnFailover: 100,
  retryDelayOnClusterDown: 100,
  retryDelayOnTryAgain: 100,
  scaleReads: 'slave' as const,
  lazyConnect: true,
  showFriendlyErrorStack: NODE_ENV !== 'production',
};

// Create Redis client (single instance or cluster)
let redisInstance: any = null;

export const createRedisClient = () => {
  if (REDIS_CLUSTER_NODES.length > 0) {
    // Cluster mode for production
    const nodes = REDIS_CLUSTER_NODES.map((node) => {
      const [host, port] = node.split(':');
      return { host, port: parseInt(port, 10) };
    });

    return new Redis.Cluster(nodes, {
      redisOptions: {
        ...redisOptions,
      } as any,
      clusterRetryStrategy: (times) => {
        if (times > 10) return null;
        return Math.min(times * 100, 3000);
      },
    });
  }

  return new Redis(REDIS_URL, redisOptions);
};

export const getRedis = () => {
  if (!REDIS_ENABLED) return null;
  if (!redisInstance) {
    redisInstance = createRedisClient();
  }
  return redisInstance;
};

// Session store for horizontal scaling
export const redisClient = REDIS_ENABLED ? createRedisClient() : null;

// Setup event handlers only if redis is enabled
if (REDIS_ENABLED && redisClient) {
  redisClient.on('connect', () => { console.log('[Redis] Connected to session store'); });
  redisClient.on('error', (err: any) => { console.error('[Redis] Session store error:', err.message); });
  redisClient.on('ready', () => { console.log('[Redis] Session store ready'); });
  redisClient.on('reconnecting', () => { console.log('[Redis] Reconnecting to session store...'); });
}

// Create Redis session store
export const createSessionStore = () => {
  if (REDIS_ENABLED && redisClient) {
    return new RedisStore({
      client: redisClient,
      prefix: 'v2resort:session:',
      ttl: 86400, // 24 hours default
    });
  }
  return undefined; // Use default MemoryStore
};

// Session middleware configuration
export const sessionConfig = {
  store: createSessionStore(),
  secret: FINAL_SESSION_SECRET,
  name: 'v2resort.sid',
  resave: false,
  saveUninitialized: false,
  rolling: true, // Reset expiration on activity
  proxy: true, // Trust first proxy
  cookie: {
    secure: NODE_ENV === 'production',
    httpOnly: true,
    sameSite: 'lax' as const,
    maxAge: 24 * 60 * 60 * 1000, // 24 hours
    domain: NODE_ENV === 'production' ? '.v2resort.com' : undefined,
  },
};

// Create configured session middleware
export const sessionMiddleware = session(sessionConfig);

// Session utilities for horizontal scaling
export const sessionUtils = {
  /**
   * Get session by ID (for debugging/admin)
   */
  async getSession(sessionId: string): Promise<any | null> {
    if (!REDIS_ENABLED || !redisClient) return null;
    const data = await redisClient.get(`v2resort:session:${sessionId}`);
    return data ? JSON.parse(data) : null;
  },

  /**
   * Destroy session by ID (force logout)
   */
  async destroySession(sessionId: string): Promise<boolean> {
    if (!REDIS_ENABLED || !redisClient) return false;
    const result = await redisClient.del(`v2resort:session:${sessionId}`);
    return result > 0;
  },

  /**
   * Destroy all sessions for a user (logout everywhere)
   */
  async destroyUserSessions(userId: string): Promise<number> {
    if (!REDIS_ENABLED || !redisClient) return 0;
    const pattern = 'v2resort:session:*';
    let cursor = '0';
    let count = 0;

    do {
      const [newCursor, keys] = await redisClient.scan(cursor, 'MATCH', pattern, 'COUNT', 100);
      cursor = newCursor;

      for (const key of keys) {
        const data = await redisClient.get(key);
        if (data) {
          const session = JSON.parse(data);
          if (session.userId === userId) {
            await redisClient.del(key);
            count++;
          }
        }
      }
    } while (cursor !== '0');

    return count;
  },

  /**
   * Get active session count for a user
   */
  async getUserSessionCount(userId: string): Promise<number> {
    if (!REDIS_ENABLED || !redisClient) return 0;
    const pattern = 'v2resort:session:*';
    let cursor = '0';
    let count = 0;

    do {
      const [newCursor, keys] = await redisClient.scan(cursor, 'MATCH', pattern, 'COUNT', 100);
      cursor = newCursor;

      for (const key of keys) {
        const data = await redisClient.get(key);
        if (data) {
          const session = JSON.parse(data);
          if (session.userId === userId) {
            count++;
          }
        }
      }
    } while (cursor !== '0');

    return count;
  },

  /**
   * Extend session TTL
   */
  async extendSession(sessionId: string, ttlSeconds: number): Promise<boolean> {
    if (!REDIS_ENABLED || !redisClient) return false;
    const result = await redisClient.expire(`v2resort:session:${sessionId}`, ttlSeconds);
    return result === 1;
  },

  /**
   * Get total active sessions (for monitoring)
   */
  async getTotalSessionCount(): Promise<number> {
    if (!REDIS_ENABLED || !redisClient) return 0;
    const pattern = 'v2resort:session:*';
    let cursor = '0';
    let count = 0;

    do {
      const [newCursor, keys] = await redisClient.scan(cursor, 'MATCH', pattern, 'COUNT', 100);
      cursor = newCursor;
      count += keys.length;
    } while (cursor !== '0');

    return count;
  },
};

// Health check for session store
export const checkSessionStoreHealth = async (): Promise<{
  healthy: boolean;
  latencyMs: number;
  error?: string;
}> => {
  const start = Date.now();
  if (!REDIS_ENABLED || !redisClient) {
    return { healthy: true, latencyMs: 0 };
  }
  try {
    await redisClient.ping();
    return {
      healthy: true,
      latencyMs: Date.now() - start,
    };
  } catch (error) {
    return {
      healthy: false,
      latencyMs: Date.now() - start,
      error: error instanceof Error ? error.message : 'Unknown error',
    };
  }
};

// Graceful shutdown
export const closeSessionStore = async (): Promise<void> => {
  if (!REDIS_ENABLED || !redisClient) return;
  console.log('[Redis] Closing session store connection...');
  await redisClient.quit();
  console.log('[Redis] Session store connection closed');
};

/**
 * Comprehensive Health Check Controller
 * Provides detailed health status for monitoring and deployment verification
 */
import { Router, Request, Response } from 'express';
import { supabase } from "../lib/supabase.js";

interface HealthCheckResult {
  status: 'healthy' | 'degraded' | 'unhealthy';
  timestamp: string;
  version: string;
  uptime: number;
  checks: {
    database: ComponentHealth;
    cache?: ComponentHealth;
    stripe?: ComponentHealth;
    email?: ComponentHealth;
    storage?: ComponentHealth;
    websocket?: ComponentHealth;
  };
  metrics?: {
    memoryUsage: NodeJS.MemoryUsage;
    cpuUsage: NodeJS.CpuUsage;
    activeConnections?: number;
  };
}

interface ComponentHealth {
  status: 'healthy' | 'degraded' | 'unhealthy';
  latency?: number;
  message?: string;
  lastCheck?: string;
}

const router = Router();
const startTime = Date.now();

/**
 * Simple health check - for load balancer
 * GET /health
 */
router.get('/', async (_req: Request, res: Response) => {
  try {
    // Quick database ping
    const start = Date.now();
    const { error } = await supabase.from('system_settings').select('key').limit(1);
    const dbLatency = Date.now() - start;

    if (error && error.code !== 'PGRST116') {
      return res.status(503).json({
        status: 'unhealthy',
        message: 'Database connection failed',
      });
    }

    return res.status(200).json({
      status: 'healthy',
      timestamp: new Date().toISOString(),
      dbLatency: `${dbLatency}ms`,
    });
  } catch (error) {
    return res.status(503).json({
      status: 'unhealthy',
      message: 'Health check failed',
    });
  }
});

/**
 * Detailed health check - for monitoring
 * GET /health/detailed
 */
router.get('/detailed', async (_req: Request, res: Response) => {
  const result: HealthCheckResult = {
    status: 'healthy',
    timestamp: new Date().toISOString(),
    version: process.env.npm_package_version || '1.0.0',
    uptime: Math.floor((Date.now() - startTime) / 1000),
    checks: {
      database: await checkDatabase(),
      storage: await checkStorage(),
      stripe: await checkStripe(),
      email: await checkEmail(),
    },
    metrics: {
      memoryUsage: process.memoryUsage(),
      cpuUsage: process.cpuUsage(),
    },
  };

  // Determine overall status
  const statuses = Object.values(result.checks).map(c => c.status);
  if (statuses.includes('unhealthy')) {
    result.status = 'unhealthy';
  } else if (statuses.includes('degraded')) {
    result.status = 'degraded';
  }

  const statusCode = result.status === 'healthy' ? 200 : result.status === 'degraded' ? 200 : 503;
  return res.status(statusCode).json(result);
});

/**
 * Database health check
 * GET /health/db
 */
router.get('/db', async (_req: Request, res: Response) => {
  const check = await checkDatabase();
  const statusCode = check.status === 'healthy' ? 200 : 503;
  return res.status(statusCode).json(check);
});

/**
 * Readiness probe - for Kubernetes
 * GET /health/ready
 */
router.get('/ready', async (_req: Request, res: Response) => {
  try {
    // Check critical dependencies
    const dbCheck = await checkDatabase();
    
    if (dbCheck.status === 'unhealthy') {
      return res.status(503).json({
        ready: false,
        reason: 'Database not available',
      });
    }

    return res.status(200).json({
      ready: true,
    });
  } catch (error) {
    return res.status(503).json({
      ready: false,
      reason: 'Readiness check failed',
    });
  }
});

/**
 * Liveness probe - for Kubernetes
 * GET /health/live
 */
router.get('/live', (_req: Request, res: Response) => {
  // Basic liveness - if we can respond, we're alive
  return res.status(200).json({
    alive: true,
    timestamp: new Date().toISOString(),
  });
});

/**
 * Startup probe - for Kubernetes
 * GET /health/startup
 */
router.get('/startup', async (_req: Request, res: Response) => {
  try {
    // Verify all critical services are initialized
    const dbCheck = await checkDatabase();
    
    if (dbCheck.status === 'unhealthy') {
      return res.status(503).json({
        started: false,
        reason: 'Database initialization failed',
      });
    }

    return res.status(200).json({
      started: true,
      uptime: Math.floor((Date.now() - startTime) / 1000),
    });
  } catch (error) {
    return res.status(503).json({
      started: false,
      reason: 'Startup check failed',
    });
  }
});

/**
 * Metrics endpoint (Prometheus format)
 * GET /health/metrics
 */
router.get('/metrics', async (_req: Request, res: Response) => {
  const metrics: string[] = [];
  
  // Process metrics
  const memory = process.memoryUsage();
  metrics.push(`# TYPE process_heap_bytes gauge`);
  metrics.push(`process_heap_bytes ${memory.heapUsed}`);
  
  metrics.push(`# TYPE process_heap_total_bytes gauge`);
  metrics.push(`process_heap_total_bytes ${memory.heapTotal}`);
  
  metrics.push(`# TYPE process_rss_bytes gauge`);
  metrics.push(`process_rss_bytes ${memory.rss}`);
  
  metrics.push(`# TYPE process_uptime_seconds gauge`);
  metrics.push(`process_uptime_seconds ${process.uptime()}`);
  
  // App metrics
  metrics.push(`# TYPE app_start_time_seconds gauge`);
  metrics.push(`app_start_time_seconds ${Math.floor(startTime / 1000)}`);

  res.set('Content-Type', 'text/plain');
  return res.send(metrics.join('\n'));
});

// Helper functions

async function checkDatabase(): Promise<ComponentHealth> {
  try {
    const start = Date.now();
    const { error } = await supabase.from('system_settings').select('key').limit(1);
    const latency = Date.now() - start;

    // Allow PGRST116 (no rows returned) as that's not an error
    if (error && error.code !== 'PGRST116') {
      return {
        status: 'unhealthy',
        latency,
        message: error.message,
        lastCheck: new Date().toISOString(),
      };
    }

    // Consider degraded if latency is high
    if (latency > 1000) {
      return {
        status: 'degraded',
        latency,
        message: 'High latency detected',
        lastCheck: new Date().toISOString(),
      };
    }

    return {
      status: 'healthy',
      latency,
      lastCheck: new Date().toISOString(),
    };
  } catch (error) {
    return {
      status: 'unhealthy',
      message: error instanceof Error ? error.message : 'Unknown error',
      lastCheck: new Date().toISOString(),
    };
  }
}

async function checkStorage(): Promise<ComponentHealth> {
  try {
    const start = Date.now();
    const { error } = await supabase.storage.listBuckets();
    const latency = Date.now() - start;

    if (error) {
      return {
        status: 'degraded',
        latency,
        message: 'Storage access limited',
        lastCheck: new Date().toISOString(),
      };
    }

    return {
      status: 'healthy',
      latency,
      lastCheck: new Date().toISOString(),
    };
  } catch (error) {
    return {
      status: 'degraded',
      message: 'Storage check failed',
      lastCheck: new Date().toISOString(),
    };
  }
}

async function checkStripe(): Promise<ComponentHealth> {
  // Don't actually call Stripe API in health check to avoid rate limits
  // Just verify the SDK is configured
  try {
    const hasKey = !!process.env.STRIPE_SECRET_KEY;
    
    return {
      status: hasKey ? 'healthy' : 'degraded',
      message: hasKey ? 'Stripe configured' : 'Stripe key not configured',
      lastCheck: new Date().toISOString(),
    };
  } catch (error) {
    return {
      status: 'degraded',
      message: 'Stripe check failed',
      lastCheck: new Date().toISOString(),
    };
  }
}

async function checkEmail(): Promise<ComponentHealth> {
  // Verify email configuration exists
  try {
    const hasConfig = !!(
      process.env.SMTP_HOST || 
      process.env.SENDGRID_API_KEY ||
      process.env.AWS_SES_REGION
    );
    
    return {
      status: hasConfig ? 'healthy' : 'degraded',
      message: hasConfig ? 'Email configured' : 'Email not configured',
      lastCheck: new Date().toISOString(),
    };
  } catch (error) {
    return {
      status: 'degraded',
      message: 'Email check failed',
      lastCheck: new Date().toISOString(),
    };
  }
}

