/**
 * Engine Observability
 * 
 * Structured logging, metrics, and audit trail for all engine operations.
 * Provides the "black box" recording needed for debugging, monitoring,
 * and compliance auditing.
 * 
 * Three pillars:
 *   1. Structured Events — typed, searchable event records
 *   2. Metrics Counters — aggregatable numeric counters
 *   3. Audit Trail Writer — DB-backed immutable state transition log
 * 
 * INVARIANT: Every state transition is logged.
 * INVARIANT: Every pricing calculation is logged.
 * INVARIANT: Every financial ledger write is logged.
 * INVARIANT: Every anomaly (invariant violation, duplicate, negative capacity) is logged.
 */

import { getSupabase } from '../database/connection.js';
import { logger } from '../utils/logger.js';
import type { EngineType, PricingResult, TransitionResult } from './types.js';

// ============================================
// Event Types
// ============================================

export type EngineEventType =
  | 'state_transition'
  | 'state_transition_rejected'
  | 'pricing_calculated'
  | 'pricing_invariant_violation'
  | 'ledger_write'
  | 'ledger_invariant_violation'
  | 'idempotency_hit'
  | 'idempotency_conflict'
  | 'transaction_started'
  | 'transaction_completed'
  | 'transaction_failed'
  | 'compensation_executed'
  | 'compensation_failed'
  | 'capacity_violation'
  | 'booking_overlap_rejected'
  | 'duplicate_loyalty_prevented'
  | 'feature_flag_checked'
  | 'rpc_call'
  | 'rpc_failure';

export interface EngineEvent {
  type: EngineEventType;
  engineType: EngineType;
  entityId?: string;
  moduleId?: string;
  tenantId?: string;
  actor?: string;
  actorId?: string;
  data: Record<string, unknown>;
  timestamp: Date;
  durationMs?: number;
}

// ============================================
// Metrics
// ============================================

interface MetricEntry {
  count: number;
  lastOccurrence: Date;
  sumValue: number;
}

export class EngineMetrics {
  private counters: Map<string, MetricEntry> = new Map();

  /**
   * Increment a counter metric.
   */
  increment(name: string, value: number = 1): void {
    const existing = this.counters.get(name) || { count: 0, lastOccurrence: new Date(), sumValue: 0 };
    existing.count += 1;
    existing.sumValue += value;
    existing.lastOccurrence = new Date();
    this.counters.set(name, existing);
  }

  /**
   * Get current metric value.
   */
  get(name: string): MetricEntry | undefined {
    return this.counters.get(name);
  }

  /**
   * Get all metrics as a snapshot.
   */
  snapshot(): Record<string, MetricEntry> {
    const result: Record<string, MetricEntry> = {};
    for (const [name, entry] of this.counters) {
      result[name] = { ...entry };
    }
    return result;
  }

  /**
   * Reset all metrics (for testing).
   */
  reset(): void {
    this.counters.clear();
  }
}

// ============================================
// Engine Observer
// ============================================

export class EngineObserver {
  private readonly metrics: EngineMetrics;
  private readonly eventBuffer: EngineEvent[] = [];
  private readonly maxBufferSize: number;
  private flushTimer: ReturnType<typeof setInterval> | null = null;

  constructor(metrics?: EngineMetrics, maxBufferSize: number = 100) {
    this.metrics = metrics || new EngineMetrics();
    this.maxBufferSize = maxBufferSize;
  }

  // ============================================
  // State Transition Events
  // ============================================

  /**
   * Log a successful state transition.
   */
  onStateTransition(
    engineType: EngineType,
    entityId: string,
    previousState: string,
    newState: string,
    action: string,
    actor: string,
    context?: Record<string, unknown>,
  ): void {
    this.metrics.increment(`state_transition.${engineType}`);
    this.metrics.increment(`state_transition.${engineType}.${action}`);

    this.emit({
      type: 'state_transition',
      engineType,
      entityId,
      actor,
      data: {
        previousState,
        newState,
        action,
        ...context,
      },
      timestamp: new Date(),
    });

    logger.info('[ENGINE EVENT] State transition', {
      engineType,
      entityId,
      previousState,
      newState,
      action,
      actor,
    });
  }

  /**
   * Log a rejected state transition.
   */
  onStateTransitionRejected(
    engineType: EngineType,
    entityId: string,
    currentState: string,
    attemptedAction: string,
    actor: string,
    reason: string,
  ): void {
    this.metrics.increment(`state_transition_rejected.${engineType}`);

    this.emit({
      type: 'state_transition_rejected',
      engineType,
      entityId,
      actor,
      data: {
        currentState,
        attemptedAction,
        reason,
      },
      timestamp: new Date(),
    });

    logger.warn('[ENGINE EVENT] State transition rejected', {
      engineType,
      entityId,
      currentState,
      attemptedAction,
      actor,
      reason,
    });
  }

  // ============================================
  // Pricing Events
  // ============================================

  /**
   * Log a pricing calculation.
   */
  onPricingCalculated(
    engineType: EngineType,
    entityId: string,
    result: PricingResult,
    durationMs: number,
  ): void {
    this.metrics.increment(`pricing_calculated.${engineType}`);
    this.metrics.increment('pricing_calculated.total_amount', result.totalAmount);

    this.emit({
      type: 'pricing_calculated',
      engineType,
      entityId,
      data: {
        subtotal: result.subtotal,
        taxAmount: result.taxAmount,
        serviceCharge: result.serviceCharge,
        deliveryFee: result.deliveryFee,
        totalDiscount: result.totalDiscount,
        totalAmount: result.totalAmount,
        lineItemCount: result.lineItems.length,
        discountCount: result.discounts.length,
      },
      timestamp: new Date(),
      durationMs,
    });
  }

  /**
   * Log a pricing invariant violation.
   */
  onPricingInvariantViolation(
    engineType: EngineType,
    entityId: string,
    expected: number,
    actual: number,
    breakdown: Record<string, number>,
  ): void {
    this.metrics.increment('pricing_invariant_violation');

    this.emit({
      type: 'pricing_invariant_violation',
      engineType,
      entityId,
      data: { expected, actual, diff: Math.abs(expected - actual), breakdown },
      timestamp: new Date(),
    });

    logger.error('[ENGINE EVENT] PRICING INVARIANT VIOLATION', {
      engineType,
      entityId,
      expected,
      actual,
      diff: Math.abs(expected - actual),
      breakdown,
    });
  }

  // ============================================
  // Ledger Events
  // ============================================

  /**
   * Log a financial ledger write.
   */
  onLedgerWrite(
    engineType: EngineType,
    entityId: string,
    transactionType: string,
    totalAmount: number,
    idempotencyKey?: string,
  ): void {
    this.metrics.increment(`ledger_write.${engineType}`);
    this.metrics.increment(`ledger_write.${transactionType}`);
    this.metrics.increment('ledger_write.total_amount', totalAmount);

    this.emit({
      type: 'ledger_write',
      engineType,
      entityId,
      data: { transactionType, totalAmount, idempotencyKey },
      timestamp: new Date(),
    });
  }

  // ============================================
  // Idempotency Events
  // ============================================

  /**
   * Log an idempotency cache hit (duplicate request).
   */
  onIdempotencyHit(key: string, engineType: EngineType, entityId: string): void {
    this.metrics.increment('idempotency_hit');

    this.emit({
      type: 'idempotency_hit',
      engineType,
      entityId,
      data: { key },
      timestamp: new Date(),
    });

    logger.info('[ENGINE EVENT] Idempotency cache hit', { key, engineType, entityId });
  }

  /**
   * Log an idempotency conflict (concurrent processing).
   */
  onIdempotencyConflict(key: string, engineType: EngineType, entityId: string): void {
    this.metrics.increment('idempotency_conflict');

    this.emit({
      type: 'idempotency_conflict',
      engineType,
      entityId,
      data: { key },
      timestamp: new Date(),
    });

    logger.warn('[ENGINE EVENT] Idempotency conflict', { key, engineType, entityId });
  }

  // ============================================
  // Transaction Events
  // ============================================

  /**
   * Log a transaction start.
   */
  onTransactionStarted(
    txId: string,
    engineType: EngineType,
    entityId: string,
    stepCount: number,
  ): void {
    this.metrics.increment(`transaction_started.${engineType}`);

    this.emit({
      type: 'transaction_started',
      engineType,
      entityId,
      data: { txId, stepCount },
      timestamp: new Date(),
    });
  }

  /**
   * Log a transaction completion.
   */
  onTransactionCompleted(
    txId: string,
    engineType: EngineType,
    entityId: string,
    durationMs: number,
  ): void {
    this.metrics.increment(`transaction_completed.${engineType}`);

    this.emit({
      type: 'transaction_completed',
      engineType,
      entityId,
      data: { txId, durationMs },
      timestamp: new Date(),
      durationMs,
    });
  }

  /**
   * Log a transaction failure.
   */
  onTransactionFailed(
    txId: string,
    engineType: EngineType,
    entityId: string,
    failedStep: string,
    error: string,
    compensatedSteps: string[],
  ): void {
    this.metrics.increment(`transaction_failed.${engineType}`);

    this.emit({
      type: 'transaction_failed',
      engineType,
      entityId,
      data: { txId, failedStep, error, compensatedSteps },
      timestamp: new Date(),
    });

    logger.error('[ENGINE EVENT] Transaction failed', {
      txId,
      engineType,
      entityId,
      failedStep,
      error,
      compensatedSteps,
    });
  }

  // ============================================
  // Anomaly Events
  // ============================================

  /**
   * Log a capacity violation attempt.
   */
  onCapacityViolation(
    engineType: EngineType,
    entityId: string,
    currentOccupancy: number,
    maxCapacity: number,
  ): void {
    this.metrics.increment('capacity_violation');

    this.emit({
      type: 'capacity_violation',
      engineType,
      entityId,
      data: { currentOccupancy, maxCapacity },
      timestamp: new Date(),
    });

    logger.error('[ENGINE EVENT] Capacity violation', {
      engineType,
      entityId,
      currentOccupancy,
      maxCapacity,
    });
  }

  /**
   * Log a duplicate loyalty earn prevention.
   */
  onDuplicateLoyaltyPrevented(
    engineType: EngineType,
    entityId: string,
    customerId: string,
  ): void {
    this.metrics.increment('duplicate_loyalty_prevented');

    this.emit({
      type: 'duplicate_loyalty_prevented',
      engineType,
      entityId,
      data: { customerId },
      timestamp: new Date(),
    });

    logger.warn('[ENGINE EVENT] Duplicate loyalty earn prevented', {
      engineType,
      entityId,
      customerId,
    });
  }

  /**
   * Log an RPC failure.
   */
  onRpcFailure(
    rpcName: string,
    engineType: EngineType,
    error: string,
  ): void {
    this.metrics.increment(`rpc_failure.${rpcName}`);
    this.metrics.increment('rpc_failure.total');

    this.emit({
      type: 'rpc_failure',
      engineType,
      data: { rpcName, error },
      timestamp: new Date(),
    });

    logger.error('[ENGINE EVENT] RPC failure', { rpcName, engineType, error });
  }

  // ============================================
  // Metrics Access
  // ============================================

  /**
   * Get the metrics instance for querying counters.
   */
  getMetrics(): EngineMetrics {
    return this.metrics;
  }

  /**
   * Get all buffered events (for testing or batch processing).
   */
  getEventBuffer(): EngineEvent[] {
    return [...this.eventBuffer];
  }

  /**
   * Clear the event buffer.
   */
  clearEventBuffer(): void {
    this.eventBuffer.length = 0;
  }

  // ============================================
  // Audit Trail Writer
  // ============================================

  /**
   * Write a state transition to the persistent audit trail.
   * This is the DB-backed immutable record.
   */
  async writeAuditTrail(
    tenantId: string,
    moduleId: string,
    engineType: EngineType,
    entityId: string,
    previousState: string,
    newState: string,
    action: string,
    actorType: string,
    actorId?: string,
    context?: Record<string, unknown>,
    transactionId?: string,
  ): Promise<void> {
    try {
      const supabase = getSupabase();
      await supabase.from('engine_state_transitions').insert({
        tenant_id: tenantId,
        module_id: moduleId,
        engine_type: engineType,
        entity_id: entityId,
        previous_state: previousState,
        new_state: newState,
        action,
        actor_type: actorType,
        actor_id: actorId,
        context: context || {},
        transaction_id: transactionId,
      });
    } catch (err) {
      logger.error('[AUDIT TRAIL] Failed to write state transition audit', {
        entityId,
        action,
        error: err instanceof Error ? err.message : String(err),
      });
      // Audit trail failures are logged but not propagated — they shouldn't block operations
    }
  }

  // ============================================
  // Internal
  // ============================================

  private emit(event: EngineEvent): void {
    this.eventBuffer.push(event);

    // Auto-flush if buffer is full
    if (this.eventBuffer.length >= this.maxBufferSize) {
      this.flush();
    }
  }

  /**
   * Flush buffered events (for batch processing or periodic writes).
   * Default implementation just clears the buffer; override for external systems.
   */
  flush(): void {
    // In production, this would send to an external observability system
    // (DataDog, New Relic, CloudWatch, etc.)
    // For now, just clear the buffer — events are already logged individually
    this.eventBuffer.length = 0;
  }
}

// ============================================
// Singleton
// ============================================

let _observer: EngineObserver | null = null;
let _metrics: EngineMetrics | null = null;

export function getEngineObserver(): EngineObserver {
  if (!_observer) {
    _metrics = new EngineMetrics();
    _observer = new EngineObserver(_metrics);
  }
  return _observer;
}

export function getEngineMetrics(): EngineMetrics {
  if (!_metrics) {
    getEngineObserver(); // Initialize both
  }
  return _metrics!;
}

export function resetEngineObserver(): void {
  _observer = null;
  _metrics = null;
}

/**
 * Unified Pricing Pipeline
 * 
 * ONE universal pricing calculation that ALL engines route through.
 * This replaces the four independent financial calculators:
 *   - order.service.ts L131-556 (restaurant)
 *   - snack.controller.ts L93-149 (snack bar)
 *   - bookings.service.ts L167-258 (chalets)
 *   - pool.controller.ts L148-261 (pool)
 * 
 * FINANCIAL INVARIANTS:
 *   1. totalAmount = subtotal + taxAmount + serviceCharge + deliveryFee - totalDiscount
 *   2. totalAmount >= 0 (never negative)
 *   3. Tax is (subtotal - preBasketDiscount) * taxRate
 *   4. Discounts are applied in order: coupon → gift card → loyalty
 *   5. Each discount is capped at remaining balance (no negative intermediate totals)
 *   6. All monetary values are rounded to decimalPlaces at final output (not intermediate)
 * 
 * Usage:
 *   const pipeline = new PricingPipeline(taxService, orderConfigService);
 *   const result = await pipeline.calculate(lineItems, pricingConfig, pricingContext);
 */

import type {
  PricingLineItem,
  PricingConfig,
  PricingContext,
  PricingResult,
  DiscountBreakdown,
} from './types.js';
import type { TaxService } from '../services/tax.service.js';
import type { OrderConfigService } from '../services/order-config.service.js';
import { logger } from '../utils/logger.js';

// ============================================
// Discount Resolver Interface
// ============================================

/**
 * Discount resolvers are injected to handle coupon/gift card/loyalty operations.
 * This decouples the pricing pipeline from specific Supabase RPCs.
 */
export interface CouponResolver {
  /**
   * Apply a coupon and return the discount amount.
   * Must call the atomic RPC and return { discountAmount, taxSavings, couponId }.
   * Returns null if coupon is invalid/expired.
   */
  apply(
    couponCode: string,
    subtotal: number,
    customerId?: string,
    moduleId?: string,
  ): Promise<{ discountAmount: number; taxSavings: number; couponId: string } | null>;
}

export interface GiftCardResolver {
  /**
   * Redeem a gift card for up to `maxAmount`.
   * Must call the atomic RPC.
   * Returns actual amount deducted.
   */
  redeem(
    giftCardCode: string,
    maxAmount: number,
  ): Promise<{ amountDeducted: number; giftCardId: string } | null>;
}

export interface LoyaltyResolver {
  /**
   * Redeem loyalty points for up to `maxAmount`.
   * Must call the atomic RPC.
   * Returns actual amount deducted and points used.
   */
  redeem(
    customerId: string,
    pointsToRedeem: number,
    maxAmount: number,
  ): Promise<{ amountDeducted: number; pointsUsed: number } | null>;

  /**
   * Calculate and award loyalty points for a completed transaction.
   * Returns points earned.
   */
  earn(
    customerId: string,
    totalAmount: number,
    moduleId: string,
  ): Promise<number>;
}

// ============================================
// Pricing Pipeline
// ============================================

export interface PricingPipelineDeps {
  taxService: TaxService;
  orderConfigService: OrderConfigService;
  couponResolver?: CouponResolver;
  giftCardResolver?: GiftCardResolver;
  loyaltyResolver?: LoyaltyResolver;
}

export class PricingPipeline {
  private readonly deps: PricingPipelineDeps;

  constructor(deps: PricingPipelineDeps) {
    this.deps = deps;
  }

  /**
   * Calculate the complete pricing for a set of line items.
   * 
   * This is the SINGLE entry point for ALL financial calculations in the system.
   */
  async calculate(
    lineItems: PricingLineItem[],
    config: PricingConfig,
    context: PricingContext,
  ): Promise<PricingResult> {
    // ---- Step 1: Calculate subtotal ----
    const processedLineItems = lineItems.map((item, idx) => {
      const unitAdj = item.unitAdjustment ?? 0;
      const lineTotal = (item.unitPrice + unitAdj) * item.quantity;
      return {
        itemId: item.itemId || `line-${idx}`,
        name: item.name,
        unitPrice: item.unitPrice,
        unitAdjustment: unitAdj,
        quantity: item.quantity,
        lineTotal,
      };
    });

    const subtotal = processedLineItems.reduce((sum, item) => sum + item.lineTotal, 0);

    // ---- Step 2: Apply pre-tax discounts (coupons are pre-tax) ----
    const discounts: DiscountBreakdown[] = [];
    let preBasketDiscount = 0;

    if (config.supportsCoupons && context.couponCode && this.deps.couponResolver) {
      const couponResult = await this.deps.couponResolver.apply(
        context.couponCode,
        subtotal,
        context.customerId,
        context.moduleId,
      );
      if (couponResult) {
        preBasketDiscount += couponResult.discountAmount;
        discounts.push({
          type: 'coupon',
          referenceId: couponResult.couponId,
          label: `Coupon: ${context.couponCode}`,
          amount: couponResult.discountAmount,
          taxSavings: couponResult.taxSavings,
        });
      }
    }

    // ---- Step 3: Calculate tax (on subtotal minus pre-tax discounts) ----
    let taxRate = 0;
    let taxAmount = 0;
    if (config.applyTax) {
      taxRate = await this.deps.taxService.getTaxRate(context.moduleId ?? 'default');
      const taxableAmount = Math.max(0, subtotal - preBasketDiscount);
      taxAmount = taxableAmount * taxRate;
    }

    // ---- Step 4: Calculate service charge ----
    let serviceChargeRate = 0;
    let serviceCharge = 0;
    if (config.applyServiceCharge) {
      const shouldApply = this.evaluateCondition(config.serviceChargeCondition, context.conditions ?? {});
      if (shouldApply) {
        const orderConfig = await this.deps.orderConfigService.getOrderConfig();
        serviceChargeRate = orderConfig.serviceChargeRate;
        serviceCharge = subtotal * serviceChargeRate;
      }
    }

    // ---- Step 5: Calculate delivery fee ----
    let deliveryFee = 0;
    if (config.applyDeliveryFee) {
      const shouldApply = this.evaluateCondition(config.deliveryFeeCondition, context.conditions ?? {});
      if (shouldApply) {
        const orderConfig = await this.deps.orderConfigService.getOrderConfig();
        deliveryFee = orderConfig.deliveryFee;
      }
    }

    // ---- Step 6: Pre-discount total ----
    const preDiscountTotal = subtotal + taxAmount + serviceCharge + deliveryFee;

    // ---- Step 7: Post-tax discounts (gift cards & loyalty, applied to total) ----
    let remainingTotal = preDiscountTotal - preBasketDiscount;
    // Subtract any tax savings from coupon
    const couponTaxSavings = discounts
      .filter(d => d.type === 'coupon')
      .reduce((sum, d) => sum + d.taxSavings, 0);
    remainingTotal -= couponTaxSavings;

    // Gift cards
    if (config.supportsGiftCards && context.giftCardCodes?.length && this.deps.giftCardResolver) {
      for (const code of context.giftCardCodes) {
        if (remainingTotal <= 0) break;
        const result = await this.deps.giftCardResolver.redeem(code, remainingTotal);
        if (result) {
          remainingTotal -= result.amountDeducted;
          discounts.push({
            type: 'gift_card',
            referenceId: result.giftCardId,
            label: `Gift Card: ${code}`,
            amount: result.amountDeducted,
            taxSavings: 0,
          });
        }
      }
    }

    // Loyalty points
    if (
      config.supportsLoyaltyRedemption &&
      context.loyaltyPointsToRedeem &&
      context.customerId &&
      this.deps.loyaltyResolver
    ) {
      if (remainingTotal > 0) {
        const result = await this.deps.loyaltyResolver.redeem(
          context.customerId,
          context.loyaltyPointsToRedeem,
          remainingTotal,
        );
        if (result) {
          remainingTotal -= result.amountDeducted;
          discounts.push({
            type: 'loyalty',
            referenceId: context.customerId,
            label: `Loyalty Points: ${result.pointsUsed} points`,
            amount: result.amountDeducted,
            taxSavings: 0,
            metadata: { pointsUsed: result.pointsUsed },
          });
        }
      }
    }

    // ---- Step 8: Calculate totals ----
    const totalDiscount = discounts.reduce((sum, d) => sum + d.amount + d.taxSavings, 0);
    const totalAmount = Math.max(0, preDiscountTotal - totalDiscount);

    // ---- Step 9: Calculate loyalty points earned ----
    let loyaltyPointsEarned = 0;
    // Note: loyalty earning should happen ONLY ONCE (either at order creation or payment confirmation, not both)
    // The engine definition specifies when to earn — this pipeline only calculates, doesn't trigger.
    // The caller decides when to call loyaltyResolver.earn().

    // ---- Step 10: Calculate deposit (for reservations) ----
    const depositAmount = this.calculateDeposit(totalAmount, context);

    // ---- Step 11: Round and return ----
    const round = (n: number) => this.roundAmount(n, config.decimalPlaces, config.rounding);

    const result: PricingResult = {
      subtotal: round(subtotal),
      taxAmount: round(taxAmount),
      taxRate,
      serviceCharge: round(serviceCharge),
      serviceChargeRate,
      deliveryFee: round(deliveryFee),
      preDiscountTotal: round(preDiscountTotal),
      discounts: discounts.map(d => ({
        ...d,
        amount: round(d.amount),
        taxSavings: round(d.taxSavings),
      })),
      totalDiscount: round(totalDiscount),
      totalAmount: round(totalAmount),
      lineItems: processedLineItems.map(item => ({
        ...item,
        lineTotal: round(item.lineTotal),
      })),
      loyaltyPointsEarned,
      depositAmount: round(depositAmount),
    };

    // Validate invariant
    this.validateInvariant(result);

    return result;
  }

  // ============================================
  // Private Helpers
  // ============================================

  /**
   * Evaluate a condition string against runtime conditions.
   * Conditions are simple key=value checks: "orderType=dine_in", "orderType=delivery"
   */
  private evaluateCondition(
    condition: string | undefined,
    conditions: Record<string, unknown>,
  ): boolean {
    if (!condition) return true; // No condition = always apply

    // Support simple conditions: "key=value"
    const parts = condition.split('=');
    if (parts.length !== 2) {
      logger.warn(`Invalid pricing condition: '${condition}', defaulting to true`);
      return true;
    }

    const [key, expectedValue] = parts;
    const actualValue = conditions[key.trim()];
    return String(actualValue) === expectedValue.trim();
  }

  /**
   * Calculate deposit for reservation-type engines.
   */
  private calculateDeposit(
    totalAmount: number,
    context: PricingContext,
  ): number {
    // Deposit config comes from module settings / context
    const depositConfig = (context.conditions ?? {}).depositConfig as
      | { type: 'fixed'; amount: number }
      | { type: 'percentage'; rate: number }
      | undefined;

    if (!depositConfig) return 0;

    if (depositConfig.type === 'fixed') {
      return Math.min(depositConfig.amount, totalAmount);
    }

    if (depositConfig.type === 'percentage') {
      return totalAmount * depositConfig.rate;
    }

    return 0;
  }

  /**
   * Round a monetary amount according to the configured strategy.
   */
  private roundAmount(
    amount: number,
    decimalPlaces: number,
    strategy: 'round' | 'floor' | 'ceil',
  ): number {
    const factor = Math.pow(10, decimalPlaces);
    switch (strategy) {
      case 'floor':
        return Math.floor(amount * factor) / factor;
      case 'ceil':
        return Math.ceil(amount * factor) / factor;
      case 'round':
      default:
        return Math.round(amount * factor) / factor;
    }
  }

  /**
   * Validate the pricing invariant.
   * totalAmount should equal subtotal + taxAmount + serviceCharge + deliveryFee - totalDiscount
   * (within floating-point tolerance)
   */
  private validateInvariant(result: PricingResult): void {
    const expected = result.subtotal + result.taxAmount + result.serviceCharge + result.deliveryFee - result.totalDiscount;
    const clamped = Math.max(0, expected);
    const diff = Math.abs(result.totalAmount - clamped);

    if (diff > 0.02) {
      // Tolerance for floating-point + rounding
      logger.error('PRICING INVARIANT VIOLATION', {
        expected: clamped,
        actual: result.totalAmount,
        diff,
        breakdown: {
          subtotal: result.subtotal,
          taxAmount: result.taxAmount,
          serviceCharge: result.serviceCharge,
          deliveryFee: result.deliveryFee,
          totalDiscount: result.totalDiscount,
        },
      });
    }
  }
}

import app from './app.js';
import { config } from './config/index.js';
import { logger } from './utils/logger.js';
import { initializeDatabase, closeDatabase } from './database/connection.js';
import { initializeSocketServer, closeSocketServer } from './socket/index.js';
import { initSentry } from './utils/sentry.js';
import { SchedulerService } from './services/scheduler.service.js';
import http from 'http';

// Track server state for graceful shutdown
let isShuttingDown = false;

async function main() {
  try {
    // Create HTTP server first (so health check works immediately)
    const server = http.createServer(app);

    // Initialize Sentry for error tracking (must be early)
    initSentry(app);

    // Start server immediately so Render health check passes
    server.listen(config.port, '0.0.0.0', () => {
      logger.info(`Server running on ${config.port}`);
      logger.info(`🚀 Server running on port ${config.port}`);
      logger.info(`📍 Environment: ${config.env}`);
      logger.info(`🔗 API URL: ${config.apiUrl}`);
    });

    // Initialize database in background (don't block startup)
    initializeDatabase()
      .then(() => logger.info('Database connected successfully'))
      .catch((error) => logger.error('Database connection failed:', error));

    // Initialize WebSocket
    initializeSocketServer(server);
    logger.info('WebSocket server initialized');

    // Initialize Scheduler
    SchedulerService.init();

    // Graceful shutdown with timeout and proper cleanup
    const shutdown = async (signal: string) => {
      if (isShuttingDown) {
        logger.warn('Shutdown already in progress, ignoring duplicate signal');
        return;
      }
      isShuttingDown = true;
      logger.info(`Received ${signal}, shutting down gracefully...`);

      // Force exit after timeout (30 seconds)
      const forceExitTimeout = setTimeout(() => {
        logger.error('Graceful shutdown timed out, forcing exit');
        process.exit(1);
      }, 30000);

      try {
        // Stop accepting new connections
        server.close(() => {
          logger.info('HTTP server closed');
        });

        // Close WebSocket connections
        try {
          await closeSocketServer();
          logger.info('WebSocket server closed');
        } catch (err) {
          logger.warn('Error closing WebSocket server:', err);
        }

        // Close database connections
        try {
          await closeDatabase();
          logger.info('Database connections closed');
        } catch (err) {
          logger.warn('Error closing database:', err);
        }

        clearTimeout(forceExitTimeout);
        logger.info(`Graceful shutdown completed for signal: ${signal}`);
        process.exit(0);
      } catch (error) {
        logger.error('Error during shutdown:', error);
        clearTimeout(forceExitTimeout);
        process.exit(1);
      }
    };

    process.on('SIGTERM', () => shutdown('SIGTERM'));
    process.on('SIGINT', () => shutdown('SIGINT'));

    // Handle uncaught exceptions and unhandled rejections
    process.on('uncaughtException', (error) => {
      logger.error('Uncaught exception:', error);

      // Don't shutdown for "headers already sent" errors - these are recoverable
      if (error && (error as any).message?.includes('Cannot set headers after they are sent')) {
        logger.warn('Ignoring "headers already sent" error - not triggering shutdown');
        return;
      }

      shutdown('uncaughtException');
    });

    process.on('unhandledRejection', (reason) => {
      logger.error('Unhandled rejection:', reason);
      // Don't shutdown on unhandled rejection, just log it
    });

  } catch (error) {
    logger.error('Failed to start server:', error);
    process.exit(1);
  }
}

main();

/**
 * Dependency Injection Container
 * 
 * Central container for all application dependencies.
 * Enables easy testing by allowing dependency substitution.
 * 
 * Usage in production:
 *   const container = createContainer();
 *   app.locals.container = container;
 * 
 * Usage in tests:
 *   const mockRepo = createInMemoryPoolRepository();
 *   const container = createContainer({ poolRepository: mockRepo });
 */

import type { SupabaseClient } from '@supabase/supabase-js';
import type {
  Container,
  PoolRepository,
  EmailService,
  QRCodeService,
  LoggerService,
  ActivityLoggerService,
  SocketEmitter,
  AppConfig,
  DatabaseClient,
} from './types.js';
import { SupabasePoolRepository } from '../repositories/pool.repository.js';
import { logger as winstonLogger } from '../../utils/logger.js';
import { config as appConfig } from '../../config/index.js';
import { getSupabase } from '../../database/connection.js';
import QRCode from 'qrcode';

import { createSupabaseNotificationRepository } from '../repositories/notification.repository.supabase.js';
import { createNotificationService } from '../services/notification.service.js';

// ============================================
// SERVICE IMPLEMENTATIONS
// ============================================

/**
 * QR Code service implementation
 */
class QRCodeServiceImpl implements QRCodeService {
  async generate(data: string): Promise<string> {
    return QRCode.toDataURL(data, {
      errorCorrectionLevel: 'M',
      type: 'image/png',
      width: 300,
      margin: 2,
    });
  }

  async generateAsBuffer(data: string): Promise<Buffer> {
    return QRCode.toBuffer(data, {
      errorCorrectionLevel: 'M',
      type: 'png',
      width: 300,
      margin: 2,
    });
  }
}

/**
 * Winston logger adapter implementing LoggerService interface
 */
class WinstonLoggerAdapter implements LoggerService {
  info(message: string, ...args: unknown[]): void {
    winstonLogger.info(message, ...args);
  }
  warn(message: string, ...args: unknown[]): void {
    winstonLogger.warn(message, ...args);
  }
  error(message: string, ...args: unknown[]): void {
    winstonLogger.error(message, ...args);
  }
  debug(message: string, ...args: unknown[]): void {
    winstonLogger.debug(message, ...args);
  }
}

/**
 * Activity logger that writes to database
 */
class ActivityLoggerImpl implements ActivityLoggerService {
  constructor(private readonly db: SupabaseClient) { }

  async log(action: string, details: Record<string, unknown>, userId?: string): Promise<void> {
    try {
      await this.db.from('activity_logs').insert({
        action,
        details,
        user_id: userId,
        created_at: new Date().toISOString(),
      });
    } catch (error) {
      // Don't fail operations due to logging errors
      console.error('Activity log failed:', error);
    }
  }
}

/**
 * Socket emitter that integrates with Socket.io
 */
class SocketEmitterImpl implements SocketEmitter {
  private io: unknown = null;

  setIO(io: unknown): void {
    this.io = io;
  }

  emitToUnit(unit: string, event: string, data: unknown): void {
    if (this.io && typeof (this.io as { to: (room: string) => { emit: (event: string, data: unknown) => void } }).to === 'function') {
      (this.io as { to: (room: string) => { emit: (event: string, data: unknown) => void } }).to(unit).emit(event, data);
    }
  }

  emitToRoom(room: string, event: string, data: unknown): void {
    if (this.io && typeof (this.io as { to: (room: string) => { emit: (event: string, data: unknown) => void } }).to === 'function') {
      (this.io as { to: (room: string) => { emit: (event: string, data: unknown) => void } }).to(room).emit(event, data);
    }
  }

  emitToUser(userId: string, event: string, data: unknown): void {
    // Emit to user-specific room
    this.emitToRoom(`user-${userId}`, event, data);
  }
}

// ============================================
// CONTAINER FACTORY
// ============================================

let defaultContainer: Container | null = null;
let socketEmitterSingleton: SocketEmitterImpl | null = null;

/**
 * Create a dependency injection container
 * 
 * @param overrides - Partial container to override default implementations
 * @returns Complete container with all dependencies
 */
export function createContainer(overrides?: Partial<Container>): Container {
  // Get or create socket emitter singleton (needs to persist across container recreations)
  if (!socketEmitterSingleton) {
    socketEmitterSingleton = new SocketEmitterImpl();
  }

  // Default implementations
  const supabase = getSupabase();

  // Core defaults - use Supabase for production, in-memory for tests
  // Use Supabase notification repository for persistent notifications
  const notificationRepo = createSupabaseNotificationRepository();

  const defaults: Partial<Container> = {
    // Database client (Supabase adapter)
    database: supabase as unknown as DatabaseClient,

    // Repositories
    poolRepository: new SupabasePoolRepository(supabase),
    notificationRepository: notificationRepo,

    // Services
    emailService: null as unknown as EmailService, // Lazy loaded below
    qrCodeService: new QRCodeServiceImpl(),
    notificationService: () => createNotificationService({ notificationRepository: notificationRepo }),
    logger: new WinstonLoggerAdapter(),
    activityLogger: new ActivityLoggerImpl(supabase),
    socketEmitter: socketEmitterSingleton,

    // Config
    config: appConfig as unknown as AppConfig,
  };

  // Merge overrides - cast as Container since caller is responsible for full config
  const container = { ...defaults, ...overrides } as Container;

  // Lazy load email service if not overridden
  if (!overrides?.emailService) {
    // Import dynamically to avoid circular dependencies
    import('../../services/email.service.js').then(({ emailService }) => {
      if (!overrides?.emailService) {
        (container as { emailService: EmailService }).emailService = emailService;
      }
    });
  }

  return container;
}

/**
 * Get the default application container
 * Creates one if it doesn't exist
 */
export function getContainer(): Container {
  if (!defaultContainer) {
    defaultContainer = createContainer();
  }
  return defaultContainer;
}

/**
 * Reset the default container (for testing)
 */
export function resetContainer(): void {
  defaultContainer = null;
}

/**
 * Set the Socket.io instance for the socket emitter
 */
export function setSocketIO(io: unknown): void {
  if (socketEmitterSingleton) {
    socketEmitterSingleton.setIO(io);
  }
}

