/**
 * Order Controller Factory
 * 
 * Creates thin HTTP handlers for restaurant order routes.
 * All business logic lives in OrderService.
 */

import { z } from 'zod';
import type { Request, Response } from 'express';
import type { OrderService } from '../services/index.js';
import type { LoggerService } from '../container/types.js';
import { isErrorWithStatusCode, getErrorMessage } from '../../types/index.js';

// Extended error type for service errors with code
interface ServiceError {
  statusCode: number;
  message: string;
  code?: string;
}

function isServiceError(error: unknown): error is ServiceError {
  return (
    isErrorWithStatusCode(error) &&
    (!(error as { code?: unknown }).code || typeof (error as { code?: unknown }).code === 'string')
  );
}

// ============================================
// VALIDATION SCHEMAS
// ============================================

const createOrderSchema = z.object({
  customerId: z.string().uuid().optional(),
  customerName: z.string().min(1).max(100),
  customerEmail: z.string().email().optional(),
  customerPhone: z.string().optional(),
  orderType: z.enum(['dine_in', 'takeaway', 'delivery', 'room_service']),
  tableId: z.string().uuid().optional(),
  roomNumber: z.string().optional(),
  deliveryAddress: z.string().optional(),
  items: z.array(z.object({
    menuItemId: z.string().uuid(),
    quantity: z.number().int().positive(),
    specialInstructions: z.string().optional(),
  })).min(1),
  specialInstructions: z.string().optional(),
});

const updateStatusSchema = z.object({
  status: z.enum(['pending', 'confirmed', 'preparing', 'ready', 'served', 'delivered', 'completed', 'cancelled']),
});

const cancelOrderSchema = z.object({
  reason: z.string().min(1).max(500),
});

const getOrdersQuerySchema = z.object({
  status: z.enum(['pending', 'confirmed', 'preparing', 'ready', 'out_for_delivery', 'delivered', 'completed', 'cancelled']).optional(),
  orderType: z.enum(['dine_in', 'takeaway', 'delivery', 'room_service']).optional(),
  limit: z.coerce.number().int().positive().max(100).default(50),
  offset: z.coerce.number().int().nonnegative().default(0),
});

// ============================================
// CONTROLLER TYPES
// ============================================

export interface OrderControllerDeps {
  orderService: OrderService;
  logger: LoggerService;
}

export interface OrderController {
  createOrder: (req: Request, res: Response) => Promise<void>;
  getOrderById: (req: Request, res: Response) => Promise<void>;
  getOrderByNumber: (req: Request, res: Response) => Promise<void>;
  getOrders: (req: Request, res: Response) => Promise<void>;
  getLiveOrders: (req: Request, res: Response) => Promise<void>;
  getMyOrders: (req: Request, res: Response) => Promise<void>;
  updateOrderStatus: (req: Request, res: Response) => Promise<void>;
  cancelOrder: (req: Request, res: Response) => Promise<void>;
}

// ============================================
// CONTROLLER FACTORY
// ============================================

export function createOrderController(deps: OrderControllerDeps): OrderController {
  const { orderService, logger } = deps;

  return {
    /**
     * Create a new order
     * POST /api/restaurant/orders
     */
    async createOrder(req: Request, res: Response): Promise<void> {
      try {
        const validation = createOrderSchema.safeParse(req.body);
        if (!validation.success) {
          res.status(400).json({
            error: 'Validation failed',
            details: validation.error.issues,
          });
          return;
        }

        const result = await orderService.createOrder(validation.data as any);

        res.status(201).json({
          success: true,
          data: {
            order: result.order,
            items: result.items,
          },
        });
      } catch (error: unknown) {
        logger.error('Create order failed', { error: getErrorMessage(error) });

        if (isServiceError(error)) {
          res.status(error.statusCode).json({
            error: error.message,
            code: error.code,
          });
          return;
        }

        res.status(500).json({ error: 'Failed to create order' });
      }
    },

    /**
     * Get order by ID
     * GET /api/restaurant/orders/:id
     */
    async getOrderById(req: Request, res: Response): Promise<void> {
      try {
        const { id } = req.params;
        const result = await orderService.getOrderById(id);

        if (!result) {
          res.status(404).json({ error: 'Order not found' });
          return;
        }

        res.json({
          success: true,
          data: result,
        });
      } catch (error: unknown) {
        logger.error('Get order failed', { error: getErrorMessage(error) });
        res.status(500).json({ error: 'Failed to get order' });
      }
    },

    /**
     * Get order by order number
     * GET /api/restaurant/orders/number/:orderNumber
     */
    async getOrderByNumber(req: Request, res: Response): Promise<void> {
      try {
        const { orderNumber } = req.params;
        const order = await orderService.getOrderByNumber(orderNumber);

        if (!order) {
          res.status(404).json({ error: 'Order not found' });
          return;
        }

        // Get items for the order
        const result = await orderService.getOrderById(order.id);

        res.json({
          success: true,
          data: result,
        });
      } catch (error: unknown) {
        logger.error('Get order by number failed', { error: getErrorMessage(error) });
        res.status(500).json({ error: 'Failed to get order' });
      }
    },

    /**
     * Get orders with filtering
     * GET /api/restaurant/orders
     */
    async getOrders(req: Request, res: Response): Promise<void> {
      try {
        const validation = getOrdersQuerySchema.safeParse(req.query);
        if (!validation.success) {
          res.status(400).json({
            error: 'Validation failed',
            details: validation.error.issues,
          });
          return;
        }

        const orders = await orderService.getOrders(validation.data);

        res.json({
          success: true,
          data: orders,
        });
      } catch (error: unknown) {
        logger.error('Get orders failed', { error: getErrorMessage(error) });
        res.status(500).json({ error: 'Failed to get orders' });
      }
    },

    /**
     * Get live (active) orders
     * GET /api/restaurant/orders/live
     */
    async getLiveOrders(req: Request, res: Response): Promise<void> {
      try {
        const orders = await orderService.getLiveOrders();

        res.json({
          success: true,
          data: orders,
        });
      } catch (error: unknown) {
        logger.error('Get live orders failed', { error: getErrorMessage(error) });
        res.status(500).json({ error: 'Failed to get live orders' });
      }
    },

    /**
     * Get orders for current user
     * GET /api/restaurant/orders/mine
     */
    async getMyOrders(req: Request, res: Response): Promise<void> {
      try {
        const userId = req.user?.userId;
        if (!userId) {
          res.status(401).json({ error: 'Authentication required' });
          return;
        }

        const orders = await orderService.getOrdersByCustomer(userId);

        res.json({
          success: true,
          data: orders,
        });
      } catch (error: unknown) {
        logger.error('Get my orders failed', { error: getErrorMessage(error) });
        res.status(500).json({ error: 'Failed to get orders' });
      }
    },

    /**
     * Update order status
     * PATCH /api/restaurant/orders/:id/status
     */
    async updateOrderStatus(req: Request, res: Response): Promise<void> {
      try {
        const { id } = req.params;
        const userId = req.user?.userId;

        const validation = updateStatusSchema.safeParse(req.body);
        if (!validation.success) {
          res.status(400).json({
            error: 'Validation failed',
            details: validation.error.issues,
          });
          return;
        }

        const order = await orderService.updateOrderStatus(
          id,
          validation.data.status,
          userId
        );

        res.json({
          success: true,
          data: order,
        });
      } catch (error: unknown) {
        logger.error('Update order status failed', { error: getErrorMessage(error) });

        if (isServiceError(error)) {
          res.status(error.statusCode).json({
            error: error.message,
            code: error.code,
          });
          return;
        }

        res.status(500).json({ error: 'Failed to update order status' });
      }
    },

    /**
     * Cancel order
     * POST /api/restaurant/orders/:id/cancel
     */
    async cancelOrder(req: Request, res: Response): Promise<void> {
      try {
        const { id } = req.params;
        const userId = req.user?.userId;

        const validation = cancelOrderSchema.safeParse(req.body);
        if (!validation.success) {
          res.status(400).json({
            error: 'Validation failed',
            details: validation.error.issues,
          });
          return;
        }

        const order = await orderService.cancelOrder(
          id,
          validation.data.reason,
          userId
        );

        res.json({
          success: true,
          data: order,
        });
      } catch (error: unknown) {
        logger.error('Cancel order failed', { error: getErrorMessage(error) });

        if (isServiceError(error)) {
          res.status(error.statusCode).json({
            error: error.message,
            code: error.code,
          });
          return;
        }

        res.status(500).json({ error: 'Failed to cancel order' });
      }
    },
  };
}

/**
 * In-Memory Audit Repository
 * Test double for AuditRepository using in-memory data structures.
 */

import type {
  AuditRepository,
  AuditLog,
  AuditLogWithUser,
  AuditFilters,
  AuditResource,
} from '../container/types.js';

export function createInMemoryAuditRepository(): AuditRepository & {
  addLog(log: AuditLog): void;
  addUser(user: { id: string; full_name: string; email: string }): void;
  getAllLogs(): AuditLogWithUser[];
  clear(): void;
  reset(): void;
} {
  const logs = new Map<string, AuditLog>();
  const users = new Map<string, { full_name: string; email: string }>();

  function enrich(log: AuditLog): AuditLogWithUser {
    const user = users.get(log.user_id);
    return { ...log, user: user ?? null };
  }

  return {
    addLog(log: AuditLog) {
      logs.set(log.id, log);
    },
    addUser(user: { id: string; full_name: string; email: string }) {
      users.set(user.id, { full_name: user.full_name, email: user.email });
    },
    getAllLogs(): AuditLogWithUser[] {
      return [...logs.values()].map(enrich);
    },
    clear() {
      logs.clear();
      users.clear();
    },
    reset() {
      logs.clear();
      users.clear();
    },

    async createLog(data) {
      const id = crypto.randomUUID();
      const now = new Date().toISOString();
      const log: AuditLog = { ...data, id, created_at: now } as AuditLog;
      logs.set(id, log);
      return log;
    },
    async getLogs(filters, pagination) {
      let result = [...logs.values()];
      if (filters?.userId) result = result.filter(l => l.user_id === filters.userId);
      if (filters?.action) result = result.filter(l => l.action === filters.action);
      if (filters?.resource) result = result.filter(l => l.resource === filters.resource);
      if (filters?.resourceId) result = result.filter(l => l.resource_id === filters.resourceId);
      if (filters?.startDate) result = result.filter(l => l.created_at >= filters.startDate!);
      if (filters?.endDate) result = result.filter(l => l.created_at <= filters.endDate!);
      result.sort((a, b) => b.created_at.localeCompare(a.created_at));
      const total = result.length;
      if (pagination) {
        result = result.slice(pagination.offset, pagination.offset + pagination.limit);
      }
      return { logs: result.map(enrich), total };
    },
    async getLogById(id) {
      const log = logs.get(id);
      return log ? enrich(log) : null;
    },
    async getLogsByResource(resource, resourceId) {
      let result = [...logs.values()].filter(l => l.resource === resource);
      if (resourceId) result = result.filter(l => l.resource_id === resourceId);
      return result.map(enrich);
    },
    async deleteOldLogs(olderThanDays) {
      const cutoff = new Date();
      cutoff.setDate(cutoff.getDate() - olderThanDays);
      const cutoffStr = cutoff.toISOString();
      let count = 0;
      for (const [id, log] of logs) {
        if (log.created_at < cutoffStr) {
          logs.delete(id);
          count++;
        }
      }
      return count;
    },
  };
}

/**
 * Chalet Repository - Supabase Implementation
 * 
 * Implements ChaletRepository interface using Supabase as the data store.
 */

import type { SupabaseClient } from '@supabase/supabase-js';
import type {
  Chalet,
  ChaletBooking,
  ChaletBookingAddOn,
  ChaletAddOn,
  ChaletPriceRule,
  ChaletRepository,
} from '../container/types.js';
import dayjs from 'dayjs';

export function createSupabaseChaletRepository(supabase: SupabaseClient): ChaletRepository {
  return {
    // ============================================
    // CHALET OPERATIONS
    // ============================================
    
    async getChalets(filters = {}) {
      let query = supabase
        .from('chalets')
        .select('*')
        .is('deleted_at', null);

      if (filters.moduleId) {
        query = query.eq('module_id', filters.moduleId);
      }
      if (filters.activeOnly !== false) {
        query = query.eq('is_active', true);
      }

      const { data, error } = await query;
      if (error) throw error;
      return data || [];
    },

    async getChaletById(id: string) {
      const { data, error } = await supabase
        .from('chalets')
        .select('*')
        .eq('id', id)
        .single();

      if (error && error.code === 'PGRST116') return null;
      if (error) throw error;
      return data;
    },

    async createChalet(chalet) {
      const { data, error } = await supabase
        .from('chalets')
        .insert(chalet)
        .select()
        .single();

      if (error) throw error;
      return data;
    },

    async updateChalet(id: string, updates) {
      const { data, error } = await supabase
        .from('chalets')
        .update({ ...updates, updated_at: new Date().toISOString() })
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;
      return data;
    },

    async deleteChalet(id: string) {
      const { error } = await supabase
        .from('chalets')
        .update({ deleted_at: new Date().toISOString() })
        .eq('id', id);

      if (error) throw error;
    },

    // ============================================
    // BOOKING OPERATIONS
    // ============================================

    async createBooking(booking) {
      const { data, error } = await supabase
        .from('chalet_bookings')
        .insert(booking)
        .select()
        .single();

      if (error) throw error;
      return data;
    },

    async getBookingById(id: string) {
      const { data, error } = await supabase
        .from('chalet_bookings')
        .select(`
          *,
          chalet:chalets(*),
          add_ons:chalet_booking_add_ons(*, add_on:chalet_add_ons(*))
        `)
        .eq('id', id)
        .single();

      if (error && error.code === 'PGRST116') return null;
      if (error) throw error;
      return data;
    },

    async getBookingByNumber(bookingNumber: string) {
      const { data, error } = await supabase
        .from('chalet_bookings')
        .select('*')
        .eq('booking_number', bookingNumber)
        .single();

      if (error && error.code === 'PGRST116') return null;
      if (error) throw error;
      return data;
    },

    async getBookings(filters) {
      let query = supabase
        .from('chalet_bookings')
        .select('*, chalets:chalet_id(id, name, capacity), users:customer_id(full_name, email, phone)')
        .is('deleted_at', null)
        .order('check_in_date', { ascending: true });

      if (filters.status) query = query.eq('status', filters.status);
      if (filters.chaletId) query = query.eq('chalet_id', filters.chaletId);
      if (filters.startDate) query = query.gte('check_in_date', filters.startDate);
      if (filters.endDate) query = query.lte('check_in_date', filters.endDate);

      const { data, error } = await query;
      if (error) throw error;
      return data || [];
    },

    async getBookingsByCustomer(customerId: string) {
      const { data, error } = await supabase
        .from('chalet_bookings')
        .select('*, chalet:chalets(name, images)')
        .eq('customer_id', customerId)
        .is('deleted_at', null)
        .order('created_at', { ascending: false });

      if (error) throw error;
      return data || [];
    },

    async getBookingsForChalet(chaletId: string, startDate?: string, endDate?: string) {
      let query = supabase
        .from('chalet_bookings')
        .select('*')
        .eq('chalet_id', chaletId)
        .is('deleted_at', null);

      if (startDate) query = query.gte('check_out_date', startDate);
      if (endDate) query = query.lte('check_in_date', endDate);

      const { data, error } = await query;
      if (error) throw error;
      return (data || []) as ChaletBooking[];
    },

    async getTodayBookings() {
      const today = dayjs().format('YYYY-MM-DD');

      const [checkInsResult, checkOutsResult] = await Promise.all([
        supabase
          .from('chalet_bookings')
          .select('*, chalets:chalet_id(id, name, capacity), users:customer_id(full_name, email, phone)')
          .gte('check_in_date', `${today}T00:00:00`)
          .lt('check_in_date', `${today}T23:59:59`)
          .is('deleted_at', null),
        supabase
          .from('chalet_bookings')
          .select('*, chalets:chalet_id(id, name, capacity), users:customer_id(full_name, email, phone)')
          .gte('check_out_date', `${today}T00:00:00`)
          .lt('check_out_date', `${today}T23:59:59`)
          .is('deleted_at', null),
      ]);

      if (checkInsResult.error) throw checkInsResult.error;
      if (checkOutsResult.error) throw checkOutsResult.error;

      return {
        checkIns: checkInsResult.data || [],
        checkOuts: checkOutsResult.data || [],
      };
    },

    async updateBooking(id: string, updates) {
      const { data, error } = await supabase
        .from('chalet_bookings')
        .update({ ...updates, updated_at: new Date().toISOString() })
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;
      return data;
    },

    // ============================================
    // BOOKING ADD-ONS
    // ============================================

    async createBookingAddOns(addOns) {
      if (addOns.length === 0) return [];

      const { data, error } = await supabase
        .from('chalet_booking_add_ons')
        .insert(addOns)
        .select();

      if (error) throw error;
      return data || [];
    },

    async getBookingAddOns(bookingId: string) {
      const { data, error } = await supabase
        .from('chalet_booking_add_ons')
        .select('*, add_on:chalet_add_ons(*)')
        .eq('booking_id', bookingId);

      if (error) throw error;
      return data || [];
    },

    // ============================================
    // ADD-ON OPERATIONS
    // ============================================

    async getAddOns(activeOnly = true) {
      let query = supabase.from('chalet_add_ons').select('*');
      if (activeOnly) query = query.eq('is_active', true);

      const { data, error } = await query;
      if (error) throw error;
      return data || [];
    },

    async getAddOnById(id: string) {
      const { data, error } = await supabase
        .from('chalet_add_ons')
        .select('*')
        .eq('id', id)
        .single();

      if (error && error.code === 'PGRST116') return null;
      if (error) throw error;
      return data;
    },

    async getAddOnsByIds(ids: string[]) {
      if (ids.length === 0) return [];

      const { data, error } = await supabase
        .from('chalet_add_ons')
        .select('*')
        .in('id', ids);

      if (error) throw error;
      return data || [];
    },

    async createAddOn(addOn) {
      const { data, error } = await supabase
        .from('chalet_add_ons')
        .insert(addOn)
        .select()
        .single();

      if (error) throw error;
      return data;
    },

    async updateAddOn(id: string, updates) {
      const { data, error } = await supabase
        .from('chalet_add_ons')
        .update({ ...updates, updated_at: new Date().toISOString() })
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;
      return data;
    },

    async deleteAddOn(id: string) {
      const { error } = await supabase
        .from('chalet_add_ons')
        .update({ is_active: false })
        .eq('id', id);

      if (error) throw error;
    },

    // ============================================
    // PRICE RULE OPERATIONS
    // ============================================

    async getPriceRules(chaletId?: string) {
      let query = supabase
        .from('chalet_price_rules')
        .select('*, chalet:chalets(name)')
        .order('start_date', { ascending: true });

      if (chaletId) query = query.eq('chalet_id', chaletId);

      const { data, error } = await query;
      if (error) throw error;
      return data || [];
    },

    async createPriceRule(rule) {
      const { data, error } = await supabase
        .from('chalet_price_rules')
        .insert(rule)
        .select()
        .single();

      if (error) throw error;
      return data;
    },

    async updatePriceRule(id: string, updates) {
      const { data, error } = await supabase
        .from('chalet_price_rules')
        .update({ ...updates, updated_at: new Date().toISOString() })
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;
      return data;
    },

    async deletePriceRule(id: string) {
      const { error } = await supabase
        .from('chalet_price_rules')
        .update({ is_active: false })
        .eq('id', id);

      if (error) throw error;
    },

    // ============================================
    // SETTINGS OPERATIONS
    // ============================================

    async getChaletSettings() {
      const defaults = {
        deposit_percentage: 30,
        check_in_time: '14:00',
        check_out_time: '11:00',
        deposit_type: 'percentage' as const,
        deposit_fixed: 100,
      };

      try {
        const { data } = await supabase
          .from('site_settings')
          .select('value')
          .eq('key', 'chalets')
          .single();

        if (data?.value) {
          const settings = typeof data.value === 'string' ? JSON.parse(data.value) : data.value;
          return {
            deposit_percentage: settings.chaletDeposit || settings.depositPercent || defaults.deposit_percentage,
            check_in_time: settings.checkIn || defaults.check_in_time,
            check_out_time: settings.checkOut || defaults.check_out_time,
            deposit_type: settings.chaletDepositType || defaults.deposit_type,
            deposit_fixed: settings.chaletDepositFixed || defaults.deposit_fixed,
          };
        }
      } catch {
        // Return defaults if settings not found
      }

      return defaults;
    },

    async updateChaletSettings(settings: Record<string, unknown>) {
      for (const [key, value] of Object.entries(settings)) {
        await supabase
          .from('site_settings')
          .upsert(
            {
              key,
              value: String(value),
              category: 'chalet',
              updated_at: new Date().toISOString(),
            },
            { onConflict: 'key,category' }
          );
      }
    },
  };
}

/**
