      if (filters.isGlutenFree === true) query = query.eq('is_gluten_free', true);
      if (filters.isDairyFree === true) query = query.eq('is_dairy_free', true);
      if (filters.isHalal === true) query = query.eq('is_halal', true);

      if (filters.search) {
