/**
 * In-Memory Notification Repository
 * Test double for NotificationRepository using in-memory data structures.
 */

import type {
  NotificationRepository,
  Notification,
  NotificationFilters,
  NotificationTargetType,
  BroadcastNotification,
  NotificationTemplate,
} from '../container/types.js';

export function createInMemoryNotificationRepository(): NotificationRepository & {
  addNotification(n: Notification): void;
  getAllNotifications(): Notification[];
  clear(): void;
  reset(): void;
} {
  const notifications = new Map<string, Notification>();
  const broadcasts = new Map<string, BroadcastNotification>();
  const templates = new Map<string, NotificationTemplate>();

  return {
    addNotification(n: Notification) {
      notifications.set(n.id, n);
    },
    getAllNotifications(): Notification[] {
      return [...notifications.values()];
    },
    clear() {
      notifications.clear();
      broadcasts.clear();
      templates.clear();
    },
    reset() {
      notifications.clear();
      broadcasts.clear();
      templates.clear();
    },

    async create(data) {
      const id = crypto.randomUUID();
      const now = new Date().toISOString();
      const notification: Notification = { ...data, id, created_at: now } as Notification;
      notifications.set(id, notification);
      return notification;
    },
    async getById(id) {
      return notifications.get(id) ?? null;
    },
    async getByUserId(userId, filters) {
      let result = [...notifications.values()].filter(n => n.user_id === userId);
      if (filters?.type) result = result.filter(n => n.type === filters.type);
      if (filters?.isRead !== undefined) result = result.filter(n => n.is_read === filters.isRead);
      if (filters?.channel) result = result.filter(n => n.channel === filters.channel);
      if (filters?.priority) result = result.filter(n => n.priority === filters.priority);
      return result;
    },
    async getAll(filters, pagination) {
      let result = [...notifications.values()];
      if (filters?.userId) result = result.filter(n => n.user_id === filters.userId);
      if (filters?.type) result = result.filter(n => n.type === filters.type);
      if (filters?.targetType) result = result.filter(n => n.target_type === filters.targetType);
      if (filters?.isRead !== undefined) result = result.filter(n => n.is_read === filters.isRead);
      if (filters?.channel) result = result.filter(n => n.channel === filters.channel);
      if (filters?.scheduled) result = result.filter(n => !!n.scheduled_for);
      if (filters?.sent !== undefined) result = result.filter(n => filters.sent ? !!n.sent_at : !n.sent_at);
      const total = result.length;
      if (pagination) {
        result = result.slice(pagination.offset, pagination.offset + pagination.limit);
      }
      return { notifications: result, total };
    },
    async markAsRead(id) {
      const existing = notifications.get(id);
      if (!existing) throw new Error(`Notification ${id} not found`);
      const updated = { ...existing, is_read: true, read_at: new Date().toISOString() };
      notifications.set(id, updated);
      return updated;
    },
    async markAllAsRead(userId) {
      let count = 0;
      for (const [id, n] of notifications) {
        if (n.user_id === userId && !n.is_read) {
          notifications.set(id, { ...n, is_read: true, read_at: new Date().toISOString() });
          count++;
        }
      }
      return count;
    },
    async delete(id) {
      notifications.delete(id);
    },
    async deleteExpired() {
      const now = new Date().toISOString();
      let count = 0;
      for (const [id, n] of notifications) {
        if (n.expires_at && n.expires_at < now) {
          notifications.delete(id);
          count++;
        }
      }
      return count;
    },
    async deleteMultiple(ids) {
      let count = 0;
      for (const id of ids) {
        if (notifications.delete(id)) count++;
      }
      return count;
    },
    async createBroadcast(data) {
      const id = crypto.randomUUID();
      const now = new Date().toISOString();
      const broadcast: BroadcastNotification = { ...data, id, created_at: now } as BroadcastNotification;
      broadcasts.set(id, broadcast);
      return broadcast;
    },
    async getBroadcasts(targetType) {
      let result = [...broadcasts.values()];
      if (targetType) result = result.filter(b => b.target_type === targetType);
      return result;
    },
    async getBroadcastById(id) {
      return broadcasts.get(id) ?? null;
    },
    async updateBroadcast(id, data) {
      const existing = broadcasts.get(id);
      if (!existing) throw new Error(`Broadcast ${id} not found`);
      const updated = { ...existing, ...data };
      broadcasts.set(id, updated);
      return updated;
    },
    async getScheduledNotifications() {
      const now = new Date().toISOString();
      return [...notifications.values()].filter(n => n.scheduled_for && !n.sent_at && n.scheduled_for <= now);
    },
    async getScheduledBroadcasts() {
      const now = new Date().toISOString();
      return [...broadcasts.values()].filter(b => b.scheduled_for && !b.sent_at && b.scheduled_for <= now);
    },
    async createTemplate(data) {
      const id = crypto.randomUUID();
      const now = new Date().toISOString();
      const template: NotificationTemplate = { ...data, id, created_at: now, updated_at: now } as NotificationTemplate;
      templates.set(id, template);
      return template;
    },
    async getTemplates(activeOnly) {
      let result = [...templates.values()];
      if (activeOnly) result = result.filter(t => t.is_active);
      return result;
    },
    async getTemplateById(id) {
      return templates.get(id) ?? null;
    },
    async updateTemplate(id, data) {
      const existing = templates.get(id);
      if (!existing) throw new Error(`Template ${id} not found`);
      const updated = { ...existing, ...data, updated_at: new Date().toISOString() };
      templates.set(id, updated);
      return updated;
    },
    async deleteTemplate(id) {
      templates.delete(id);
    },
  };
}

/**
 * In-Memory Pool Repository
 * Test double for PoolRepository using in-memory data structures.
 */

import type { PoolRepository, PoolSession, PoolTicket } from '../container/types.js';

export interface InMemoryPoolRepository extends PoolRepository {
  addSession(data: Partial<PoolSession>): PoolSession;
  addTicket(data: Partial<PoolTicket>): PoolTicket;
  reset(): void;
}

export function createInMemoryPoolRepository(): InMemoryPoolRepository {
  const sessions = new Map<string, PoolSession>();
  const tickets = new Map<string, PoolTicket>();
  let ticketCounter = 1000;

  return {
    addSession(data: Partial<PoolSession>): PoolSession {
      const id = data.id ?? crypto.randomUUID();
      const now = new Date().toISOString();
      const session: PoolSession = {
        id,
        name: data.name ?? 'Session',
        module_id: data.module_id,
        start_time: data.start_time ?? '09:00',
        end_time: data.end_time ?? '12:00',
        capacity: data.capacity ?? 50,
        price: data.price ?? 10,
        adult_price: data.adult_price,
        child_price: data.child_price,
        is_active: data.is_active ?? true,
        created_at: data.created_at ?? now,
        updated_at: data.updated_at ?? now,
      };
      sessions.set(id, session);
      return session;
    },

    addTicket(data: Partial<PoolTicket>): PoolTicket {
      const id = data.id ?? crypto.randomUUID();
      const now = new Date().toISOString();
      const ticket: PoolTicket = {
        id,
        ticket_number: data.ticket_number ?? `PT-${++ticketCounter}`,
        session_id: data.session_id ?? '',
        date: data.date ?? now.split('T')[0],
        guest_name: data.guest_name ?? 'Guest',
        guest_email: data.guest_email,
        guest_phone: data.guest_phone,
        adults: data.adults ?? 1,
        children: data.children ?? 0,
        infants: data.infants ?? 0,
        total_price: data.total_price ?? 0,
        payment_method: data.payment_method ?? 'cash',
        payment_status: data.payment_status ?? 'pending',
        qr_code: data.qr_code,
        entry_time: data.entry_time,
        exit_time: data.exit_time,
        status: data.status ?? 'valid',
        created_at: data.created_at ?? now,
        updated_at: data.updated_at ?? now,
      };
      tickets.set(id, ticket);
      return ticket;
    },

    reset() {
      sessions.clear();
      tickets.clear();
      ticketCounter = 1000;
    },

    // PoolRepository interface
    async getSessions(moduleId?: string) {
      let result = [...sessions.values()].filter(s => s.is_active);
      if (moduleId) result = result.filter(s => s.module_id === moduleId);
      return result;
    },

    async getSessionById(id) {
      return sessions.get(id) ?? null;
    },

    async getAvailability(date, sessionId?, moduleId?) {
      let sessionList = [...sessions.values()].filter(s => s.is_active);
      if (sessionId) sessionList = sessionList.filter(s => s.id === sessionId);
      if (moduleId) sessionList = sessionList.filter(s => s.module_id === moduleId);

      return sessionList.map(session => {
        const sessionTickets = [...tickets.values()].filter(
          t => t.session_id === session.id && t.date === date && t.status !== 'cancelled'
        );
        const booked = sessionTickets.reduce((sum, t) => sum + t.adults + t.children, 0);
        return { session, booked, available: session.capacity - booked };
      });
    },

    async createTicket(data) {
      const id = crypto.randomUUID();
      const now = new Date().toISOString();
      const ticket: PoolTicket = {
        ...data,
        id,
        ticket_number: (data as any).ticket_number ?? `PT-${++ticketCounter}`,
        infants: (data as any).infants ?? 0,
        total_price: (data as any).total_price ?? 0,
        payment_method: (data as any).payment_method ?? 'cash',
        payment_status: (data as any).payment_status ?? 'pending',
        status: (data as any).status ?? 'valid',
        created_at: now,
        updated_at: now,
      } as PoolTicket;
      tickets.set(id, ticket);
      return ticket;
    },

    async getTicketById(id) {
      return tickets.get(id) ?? null;
    },

    async getTicketByNumber(ticketNumber) {
      for (const t of tickets.values()) {
        if (t.ticket_number === ticketNumber) return t;
      }
      return null;
    },

    async getTicketsByDate(date) {
      return [...tickets.values()].filter(t => t.date === date);
    },

    async getTicketsByUser(userId) {
      return [...tickets.values()].filter(t => (t as any).user_id === userId);
    },

    async updateTicket(id, data) {
      const existing = tickets.get(id);
      if (!existing) throw new Error(`Ticket ${id} not found`);
      const updated = { ...existing, ...data, updated_at: new Date().toISOString() };
      tickets.set(id, updated);
      return updated;
    },

    async createSession(data) {
      const id = crypto.randomUUID();
      const now = new Date().toISOString();
      const session: PoolSession = {
        ...data,
        id,
        is_active: (data as any).is_active ?? true,
        capacity: (data as any).capacity ?? 50,
        price: (data as any).price ?? 10,
        created_at: now,
        updated_at: now,
      } as PoolSession;
      sessions.set(id, session);
      return session;
    },

    async updateSession(id, data) {
      const existing = sessions.get(id);
      if (!existing) throw new Error(`Session ${id} not found`);
      const updated = { ...existing, ...data, updated_at: new Date().toISOString() };
      sessions.set(id, updated);
      return updated;
    },

    async deleteSession(id) {
      sessions.delete(id);
    },
  };
}

/**
 * Restaurant Repository - Supabase Implementation
 * 
 * Handles all database operations for restaurant orders, menu items, and tables.
 */

import type { SupabaseClient } from '@supabase/supabase-js';
import type { 
  RestaurantRepository, 
  RestaurantOrder, 
  RestaurantOrderItem, 
  RestaurantMenuItem, 
  RestaurantTable 
} from '../container/types.js';

export function createRestaurantRepository(supabase: SupabaseClient): RestaurantRepository {
  return {
    // ============================================
    // ORDER OPERATIONS
    // ============================================

    async createOrder(order: Omit<RestaurantOrder, 'id' | 'created_at' | 'updated_at'>): Promise<RestaurantOrder> {
      const { data, error } = await supabase
        .from('restaurant_orders')
        .insert(order)
        .select()
        .single();

      if (error) throw error;
      return data as RestaurantOrder;
    },

    async getOrderById(id: string): Promise<RestaurantOrder | null> {
      const { data, error } = await supabase
        .from('restaurant_orders')
        .select('*')
        .eq('id', id)
        .single();

      if (error) {
        if (error.code === 'PGRST116') return null;
        throw error;
      }
      return data as RestaurantOrder;
    },

    async getOrderByNumber(orderNumber: string): Promise<RestaurantOrder | null> {
      const { data, error } = await supabase
        .from('restaurant_orders')
        .select('*')
        .eq('order_number', orderNumber)
        .single();

      if (error) {
        if (error.code === 'PGRST116') return null;
        throw error;
      }
      return data as RestaurantOrder;
    },

    async getOrders(filters: { status?: string; date?: string; moduleId?: string }): Promise<RestaurantOrder[]> {
      let query = supabase
        .from('restaurant_orders')
        .select('*')
        .is('deleted_at', null)
        .order('created_at', { ascending: false });

      if (filters.moduleId) {
        query = query.eq('module_id', filters.moduleId);
      }

      if (filters.status) {
        const statuses = filters.status.split(',').map(s => s.trim());
        if (statuses.length > 1) {
          query = query.in('status', statuses);
        } else {
          query = query.eq('status', filters.status);
        }
      }

      if (filters.date) {
        const startOfDay = new Date(filters.date);
        startOfDay.setHours(0, 0, 0, 0);
        const endOfDay = new Date(filters.date);
        endOfDay.setHours(23, 59, 59, 999);
        
        query = query
          .gte('created_at', startOfDay.toISOString())
          .lte('created_at', endOfDay.toISOString());
      }

      const { data, error } = await query;
      if (error) throw error;
      return (data || []) as RestaurantOrder[];
    },

    async getLiveOrders(moduleId?: string): Promise<RestaurantOrder[]> {
      const activeStatuses = ['pending', 'confirmed', 'preparing', 'ready'];

      let query = supabase
        .from('restaurant_orders')
        .select('*')
        .in('status', activeStatuses)
        .order('created_at', { ascending: true });

      if (moduleId) {
        query = query.eq('module_id', moduleId);
      }

      const { data, error } = await query;
      if (error) throw error;
      return (data || []) as RestaurantOrder[];
    },

    async getOrdersByCustomer(customerId: string): Promise<RestaurantOrder[]> {
      const { data, error } = await supabase
        .from('restaurant_orders')
        .select('*')
        .eq('customer_id', customerId)
        .order('created_at', { ascending: false });

      if (error) throw error;
      return (data || []) as RestaurantOrder[];
    },

    async updateOrder(id: string, updates: Partial<RestaurantOrder>): Promise<RestaurantOrder> {
      const { data, error } = await supabase
        .from('restaurant_orders')
        .update({
          ...updates,
          updated_at: new Date().toISOString(),
        })
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;
      return data as RestaurantOrder;
    },

    // ============================================
    // ORDER ITEMS OPERATIONS
    // ============================================

    async createOrderItems(items: Omit<RestaurantOrderItem, 'id' | 'created_at'>[]): Promise<RestaurantOrderItem[]> {
      const { data, error } = await supabase
        .from('restaurant_order_items')
        .insert(items)
        .select();

      if (error) throw error;
      return (data || []) as RestaurantOrderItem[];
    },

    async getOrderItems(orderId: string): Promise<RestaurantOrderItem[]> {
      const { data, error } = await supabase
        .from('restaurant_order_items')
        .select('*')
        .eq('order_id', orderId);

      if (error) throw error;
      return (data || []) as RestaurantOrderItem[];
    },

    // ============================================
    // MENU ITEMS OPERATIONS
    // ============================================

    async getMenuItemById(id: string): Promise<RestaurantMenuItem | null> {
      const { data, error } = await supabase
        .from('menu_items')
        .select('*')
        .eq('id', id)
        .single();

      if (error) {
        if (error.code === 'PGRST116') return null;
        throw error;
      }
      return data as RestaurantMenuItem;
    },

    async getMenuItemsByIds(ids: string[]): Promise<RestaurantMenuItem[]> {
      const { data, error } = await supabase
        .from('menu_items')
        .select('*')
        .in('id', ids);

      if (error) throw error;
      return (data || []) as RestaurantMenuItem[];
    },

    async getMenuItems(filters?: { categoryId?: string; moduleId?: string; available?: boolean }): Promise<RestaurantMenuItem[]> {
      let query = supabase
        .from('menu_items')
        .select('*')
        .order('name');

      if (filters?.categoryId) {
        query = query.eq('category_id', filters.categoryId);
      }
      if (filters?.moduleId) {
        query = query.eq('module_id', filters.moduleId);
      }
      if (filters?.available !== undefined) {
        query = query.eq('is_available', filters.available);
      }

      const { data, error } = await query;
      if (error) throw error;
      return (data || []) as RestaurantMenuItem[];
    },

    // ============================================
    // TABLE OPERATIONS
    // ============================================

    async getTableById(id: string): Promise<RestaurantTable | null> {
      const { data, error } = await supabase
        .from('restaurant_tables')
        .select('*')
        .eq('id', id)
        .single();

      if (error) {
        if (error.code === 'PGRST116') return null;
        throw error;
      }
      return data as RestaurantTable;
    },

    async getTables(moduleId?: string): Promise<RestaurantTable[]> {
      let query = supabase
        .from('restaurant_tables')
        .select('*')
        .order('table_number');

      if (moduleId) {
        query = query.eq('module_id', moduleId);
      }

      const { data, error } = await query;
      if (error) throw error;
      return (data || []) as RestaurantTable[];
    },

    async updateTable(id: string, updates: Partial<RestaurantTable>): Promise<RestaurantTable> {
      const { data, error } = await supabase
        .from('restaurant_tables')
        .update({
          ...updates,
          updated_at: new Date().toISOString(),
        })
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;
      return data as RestaurantTable;
    },

    async rpc(fn: string, params?: Record<string, unknown>): Promise<{ data: unknown; error: Error | null }> {
      // @ts-ignore - PostgrestError is close enough to Error for our needs
      return supabase.rpc(fn, params);
    },
  };
}

