/**
 * In-Memory Review Repository
 * Test double for ReviewRepository using in-memory data structures.
 */

import type {
  ReviewRepository,
  Review,
  ReviewWithUser,
  ReviewFilters,
  ReviewStats,
  ServiceType,
} from '../container/types.js';

export interface InMemoryReviewRepo extends ReviewRepository {
  addReview(review: Partial<Review> & { id: string; user_id: string; rating: number; text: string; service_type: ServiceType; is_approved: boolean; created_at: string }): void;
  setUser(userId: string, user: { id?: string; full_name?: string; email?: string; profile_image_url?: string }): void;
  getAllReviewsRaw(): Review[];
  reset(): void;
}

export function createInMemoryReviewRepository(): InMemoryReviewRepo {
  const reviews = new Map<string, Review>();
  const users = new Map<string, { id?: string; full_name?: string; email?: string; profile_image_url?: string }>();

  function enrichWithUser(review: Review): ReviewWithUser {
    const user = users.get(review.user_id);
    return user ? { ...review, user } : { ...review };
  }

  return {
    addReview(review) {
      reviews.set(review.id, review as Review);
    },
    setUser(userId, user) {
      users.set(userId, user);
    },
    getAllReviewsRaw() {
      return [...reviews.values()];
    },
    reset() {
      reviews.clear();
      users.clear();
    },

    // ReviewRepository interface
    async getApprovedReviews(serviceType?, limit?) {
      let result = [...reviews.values()].filter(r => r.is_approved);
      if (serviceType) result = result.filter(r => r.service_type === serviceType);
      if (limit) result = result.slice(0, limit);
      return result.map(enrichWithUser);
    },

    async getReviewStats() {
      const approved = [...reviews.values()].filter(r => r.is_approved);
      const totalReviews = approved.length;
      const averageRating = totalReviews > 0
        ? approved.reduce((sum, r) => sum + r.rating, 0) / totalReviews
        : 0;
      return { totalReviews, averageRating };
    },

    async getReviewById(id) {
      return reviews.get(id) ?? null;
    },

    async getReviewByUserAndService(userId, serviceType) {
      for (const r of reviews.values()) {
        if (r.user_id === userId && r.service_type === serviceType) return r;
      }
      return null;
    },

    async getAllReviews(filters?: ReviewFilters) {
      let result = [...reviews.values()];
      if (filters?.status === 'approved') result = result.filter(r => r.is_approved);
      if (filters?.status === 'pending') result = result.filter(r => !r.is_approved);
      if (filters?.serviceType) result = result.filter(r => r.service_type === filters.serviceType);
      if (filters?.userId) result = result.filter(r => r.user_id === filters.userId);
      return result.map(enrichWithUser);
    },

    async createReview(data) {
      const id = crypto.randomUUID();
      const now = new Date().toISOString();
      const review: Review = { ...data, id, created_at: now, updated_at: now };
      reviews.set(id, review);
      return review;
    },

    async updateReviewStatus(id, isApproved) {
      const existing = reviews.get(id);
      if (!existing) throw new Error(`Review ${id} not found`);
      const updated = { ...existing, is_approved: isApproved, updated_at: new Date().toISOString() };
      reviews.set(id, updated);
      return updated;
    },

    async deleteReview(id) {
      reviews.delete(id);
    },
  };
}

/**
 * Review Repository - Supabase Implementation
 * 
 * Implements ReviewRepository interface using Supabase.
 */

import type { SupabaseClient } from '@supabase/supabase-js';
import type {
  Review,
  ReviewWithUser,
  ReviewRepository,
  ReviewFilters,
  ReviewStats,
  ServiceType,
} from '../container/types.js';

export function createReviewRepository(supabase: SupabaseClient): ReviewRepository {
  return {
    async getApprovedReviews(serviceType?: ServiceType, limit = 10) {
      let query = supabase
        .from('reviews')
        .select(`
          id,
          user_id,
          rating,
          text,
          service_type,
          is_approved,
          created_at,
          users!reviews_user_id_fkey (
            full_name,
            profile_image_url
          )
        `)
        .eq('is_approved', true)
        .order('created_at', { ascending: false })
        .limit(limit);

      if (serviceType && serviceType !== 'general') {
        query = query.eq('service_type', serviceType);
      }

      const { data, error } = await query;
      if (error) throw error;

      return (data || []).map(row => ({
        ...row,
        user: row.users,
      })) as ReviewWithUser[];
    },

    async getReviewStats() {
      const { data, error } = await supabase
        .from('reviews')
        .select('rating')
        .eq('is_approved', true);

      if (error) throw error;

      const ratings = data || [];
      const totalReviews = ratings.length;
      const averageRating = totalReviews > 0
        ? Math.round((ratings.reduce((sum, r) => sum + r.rating, 0) / totalReviews) * 10) / 10
        : 0;

      return { totalReviews, averageRating };
    },

    async getReviewById(id: string) {
      const { data, error } = await supabase
        .from('reviews')
        .select('*')
        .eq('id', id)
        .single();

      if (error && error.code !== 'PGRST116') throw error;
      return data as Review | null;
    },

    async getReviewByUserAndService(userId: string, serviceType: ServiceType) {
      const { data, error } = await supabase
        .from('reviews')
        .select('*')
        .eq('user_id', userId)
        .eq('service_type', serviceType)
        .single();

      if (error && error.code !== 'PGRST116') throw error;
      return data as Review | null;
    },

    async getAllReviews(filters: ReviewFilters = {}) {
      let query = supabase
        .from('reviews')
        .select(`
          id,
          user_id,
          rating,
          text,
          service_type,
          is_approved,
          created_at,
          users!reviews_user_id_fkey (
            id,
            full_name,
            email,
            profile_image_url
          )
        `)
        .order('created_at', { ascending: false });

      if (filters.status === 'pending') {
        query = query.eq('is_approved', false);
      } else if (filters.status === 'approved') {
        query = query.eq('is_approved', true);
      }

      if (filters.serviceType && filters.serviceType !== 'general') {
        query = query.eq('service_type', filters.serviceType);
      }

      if (filters.userId) {
        query = query.eq('user_id', filters.userId);
      }

      const { data, error } = await query;
      if (error) throw error;

      return (data || []).map(row => ({
        ...row,
        user: row.users,
      })) as ReviewWithUser[];
    },

    async createReview(reviewData) {
      const { data, error } = await supabase
        .from('reviews')
        .insert(reviewData)
        .select()
        .single();

      if (error) throw error;
      return data as Review;
    },

    async updateReviewStatus(id: string, isApproved: boolean) {
      const { data, error } = await supabase
        .from('reviews')
        .update({ is_approved: isApproved })
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;
      return data as Review;
    },

    async deleteReview(id: string) {
      const { error } = await supabase
        .from('reviews')
        .delete()
        .eq('id', id);

      if (error) throw error;
    },
  };
}

/**
 * In-Memory Snack Repository
 * Test double for SnackRepository using in-memory data structures.
 */

import type {
  SnackRepository,
  SnackItem,
  SnackOrder,
  SnackOrderItem,
  SnackOrderWithItems,
  SnackItemFilters,
  SnackOrderFilters,
  SnackOrderStatus,
} from '../container/types.js';

export interface InMemorySnackRepo extends SnackRepository {
  addItem(item: SnackItem): void;
  reset(): void;
}

export function createInMemorySnackRepository(): InMemorySnackRepo {
  const items = new Map<string, SnackItem>();
  const orders = new Map<string, SnackOrder>();
  const orderItems = new Map<string, SnackOrderItem[]>(); // orderId -> items
  let orderCounter = 5000;

  function buildOrderWithItems(order: SnackOrder): SnackOrderWithItems {
    const oi = orderItems.get(order.id) ?? [];
    return {
      ...order,
      items: oi.map(i => {
        const item = items.get(i.snack_item_id);
        return item ? { ...i, item } : i;
      }) as any,
    };
  }

  return {
    addItem(item: SnackItem) {
      items.set(item.id, item);
    },
    reset() {
      items.clear();
      orders.clear();
      orderItems.clear();
      orderCounter = 5000;
    },

    // Item operations
    async getItems(filters?: SnackItemFilters) {
      let result = [...items.values()].filter(i => !i.deleted_at);
      if (filters?.category) result = result.filter(i => i.category === filters.category);
      if (filters?.moduleId) result = result.filter(i => i.module_id === filters.moduleId);
      if (filters?.availableOnly) result = result.filter(i => i.is_available);
      return result;
    },
    async getItemById(id) {
      const item = items.get(id);
      return item && !item.deleted_at ? item : null;
    },
    async getItemsByIds(ids) {
      return ids.map(id => items.get(id)).filter((i): i is SnackItem => !!i && !i.deleted_at);
    },
    async createItem(data) {
      const id = crypto.randomUUID();
      const now = new Date().toISOString();
      const item: SnackItem = { ...data, id, created_at: now, updated_at: now } as SnackItem;
      items.set(id, item);
      return item;
    },
    async updateItem(id, data) {
      const existing = items.get(id);
      if (!existing) throw new Error(`Item ${id} not found`);
      const updated = { ...existing, ...data, updated_at: new Date().toISOString() };
      items.set(id, updated);
      return updated;
    },
    async deleteItem(id) {
      const existing = items.get(id);
      if (existing) {
        items.set(id, { ...existing, deleted_at: new Date().toISOString() });
      }
    },
    async setItemAvailability(id, isAvailable) {
      const existing = items.get(id);
      if (!existing) throw new Error(`Item ${id} not found`);
      const updated = { ...existing, is_available: isAvailable, updated_at: new Date().toISOString() };
      items.set(id, updated);
      return updated;
    },

    // Order operations
    async createOrder(data) {
      const id = crypto.randomUUID();
      const now = new Date().toISOString();
      const order: SnackOrder = {
        ...data,
        id,
        order_number: data.order_number ?? `SN-${++orderCounter}`,
        created_at: now,
        updated_at: now,
      } as SnackOrder;
      orders.set(id, order);
      return order;
    },
    async createOrderItems(newItems) {
      const created: SnackOrderItem[] = newItems.map(item => ({
        ...item,
        id: crypto.randomUUID(),
      }));
      for (const item of created) {
        const existing = orderItems.get(item.order_id) ?? [];
        existing.push(item);
        orderItems.set(item.order_id, existing);
      }
      return created;
    },
    async getOrderById(id) {
      const order = orders.get(id);
      if (!order || order.deleted_at) return null;
      return buildOrderWithItems(order);
    },
    async getOrders(filters?: SnackOrderFilters) {
      let result = [...orders.values()].filter(o => !o.deleted_at);
      if (filters?.status) {
        const statuses = Array.isArray(filters.status) ? filters.status : [filters.status];
        result = result.filter(o => statuses.includes(o.status));
      }
      if (filters?.customerId) result = result.filter(o => o.customer_id === filters.customerId);
      if (filters?.limit) result = result.slice(0, filters.limit);
      return result.map(buildOrderWithItems);
    },
    async getOrdersByCustomer(customerId, limit?) {
      let result = [...orders.values()].filter(o => o.customer_id === customerId && !o.deleted_at);
      if (limit) result = result.slice(0, limit);
      return result.map(buildOrderWithItems);
    },
    async getLiveOrders() {
      const liveStatuses: SnackOrderStatus[] = ['pending', 'preparing', 'ready'];
      return [...orders.values()]
        .filter(o => liveStatuses.includes(o.status) && !o.deleted_at)
        .map(buildOrderWithItems);
    },
    async updateOrderStatus(id, status, additionalData?) {
      const existing = orders.get(id);
      if (!existing) throw new Error(`Order ${id} not found`);
      const updated = { ...existing, ...additionalData, status, updated_at: new Date().toISOString() };
      orders.set(id, updated);
      return updated;
    },
  };
}

/**
 * In-Memory User Repository
 * Test double for UserRepository using in-memory data structures.
 */

import type {
  UserRepository,
  User,
  UserWithRoles,
  UserFilters,
  Role,
} from '../container/types.js';

export interface InMemoryUserRepo extends UserRepository {
  addUser(user: UserWithRoles): void;
  addRole(role: Role): void;
  reset(): void;
}

export function createInMemoryUserRepository(): InMemoryUserRepo {
  const users = new Map<string, UserWithRoles>();
  const roles = new Map<string, Role>();

  return {
    addUser(user: UserWithRoles) {
      users.set(user.id, user);
    },
    addRole(role: Role) {
      roles.set(role.id, role);
    },
    reset() {
      users.clear();
      roles.clear();
    },

    async getUserById(id) {
      return users.get(id) ?? null;
    },

    async getUserByEmail(email) {
      for (const u of users.values()) {
        if (u.email === email) return u;
      }
      return null;
    },

    async getUsers(filters?: UserFilters, pagination?: { page: number; limit: number }) {
      let result = [...users.values()];
      if (filters?.search) {
        const q = filters.search.toLowerCase();
        result = result.filter(u =>
          u.full_name.toLowerCase().includes(q) ||
          u.email.toLowerCase().includes(q)
        );
      }
      if (filters?.isActive !== undefined) {
        result = result.filter(u => u.is_active === filters.isActive);
      }
      if (filters?.roleId) {
        result = result.filter(u => u.roles.some(r => r.id === filters.roleId));
      }
      const total = result.length;
      if (pagination) {
        const start = (pagination.page - 1) * pagination.limit;
        result = result.slice(start, start + pagination.limit);
      }
      return { users: result, total };
    },

    async updateUser(id, data) {
      const existing = users.get(id);
      if (!existing) throw new Error(`User ${id} not found`);
      const updated: UserWithRoles = {
        ...existing,
        ...data,
        roles: existing.roles,
        updated_at: new Date().toISOString(),
      };
      users.set(id, updated);
      return updated;
    },

    async updateUserRoles(id, roleIds) {
      const existing = users.get(id);
      if (!existing) throw new Error(`User ${id} not found`);
      const newRoles = roleIds.map(rid => roles.get(rid)).filter((r): r is Role => !!r);
      const updated: UserWithRoles = { ...existing, roles: newRoles, updated_at: new Date().toISOString() };
      users.set(id, updated);
      return newRoles;
    },

    async getRoleById(id) {
      return roles.get(id) ?? null;
    },

    async getRolesByIds(ids) {
      return ids.map(id => roles.get(id)).filter((r): r is Role => !!r);
    },

    async getUserRoles(userId) {
      const user = users.get(userId);
      return user?.roles ?? [];
    },
  };
}

/**
 * Analytics Service
 *
 * Provides hotel performance metrics, KPIs, and dashboard management.
 */

import type {
  Container,
  Metric,
  MetricType,
  MetricPeriod,
  MetricAggregation,
  Dashboard,
  DashboardWidget,
  TimeSeriesPoint,
  AnalyticsFilters,
} from '../container/types.js';

// Constants
const METRIC_TYPES: MetricType[] = [
  'revenue',
  'occupancy',
  'bookings',
  'guests',
  'ratings',
  'cancellations',
  'adr',
  'revpar',
  'custom',
];

const METRIC_PERIODS: MetricPeriod[] = [
  'daily',
  'weekly',
  'monthly',
  'quarterly',
  'yearly',
];

const METRIC_AGGREGATIONS: MetricAggregation[] = [
  'sum',
  'average',
  'count',
  'min',
  'max',
];

const WIDGET_TYPES = ['metric', 'chart', 'table', 'gauge', 'heatmap'] as const;

// Custom error class
export class AnalyticsServiceError extends Error {
  constructor(
    message: string,
    public code: string,
    public statusCode: number = 400
  ) {
    super(message);
    this.name = 'AnalyticsServiceError';
  }
}

// UUID validation regex
const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export interface RecordMetricInput {
  name: string;
  type: MetricType;
  value: number;
  previousValue?: number;
  period: MetricPeriod;
  startDate: string;
  endDate: string;
  unit?: string;
  metadata?: Record<string, unknown>;
}

export interface CreateDashboardInput {
  name: string;
  description?: string;
  ownerId: string;
  isDefault?: boolean;
  isPublic?: boolean;
}

export interface UpdateDashboardInput {
  name?: string;
  description?: string;
  isDefault?: boolean;
  isPublic?: boolean;
}

export interface CreateWidgetInput {
  dashboardId: string;
  name: string;
  type: typeof WIDGET_TYPES[number];
  metricType?: MetricType;
  config?: Record<string, unknown>;
  position?: { x: number; y: number; width: number; height: number };
}

export interface UpdateWidgetInput {
  name?: string;
  config?: Record<string, unknown>;
  position?: { x: number; y: number; width: number; height: number };
}

export interface PerformanceSummary {
  revenue: { value: number; change: number | null };
  occupancy: { value: number; change: number | null };
  adr: { value: number; change: number | null };
  revpar: { value: number; change: number | null };
  bookings: { value: number; change: number | null };
  cancellations: { value: number; change: number | null };
  rating: { value: number; change: number | null };
  periodStart: string;
  periodEnd: string;
}

export function createAnalyticsService(container: Container) {
  const { analyticsRepository, logger } = container;

  // ============================================
  // VALIDATION HELPERS
  // ============================================
  function validateId(id: string, field: string = 'ID'): void {
    if (!UUID_REGEX.test(id)) {
      throw new AnalyticsServiceError(`Invalid ${field} format`, 'INVALID_ID');
    }
  }

  function validateDateRange(startDate: string, endDate: string): void {
    const start = new Date(startDate);
    const end = new Date(endDate);

    if (isNaN(start.getTime())) {
      throw new AnalyticsServiceError('Invalid start date', 'INVALID_START_DATE');
    }
    if (isNaN(end.getTime())) {
      throw new AnalyticsServiceError('Invalid end date', 'INVALID_END_DATE');
    }
    if (end < start) {
      throw new AnalyticsServiceError('End date must be after start date', 'INVALID_DATE_RANGE');
    }
  }

  async function getDashboardOrThrow(id: string): Promise<Dashboard> {
    validateId(id);
    const dashboard = await analyticsRepository.getDashboard(id);
    if (!dashboard) {
      throw new AnalyticsServiceError('Dashboard not found', 'NOT_FOUND', 404);
    }
    return dashboard;
  }

  async function getWidgetOrThrow(id: string): Promise<DashboardWidget> {
    validateId(id);
    const widget = await analyticsRepository.getWidget(id);
    if (!widget) {
      throw new AnalyticsServiceError('Widget not found', 'WIDGET_NOT_FOUND', 404);
    }
    return widget;
  }

  // ============================================
  // METRIC RECORDING
  // ============================================
  async function recordMetric(input: RecordMetricInput): Promise<Metric> {
    // Validate name
    if (!input.name || input.name.trim().length === 0) {
      throw new AnalyticsServiceError('Metric name is required', 'INVALID_NAME');
    }

    // Validate type
    if (!METRIC_TYPES.includes(input.type)) {
      throw new AnalyticsServiceError('Invalid metric type', 'INVALID_TYPE');
    }

    // Validate period
    if (!METRIC_PERIODS.includes(input.period)) {
      throw new AnalyticsServiceError('Invalid metric period', 'INVALID_PERIOD');
    }

    // Validate dates
    validateDateRange(input.startDate, input.endDate);

    // Calculate change
    let change: number | null = null;
    let changePercent: number | null = null;

    if (input.previousValue !== undefined && input.previousValue !== null) {
      change = input.value - input.previousValue;
      if (input.previousValue !== 0) {
        changePercent = Math.round((change / input.previousValue) * 100 * 100) / 100;
      }
    }

    const metric = await analyticsRepository.createMetric({
      name: input.name.trim(),
      type: input.type,
      value: input.value,
      previousValue: input.previousValue ?? null,
      change,
      changePercent,
      period: input.period,
      startDate: input.startDate,
      endDate: input.endDate,
      unit: input.unit || null,
      metadata: input.metadata || {},
    });

    logger?.info?.(`Metric recorded: ${metric.name} = ${metric.value}`);
    return metric;
  }

  async function getMetric(id: string): Promise<Metric | null> {
    validateId(id);
    return analyticsRepository.getMetric(id);
  }

  async function getMetricsByType(type: MetricType, period: MetricPeriod): Promise<Metric[]> {
    if (!METRIC_TYPES.includes(type)) {
      throw new AnalyticsServiceError('Invalid metric type', 'INVALID_TYPE');
    }
    if (!METRIC_PERIODS.includes(period)) {
      throw new AnalyticsServiceError('Invalid metric period', 'INVALID_PERIOD');
    }

    return analyticsRepository.getMetricsByType(type, period);
  }

  async function getMetricsForPeriod(startDate: string, endDate: string): Promise<Metric[]> {
    validateDateRange(startDate, endDate);
    return analyticsRepository.getMetricsForPeriod(startDate, endDate);
  }

  async function getLatestMetrics(types?: MetricType[]): Promise<Metric[]> {
    const metricTypes = types || METRIC_TYPES;
    return analyticsRepository.getLatestMetrics(metricTypes);
  }

  // ============================================
  // DASHBOARD MANAGEMENT
  // ============================================
  async function createDashboard(input: CreateDashboardInput): Promise<Dashboard> {
    // Validate name
    if (!input.name || input.name.trim().length === 0) {
      throw new AnalyticsServiceError('Dashboard name is required', 'INVALID_NAME');
    }

    // Validate owner
    validateId(input.ownerId, 'owner ID');

    // If setting as default, unset any existing default
    if (input.isDefault) {
      const existingDefault = await analyticsRepository.getDefaultDashboard();
      if (existingDefault) {
        await analyticsRepository.updateDashboard(existingDefault.id, { isDefault: false });
      }
    }

    const dashboard = await analyticsRepository.createDashboard({
      name: input.name.trim(),
      description: input.description?.trim() || null,
      widgets: [],
      ownerId: input.ownerId,
      isDefault: input.isDefault || false,
      isPublic: input.isPublic || false,
    });

    logger?.info?.(`Dashboard created: ${dashboard.name}`);
    return dashboard;
  }

  async function getDashboard(id: string): Promise<Dashboard | null> {
    validateId(id);
    return analyticsRepository.getDashboard(id);
  }

  async function getDashboardsByOwner(ownerId: string): Promise<Dashboard[]> {
    validateId(ownerId, 'owner ID');
    return analyticsRepository.getDashboardsByOwner(ownerId);
  }

  async function getDefaultDashboard(): Promise<Dashboard | null> {
    return analyticsRepository.getDefaultDashboard();
  }

  async function updateDashboard(id: string, input: UpdateDashboardInput): Promise<Dashboard> {
    const dashboard = await getDashboardOrThrow(id);

    const updates: Partial<Dashboard> = {};

    if (input.name !== undefined) {
      if (input.name.trim().length === 0) {
        throw new AnalyticsServiceError('Dashboard name cannot be empty', 'INVALID_NAME');
      }
      updates.name = input.name.trim();
    }

    if (input.description !== undefined) {
      updates.description = input.description?.trim() || null;
    }

    if (input.isDefault !== undefined) {
      if (input.isDefault && !dashboard.isDefault) {
        // Unset any existing default
        const existingDefault = await analyticsRepository.getDefaultDashboard();
        if (existingDefault && existingDefault.id !== id) {
          await analyticsRepository.updateDashboard(existingDefault.id, { isDefault: false });
        }
      }
      updates.isDefault = input.isDefault;
    }

    if (input.isPublic !== undefined) {
      updates.isPublic = input.isPublic;
    }

    if (Object.keys(updates).length === 0) {
      return dashboard;
    }

    const updated = await analyticsRepository.updateDashboard(id, updates);
    logger?.info?.(`Dashboard updated: ${updated.name}`);
    return updated;
  }

  async function deleteDashboard(id: string): Promise<void> {
    const dashboard = await getDashboardOrThrow(id);

    if (dashboard.isDefault) {
      throw new AnalyticsServiceError(
        'Cannot delete default dashboard',
        'CANNOT_DELETE_DEFAULT'
      );
    }

    await analyticsRepository.deleteDashboard(id);
    logger?.info?.(`Dashboard deleted: ${dashboard.name}`);
  }

  async function setDefaultDashboard(id: string): Promise<Dashboard> {
    const dashboard = await getDashboardOrThrow(id);

    if (dashboard.isDefault) {
      return dashboard;
    }

    // Unset existing default
    const existingDefault = await analyticsRepository.getDefaultDashboard();
    if (existingDefault) {
      await analyticsRepository.updateDashboard(existingDefault.id, { isDefault: false });
    }

    const updated = await analyticsRepository.updateDashboard(id, { isDefault: true });
    logger?.info?.(`Dashboard set as default: ${updated.name}`);
    return updated;
  }

  // ============================================
  // WIDGET MANAGEMENT
  // ============================================
  async function createWidget(input: CreateWidgetInput): Promise<DashboardWidget> {
    // Validate dashboard
    await getDashboardOrThrow(input.dashboardId);

    // Validate name
    if (!input.name || input.name.trim().length === 0) {
      throw new AnalyticsServiceError('Widget name is required', 'INVALID_NAME');
    }

    // Validate type
    if (!WIDGET_TYPES.includes(input.type)) {
      throw new AnalyticsServiceError('Invalid widget type', 'INVALID_WIDGET_TYPE');
    }

    // Validate metric type if provided
    if (input.metricType && !METRIC_TYPES.includes(input.metricType)) {
      throw new AnalyticsServiceError('Invalid metric type', 'INVALID_METRIC_TYPE');
    }

    const position = input.position || { x: 0, y: 0, width: 1, height: 1 };

    // Validate position
    if (position.width <= 0 || position.height <= 0) {
      throw new AnalyticsServiceError(
        'Widget dimensions must be positive',
        'INVALID_DIMENSIONS'
      );
    }

    const widget = await analyticsRepository.createWidget({
      dashboardId: input.dashboardId,
      name: input.name.trim(),
      type: input.type,
      metricType: input.metricType || null,
      config: input.config || {},
      position,
    });

    logger?.info?.(`Widget created: ${widget.name}`);
    return widget;
  }

  async function getWidget(id: string): Promise<DashboardWidget | null> {
    validateId(id);
    try {
      return await getWidgetOrThrow(id);
    } catch (e) {
      if (e instanceof AnalyticsServiceError && e.code === 'WIDGET_NOT_FOUND') {
        return null;
      }
      throw e;
    }
  }

  async function getWidgetsForDashboard(dashboardId: string): Promise<DashboardWidget[]> {
    await getDashboardOrThrow(dashboardId);
    return analyticsRepository.getWidgetsForDashboard(dashboardId);
  }

  async function updateWidget(id: string, input: UpdateWidgetInput): Promise<DashboardWidget> {
    const widget = await getWidgetOrThrow(id);

    const updates: Partial<DashboardWidget> = {};

    if (input.name !== undefined) {
      if (input.name.trim().length === 0) {
        throw new AnalyticsServiceError('Widget name cannot be empty', 'INVALID_NAME');
      }
      updates.name = input.name.trim();
    }

    if (input.config !== undefined) {
      updates.config = input.config;
    }

    if (input.position !== undefined) {
      if (input.position.width <= 0 || input.position.height <= 0) {
        throw new AnalyticsServiceError(
          'Widget dimensions must be positive',
          'INVALID_DIMENSIONS'
        );
      }
      updates.position = input.position;
    }

    if (Object.keys(updates).length === 0) {
      return widget;
    }

    const updated = await analyticsRepository.updateWidget(id, updates);
    logger?.info?.(`Widget updated: ${updated.name}`);
    return updated;
  }

  async function deleteWidget(id: string): Promise<void> {
    const widget = await getWidgetOrThrow(id);
    await analyticsRepository.deleteWidget(id);
    logger?.info?.(`Widget deleted: ${widget.name}`);
  }

  async function moveWidget(
    id: string,
    position: { x: number; y: number }
  ): Promise<DashboardWidget> {
    const widget = await getWidgetOrThrow(id);
    
    const newPosition = {
      ...widget.position,
      x: position.x,
      y: position.y,
    };

    const updated = await analyticsRepository.updateWidget(id, { position: newPosition });
    return updated;
  }

  async function resizeWidget(
    id: string,
    dimensions: { width: number; height: number }
  ): Promise<DashboardWidget> {
    const widget = await getWidgetOrThrow(id);

    if (dimensions.width <= 0 || dimensions.height <= 0) {
      throw new AnalyticsServiceError(
        'Widget dimensions must be positive',
        'INVALID_DIMENSIONS'
      );
    }

    const newPosition = {
      ...widget.position,
      width: dimensions.width,
      height: dimensions.height,
    };

    const updated = await analyticsRepository.updateWidget(id, { position: newPosition });
    return updated;
  }

  // ============================================
  // PERFORMANCE CALCULATIONS
  // ============================================
  function calculateOccupancyRate(
    occupiedRooms: number,
    totalRooms: number
  ): number {
    if (totalRooms <= 0) {
      throw new AnalyticsServiceError('Total rooms must be positive', 'INVALID_TOTAL_ROOMS');
    }
    return Math.round((occupiedRooms / totalRooms) * 100 * 100) / 100;
  }

  function calculateADR(totalRevenue: number, roomsSold: number): number {
    if (roomsSold <= 0) {
      return 0;
    }
    return Math.round((totalRevenue / roomsSold) * 100) / 100;
  }

  function calculateRevPAR(totalRevenue: number, totalRoomsAvailable: number): number {
    if (totalRoomsAvailable <= 0) {
      throw new AnalyticsServiceError(
        'Total rooms available must be positive',
        'INVALID_ROOMS_AVAILABLE'
      );
    }
    return Math.round((totalRevenue / totalRoomsAvailable) * 100) / 100;
  }

  function calculateGrowthRate(current: number, previous: number): number | null {
    if (previous === 0) {
      return null;
    }
    return Math.round(((current - previous) / previous) * 100 * 100) / 100;
  }

  // ============================================
  // TIME SERIES DATA
  // ============================================
  function generateTimeSeries(
    metrics: Metric[],
    aggregation: MetricAggregation = 'sum'
  ): TimeSeriesPoint[] {
    // Group by date
    const grouped: Map<string, number[]> = new Map();
    
    for (const metric of metrics) {
      const date = metric.startDate;
      if (!grouped.has(date)) {
        grouped.set(date, []);
      }
      grouped.get(date)!.push(metric.value);
    }

    // Apply aggregation
    const result: TimeSeriesPoint[] = [];
    
    for (const [date, values] of grouped) {
      let value: number;
      
      switch (aggregation) {
        case 'sum':
          value = values.reduce((a, b) => a + b, 0);
          break;
        case 'average':
          value = values.reduce((a, b) => a + b, 0) / values.length;
          break;
        case 'count':
          value = values.length;
          break;
        case 'min':
          value = Math.min(...values);
          break;
        case 'max':
          value = Math.max(...values);
          break;
        default:
          value = values.reduce((a, b) => a + b, 0);
      }

      result.push({ date, value: Math.round(value * 100) / 100 });
    }

    // Sort by date
    return result.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }

  // ============================================
  // PERFORMANCE SUMMARY
  // ============================================
  async function getPerformanceSummary(
    startDate: string,
    endDate: string
  ): Promise<PerformanceSummary> {
    validateDateRange(startDate, endDate);

    const metrics = await analyticsRepository.getMetricsForPeriod(startDate, endDate);

    const getMetricValue = (type: MetricType): { value: number; change: number | null } => {
      const metric = metrics.find(m => m.type === type);
      return {
        value: metric?.value ?? 0,
        change: metric?.changePercent ?? null,
      };
    };

    return {
      revenue: getMetricValue('revenue'),
      occupancy: getMetricValue('occupancy'),
      adr: getMetricValue('adr'),
      revpar: getMetricValue('revpar'),
      bookings: getMetricValue('bookings'),
      cancellations: getMetricValue('cancellations'),
      rating: getMetricValue('ratings'),
      periodStart: startDate,
      periodEnd: endDate,
    };
  }

  // ============================================
  // UTILITY METHODS
  // ============================================
  function getMetricTypes(): MetricType[] {
    return [...METRIC_TYPES];
  }

  function getMetricPeriods(): MetricPeriod[] {
    return [...METRIC_PERIODS];
  }

  function getMetricAggregations(): MetricAggregation[] {
    return [...METRIC_AGGREGATIONS];
  }

  function getWidgetTypes(): typeof WIDGET_TYPES[number][] {
    return [...WIDGET_TYPES];
  }

  function formatCurrency(value: number, currency: string = 'EUR'): string {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency,
    }).format(value);
  }

  function formatPercentage(value: number): string {
    return `${value >= 0 ? '+' : ''}${value}%`;
  }

  return {
    // Metrics
    recordMetric,
    getMetric,
    getMetricsByType,
    getMetricsForPeriod,
    getLatestMetrics,

    // Dashboards
    createDashboard,
    getDashboard,
    getDashboardsByOwner,
    getDefaultDashboard,
    updateDashboard,
    deleteDashboard,
    setDefaultDashboard,

    // Widgets
    createWidget,
    getWidget,
    getWidgetsForDashboard,
    updateWidget,
    deleteWidget,
    moveWidget,
    resizeWidget,

    // Calculations
    calculateOccupancyRate,
    calculateADR,
    calculateRevPAR,
    calculateGrowthRate,

    // Time series
    generateTimeSeries,

    // Summary
    getPerformanceSummary,

    // Utility
    getMetricTypes,
    getMetricPeriods,
    getMetricAggregations,
    getWidgetTypes,
    formatCurrency,
    formatPercentage,
  };
}

export type AnalyticsService = ReturnType<typeof createAnalyticsService>;

/**
 * Auth Service
 * 
 * Business logic for authentication with dependency injection.
 * All dependencies are injected via constructor, making this fully testable.
 */

import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import { v4 as uuidv4 } from 'uuid';
import type {
  AuthRepository,
  AuthUser,
  AuthTokens,
  EmailService,
  LoggerService,
  ActivityLoggerService,
  AppConfig,
} from '../container/types.js';

// ============================================
// ERROR TYPES
// ============================================

export class AuthServiceError extends Error {
  constructor(
    message: string,
    public code: string,
    public statusCode: number = 400
  ) {
    super(message);
    this.name = 'AuthServiceError';
  }
}

// ============================================
// SERVICE TYPES
// ============================================

export interface RegisterData {
  email: string;
  password: string;
  fullName: string;
  phone?: string;
  preferredLanguage?: 'en' | 'ar' | 'fr';
}

export interface LoginData {
  email: string;
  password: string;
  ipAddress?: string;
  userAgent?: string;
}

export interface TokenPayload {
  userId: string;
  email: string;
  roles: string[];
}

export interface AuthResult {
  user: {
    id: string;
    email: string;
    fullName: string;
    profileImageUrl?: string;
    preferredLanguage: string;
    roles: string[];
  };
  tokens: AuthTokens;
}

// ============================================
// SERVICE DEPENDENCIES
// ============================================

export interface AuthServiceDependencies {
  authRepository: AuthRepository;
  emailService: EmailService;
  logger: LoggerService;
  activityLogger: ActivityLoggerService;
  config: AppConfig;
}

// ============================================
// AUTH SERVICE
// ============================================

export interface AuthService {
  register(data: RegisterData): Promise<{ user: { id: string; email: string; fullName: string } }>;
  login(data: LoginData): Promise<AuthResult>;
  refreshAccessToken(refreshToken: string): Promise<{ tokens: AuthTokens }>;
  logout(token: string): Promise<void>;
  getUserById(userId: string): Promise<AuthUser & { roles: string[] }>;
  changePassword(userId: string, currentPassword: string, newPassword: string): Promise<void>;
  sendPasswordResetEmail(email: string): Promise<void>;
  resetPassword(token: string, newPassword: string): Promise<{ userId: string }>;
  generateTokens(payload: TokenPayload): AuthTokens;
  verifyToken(token: string): TokenPayload;
  verifyRefreshToken(token: string): { userId: string };
}

export function createAuthService(deps: AuthServiceDependencies): AuthService {
  const { authRepository, emailService, logger, activityLogger, config } = deps;

  // ============================================
  // TOKEN UTILITIES
  // ============================================

  function parseExpiryToSeconds(expiry: string): number {
    const match = expiry.match(/^(\d+)([smhd])$/);
    if (!match) return 900; // default 15 minutes

    const value = parseInt(match[1], 10);
    const unit = match[2];

    switch (unit) {
      case 's': return value;
      case 'm': return value * 60;
      case 'h': return value * 60 * 60;
      case 'd': return value * 60 * 60 * 24;
      default: return 900;
    }
  }

  function generateTokens(payload: TokenPayload): AuthTokens {
    const accessExpiresIn = parseExpiryToSeconds(config.jwt.expiresIn);
    const refreshExpiresIn = parseExpiryToSeconds(config.jwt.refreshExpiresIn);

    const accessToken = jwt.sign(
      { userId: payload.userId, email: payload.email, roles: payload.roles },
      config.jwt.secret,
      { expiresIn: accessExpiresIn }
    );

    const refreshToken = jwt.sign(
      { userId: payload.userId, type: 'refresh' },
      config.jwt.refreshSecret,
      { expiresIn: refreshExpiresIn }
    );

    return { accessToken, refreshToken, expiresIn: accessExpiresIn };
  }

  function verifyToken(token: string): TokenPayload {
    return jwt.verify(token, config.jwt.secret) as TokenPayload;
  }

  function verifyRefreshToken(token: string): { userId: string } {
    const decoded = jwt.verify(token, config.jwt.refreshSecret) as { userId: string; type: string };
    if (decoded.type !== 'refresh') {
      throw new AuthServiceError('Invalid token type', 'INVALID_TOKEN_TYPE', 401);
    }
    return { userId: decoded.userId };
  }

  // ============================================
  // SERVICE METHODS
  // ============================================

  return {
    generateTokens,
    verifyToken,
    verifyRefreshToken,

    async register(data: RegisterData) {
      logger.info('[AUTH SERVICE] Starting registration for:', data.email);

      // Check if email exists
      const existing = await authRepository.getUserByEmail(data.email);
      if (existing) {
        logger.warn('[AUTH SERVICE] Email already exists:', data.email);
        throw new AuthServiceError('Email already registered', 'EMAIL_EXISTS', 409);
      }

      // Hash password
      const passwordHash = await bcrypt.hash(data.password, 12);

      // Create user
      const user = await authRepository.createUser({
        email: data.email.toLowerCase(),
        password_hash: passwordHash,
        full_name: data.fullName,
        phone: data.phone,
        preferred_language: data.preferredLanguage || 'en',
        email_verified: false,
        is_active: true,
      });

      logger.info('[AUTH SERVICE] User created with ID:', user.id);

      // Assign default customer role
      const customerRole = await authRepository.getRoleByName('customer');
      if (customerRole) {
        await authRepository.assignRole(user.id, customerRole.id);
        logger.info('[AUTH SERVICE] Customer role assigned');
      } else {
        logger.warn('[AUTH SERVICE] Could not find customer role');
      }

      await activityLogger.log('REGISTER', {
        email: data.email,
        fullName: data.fullName,
      }, user.id);

      return {
        user: {
          id: user.id,
          email: user.email,
          fullName: user.full_name,
        },
      };
    },

    async login(data: LoginData): Promise<AuthResult> {
      logger.info('[AUTH SERVICE] Login attempt for:', data.email);

      // Find user
      const user = await authRepository.getUserByEmail(data.email);
      if (!user) {
        logger.warn('[AUTH SERVICE] User not found:', data.email);
        throw new AuthServiceError('Invalid credentials', 'INVALID_CREDENTIALS', 401);
      }

      if (!user.is_active) {
        logger.warn('[AUTH SERVICE] Account is disabled:', data.email);
        throw new AuthServiceError('Account is disabled', 'ACCOUNT_DISABLED', 403);
      }

      // Verify password
      const isValid = await bcrypt.compare(data.password, user.password_hash);
      if (!isValid) {
        logger.warn('[AUTH SERVICE] Invalid password for:', data.email);
        throw new AuthServiceError('Invalid credentials', 'INVALID_CREDENTIALS', 401);
      }

      // Get user roles
      const roles = await authRepository.getUserRoles(user.id);

      // Generate tokens
      const tokens = generateTokens({
        userId: user.id,
        email: user.email,
        roles,
      });

      // Create session
      const expiresAt = new Date();
      expiresAt.setDate(expiresAt.getDate() + 7); // 7 days

      try {
        await authRepository.createSession({
          user_id: user.id,
          token: tokens.accessToken,
          refresh_token: tokens.refreshToken,
          expires_at: expiresAt.toISOString(),
          ip_address: data.ipAddress,
          user_agent: data.userAgent,
          is_active: true,
        });
        logger.info('[AUTH SERVICE] Session created');
      } catch (error) {
        // Session is not critical, log and continue
        logger.error('[AUTH SERVICE] Error creating session:', error);
      }

      // Update last login
      await authRepository.updateUser(user.id, {
        last_login_at: new Date().toISOString(),
      });

      await activityLogger.log('LOGIN', {
        ipAddress: data.ipAddress,
        userAgent: data.userAgent,
      }, user.id);

      logger.info('[AUTH SERVICE] Login successful for:', user.id);

      return {
        user: {
          id: user.id,
          email: user.email,
          fullName: user.full_name,
          profileImageUrl: user.profile_image_url,
          preferredLanguage: user.preferred_language,
          roles,
        },
        tokens,
      };
    },

    async refreshAccessToken(refreshToken: string) {
      // Verify refresh token
      const payload = verifyRefreshToken(refreshToken);

      // Find session
      const session = await authRepository.getSessionByRefreshToken(refreshToken);
      if (!session || !session.is_active) {
        throw new AuthServiceError('Invalid refresh token', 'INVALID_REFRESH_TOKEN', 401);
      }

      // Check expiration
      if (new Date(session.expires_at) < new Date()) {
        await authRepository.deleteSession(session.id);
        throw new AuthServiceError('Session expired', 'SESSION_EXPIRED', 401);
      }

      // Get user with roles
      const user = await authRepository.getUserById(session.user_id);
      if (!user || !user.is_active) {
        throw new AuthServiceError('User not found or inactive', 'USER_INACTIVE', 401);
      }

      const roles = await authRepository.getUserRoles(user.id);

      // Generate new tokens
      const tokens = generateTokens({
        userId: user.id,
        email: user.email,
        roles,
      });

      // Update session
      const expiresAt = new Date();
      expiresAt.setDate(expiresAt.getDate() + 7);

      await authRepository.updateSession(session.id, {
        token: tokens.accessToken,
        refresh_token: tokens.refreshToken,
        expires_at: expiresAt.toISOString(),
        last_activity: new Date().toISOString(),
      });

      return { tokens };
    },

    async logout(token: string) {
      await authRepository.invalidateSession(token);
      logger.info('[AUTH SERVICE] Session invalidated');
    },

    async getUserById(userId: string) {
      const user = await authRepository.getUserById(userId);
      if (!user) {
        throw new AuthServiceError('User not found', 'USER_NOT_FOUND', 404);
      }

      const roles = await authRepository.getUserRoles(userId);

      return {
        ...user,
        roles,
      };
    },

    async changePassword(userId: string, currentPassword: string, newPassword: string) {
      const user = await authRepository.getUserById(userId);
      if (!user) {
        throw new AuthServiceError('User not found', 'USER_NOT_FOUND', 404);
      }

      const isValid = await bcrypt.compare(currentPassword, user.password_hash);
      if (!isValid) {
        throw new AuthServiceError('Current password is incorrect', 'INVALID_PASSWORD', 401);
      }

      const passwordHash = await bcrypt.hash(newPassword, 12);
      await authRepository.updateUser(userId, {
        password_hash: passwordHash,
      });

      // Invalidate all sessions for security
      await authRepository.invalidateUserSessions(userId);

      await activityLogger.log('CHANGE_PASSWORD', {}, userId);

      logger.info('[AUTH SERVICE] Password changed for user:', userId);
    },

    async sendPasswordResetEmail(email: string) {
      const user = await authRepository.getUserByEmail(email);
      if (!user) {
        // Don't reveal if email exists
        logger.info('[AUTH SERVICE] Password reset requested for non-existent email:', email);
        return;
      }

      // Generate reset token
      const resetToken = uuidv4();
      const expiresAt = new Date(Date.now() + 60 * 60 * 1000); // 1 hour

      // Create a session to store the reset token
      await authRepository.createSession({
        user_id: user.id,
        token: '',
        refresh_token: resetToken,
        expires_at: expiresAt.toISOString(),
        is_active: true,
      });

      // Send email with reset link
      const resetUrl = `${config.frontendUrl}/reset-password?token=${resetToken}`;

      await emailService.sendEmail({
        to: user.email,
        subject: 'Reset Your Password - V2 Resort',
        html: `
          <h1>Password Reset Request</h1>
          <p>Hi ${user.full_name},</p>
          <p>You requested to reset your password. Click the link below to set a new password:</p>
          <p><a href="${resetUrl}" style="background: #3b82f6; color: white; padding: 12px 24px; text-decoration: none; border-radius: 6px;">Reset Password</a></p>
          <p>This link will expire in 1 hour.</p>
          <p>If you didn't request this, you can safely ignore this email.</p>
          <p>Thanks,<br>V2 Resort Team</p>
        `,
      });

      logger.info('[AUTH SERVICE] Password reset email sent to:', email);
    },

    async resetPassword(token: string, newPassword: string) {
      // Find valid reset token
      const session = await authRepository.getSessionByRefreshToken(token);
      if (!session || !session.is_active) {
        throw new AuthServiceError('Invalid or expired reset token', 'INVALID_RESET_TOKEN', 400);
      }

      // Check expiration
      if (new Date(session.expires_at) < new Date()) {
        await authRepository.deleteSession(session.id);
        throw new AuthServiceError('Reset token has expired', 'TOKEN_EXPIRED', 400);
      }

      // Hash new password
      const passwordHash = await bcrypt.hash(newPassword, 12);

      // Update user password
      await authRepository.updateUser(session.user_id, {
        password_hash: passwordHash,
      });

      // Delete reset token session
      await authRepository.deleteSession(session.id);

      // Invalidate all other sessions for security
      await authRepository.invalidateUserSessions(session.user_id);

      await activityLogger.log('RESET_PASSWORD', {}, session.user_id);

      logger.info('[AUTH SERVICE] Password reset completed for user:', session.user_id);

      return { userId: session.user_id };
    },
  };
}

/**
 * Booking Service
 *
 * Business logic for chalet booking operations with dependency injection.
 * Handles booking creation, check-in/check-out, cancellations, and availability.
 */

import dayjs from 'dayjs';
import type {
  ChaletRepository,
  ChaletBooking,
  ChaletBookingAddOn,
  Chalet,
  ChaletAddOn,
  EmailService,
  LoggerService,
  ActivityLoggerService,
  SocketEmitter,
  AppConfig,
} from '../container/types.js';

// ============================================
// ERROR TYPES
// ============================================

export class BookingServiceError extends Error {
  constructor(
    message: string,
    public code: string,
    public statusCode: number = 400
  ) {
    super(message);
    this.name = 'BookingServiceError';
  }
}

// ============================================
// SERVICE TYPES
// ============================================

export interface CreateBookingInput {
  chaletId: string;
  customerId?: string;
  customerName: string;
  customerEmail?: string;
  customerPhone?: string;
  checkInDate: string;
  checkOutDate: string;
  numberOfGuests: number;
  addOns?: Array<{ addOnId: string; quantity: number }>;
  specialRequests?: string;
  paymentMethod?: string;
}

export interface BookingResult {
  booking: ChaletBooking;
  chalet: Chalet;
}

export interface BookingServiceDeps {
  chaletRepository: ChaletRepository;
  emailService: EmailService;
  logger: LoggerService;
  activityLogger: ActivityLoggerService;
  socketEmitter: SocketEmitter;
  config: AppConfig;
}

// ============================================
// SERVICE INTERFACE
// ============================================

export interface BookingService {
  createBooking(input: CreateBookingInput): Promise<BookingResult>;
  getBookingById(id: string): Promise<ChaletBooking | null>;
  getBookingByNumber(bookingNumber: string): Promise<ChaletBooking | null>;
  getBookingsByCustomer(customerId: string): Promise<ChaletBooking[]>;
  getBookings(filters: { status?: string; chaletId?: string }): Promise<ChaletBooking[]>;
  getTodayBookings(): Promise<{ checkIns: ChaletBooking[]; checkOuts: ChaletBooking[] }>;
  updateStatus(id: string, status: string, userId?: string): Promise<ChaletBooking>;
  checkIn(id: string, staffId: string): Promise<ChaletBooking>;
  checkOut(id: string, staffId: string): Promise<ChaletBooking>;
  cancelBooking(id: string, reason: string, userId?: string): Promise<ChaletBooking>;
  checkAvailability(chaletId: string, checkIn: string, checkOut: string): Promise<boolean>;
  getAvailability(chaletId: string, startDate: string, endDate: string): Promise<{ blockedDates: string[] }>;
}

function generateBookingNumber(): string {
  const date = new Date();
  const dateStr = date.toISOString().slice(2, 10).replace(/-/g, '');
  const random = Math.floor(Math.random() * 1000).toString().padStart(3, '0');
  return `C-${dateStr}-${random}`;
}

// ============================================
// SERVICE FACTORY
// ============================================

export function createBookingService(deps: BookingServiceDeps): BookingService {
  const { chaletRepository, emailService, logger, activityLogger, socketEmitter, config } = deps;

  // Helper to check date overlap
  function datesOverlap(
    start1: string,
    end1: string,
    start2: string,
    end2: string
  ): boolean {
    return start1 < end2 && start2 < end1;
  }

  // Calculate nightly price for a specific date
  function getNightlyPrice(
    chalet: Chalet,
    date: dayjs.Dayjs,
  ): number {
    const dayOfWeek = date.day();
    // Friday (5) and Saturday (6) are weekend days
    const isWeekend = dayOfWeek === 5 || dayOfWeek === 6;
    return parseFloat(isWeekend ? chalet.weekend_price : chalet.base_price);
  }

  return {
    async createBooking(input: CreateBookingInput): Promise<BookingResult> {
      // Validate chalet exists
      const chalet = await chaletRepository.getChaletById(input.chaletId);
      if (!chalet) {
        throw new BookingServiceError('Chalet not found', 'CHALET_NOT_FOUND', 404);
      }

      if (!chalet.is_active) {
        throw new BookingServiceError('Chalet is not available', 'CHALET_INACTIVE');
      }

      // Validate dates
      const checkIn = dayjs(input.checkInDate);
      const checkOut = dayjs(input.checkOutDate);
      const numberOfNights = checkOut.diff(checkIn, 'day');

      if (numberOfNights <= 0) {
        throw new BookingServiceError('Invalid date range', 'INVALID_DATE_RANGE');
      }

      // Validate capacity
      if (input.numberOfGuests > chalet.capacity) {
        throw new BookingServiceError(
          `Chalet capacity is ${chalet.capacity} guests`,
          'CAPACITY_EXCEEDED'
        );
      }

      // Check availability (no overlapping bookings)
      const existingBookings = await chaletRepository.getBookingsForChalet(
        input.chaletId,
        input.checkInDate,
        input.checkOutDate
      );
      if (existingBookings.length > 0) {
        throw new BookingServiceError(
          'Chalet is already booked for the selected dates',
          'DATES_UNAVAILABLE'
        );
      }

      // Calculate base amount (sum of nightly prices)
      let baseAmount = 0;
      for (let i = 0; i < numberOfNights; i++) {
        const nightDate = checkIn.add(i, 'day');
        baseAmount += getNightlyPrice(chalet, nightDate);
      }

      // Calculate add-ons
      let addOnsAmount = 0;
      const addOnDetails: Array<{ addOnId: string; quantity: number; unitPrice: string; subtotal: string }> = [];

      if (input.addOns && input.addOns.length > 0) {
        const addOnIds = input.addOns.map(a => a.addOnId);
        const addOns = await chaletRepository.getAddOnsByIds(addOnIds);
        const addOnMap = new Map<string, ChaletAddOn>();
        for (const ao of addOns) {
          addOnMap.set(ao.id, ao);
        }

        for (const addOnInput of input.addOns) {
          const addOn = addOnMap.get(addOnInput.addOnId);
          if (!addOn) continue;

          const unitPrice = parseFloat(addOn.price);
          let subtotal: number;

          if (addOn.price_type === 'per_night') {
            subtotal = unitPrice * addOnInput.quantity * numberOfNights;
          } else {
            subtotal = unitPrice * addOnInput.quantity;
          }

          addOnsAmount += subtotal;
          addOnDetails.push({
            addOnId: addOnInput.addOnId,
            quantity: addOnInput.quantity,
            unitPrice: addOn.price,
            subtotal: subtotal.toFixed(2),
          });
        }
      }

      const totalAmount = baseAmount + addOnsAmount;

      // Calculate deposit
      const settings = await chaletRepository.getChaletSettings();
      let depositAmount: number;
      if (settings.deposit_type === 'fixed' && settings.deposit_fixed) {
        depositAmount = settings.deposit_fixed;
      } else {
        depositAmount = Math.round(totalAmount * (settings.deposit_percentage / 100) * 100) / 100;
      }

      const bookingNumber = generateBookingNumber();

      // Create the booking
      const booking = await chaletRepository.createBooking({
        booking_number: bookingNumber,
        chalet_id: input.chaletId,
        customer_id: input.customerId,
        customer_name: input.customerName,
        customer_email: input.customerEmail,
        customer_phone: input.customerPhone,
        check_in_date: input.checkInDate,
        check_out_date: input.checkOutDate,
        number_of_guests: input.numberOfGuests,
        number_of_nights: numberOfNights,
        base_amount: baseAmount.toFixed(2),
        add_ons_amount: addOnsAmount.toFixed(2),
        deposit_amount: depositAmount.toFixed(2),
        total_amount: totalAmount.toFixed(2),
        status: 'pending',
        payment_status: 'pending',
        payment_method: input.paymentMethod as ChaletBooking['payment_method'],
        special_requests: input.specialRequests,
      } as Omit<ChaletBooking, 'id' | 'created_at' | 'updated_at'>);

      // Create booking add-ons
      if (addOnDetails.length > 0) {
        await chaletRepository.createBookingAddOns(
          addOnDetails.map(d => ({
            booking_id: booking.id,
            add_on_id: d.addOnId,
            quantity: d.quantity,
            unit_price: d.unitPrice,
            subtotal: d.subtotal,
          })) as Omit<ChaletBookingAddOn, 'id' | 'created_at'>[]
        );
      }

      // Emit socket event
      socketEmitter.emitToUnit('chalets', 'booking:new', {
        bookingId: booking.id,
        bookingNumber: booking.booking_number,
        customerName: input.customerName,
        chaletName: chalet.name,
        checkIn: input.checkInDate,
        checkOut: input.checkOutDate,
      });

      // Log activity
      await activityLogger.log(
        'CREATE_BOOKING',
        {
          bookingId: booking.id,
          bookingNumber: booking.booking_number,
          chaletId: input.chaletId,
          totalAmount,
        },
        input.customerId
      );

      logger.info('Booking created', { bookingId: booking.id, bookingNumber: booking.booking_number });

      return { booking, chalet };
    },

    async getBookingById(id: string): Promise<ChaletBooking | null> {
      return chaletRepository.getBookingById(id);
    },

    async getBookingByNumber(bookingNumber: string): Promise<ChaletBooking | null> {
      return chaletRepository.getBookingByNumber(bookingNumber);
    },

    async getBookingsByCustomer(customerId: string): Promise<ChaletBooking[]> {
      return chaletRepository.getBookingsByCustomer(customerId);
    },

    async getBookings(filters: { status?: string; chaletId?: string }): Promise<ChaletBooking[]> {
      return chaletRepository.getBookings(filters);
    },

    async getTodayBookings(): Promise<{ checkIns: ChaletBooking[]; checkOuts: ChaletBooking[] }> {
      return chaletRepository.getTodayBookings();
    },

    async updateStatus(id: string, status: string, userId?: string): Promise<ChaletBooking> {
      const booking = await chaletRepository.getBookingById(id);
      if (!booking) {
        throw new BookingServiceError('Booking not found', 'BOOKING_NOT_FOUND', 404);
      }
      return chaletRepository.updateBooking(id, { status: status as ChaletBooking['status'] });
    },

    async checkIn(id: string, staffId: string): Promise<ChaletBooking> {
      const booking = await chaletRepository.getBookingById(id);
      if (!booking) {
        throw new BookingServiceError('Booking not found', 'BOOKING_NOT_FOUND', 404);
      }

      if (booking.status !== 'pending' && booking.status !== 'confirmed') {
        throw new BookingServiceError(
          `Cannot check in a booking with status: ${booking.status}`,
          'INVALID_CHECK_IN'
        );
      }

      const updated = await chaletRepository.updateBooking(id, {
        status: 'checked_in',
        checked_in_at: new Date().toISOString(),
        checked_in_by: staffId,
      });

      socketEmitter.emitToUnit('chalets', 'booking:checked_in', {
        bookingId: id,
        staffId,
      });

      logger.info('Guest checked in', { bookingId: id, staffId });

      return updated;
    },

    async checkOut(id: string, staffId: string): Promise<ChaletBooking> {
      const booking = await chaletRepository.getBookingById(id);
      if (!booking) {
        throw new BookingServiceError('Booking not found', 'BOOKING_NOT_FOUND', 404);
      }

      if (booking.status !== 'checked_in') {
        throw new BookingServiceError(
          `Cannot check out a booking with status: ${booking.status}`,
          'INVALID_CHECK_OUT'
        );
      }

      const updated = await chaletRepository.updateBooking(id, {
        status: 'checked_out',
        checked_out_at: new Date().toISOString(),
        checked_out_by: staffId,
      });

      socketEmitter.emitToUnit('chalets', 'booking:checked_out', {
        bookingId: id,
        staffId,
      });

      logger.info('Guest checked out', { bookingId: id, staffId });

      return updated;
    },

    async cancelBooking(id: string, reason: string, userId?: string): Promise<ChaletBooking> {
      const booking = await chaletRepository.getBookingById(id);
      if (!booking) {
        throw new BookingServiceError('Booking not found', 'BOOKING_NOT_FOUND', 404);
      }

      if (booking.status === 'cancelled') {
        throw new BookingServiceError('Booking is already cancelled', 'ALREADY_CANCELLED');
      }

      if (booking.status === 'checked_out') {
        throw new BookingServiceError('Cannot cancel a completed booking', 'CANNOT_CANCEL');
      }

      const updated = await chaletRepository.updateBooking(id, {
        status: 'cancelled',
        cancellation_reason: reason,
        cancelled_at: new Date().toISOString(),
      });

      socketEmitter.emitToUnit('chalets', 'booking:cancelled', {
        bookingId: id,
        reason,
      });

      await activityLogger.log(
        'CANCEL_BOOKING',
        { bookingId: id, reason },
        userId
      );

      logger.info('Booking cancelled', { bookingId: id, reason });

      return updated;
    },

    async checkAvailability(chaletId: string, checkInDate: string, checkOutDate: string): Promise<boolean> {
      const existing = await chaletRepository.getBookingsForChalet(chaletId, checkInDate, checkOutDate);
      return existing.length === 0;
    },

    async getAvailability(chaletId: string, startDate: string, endDate: string): Promise<{ blockedDates: string[] }> {
      const bookings = await chaletRepository.getBookingsForChalet(chaletId, startDate, endDate);
      const blockedDates: string[] = [];

      for (const booking of bookings) {
        const start = dayjs(booking.check_in_date);
        const end = dayjs(booking.check_out_date);
        let current = start;
        while (current.isBefore(end)) {
          const dateStr = current.format('YYYY-MM-DD');
          if (!blockedDates.includes(dateStr)) {
            blockedDates.push(dateStr);
          }
          current = current.add(1, 'day');
        }
      }

      return { blockedDates };
    },
  };
}

/**
 * Currency Service
 * 
 * Provides multi-currency support, exchange rate management,
 * currency conversion with fees, and conversion history tracking.
 */

import type { 
  Container,
  CurrencyRepository,
  Currency,
  ExchangeRate,
  CurrencyConversion,
} from '../container/types';

// ============================================
// TYPES
// ============================================

export interface CreateCurrencyInput {
  code: string;
  name: string;
  symbol: string;
  decimalPlaces?: number;
}

export interface UpdateCurrencyInput {
  name?: string;
  symbol?: string;
  decimalPlaces?: number;
  isActive?: boolean;
}

export interface SetExchangeRateInput {
  baseCurrency: string;
  targetCurrency: string;
  rate: number;
  source?: string;
  validFrom?: string;
  validTo?: string | null;
}

export interface ConvertCurrencyInput {
  fromCurrency: string;
  toCurrency: string;
  amount: number;
  feePercent?: number;
  reference?: string;
  entityType?: string;
  entityId?: string;
}

export interface ConversionResult {
  fromCurrency: string;
  toCurrency: string;
  fromAmount: number;
  toAmount: number;
  rate: number;
  fee: number;
  netAmount: number;
  reference: string;
}

export interface CurrencyServiceResult<T> {
  success: boolean;
  data?: T;
  error?: string;
}

// ============================================
// VALIDATION
// ============================================

// ISO 4217 currency code pattern
const CURRENCY_CODE_PATTERN = /^[A-Z]{3}$/;

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

// Common currencies for validation reference
const COMMON_CURRENCIES = [
  'USD', 'EUR', 'GBP', 'JPY', 'CHF', 'CAD', 'AUD', 'NZD',
  'CNY', 'INR', 'BRL', 'MXN', 'ZAR', 'SGD', 'HKD', 'KRW',
  'SEK', 'NOK', 'DKK', 'PLN', 'CZK', 'HUF', 'RUB', 'TRY',
  'THB', 'MYR', 'IDR', 'PHP', 'VND', 'TWD', 'AED', 'SAR'
];

function isValidCurrencyCode(code: string): boolean {
  return CURRENCY_CODE_PATTERN.test(code.toUpperCase());
}

function isValidUUID(id: string): boolean {
  return UUID_PATTERN.test(id);
}

function isValidDate(dateStr: string): boolean {
  if (!dateStr) return false;
  const date = new Date(dateStr);
  return !isNaN(date.getTime());
}

// ============================================
// SERVICE FACTORY
// ============================================

export function createCurrencyService(container: Container) {
  const { currencyRepository } = container;

  // ============================================
  // CURRENCY MANAGEMENT
  // ============================================

  async function createCurrency(input: CreateCurrencyInput): Promise<CurrencyServiceResult<Currency>> {
    // Validate code
    if (!input.code || !isValidCurrencyCode(input.code)) {
      return { success: false, error: 'Invalid currency code. Must be 3 uppercase letters (ISO 4217)' };
    }

    // Validate name
    if (!input.name || input.name.trim() === '') {
      return { success: false, error: 'Currency name is required' };
    }

    // Validate symbol
    if (!input.symbol || input.symbol.trim() === '') {
      return { success: false, error: 'Currency symbol is required' };
    }

    // Validate decimal places
    const decimalPlaces = input.decimalPlaces ?? 2;
    if (decimalPlaces < 0 || decimalPlaces > 4) {
      return { success: false, error: 'Decimal places must be between 0 and 4' };
    }

    // Check if currency already exists
    const existing = await currencyRepository.getCurrency(input.code);
    if (existing) {
      return { success: false, error: 'Currency already exists' };
    }

    const currency = await currencyRepository.createCurrency({
      code: input.code.toUpperCase(),
      name: input.name.trim(),
      symbol: input.symbol.trim(),
      decimalPlaces,
      isActive: true,
    });

    return { success: true, data: currency };
  }

  async function getCurrency(code: string): Promise<CurrencyServiceResult<Currency>> {
    if (!code || !isValidCurrencyCode(code)) {
      return { success: false, error: 'Invalid currency code' };
    }

    const currency = await currencyRepository.getCurrency(code.toUpperCase());
    
    if (!currency) {
      return { success: false, error: 'Currency not found' };
    }

    return { success: true, data: currency };
  }

  async function getCurrencies(): Promise<CurrencyServiceResult<Currency[]>> {
    const currencies = await currencyRepository.getCurrencies();
    return { success: true, data: currencies };
  }

  async function updateCurrency(code: string, input: UpdateCurrencyInput): Promise<CurrencyServiceResult<Currency>> {
    if (!code || !isValidCurrencyCode(code)) {
      return { success: false, error: 'Invalid currency code' };
    }

    // Validate name if provided
    if (input.name !== undefined && input.name.trim() === '') {
      return { success: false, error: 'Currency name cannot be empty' };
    }

    // Validate symbol if provided
    if (input.symbol !== undefined && input.symbol.trim() === '') {
      return { success: false, error: 'Currency symbol cannot be empty' };
    }

    // Validate decimal places if provided
    if (input.decimalPlaces !== undefined && (input.decimalPlaces < 0 || input.decimalPlaces > 4)) {
      return { success: false, error: 'Decimal places must be between 0 and 4' };
    }

    try {
      const updated = await currencyRepository.updateCurrency(code, {
        ...(input.name !== undefined && { name: input.name.trim() }),
        ...(input.symbol !== undefined && { symbol: input.symbol.trim() }),
        ...(input.decimalPlaces !== undefined && { decimalPlaces: input.decimalPlaces }),
        ...(input.isActive !== undefined && { isActive: input.isActive }),
      });
      return { success: true, data: updated };
    } catch (error) {
      return { success: false, error: 'Currency not found' };
    }
  }

  async function deleteCurrency(code: string): Promise<CurrencyServiceResult<void>> {
    if (!code || !isValidCurrencyCode(code)) {
      return { success: false, error: 'Invalid currency code' };
    }

    await currencyRepository.deleteCurrency(code);
    return { success: true };
  }

  async function activateCurrency(code: string): Promise<CurrencyServiceResult<Currency>> {
    return updateCurrency(code, { isActive: true });
  }

  async function deactivateCurrency(code: string): Promise<CurrencyServiceResult<Currency>> {
    return updateCurrency(code, { isActive: false });
  }

  // ============================================
  // EXCHANGE RATE MANAGEMENT
  // ============================================

  async function setExchangeRate(input: SetExchangeRateInput): Promise<CurrencyServiceResult<ExchangeRate>> {
    // Validate base currency
    if (!input.baseCurrency || !isValidCurrencyCode(input.baseCurrency)) {
      return { success: false, error: 'Invalid base currency code' };
    }

    // Validate target currency
    if (!input.targetCurrency || !isValidCurrencyCode(input.targetCurrency)) {
      return { success: false, error: 'Invalid target currency code' };
    }

    // Cannot exchange same currency
    if (input.baseCurrency.toUpperCase() === input.targetCurrency.toUpperCase()) {
      return { success: false, error: 'Base and target currency cannot be the same' };
    }

    // Validate rate
    if (typeof input.rate !== 'number' || input.rate <= 0) {
      return { success: false, error: 'Exchange rate must be a positive number' };
    }

    // Validate validFrom if provided
    const validFrom = input.validFrom || new Date().toISOString();
    if (input.validFrom && !isValidDate(input.validFrom)) {
      return { success: false, error: 'Invalid validFrom date' };
    }

    // Validate validTo if provided
    if (input.validTo !== undefined && input.validTo !== null && !isValidDate(input.validTo)) {
      return { success: false, error: 'Invalid validTo date' };
    }

    // ValidTo must be after validFrom
    if (input.validTo && new Date(input.validTo) <= new Date(validFrom)) {
      return { success: false, error: 'validTo must be after validFrom' };
    }

    const rate = await currencyRepository.saveExchangeRate({
      baseCurrency: input.baseCurrency.toUpperCase(),
      targetCurrency: input.targetCurrency.toUpperCase(),
      rate: input.rate,
      source: input.source || 'manual',
      validFrom,
      validTo: input.validTo ?? null,
    });

    return { success: true, data: rate };
  }

  async function getExchangeRate(baseCurrency: string, targetCurrency: string): Promise<CurrencyServiceResult<ExchangeRate>> {
    if (!baseCurrency || !isValidCurrencyCode(baseCurrency)) {
      return { success: false, error: 'Invalid base currency code' };
    }

    if (!targetCurrency || !isValidCurrencyCode(targetCurrency)) {
      return { success: false, error: 'Invalid target currency code' };
    }

    // Same currency has rate of 1
    if (baseCurrency.toUpperCase() === targetCurrency.toUpperCase()) {
      return { 
        success: true, 
        data: {
          id: 'same-currency',
          baseCurrency: baseCurrency.toUpperCase(),
          targetCurrency: targetCurrency.toUpperCase(),
          rate: 1,
          source: 'system',
          validFrom: new Date().toISOString(),
          validTo: null,
          createdAt: new Date().toISOString(),
        }
      };
    }

    const rate = await currencyRepository.getExchangeRate(baseCurrency, targetCurrency);
    
    if (!rate) {
      return { success: false, error: 'Exchange rate not found' };
    }

    return { success: true, data: rate };
  }

  async function getExchangeRates(baseCurrency: string): Promise<CurrencyServiceResult<ExchangeRate[]>> {
    if (!baseCurrency || !isValidCurrencyCode(baseCurrency)) {
      return { success: false, error: 'Invalid base currency code' };
    }

    const rates = await currencyRepository.getExchangeRates(baseCurrency);
    return { success: true, data: rates };
  }

  // ============================================
  // CURRENCY CONVERSION
  // ============================================

  async function convert(input: ConvertCurrencyInput): Promise<CurrencyServiceResult<ConversionResult>> {
    // Validate currencies
    if (!input.fromCurrency || !isValidCurrencyCode(input.fromCurrency)) {
      return { success: false, error: 'Invalid source currency code' };
    }

    if (!input.toCurrency || !isValidCurrencyCode(input.toCurrency)) {
      return { success: false, error: 'Invalid target currency code' };
    }

    // Validate amount
    if (typeof input.amount !== 'number' || input.amount <= 0) {
      return { success: false, error: 'Amount must be a positive number' };
    }

    // Validate fee
    const feePercent = input.feePercent ?? 0;
    if (feePercent < 0 || feePercent > 100) {
      return { success: false, error: 'Fee percent must be between 0 and 100' };
    }

    // Get exchange rate
    const rateResult = await getExchangeRate(input.fromCurrency, input.toCurrency);
    
    if (!rateResult.success || !rateResult.data) {
      return { success: false, error: rateResult.error || 'Exchange rate not available' };
    }

    const rate = rateResult.data.rate;
    
    // Calculate conversion
    const grossAmount = input.amount * rate;
    const fee = grossAmount * (feePercent / 100);
    const netAmount = grossAmount - fee;

    // Generate reference if not provided
    const reference = input.reference || `CNV-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

    // Log the conversion
    await currencyRepository.logConversion({
      fromCurrency: input.fromCurrency.toUpperCase(),
      toCurrency: input.toCurrency.toUpperCase(),
      fromAmount: input.amount,
      toAmount: netAmount,
      rate,
      fee,
      reference,
      entityType: input.entityType,
      entityId: input.entityId,
    });

    return {
      success: true,
      data: {
        fromCurrency: input.fromCurrency.toUpperCase(),
        toCurrency: input.toCurrency.toUpperCase(),
        fromAmount: input.amount,
        toAmount: netAmount,
        rate,
        fee,
        netAmount,
        reference,
      },
    };
  }

  async function getConversionHistory(filters: {
    fromDate?: string;
    toDate?: string;
    currency?: string;
  } = {}): Promise<CurrencyServiceResult<CurrencyConversion[]>> {
    // Validate dates if provided
    if (filters.fromDate && !isValidDate(filters.fromDate)) {
      return { success: false, error: 'Invalid fromDate' };
    }

    if (filters.toDate && !isValidDate(filters.toDate)) {
      return { success: false, error: 'Invalid toDate' };
    }

    // Validate currency if provided
    if (filters.currency && !isValidCurrencyCode(filters.currency)) {
      return { success: false, error: 'Invalid currency code' };
    }

    const conversions = await currencyRepository.getConversions(filters);
    return { success: true, data: conversions };
  }

  // ============================================
  // CALCULATION UTILITIES
  // ============================================

  function calculateConversion(amount: number, rate: number, feePercent: number = 0): {
    grossAmount: number;
    fee: number;
    netAmount: number;
  } {
    const grossAmount = amount * rate;
    const fee = grossAmount * (feePercent / 100);
    const netAmount = grossAmount - fee;
    
    return { grossAmount, fee, netAmount };
  }

  function formatCurrency(amount: number, currencyCode: string, locale: string = 'en-US'): string {
    try {
      return new Intl.NumberFormat(locale, {
        style: 'currency',
        currency: currencyCode.toUpperCase(),
      }).format(amount);
    } catch {
      // Fallback for unknown currencies
      return `${currencyCode.toUpperCase()} ${amount.toFixed(2)}`;
    }
  }

  function roundToDecimalPlaces(amount: number, decimalPlaces: number): number {
    const factor = Math.pow(10, decimalPlaces);
    return Math.round(amount * factor) / factor;
  }

  function getCommonCurrencies(): string[] {
    return [...COMMON_CURRENCIES];
  }

  function getCurrencySymbol(code: string): string {
    const symbols: Record<string, string> = {
      'USD': '$',
      'EUR': '€',
      'GBP': '£',
      'JPY': '¥',
      'CHF': 'CHF',
      'CAD': 'C$',
      'AUD': 'A$',
      'NZD': 'NZ$',
      'CNY': '¥',
      'INR': '₹',
      'BRL': 'R$',
      'MXN': '$',
      'ZAR': 'R',
      'SGD': 'S$',
      'HKD': 'HK$',
      'KRW': '₩',
      'SEK': 'kr',
      'NOK': 'kr',
      'DKK': 'kr',
      'PLN': 'zł',
      'CZK': 'Kč',
      'HUF': 'Ft',
      'RUB': '₽',
      'TRY': '₺',
      'THB': '฿',
      'AED': 'د.إ',
      'SAR': '﷼',
    };
    
    return symbols[code.toUpperCase()] || code.toUpperCase();
  }

  function getInverseRate(rate: number): number {
    if (rate === 0) return 0;
    return roundToDecimalPlaces(1 / rate, 6);
  }

  function calculateCrossRate(
    baseToIntermediate: number, 
    intermediateToTarget: number
  ): number {
    return roundToDecimalPlaces(baseToIntermediate * intermediateToTarget, 6);
  }

  function isVolatileRate(currentRate: number, previousRate: number, thresholdPercent: number = 5): boolean {
    if (previousRate === 0) return false;
    const change = Math.abs((currentRate - previousRate) / previousRate) * 100;
    return change >= thresholdPercent;
  }

  // ============================================
  // RETURN SERVICE
  // ============================================

  return {
    // Currency management
    createCurrency,
    getCurrency,
    getCurrencies,
    updateCurrency,
    deleteCurrency,
    activateCurrency,
    deactivateCurrency,
    
    // Exchange rates
    setExchangeRate,
    getExchangeRate,
    getExchangeRates,
    
    // Conversion
    convert,
    getConversionHistory,
    
    // Utilities
    calculateConversion,
    formatCurrency,
    roundToDecimalPlaces,
    getCommonCurrencies,
    getCurrencySymbol,
    getInverseRate,
    calculateCrossRate,
    isVolatileRate,
  };
}

/**
 * Document Service
 *
 * Handles document management including upload, versioning, and access control.
 */

import type {
  Container,
  Document,
  DocumentVersion,
  DocumentType,
  DocumentStatus,
  DocumentVisibility,
  DocumentFilters,
} from '../container/types.js';

// Document types and statuses
const DOCUMENT_TYPES: DocumentType[] = [
  'contract',
  'invoice',
  'receipt',
  'id_document',
  'reservation_confirmation',
  'report',
  'policy',
  'image',
  'other',
];

const DOCUMENT_STATUSES: DocumentStatus[] = [
  'pending',
  'approved',
  'rejected',
  'expired',
  'archived',
];

const DOCUMENT_VISIBILITIES: DocumentVisibility[] = [
  'public',
  'private',
  'internal',
  'guest_only',
];

// MIME type to document type mapping
const MIME_TYPE_MAP: Record<string, DocumentType> = {
  'image/jpeg': 'image',
  'image/png': 'image',
  'image/gif': 'image',
  'image/webp': 'image',
  'application/pdf': 'other',
  'application/msword': 'other',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'other',
  'application/vnd.ms-excel': 'other',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'other',
};

// Custom error class
export class DocumentServiceError extends Error {
  constructor(
    message: string,
    public code: string,
    public statusCode: number = 400
  ) {
    super(message);
    this.name = 'DocumentServiceError';
  }
}

// UUID validation regex
const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export interface UploadDocumentInput {
  name: string;
  originalName: string;
  type?: DocumentType;
  visibility?: DocumentVisibility;
  mimeType: string;
  size: number;
  path: string;
  description?: string;
  tags?: string[];
  relatedEntityType?: string;
  relatedEntityId?: string;
  uploadedBy: string;
  expiresAt?: string;
  metadata?: Record<string, unknown>;
}

export interface UpdateDocumentInput {
  name?: string;
  description?: string;
  tags?: string[];
  visibility?: DocumentVisibility;
  expiresAt?: string | null;
  metadata?: Record<string, unknown>;
}

export interface CreateVersionInput {
  documentId: string;
  path: string;
  size: number;
  changes?: string;
  createdBy: string;
}

export interface DocumentStats {
  total: number;
  byType: Record<DocumentType, number>;
  byStatus: Record<DocumentStatus, number>;
  totalSize: number;
  pendingApproval: number;
  expiringThisMonth: number;
}

export function createDocumentService(container: Container) {
  const { documentRepository, logger } = container;

  // ============================================
  // VALIDATION HELPERS
  // ============================================
  function validateId(id: string, field: string = 'ID'): void {
    if (!UUID_REGEX.test(id)) {
      throw new DocumentServiceError(`Invalid ${field} format`, 'INVALID_ID');
    }
  }

  async function getDocumentOrThrow(id: string): Promise<Document> {
    validateId(id);
    const doc = await documentRepository.getById(id);
    if (!doc) {
      throw new DocumentServiceError('Document not found', 'NOT_FOUND', 404);
    }
    return doc;
  }

  function inferDocumentType(mimeType: string): DocumentType {
    return MIME_TYPE_MAP[mimeType] || 'other';
  }

  // ============================================
  // DOCUMENT MANAGEMENT
  // ============================================
  async function uploadDocument(input: UploadDocumentInput): Promise<Document> {
    // Validate name
    if (!input.name || input.name.trim().length === 0) {
      throw new DocumentServiceError('Document name is required', 'INVALID_NAME');
    }

    // Validate original name
    if (!input.originalName || input.originalName.trim().length === 0) {
      throw new DocumentServiceError('Original file name is required', 'INVALID_ORIGINAL_NAME');
    }

    // Validate mime type
    if (!input.mimeType || input.mimeType.trim().length === 0) {
      throw new DocumentServiceError('MIME type is required', 'INVALID_MIME_TYPE');
    }

    // Validate size
    if (input.size <= 0) {
      throw new DocumentServiceError('File size must be positive', 'INVALID_SIZE');
    }

    // Validate path
    if (!input.path || input.path.trim().length === 0) {
      throw new DocumentServiceError('File path is required', 'INVALID_PATH');
    }

    // Check for duplicate path
    const existing = await documentRepository.getByPath(input.path);
    if (existing) {
      throw new DocumentServiceError('File path already exists', 'DUPLICATE_PATH');
    }

    // Validate uploader ID
    validateId(input.uploadedBy, 'uploader ID');

    // Validate type if provided
    const type = input.type || inferDocumentType(input.mimeType);
    if (!DOCUMENT_TYPES.includes(type)) {
      throw new DocumentServiceError('Invalid document type', 'INVALID_TYPE');
    }

    // Validate visibility if provided
    const visibility = input.visibility || 'private';
    if (!DOCUMENT_VISIBILITIES.includes(visibility)) {
      throw new DocumentServiceError('Invalid visibility', 'INVALID_VISIBILITY');
    }

    // Validate related entity if provided
    if (input.relatedEntityId) {
      validateId(input.relatedEntityId, 'related entity ID');
    }

    // Validate expiry date if provided
    if (input.expiresAt) {
      const expiresDate = new Date(input.expiresAt);
      if (isNaN(expiresDate.getTime())) {
        throw new DocumentServiceError('Invalid expiry date', 'INVALID_EXPIRY_DATE');
      }
    }

    const doc = await documentRepository.create({
      name: input.name.trim(),
      originalName: input.originalName.trim(),
      type,
      status: 'pending',
      visibility,
      mimeType: input.mimeType,
      size: input.size,
      path: input.path,
      url: null,
      description: input.description?.trim() || null,
      tags: input.tags || [],
      relatedEntityType: input.relatedEntityType || null,
      relatedEntityId: input.relatedEntityId || null,
      uploadedBy: input.uploadedBy,
      approvedBy: null,
      approvedAt: null,
      expiresAt: input.expiresAt || null,
      metadata: input.metadata || {},
    });

    logger?.info?.(`Document uploaded: ${doc.name} (${doc.id})`);
    return doc;
  }

  async function getDocument(id: string): Promise<Document | null> {
    validateId(id);
    return documentRepository.getById(id);
  }

  async function getDocumentByPath(path: string): Promise<Document | null> {
    if (!path || path.trim().length === 0) {
      throw new DocumentServiceError('Path is required', 'INVALID_PATH');
    }
    return documentRepository.getByPath(path);
  }

  async function updateDocument(id: string, input: UpdateDocumentInput): Promise<Document> {
    const doc = await getDocumentOrThrow(id);

    const updates: Partial<Document> = {};

    if (input.name !== undefined) {
      if (input.name.trim().length === 0) {
        throw new DocumentServiceError('Document name cannot be empty', 'INVALID_NAME');
      }
      updates.name = input.name.trim();
    }

    if (input.description !== undefined) {
      updates.description = input.description?.trim() || null;
    }

    if (input.tags !== undefined) {
      updates.tags = input.tags;
    }

    if (input.visibility !== undefined) {
      if (!DOCUMENT_VISIBILITIES.includes(input.visibility)) {
        throw new DocumentServiceError('Invalid visibility', 'INVALID_VISIBILITY');
      }
      updates.visibility = input.visibility;
    }

    if (input.expiresAt !== undefined) {
      if (input.expiresAt !== null) {
        const expiresDate = new Date(input.expiresAt);
        if (isNaN(expiresDate.getTime())) {
          throw new DocumentServiceError('Invalid expiry date', 'INVALID_EXPIRY_DATE');
        }
      }
      updates.expiresAt = input.expiresAt;
    }

    if (input.metadata !== undefined) {
      updates.metadata = input.metadata;
    }

    if (Object.keys(updates).length === 0) {
      return doc;
    }

    const updated = await documentRepository.update(id, updates);
    logger?.info?.(`Document updated: ${updated.name} (${updated.id})`);
    return updated;
  }

  async function deleteDocument(id: string): Promise<void> {
    const doc = await getDocumentOrThrow(id);

    // Cannot delete approved documents
    if (doc.status === 'approved') {
      throw new DocumentServiceError(
        'Cannot delete approved documents',
        'CANNOT_DELETE_APPROVED'
      );
    }

    await documentRepository.delete(id);
    logger?.info?.(`Document deleted: ${doc.name} (${id})`);
  }

  async function listDocuments(filters?: DocumentFilters): Promise<Document[]> {
    return documentRepository.list(filters);
  }

  async function getDocumentsForEntity(
    entityType: string,
    entityId: string
  ): Promise<Document[]> {
    validateId(entityId, 'entity ID');
    return documentRepository.getByRelatedEntity(entityType, entityId);
  }

  // ============================================
  // APPROVAL WORKFLOW
  // ============================================
  async function approveDocument(id: string, approverId: string): Promise<Document> {
    const doc = await getDocumentOrThrow(id);
    validateId(approverId, 'approver ID');

    if (doc.status !== 'pending') {
      throw new DocumentServiceError(
        'Only pending documents can be approved',
        'INVALID_STATUS'
      );
    }

    const updated = await documentRepository.update(id, {
      status: 'approved',
      approvedBy: approverId,
      approvedAt: new Date().toISOString(),
    });

    logger?.info?.(`Document approved: ${updated.name} by ${approverId}`);
    return updated;
  }

  async function rejectDocument(id: string, reason?: string): Promise<Document> {
    const doc = await getDocumentOrThrow(id);

    if (doc.status !== 'pending') {
      throw new DocumentServiceError(
        'Only pending documents can be rejected',
        'INVALID_STATUS'
      );
    }

    const metadata = {
      ...doc.metadata,
      rejectionReason: reason || null,
      rejectedAt: new Date().toISOString(),
    };

    const updated = await documentRepository.update(id, {
      status: 'rejected',
      metadata,
    });

    logger?.info?.(`Document rejected: ${updated.name}`);
    return updated;
  }

  async function archiveDocument(id: string): Promise<Document> {
    const doc = await getDocumentOrThrow(id);

    if (doc.status === 'archived') {
      throw new DocumentServiceError('Document is already archived', 'ALREADY_ARCHIVED');
    }

    const updated = await documentRepository.update(id, { status: 'archived' });
    logger?.info?.(`Document archived: ${updated.name}`);
    return updated;
  }

  async function markAsExpired(id: string): Promise<Document> {
    const doc = await getDocumentOrThrow(id);

    if (doc.status === 'expired') {
      throw new DocumentServiceError('Document is already expired', 'ALREADY_EXPIRED');
    }

    const updated = await documentRepository.update(id, { status: 'expired' });
    logger?.info?.(`Document marked as expired: ${updated.name}`);
    return updated;
  }

  // ============================================
  // VERSIONING
  // ============================================
  async function createVersion(input: CreateVersionInput): Promise<DocumentVersion> {
    const doc = await getDocumentOrThrow(input.documentId);
    validateId(input.createdBy, 'creator ID');

    if (!input.path || input.path.trim().length === 0) {
      throw new DocumentServiceError('Version path is required', 'INVALID_PATH');
    }

    if (input.size <= 0) {
      throw new DocumentServiceError('Version size must be positive', 'INVALID_SIZE');
    }

    // Get latest version to determine next version number
    const latestVersion = await documentRepository.getLatestVersion(input.documentId);
    const nextVersionNumber = latestVersion ? latestVersion.version + 1 : 1;

    const version = await documentRepository.createVersion({
      documentId: input.documentId,
      version: nextVersionNumber,
      path: input.path,
      size: input.size,
      changes: input.changes || null,
      createdBy: input.createdBy,
      createdAt: new Date().toISOString(),
    });

    // Update document with new path and size
    await documentRepository.update(input.documentId, {
      path: input.path,
      size: input.size,
    });

    logger?.info?.(`Document version ${nextVersionNumber} created for ${doc.name}`);
    return version;
  }

  async function getVersions(documentId: string): Promise<DocumentVersion[]> {
    await getDocumentOrThrow(documentId);
    return documentRepository.getVersions(documentId);
  }

  async function getLatestVersion(documentId: string): Promise<DocumentVersion | null> {
    await getDocumentOrThrow(documentId);
    return documentRepository.getLatestVersion(documentId);
  }

  // ============================================
  // ACCESS CONTROL
  // ============================================
  async function setVisibility(
    id: string,
    visibility: DocumentVisibility
  ): Promise<Document> {
    const doc = await getDocumentOrThrow(id);

    if (!DOCUMENT_VISIBILITIES.includes(visibility)) {
      throw new DocumentServiceError('Invalid visibility', 'INVALID_VISIBILITY');
    }

    if (doc.visibility === visibility) {
      return doc;
    }

    const updated = await documentRepository.update(id, { visibility });
    logger?.info?.(`Document visibility changed: ${updated.name} -> ${visibility}`);
    return updated;
  }

  async function setUrl(id: string, url: string): Promise<Document> {
    const doc = await getDocumentOrThrow(id);

    if (!url || url.trim().length === 0) {
      throw new DocumentServiceError('URL is required', 'INVALID_URL');
    }

    // Basic URL validation
    try {
      new URL(url);
    } catch {
      throw new DocumentServiceError('Invalid URL format', 'INVALID_URL_FORMAT');
    }

    const updated = await documentRepository.update(id, { url });
    logger?.info?.(`Document URL set: ${updated.name}`);
    return updated;
  }

  // ============================================
  // TAGGING
  // ============================================
  async function addTags(id: string, tags: string[]): Promise<Document> {
    const doc = await getDocumentOrThrow(id);

    if (!tags || tags.length === 0) {
      return doc;
    }

    const normalizedTags = tags.map(t => t.trim().toLowerCase()).filter(t => t.length > 0);
    const currentTags = new Set(doc.tags);
    normalizedTags.forEach(t => currentTags.add(t));

    const updated = await documentRepository.update(id, { tags: Array.from(currentTags) });
    logger?.info?.(`Tags added to document: ${updated.name}`);
    return updated;
  }

  async function removeTags(id: string, tags: string[]): Promise<Document> {
    const doc = await getDocumentOrThrow(id);

    if (!tags || tags.length === 0) {
      return doc;
    }

    const normalizedTags = new Set(tags.map(t => t.trim().toLowerCase()));
    const remaining = doc.tags.filter(t => !normalizedTags.has(t));

    const updated = await documentRepository.update(id, { tags: remaining });
    logger?.info?.(`Tags removed from document: ${updated.name}`);
    return updated;
  }

  // ============================================
  // LINKING
  // ============================================
  async function linkToEntity(
    id: string,
    entityType: string,
    entityId: string
  ): Promise<Document> {
    const doc = await getDocumentOrThrow(id);
    validateId(entityId, 'entity ID');

    if (!entityType || entityType.trim().length === 0) {
      throw new DocumentServiceError('Entity type is required', 'INVALID_ENTITY_TYPE');
    }

    const updated = await documentRepository.update(id, {
      relatedEntityType: entityType.trim(),
      relatedEntityId: entityId,
    });

    logger?.info?.(`Document linked to ${entityType}: ${updated.name}`);
    return updated;
  }

  async function unlinkFromEntity(id: string): Promise<Document> {
    const doc = await getDocumentOrThrow(id);

    if (!doc.relatedEntityType && !doc.relatedEntityId) {
      return doc;
    }

    const updated = await documentRepository.update(id, {
      relatedEntityType: null,
      relatedEntityId: null,
    });

    logger?.info?.(`Document unlinked from entity: ${updated.name}`);
    return updated;
  }

  // ============================================
  // EXPIRY MANAGEMENT
  // ============================================
  async function setExpiry(id: string, expiresAt: string): Promise<Document> {
    const doc = await getDocumentOrThrow(id);

    const expiryDate = new Date(expiresAt);
    if (isNaN(expiryDate.getTime())) {
      throw new DocumentServiceError('Invalid expiry date', 'INVALID_EXPIRY_DATE');
    }

    if (expiryDate <= new Date()) {
      throw new DocumentServiceError('Expiry date must be in the future', 'EXPIRY_IN_PAST');
    }

    const updated = await documentRepository.update(id, { expiresAt });
    logger?.info?.(`Document expiry set: ${updated.name} -> ${expiresAt}`);
    return updated;
  }

  async function clearExpiry(id: string): Promise<Document> {
    const doc = await getDocumentOrThrow(id);

    if (!doc.expiresAt) {
      return doc;
    }

    const updated = await documentRepository.update(id, { expiresAt: null });
    logger?.info?.(`Document expiry cleared: ${updated.name}`);
    return updated;
  }

  async function getExpiringDocuments(withinDays: number = 30): Promise<Document[]> {
    const allDocs = await documentRepository.list({ status: 'approved' });
    const cutoff = new Date();
    cutoff.setDate(cutoff.getDate() + withinDays);
    const now = new Date();

    return allDocs.filter(doc => {
      if (!doc.expiresAt) return false;
      const expiryDate = new Date(doc.expiresAt);
      return expiryDate > now && expiryDate <= cutoff;
    });
  }

  // ============================================
  // STATISTICS
  // ============================================
  async function getStats(): Promise<DocumentStats> {
    const all = await documentRepository.list();

    const byType: Record<DocumentType, number> = {} as Record<DocumentType, number>;
    DOCUMENT_TYPES.forEach(t => byType[t] = 0);

    const byStatus: Record<DocumentStatus, number> = {} as Record<DocumentStatus, number>;
    DOCUMENT_STATUSES.forEach(s => byStatus[s] = 0);

    let totalSize = 0;
    let pendingApproval = 0;
    let expiringThisMonth = 0;

    const now = new Date();
    const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);

    for (const doc of all) {
      byType[doc.type]++;
      byStatus[doc.status]++;
      totalSize += doc.size;

      if (doc.status === 'pending') {
        pendingApproval++;
      }

      if (doc.expiresAt) {
        const expiryDate = new Date(doc.expiresAt);
        if (expiryDate > now && expiryDate <= endOfMonth) {
          expiringThisMonth++;
        }
      }
    }

    return {
      total: all.length,
      byType,
      byStatus,
      totalSize,
      pendingApproval,
      expiringThisMonth,
    };
  }

  // ============================================
  // SEARCH
  // ============================================
  async function searchDocuments(query: string): Promise<Document[]> {
    if (!query || query.trim().length < 2) {
      throw new DocumentServiceError(
        'Search query must be at least 2 characters',
        'QUERY_TOO_SHORT'
      );
    }

    return documentRepository.list({ search: query.trim() });
  }

  async function getDocumentsByTags(tags: string[]): Promise<Document[]> {
    if (!tags || tags.length === 0) {
      throw new DocumentServiceError('At least one tag is required', 'NO_TAGS');
    }

    return documentRepository.list({ tags });
  }

  // ============================================
  // UTILITY METHODS
  // ============================================
  function getDocumentTypes(): DocumentType[] {
    return [...DOCUMENT_TYPES];
  }

  function getDocumentStatuses(): DocumentStatus[] {
    return [...DOCUMENT_STATUSES];
  }

  function getVisibilityOptions(): DocumentVisibility[] {
    return [...DOCUMENT_VISIBILITIES];
  }

  function formatFileSize(bytes: number): string {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  }

  return {
    // Document management
    uploadDocument,
    getDocument,
    getDocumentByPath,
