      }
      return template;
    },

    async getSiteSettings(): Promise<SiteSettings> {
      return { ...settings };
    },

    addTemplate(template: EmailTemplate): void {
      templates.set(template.template_name, template);
    },

    setSettings(newSettings: Partial<SiteSettings>): void {
