// ============================================
// MOCK EMAIL TRANSPORTER FOR TESTING
// ============================================

export interface SentEmail {
  from: string;
  to: string;
  subject: string;
  html: string;
  text?: string;
  attachments?: EmailAttachment[];
  messageId: string;
  sentAt: Date;
}

export function createMockEmailTransporter(): EmailTransporter & {
  getSentEmails: () => SentEmail[];
  getLastEmail: () => SentEmail | undefined;
  clear: () => void;
  setShouldFail: (shouldFail: boolean) => void;
} {
  const sentEmails: SentEmail[] = [];
  let shouldFail = false;
  let messageCounter = 1;

  return {
    async sendMail(options): Promise<{ messageId: string }> {
      if (shouldFail) {
        throw new Error('Failed to send email');
      }

      const messageId = `test-message-${messageCounter++}`;
      sentEmails.push({
        from: options.from,
        to: options.to,
        subject: options.subject,
        html: options.html,
        text: options.text,
        attachments: options.attachments,
        messageId,
        sentAt: new Date(),
      });

      return { messageId };
    },

    getSentEmails(): SentEmail[] {
      return [...sentEmails];
    },

    getLastEmail(): SentEmail | undefined {
      return sentEmails[sentEmails.length - 1];
    },

    clear(): void {
      sentEmails.length = 0;
      messageCounter = 1;
    },

    setShouldFail(value: boolean): void {
      shouldFail = value;
    },
  };
}

/**
 * Event Service
 *
 * Business logic for venue and event management with DI.
 */

import { v4 as uuidv4 } from 'uuid';
import type {
  Container,
  EventRepository,
  Venue,
  Event,
  EventType,
  EventStatus,
  VenueStatus,
  VenueFilters,
  EventFilters,
  LoggerService,
} from '../container/types.js';

// ============================================
// TYPES
// ============================================

export interface CreateVenueInput {
  name: string;
  description: string;
  capacity: number;
  indoorCapacity?: number;
  outdoorCapacity?: number;
  amenities?: string[];
  hourlyRate: number;
  dailyRate?: number;
  currency?: string;
  location: string;
  images?: string[];
}

export interface UpdateVenueInput {
