  description?: string;
  capacity?: number;
  indoorCapacity?: number;
  outdoorCapacity?: number;
  amenities?: string[];
  hourlyRate?: number;
  dailyRate?: number;
  location?: string;
  images?: string[];
}

export interface CreateEventInput {
  name: string;
  description: string;
  eventType: EventType;
  venueId: string;
  organizerId: string;
  startTime: string;
  endTime: string;
