  getVenueStatuses(): VenueStatus[];
}

// ============================================
// ERROR CLASS
// ============================================

export class EventServiceError extends Error {
  constructor(
    message: string,
    public code: string,
    public statusCode: number = 400
  ) {
    super(message);
    this.name = 'EventServiceError';
  }
}

// ============================================
// CONSTANTS
// ============================================

const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const EVENT_TYPES: EventType[] = ['wedding', 'conference', 'party', 'meeting', 'gala', 'concert', 'other'];
const EVENT_STATUSES: EventStatus[] = ['draft', 'scheduled', 'confirmed', 'in_progress', 'completed', 'cancelled'];
const VENUE_STATUSES: VenueStatus[] = ['available', 'maintenance', 'reserved', 'closed'];
const SUPPORTED_CURRENCIES = ['USD', 'EUR', 'GBP', 'AED', 'SAR'];

// ============================================
// FACTORY
// ============================================

export function createEventService(container: Container): EventService {
  const repository: EventRepository = container.eventRepository;
  const logger: LoggerService = container.logger;

  // ============================================
  // VALIDATION HELPERS
  // ============================================

  function validateUUID(id: string, field: string): void {
    if (!UUID_REGEX.test(id)) {
      throw new EventServiceError(`Invalid ${field} format`, `INVALID_${field.toUpperCase()}_ID`);
    }
  }

  function validateVenueName(name: string): void {
    if (!name || name.trim().length < 2) {
      throw new EventServiceError('Venue name must be at least 2 characters', 'INVALID_VENUE_NAME');
    }
  }

  function validateEventName(name: string): void {
    if (!name || name.trim().length < 2) {
      throw new EventServiceError('Event name must be at least 2 characters', 'INVALID_EVENT_NAME');
    }
  }

  function validateDescription(description: string): void {
    if (!description || description.trim().length === 0) {
      throw new EventServiceError('Description is required', 'INVALID_DESCRIPTION');
    }
  }

  function validateCapacity(capacity: number): void {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new EventServiceError('Capacity must be a positive integer', 'INVALID_CAPACITY');
    }
  }

  function validateHourlyRate(rate: number): void {
    if (typeof rate !== 'number' || rate < 0) {
      throw new EventServiceError('Hourly rate must be non-negative', 'INVALID_HOURLY_RATE');
    }
  }

  function validateEventType(type: EventType): void {
    if (!EVENT_TYPES.includes(type)) {
      throw new EventServiceError(`Invalid event type: ${type}`, 'INVALID_EVENT_TYPE');
    }
  }

  function validateDateRange(startTime: string, endTime: string): void {
    const start = new Date(startTime);
    const end = new Date(endTime);
    
    if (isNaN(start.getTime())) {
      throw new EventServiceError('Invalid start time', 'INVALID_START_TIME');
    }
    
    if (isNaN(end.getTime())) {
      throw new EventServiceError('Invalid end time', 'INVALID_END_TIME');
    }
    
    if (end <= start) {
      throw new EventServiceError('End time must be after start time', 'INVALID_TIME_RANGE');
    }
  }

  function validateExpectedGuests(count: number): void {
    if (!Number.isInteger(count) || count < 1) {
      throw new EventServiceError('Expected guests must be a positive integer', 'INVALID_GUEST_COUNT');
    }
  }

  // ============================================
  // VENUE OPERATIONS
  // ============================================

  async function createVenue(input: CreateVenueInput): Promise<Venue> {
    validateVenueName(input.name);
    validateDescription(input.description);
    validateCapacity(input.capacity);
    validateHourlyRate(input.hourlyRate);

    if (input.currency && !SUPPORTED_CURRENCIES.includes(input.currency)) {
      throw new EventServiceError(`Unsupported currency: ${input.currency}`, 'INVALID_CURRENCY');
    }

    const venue = await repository.createVenue({
      name: input.name.trim(),
      description: input.description.trim(),
      capacity: input.capacity,
      indoorCapacity: input.indoorCapacity ?? input.capacity,
      outdoorCapacity: input.outdoorCapacity ?? 0,
      amenities: input.amenities ?? [],
      hourlyRate: input.hourlyRate,
      dailyRate: input.dailyRate ?? input.hourlyRate * 8,
      currency: input.currency ?? 'USD',
      status: 'available',
      images: input.images ?? [],
      location: input.location.trim(),
    });

    logger.info('Venue created', { venueId: venue.id, name: venue.name });
    return venue;
  }

  async function getVenue(id: string): Promise<Venue | null> {
    validateUUID(id, 'venue');
    return repository.getVenueById(id);
  }

  async function updateVenue(id: string, input: UpdateVenueInput): Promise<Venue> {
    validateUUID(id, 'venue');

    const venue = await repository.getVenueById(id);
    if (!venue) {
      throw new EventServiceError('Venue not found', 'VENUE_NOT_FOUND', 404);
    }

    if (input.name !== undefined) {
      validateVenueName(input.name);
    }

    if (input.capacity !== undefined) {
      validateCapacity(input.capacity);
    }

    if (input.hourlyRate !== undefined) {
      validateHourlyRate(input.hourlyRate);
    }

    const updated = await repository.updateVenue(id, {
      ...(input.name && { name: input.name.trim() }),
      ...(input.description && { description: input.description.trim() }),
      ...(input.capacity !== undefined && { capacity: input.capacity }),
      ...(input.indoorCapacity !== undefined && { indoorCapacity: input.indoorCapacity }),
      ...(input.outdoorCapacity !== undefined && { outdoorCapacity: input.outdoorCapacity }),
      ...(input.amenities && { amenities: input.amenities }),
      ...(input.hourlyRate !== undefined && { hourlyRate: input.hourlyRate }),
      ...(input.dailyRate !== undefined && { dailyRate: input.dailyRate }),
      ...(input.location && { location: input.location.trim() }),
      ...(input.images && { images: input.images }),
    });

    logger.info('Venue updated', { venueId: id });
    return updated;
  }

  async function deleteVenue(id: string): Promise<void> {
    validateUUID(id, 'venue');

    const venue = await repository.getVenueById(id);
    if (!venue) {
      throw new EventServiceError('Venue not found', 'VENUE_NOT_FOUND', 404);
    }

    // Check for upcoming events
    const now = new Date().toISOString();
    const futureEvents = await repository.getEventsByVenue(id, now.split('T')[0], '2099-12-31');
    const activeEvents = futureEvents.filter(e => !['completed', 'cancelled'].includes(e.status));
    
    if (activeEvents.length > 0) {
      throw new EventServiceError(
        'Cannot delete venue with active events',
        'VENUE_HAS_ACTIVE_EVENTS'
      );
    }

    await repository.deleteVenue(id);
    logger.info('Venue deleted', { venueId: id });
  }

  async function listVenues(filters?: VenueFilters): Promise<Venue[]> {
    return repository.listVenues(filters);
  }

  async function setVenueStatus(id: string, status: VenueStatus): Promise<Venue> {
    validateUUID(id, 'venue');

    if (!VENUE_STATUSES.includes(status)) {
      throw new EventServiceError(`Invalid venue status: ${status}`, 'INVALID_VENUE_STATUS');
    }

    const venue = await repository.getVenueById(id);
    if (!venue) {
      throw new EventServiceError('Venue not found', 'VENUE_NOT_FOUND', 404);
    }

    const updated = await repository.updateVenue(id, { status });
    logger.info('Venue status updated', { venueId: id, status });
    return updated;
  }

  async function checkVenueAvailability(
    venueId: string,
    startTime: string,
    endTime: string
  ): Promise<boolean> {
    validateUUID(venueId, 'venue');
    validateDateRange(startTime, endTime);

    const venue = await repository.getVenueById(venueId);
    if (!venue) {
      throw new EventServiceError('Venue not found', 'VENUE_NOT_FOUND', 404);
    }

    if (venue.status !== 'available') {
      return false;
    }

    const startDate = startTime.split('T')[0];
    const endDate = endTime.split('T')[0];
    const existingEvents = await repository.getEventsByVenue(venueId, startDate, endDate);

    // Check for overlapping events
    const requestStart = new Date(startTime).getTime();
    const requestEnd = new Date(endTime).getTime();

    for (const event of existingEvents) {
      if (['cancelled', 'completed'].includes(event.status)) continue;

      const eventStart = new Date(event.startTime).getTime();
      const eventEnd = new Date(event.endTime).getTime();

      // Check if times overlap
      if (requestStart < eventEnd && requestEnd > eventStart) {
        return false;
      }
    }

    return true;
  }

  // ============================================
  // EVENT OPERATIONS
  // ============================================

  async function createEvent(input: CreateEventInput): Promise<Event> {
    validateEventName(input.name);
    validateDescription(input.description);
    validateEventType(input.eventType);
    validateUUID(input.venueId, 'venue');
    validateUUID(input.organizerId, 'organizer');
    validateDateRange(input.startTime, input.endTime);
    validateExpectedGuests(input.expectedGuests);

    // Check venue exists
    const venue = await repository.getVenueById(input.venueId);
    if (!venue) {
      throw new EventServiceError('Venue not found', 'VENUE_NOT_FOUND', 404);
    }

    // Check capacity
    if (input.expectedGuests > venue.capacity) {
      throw new EventServiceError(
        `Expected guests (${input.expectedGuests}) exceeds venue capacity (${venue.capacity})`,
        'EXCEEDS_CAPACITY'
      );
    }

    // Check availability
    const isAvailable = await checkVenueAvailability(input.venueId, input.startTime, input.endTime);
    if (!isAvailable) {
      throw new EventServiceError('Venue is not available for the requested time', 'VENUE_UNAVAILABLE');
    }

    const event = await repository.createEvent({
      name: input.name.trim(),
      description: input.description.trim(),
      eventType: input.eventType,
      venueId: input.venueId,
      organizerId: input.organizerId,
      startTime: input.startTime,
      endTime: input.endTime,
      expectedGuests: input.expectedGuests,
      actualGuests: null,
      status: 'scheduled',
      budget: input.budget ?? null,
      actualCost: null,
      notes: input.notes?.trim() ?? null,
      requirements: input.requirements ?? [],
    });

    logger.info('Event created', { eventId: event.id, name: event.name, venueId: event.venueId });
    return event;
  }

  async function getEvent(id: string): Promise<Event | null> {
    validateUUID(id, 'event');
    return repository.getEventById(id);
  }

  async function updateEvent(id: string, input: UpdateEventInput): Promise<Event> {
    validateUUID(id, 'event');

    const event = await repository.getEventById(id);
    if (!event) {
      throw new EventServiceError('Event not found', 'EVENT_NOT_FOUND', 404);
    }

    if (['completed', 'cancelled'].includes(event.status)) {
      throw new EventServiceError('Cannot update completed or cancelled event', 'EVENT_FINALIZED');
    }

    if (input.name !== undefined) {
      validateEventName(input.name);
    }

    if (input.expectedGuests !== undefined) {
      validateExpectedGuests(input.expectedGuests);
      
      // Check venue capacity
      const venue = await repository.getVenueById(event.venueId);
      if (venue && input.expectedGuests > venue.capacity) {
        throw new EventServiceError(
          `Expected guests (${input.expectedGuests}) exceeds venue capacity (${venue.capacity})`,
          'EXCEEDS_CAPACITY'
        );
      }
    }

    const updated = await repository.updateEvent(id, {
      ...(input.name && { name: input.name.trim() }),
      ...(input.description && { description: input.description.trim() }),
      ...(input.expectedGuests !== undefined && { expectedGuests: input.expectedGuests }),
      ...(input.actualGuests !== undefined && { actualGuests: input.actualGuests }),
      ...(input.budget !== undefined && { budget: input.budget }),
      ...(input.actualCost !== undefined && { actualCost: input.actualCost }),
      ...(input.notes !== undefined && { notes: input.notes?.trim() ?? null }),
      ...(input.requirements && { requirements: input.requirements }),
    });

    logger.info('Event updated', { eventId: id });
    return updated;
  }

  async function cancelEvent(id: string, reason?: string): Promise<Event> {
    validateUUID(id, 'event');

    const event = await repository.getEventById(id);
    if (!event) {
      throw new EventServiceError('Event not found', 'EVENT_NOT_FOUND', 404);
    }

    if (event.status === 'cancelled') {
      throw new EventServiceError('Event is already cancelled', 'ALREADY_CANCELLED');
    }

    if (event.status === 'completed') {
      throw new EventServiceError('Cannot cancel completed event', 'EVENT_COMPLETED');
    }

    const notes = reason
      ? (event.notes ? `${event.notes}\n\nCancellation: ${reason}` : `Cancellation: ${reason}`)
      : event.notes;

    const updated = await repository.updateEvent(id, {
      status: 'cancelled',
      notes,
    });

    logger.info('Event cancelled', { eventId: id, reason });
    return updated;
  }

  async function startEvent(id: string): Promise<Event> {
    validateUUID(id, 'event');

    const event = await repository.getEventById(id);
    if (!event) {
      throw new EventServiceError('Event not found', 'EVENT_NOT_FOUND', 404);
    }

    if (!['scheduled', 'confirmed'].includes(event.status)) {
      throw new EventServiceError(
        `Cannot start event with status: ${event.status}`,
        'INVALID_STATUS_TRANSITION'
      );
    }

    const updated = await repository.updateEvent(id, {
      status: 'in_progress',
    });

    logger.info('Event started', { eventId: id });
    return updated;
  }

  async function completeEvent(
    id: string,
    actualGuests?: number,
    actualCost?: number
  ): Promise<Event> {
    validateUUID(id, 'event');

    const event = await repository.getEventById(id);
    if (!event) {
      throw new EventServiceError('Event not found', 'EVENT_NOT_FOUND', 404);
    }

    if (event.status !== 'in_progress') {
      throw new EventServiceError(
        'Only in-progress events can be completed',
        'INVALID_STATUS_TRANSITION'
      );
    }

    const updated = await repository.updateEvent(id, {
      status: 'completed',
      actualGuests: actualGuests ?? event.actualGuests,
      actualCost: actualCost ?? event.actualCost,
    });

    logger.info('Event completed', { eventId: id, actualGuests, actualCost });
    return updated;
  }

  async function listEvents(filters?: EventFilters): Promise<Event[]> {
    return repository.listEvents(filters);
  }

  async function getUpcomingEvents(venueId?: string): Promise<Event[]> {
    const now = new Date().toISOString();
    const events = await repository.listEvents({
      venueId,
      dateRange: { start: now.split('T')[0], end: '2099-12-31' },
    });

    return events
      .filter(e => !['completed', 'cancelled'].includes(e.status))
      .sort((a, b) => new Date(a.startTime).getTime() - new Date(b.startTime).getTime());
  }

  // ============================================
  // UTILITY
  // ============================================

  async function getStats(): Promise<EventStats> {
    const venues = await repository.listVenues();
    const events = await repository.listEvents();

    const byType: Record<EventType, number> = {
      wedding: 0,
      conference: 0,
      party: 0,
      meeting: 0,
      gala: 0,
      concert: 0,
      other: 0,
    };

    const byStatus: Record<EventStatus, number> = {
      draft: 0,
      scheduled: 0,
      confirmed: 0,
      in_progress: 0,
      completed: 0,
      cancelled: 0,
    };

    const venuesByStatus: Record<VenueStatus, number> = {
      available: 0,
      maintenance: 0,
      reserved: 0,
      closed: 0,
    };

    let totalBudget = 0;
    let budgetCount = 0;

    for (const event of events) {
      byType[event.eventType]++;
      byStatus[event.status]++;
      
      if (event.budget !== null) {
        totalBudget += event.budget;
        budgetCount++;
      }
    }

    for (const venue of venues) {
      venuesByStatus[venue.status]++;
    }

    return {
      totalVenues: venues.length,
      totalEvents: events.length,
      byType,
      byStatus,
      venuesByStatus,
      totalCapacity: venues.reduce((sum, v) => sum + v.capacity, 0),
      avgEventBudget: budgetCount > 0 ? totalBudget / budgetCount : 0,
    };
  }

  function getEventTypes(): EventType[] {
    return [...EVENT_TYPES];
  }

  function getEventStatuses(): EventStatus[] {
    return [...EVENT_STATUSES];
  }

  function getVenueStatuses(): VenueStatus[] {
    return [...VENUE_STATUSES];
  }

  return {
    createVenue,
    getVenue,
    updateVenue,
    deleteVenue,
    listVenues,
    setVenueStatus,
    checkVenueAvailability,
    createEvent,
    getEvent,
    updateEvent,
    cancelEvent,
    startEvent,
    completeEvent,
    listEvents,
    getUpcomingEvents,
    getStats,
    getEventTypes,
    getEventStatuses,
    getVenueStatuses,
  };
}

/**
 * Feedback/Survey Service
 *
 * Manages guest feedback, complaints, and satisfaction surveys.
 */

import type {
  Container,
  Feedback,
  SurveyQuestion,
  SurveyResponse,
  FeedbackFilters,
  FeedbackType,
  FeedbackStatus,
  SurveySentiment,
} from '../container/types.js';

// Error handling
export class FeedbackServiceError extends Error {
  constructor(
    message: string,
    public code: string,
    public statusCode: number = 400
  ) {
    super(message);
    this.name = 'FeedbackServiceError';
  }
}

// Input types
export interface SubmitFeedbackInput {
  guestId?: string;
  guestName: string;
  guestEmail: string;
  type: FeedbackType;
  subject: string;
  message: string;
  rating?: number;
  department?: string;
  metadata?: Record<string, unknown>;
}

export interface RespondToFeedbackInput {
  response: string;
  respondedBy: string;
}

export interface CreateQuestionInput {
  surveyId: string;
  question: string;
  type: 'rating' | 'text' | 'choice' | 'yesno';
  options?: string[];
  required?: boolean;
  order?: number;
}

export interface SubmitResponseInput {
  surveyId: string;
  questionId: string;
  guestId?: string;
  answer: string;
  ratingValue?: number;
}

export interface FeedbackStats {
  totalFeedback: number;
  avgRating: number;
  byType: Record<FeedbackType, number>;
  byStatus: Record<FeedbackStatus, number>;
  bySentiment: Record<SurveySentiment, number>;
  responseRate: number;
  avgResponseTimeHours: number;
}

// Validation helpers
const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const FEEDBACK_TYPES: FeedbackType[] = ['general', 'service', 'food', 'room', 'facilities', 'staff', 'complaint'];
const FEEDBACK_STATUSES: FeedbackStatus[] = ['pending', 'reviewed', 'responded', 'resolved', 'archived'];
const SENTIMENTS: SurveySentiment[] = ['very_positive', 'positive', 'neutral', 'negative', 'very_negative'];
const QUESTION_TYPES = ['rating', 'text', 'choice', 'yesno'] as const;

export interface FeedbackService {
  // Feedback operations
  submitFeedback(input: SubmitFeedbackInput): Promise<Feedback>;
  getFeedback(id: string): Promise<Feedback | null>;
  updateFeedback(id: string, data: Partial<Feedback>): Promise<Feedback>;
  deleteFeedback(id: string): Promise<void>;
  listFeedback(filters?: FeedbackFilters): Promise<Feedback[]>;
  getGuestFeedback(guestId: string): Promise<Feedback[]>;
  
  // Status workflow
  markAsReviewed(id: string): Promise<Feedback>;
  respondToFeedback(id: string, input: RespondToFeedbackInput): Promise<Feedback>;
  resolveFeedback(id: string): Promise<Feedback>;
  archiveFeedback(id: string): Promise<Feedback>;
  
  // Assignment
  assignFeedback(id: string, assignedTo: string): Promise<Feedback>;
  unassignFeedback(id: string): Promise<Feedback>;
  
  // Sentiment analysis
  analyzeSentiment(id: string): Promise<Feedback>;
  
  // Survey questions
  createQuestion(input: CreateQuestionInput): Promise<SurveyQuestion>;
  updateQuestion(id: string, data: Partial<SurveyQuestion>): Promise<SurveyQuestion>;
  deleteQuestion(id: string): Promise<void>;
  getSurveyQuestions(surveyId: string): Promise<SurveyQuestion[]>;
  
  // Survey responses
  submitResponse(input: SubmitResponseInput): Promise<SurveyResponse>;
  getSurveyResponses(surveyId: string): Promise<SurveyResponse[]>;
  
  // Analytics
  getStats(): Promise<FeedbackStats>;
  getPendingFeedback(): Promise<Feedback[]>;
  getUrgentComplaints(): Promise<Feedback[]>;
  
  // Utilities
  getFeedbackTypes(): FeedbackType[];
  getFeedbackStatuses(): FeedbackStatus[];
  getSentiments(): SurveySentiment[];
}

export function createFeedbackService(container: Container): FeedbackService {
  const { feedbackRepository, logger } = container;

  // ============================================
  // FEEDBACK OPERATIONS
  // ============================================
  async function submitFeedback(input: SubmitFeedbackInput): Promise<Feedback> {
    // Validate guest name
    if (!input.guestName || input.guestName.trim().length === 0) {
      throw new FeedbackServiceError('Guest name is required', 'INVALID_GUEST_NAME');
    }

    // Validate email
    if (!input.guestEmail || !input.guestEmail.includes('@')) {
      throw new FeedbackServiceError('Valid email is required', 'INVALID_EMAIL');
    }

    // Validate type
    if (!FEEDBACK_TYPES.includes(input.type)) {
      throw new FeedbackServiceError('Invalid feedback type', 'INVALID_TYPE');
    }

    // Validate subject
    if (!input.subject || input.subject.trim().length === 0) {
      throw new FeedbackServiceError('Subject is required', 'INVALID_SUBJECT');
    }

    // Validate message
    if (!input.message || input.message.trim().length < 10) {
      throw new FeedbackServiceError('Message must be at least 10 characters', 'INVALID_MESSAGE');
    }

    // Validate rating if provided
    if (input.rating !== undefined && (input.rating < 1 || input.rating > 5)) {
      throw new FeedbackServiceError('Rating must be between 1 and 5', 'INVALID_RATING');
    }

    // Validate guest ID if provided
    if (input.guestId && !UUID_REGEX.test(input.guestId)) {
      throw new FeedbackServiceError('Invalid guest ID format', 'INVALID_GUEST_ID');
    }

    const feedback = await feedbackRepository.create({
      guestId: input.guestId || null,
      guestName: input.guestName.trim(),
      guestEmail: input.guestEmail.toLowerCase().trim(),
      type: input.type,
      status: 'pending',
      subject: input.subject.trim(),
      message: input.message.trim(),
      rating: input.rating ?? null,
      sentiment: null,
      department: input.department || null,
      assignedTo: null,
      response: null,
      respondedAt: null,
      respondedBy: null,
      metadata: input.metadata || {},
    });

    logger?.info?.(`Feedback submitted: ${feedback.type} from ${feedback.guestEmail}`);
    return feedback;
  }

  async function getFeedback(id: string): Promise<Feedback | null> {
    if (!UUID_REGEX.test(id)) {
      throw new FeedbackServiceError('Invalid feedback ID format', 'INVALID_FEEDBACK_ID');
    }
    return feedbackRepository.getById(id);
  }

  async function updateFeedback(id: string, data: Partial<Feedback>): Promise<Feedback> {
    const feedback = await getFeedbackOrThrow(id);
    return feedbackRepository.update(id, data);
  }

  async function deleteFeedback(id: string): Promise<void> {
    await getFeedbackOrThrow(id);
    await feedbackRepository.delete(id);
  }

  async function listFeedback(filters?: FeedbackFilters): Promise<Feedback[]> {
    return feedbackRepository.list(filters);
  }

  async function getGuestFeedback(guestId: string): Promise<Feedback[]> {
    if (!UUID_REGEX.test(guestId)) {
      throw new FeedbackServiceError('Invalid guest ID format', 'INVALID_GUEST_ID');
    }
    return feedbackRepository.getByGuest(guestId);
  }

  // ============================================
  // STATUS WORKFLOW
  // ============================================
  async function markAsReviewed(id: string): Promise<Feedback> {
    const feedback = await getFeedbackOrThrow(id);

    if (feedback.status !== 'pending') {
      throw new FeedbackServiceError('Feedback is not pending', 'INVALID_STATUS');
    }

    return feedbackRepository.update(id, { status: 'reviewed' });
  }

  async function respondToFeedback(id: string, input: RespondToFeedbackInput): Promise<Feedback> {
    const feedback = await getFeedbackOrThrow(id);

    if (feedback.status === 'archived') {
      throw new FeedbackServiceError('Cannot respond to archived feedback', 'INVALID_STATUS');
    }

    if (!input.response || input.response.trim().length === 0) {
      throw new FeedbackServiceError('Response is required', 'INVALID_RESPONSE');
    }

    if (!UUID_REGEX.test(input.respondedBy)) {
      throw new FeedbackServiceError('Invalid responder ID format', 'INVALID_RESPONDER_ID');
    }

    return feedbackRepository.update(id, {
      status: 'responded',
      response: input.response.trim(),
      respondedAt: new Date().toISOString(),
      respondedBy: input.respondedBy,
    });
  }

  async function resolveFeedback(id: string): Promise<Feedback> {
    const feedback = await getFeedbackOrThrow(id);

    if (feedback.status === 'pending') {
      throw new FeedbackServiceError('Feedback must be reviewed or responded first', 'INVALID_STATUS');
    }

    if (feedback.status === 'resolved' || feedback.status === 'archived') {
      throw new FeedbackServiceError('Feedback is already resolved or archived', 'INVALID_STATUS');
    }

    return feedbackRepository.update(id, { status: 'resolved' });
  }

  async function archiveFeedback(id: string): Promise<Feedback> {
    const feedback = await getFeedbackOrThrow(id);

    if (feedback.status === 'archived') {
      throw new FeedbackServiceError('Feedback is already archived', 'ALREADY_ARCHIVED');
    }

    return feedbackRepository.update(id, { status: 'archived' });
  }

  // ============================================
  // ASSIGNMENT
  // ============================================
  async function assignFeedback(id: string, assignedTo: string): Promise<Feedback> {
    await getFeedbackOrThrow(id);

    if (!UUID_REGEX.test(assignedTo)) {
      throw new FeedbackServiceError('Invalid assignee ID format', 'INVALID_ASSIGNEE_ID');
    }

    return feedbackRepository.update(id, { assignedTo });
  }

  async function unassignFeedback(id: string): Promise<Feedback> {
    const feedback = await getFeedbackOrThrow(id);

    if (!feedback.assignedTo) {
      throw new FeedbackServiceError('Feedback is not assigned', 'NOT_ASSIGNED');
    }

    return feedbackRepository.update(id, { assignedTo: null });
  }

  // ============================================
  // SENTIMENT ANALYSIS
  // ============================================
  async function analyzeSentiment(id: string): Promise<Feedback> {
    const feedback = await getFeedbackOrThrow(id);

    // Simple sentiment analysis based on rating and keywords
    let sentiment: SurveySentiment;

    if (feedback.rating !== null) {
      if (feedback.rating >= 5) sentiment = 'very_positive';
      else if (feedback.rating >= 4) sentiment = 'positive';
      else if (feedback.rating >= 3) sentiment = 'neutral';
      else if (feedback.rating >= 2) sentiment = 'negative';
      else sentiment = 'very_negative';
    } else {
      // Basic keyword analysis
      const message = feedback.message.toLowerCase();
      const positiveWords = ['great', 'excellent', 'amazing', 'wonderful', 'perfect', 'love', 'best'];
      const negativeWords = ['terrible', 'awful', 'horrible', 'worst', 'hate', 'disgusting', 'unacceptable'];

      const positiveCount = positiveWords.filter(w => message.includes(w)).length;
      const negativeCount = negativeWords.filter(w => message.includes(w)).length;

      if (positiveCount > negativeCount + 1) sentiment = 'very_positive';
      else if (positiveCount > negativeCount) sentiment = 'positive';
      else if (negativeCount > positiveCount + 1) sentiment = 'very_negative';
      else if (negativeCount > positiveCount) sentiment = 'negative';
      else sentiment = 'neutral';
    }

    return feedbackRepository.update(id, { sentiment });
  }

  // ============================================
  // SURVEY QUESTIONS
  // ============================================
  async function createQuestion(input: CreateQuestionInput): Promise<SurveyQuestion> {
    if (!UUID_REGEX.test(input.surveyId)) {
      throw new FeedbackServiceError('Invalid survey ID format', 'INVALID_SURVEY_ID');
    }

    if (!input.question || input.question.trim().length === 0) {
      throw new FeedbackServiceError('Question text is required', 'INVALID_QUESTION');
    }

    if (!QUESTION_TYPES.includes(input.type)) {
      throw new FeedbackServiceError('Invalid question type', 'INVALID_QUESTION_TYPE');
    }

    if (input.type === 'choice' && (!input.options || input.options.length < 2)) {
      throw new FeedbackServiceError('Choice questions must have at least 2 options', 'INVALID_OPTIONS');
    }

    return feedbackRepository.createQuestion({
      surveyId: input.surveyId,
      question: input.question.trim(),
      type: input.type,
      options: input.options || null,
      required: input.required ?? true,
      order: input.order ?? 0,
    });
  }

  async function updateQuestion(id: string, data: Partial<SurveyQuestion>): Promise<SurveyQuestion> {
    if (!UUID_REGEX.test(id)) {
      throw new FeedbackServiceError('Invalid question ID format', 'INVALID_QUESTION_ID');
    }

    const question = await feedbackRepository.getQuestionById(id);
    if (!question) {
      throw new FeedbackServiceError('Question not found', 'QUESTION_NOT_FOUND', 404);
    }

    return feedbackRepository.updateQuestion(id, data);
  }

  async function deleteQuestion(id: string): Promise<void> {
    if (!UUID_REGEX.test(id)) {
      throw new FeedbackServiceError('Invalid question ID format', 'INVALID_QUESTION_ID');
    }

    const question = await feedbackRepository.getQuestionById(id);
    if (!question) {
      throw new FeedbackServiceError('Question not found', 'QUESTION_NOT_FOUND', 404);
    }

    await feedbackRepository.deleteQuestion(id);
  }

  async function getSurveyQuestions(surveyId: string): Promise<SurveyQuestion[]> {
    if (!UUID_REGEX.test(surveyId)) {
      throw new FeedbackServiceError('Invalid survey ID format', 'INVALID_SURVEY_ID');
    }
    return feedbackRepository.getQuestionsForSurvey(surveyId);
  }

  // ============================================
  // SURVEY RESPONSES
  // ============================================
  async function submitResponse(input: SubmitResponseInput): Promise<SurveyResponse> {
    if (!UUID_REGEX.test(input.surveyId)) {
      throw new FeedbackServiceError('Invalid survey ID format', 'INVALID_SURVEY_ID');
    }

    if (!UUID_REGEX.test(input.questionId)) {
      throw new FeedbackServiceError('Invalid question ID format', 'INVALID_QUESTION_ID');
    }

    const question = await feedbackRepository.getQuestionById(input.questionId);
    if (!question) {
      throw new FeedbackServiceError('Question not found', 'QUESTION_NOT_FOUND', 404);
    }

    // Validate answer based on question type
    if (question.required && (!input.answer || input.answer.trim().length === 0)) {
      throw new FeedbackServiceError('Answer is required', 'INVALID_ANSWER');
    }

    if (question.type === 'rating') {
      if (input.ratingValue === undefined || input.ratingValue < 1 || input.ratingValue > 5) {
        throw new FeedbackServiceError('Rating must be between 1 and 5', 'INVALID_RATING');
      }
    }

    if (question.type === 'yesno' && !['yes', 'no'].includes(input.answer.toLowerCase())) {
      throw new FeedbackServiceError('Answer must be yes or no', 'INVALID_ANSWER');
    }

    if (question.type === 'choice' && question.options && !question.options.includes(input.answer)) {
      throw new FeedbackServiceError('Answer must be one of the provided options', 'INVALID_ANSWER');
    }

    return feedbackRepository.createResponse({
      surveyId: input.surveyId,
      questionId: input.questionId,
      guestId: input.guestId || null,
      answer: input.answer.trim(),
      ratingValue: input.ratingValue ?? null,
      submittedAt: new Date().toISOString(),
    });
  }

  async function getSurveyResponses(surveyId: string): Promise<SurveyResponse[]> {
    if (!UUID_REGEX.test(surveyId)) {
      throw new FeedbackServiceError('Invalid survey ID format', 'INVALID_SURVEY_ID');
    }
    return feedbackRepository.getResponsesForSurvey(surveyId);
  }

  // ============================================
  // ANALYTICS
  // ============================================
  async function getStats(): Promise<FeedbackStats> {
    const feedbacks = await feedbackRepository.list();

    const byType: Record<FeedbackType, number> = {
      general: 0,
      service: 0,
      food: 0,
      room: 0,
      facilities: 0,
      staff: 0,
      complaint: 0,
    };

    const byStatus: Record<FeedbackStatus, number> = {
      pending: 0,
      reviewed: 0,
      responded: 0,
      resolved: 0,
      archived: 0,
    };

    const bySentiment: Record<SurveySentiment, number> = {
      very_positive: 0,
      positive: 0,
      neutral: 0,
      negative: 0,
      very_negative: 0,
    };

    let totalRating = 0;
    let ratingCount = 0;
    let respondedCount = 0;
    let totalResponseTime = 0;

    for (const feedback of feedbacks) {
      byType[feedback.type]++;
      byStatus[feedback.status]++;

      if (feedback.sentiment) {
        bySentiment[feedback.sentiment]++;
      }

      if (feedback.rating !== null) {
        totalRating += feedback.rating;
        ratingCount++;
      }

      if (feedback.respondedAt) {
        respondedCount++;
        const created = new Date(feedback.createdAt).getTime();
        const responded = new Date(feedback.respondedAt).getTime();
        totalResponseTime += (responded - created) / (1000 * 60 * 60); // hours
      }
    }

    return {
      totalFeedback: feedbacks.length,
      avgRating: ratingCount > 0 ? Math.round((totalRating / ratingCount) * 10) / 10 : 0,
      byType,
      byStatus,
      bySentiment,
      responseRate: feedbacks.length > 0 ? Math.round((respondedCount / feedbacks.length) * 100) : 0,
      avgResponseTimeHours: respondedCount > 0 ? Math.round((totalResponseTime / respondedCount) * 10) / 10 : 0,
    };
  }

  async function getPendingFeedback(): Promise<Feedback[]> {
    return feedbackRepository.list({ status: 'pending' });
  }

  async function getUrgentComplaints(): Promise<Feedback[]> {
    const feedbacks = await feedbackRepository.list({ type: 'complaint', status: 'pending' });
    // Sort by creation date (oldest first)
    return feedbacks.sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());
  }

  // ============================================
  // UTILITIES
  // ============================================
  function getFeedbackTypes(): FeedbackType[] {
    return [...FEEDBACK_TYPES];
  }

  function getFeedbackStatuses(): FeedbackStatus[] {
    return [...FEEDBACK_STATUSES];
  }

  function getSentiments(): SurveySentiment[] {
    return [...SENTIMENTS];
  }

  // Helper
  async function getFeedbackOrThrow(id: string): Promise<Feedback> {
    if (!UUID_REGEX.test(id)) {
      throw new FeedbackServiceError('Invalid feedback ID format', 'INVALID_FEEDBACK_ID');
    }

    const feedback = await feedbackRepository.getById(id);
    if (!feedback) {
      throw new FeedbackServiceError('Feedback not found', 'FEEDBACK_NOT_FOUND', 404);
    }

    return feedback;
  }

  return {
    submitFeedback,
    getFeedback,
    updateFeedback,
    deleteFeedback,
    listFeedback,
    getGuestFeedback,
    markAsReviewed,
    respondToFeedback,
    resolveFeedback,
    archiveFeedback,
    assignFeedback,
    unassignFeedback,
    analyzeSentiment,
    createQuestion,
    updateQuestion,
    deleteQuestion,
    getSurveyQuestions,
    submitResponse,
    getSurveyResponses,
    getStats,
    getPendingFeedback,
    getUrgentComplaints,
    getFeedbackTypes,
    getFeedbackStatuses,
    getSentiments,
  };
}

/**
 * Gift Card Service
 * 
 * Provides gift card management including purchase, redemption,
 * balance checking, and transaction history.
 */

import type { 
  Container,
  GiftCardRepository,
  GiftCard,
  GiftCardTransaction,
  GiftCardStatus,
} from '../container/types';

// ============================================
// TYPES
// ============================================

export interface PurchaseGiftCardInput {
  amount: number;
  currency?: string;
  purchasedBy: string;
  purchasedFor?: string;
  recipientEmail?: string;
  recipientName?: string;
  message?: string;
  expiresIn?: number; // days
}

export interface RedeemGiftCardInput {
  code: string;
  amount: number;
  reference?: string;
  description?: string;
  redeemedBy: string;
}

export interface RefundGiftCardInput {
  giftCardId: string;
  amount: number;
  reason?: string;
  refundedBy: string;
}

export interface AdjustBalanceInput {
  giftCardId: string;
  amount: number;
  reason: string;
  adjustedBy: string;
}

export interface GiftCardServiceResult<T> {
  success: boolean;
  data?: T;
  error?: string;
}

// ============================================
// VALIDATION
// ============================================

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const GIFT_CARD_STATUSES: GiftCardStatus[] = ['active', 'redeemed', 'expired', 'cancelled', 'suspended'];

function isValidUUID(id: string): boolean {
  return UUID_PATTERN.test(id);
}

function isValidEmail(email: string): boolean {
  return EMAIL_PATTERN.test(email);
}

function generateGiftCardCode(): string {
  // Generate a 16-character alphanumeric code in groups of 4
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let code = '';
  for (let i = 0; i < 16; i++) {
    if (i > 0 && i % 4 === 0) code += '-';
    code += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return code;
}

// ============================================
// SERVICE FACTORY
// ============================================

export function createGiftCardService(container: Container) {
  const { giftCardRepository } = container;

  // ============================================
  // GIFT CARD OPERATIONS
  // ============================================

  async function purchaseGiftCard(input: PurchaseGiftCardInput): Promise<GiftCardServiceResult<GiftCard>> {
    // Validate amount
    if (typeof input.amount !== 'number' || input.amount <= 0) {
      return { success: false, error: 'Amount must be a positive number' };
    }

    // Validate minimum/maximum amounts
    if (input.amount < 10) {
      return { success: false, error: 'Minimum gift card amount is 10' };
    }

    if (input.amount > 10000) {
      return { success: false, error: 'Maximum gift card amount is 10000' };
    }

    // Validate purchaser
    if (!input.purchasedBy || !isValidUUID(input.purchasedBy)) {
      return { success: false, error: 'Invalid purchaser ID' };
    }

    // Validate recipient email if provided
    if (input.recipientEmail && !isValidEmail(input.recipientEmail)) {
      return { success: false, error: 'Invalid recipient email' };
    }

    // Calculate expiry (default 1 year)
    const expiresIn = input.expiresIn ?? 365;
    if (expiresIn <= 0) {
      return { success: false, error: 'Expiration days must be positive' };
    }

    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + expiresIn);

    // Generate unique code
    let code: string;
    let attempts = 0;
    do {
      code = generateGiftCardCode();
      const existing = await giftCardRepository.getByCode(code);
      if (!existing) break;
      attempts++;
    } while (attempts < 10);

    if (attempts >= 10) {
      return { success: false, error: 'Failed to generate unique code' };
    }

    const giftCard = await giftCardRepository.create({
      code,
      initialBalance: input.amount,
      currentBalance: input.amount,
      currency: input.currency || 'USD',
      status: 'active',
      purchasedBy: input.purchasedBy,
      purchasedFor: input.purchasedFor,
      recipientEmail: input.recipientEmail,
      recipientName: input.recipientName,
      message: input.message,
      expiresAt: expiresAt.toISOString(),
      activatedAt: new Date().toISOString(),
      redeemedAt: null,
    });

    // Log purchase transaction
    await giftCardRepository.logTransaction({
      giftCardId: giftCard.id,
      type: 'purchase',
      amount: input.amount,
      balanceBefore: 0,
      balanceAfter: input.amount,
      description: 'Gift card purchased',
      createdBy: input.purchasedBy,
    });

    return { success: true, data: giftCard };
  }

  async function getGiftCard(id: string): Promise<GiftCardServiceResult<GiftCard>> {
    if (!isValidUUID(id)) {
      return { success: false, error: 'Invalid gift card ID' };
    }

    const giftCard = await giftCardRepository.getById(id);
    
    if (!giftCard) {
      return { success: false, error: 'Gift card not found' };
    }

    return { success: true, data: giftCard };
  }

  async function getGiftCardByCode(code: string): Promise<GiftCardServiceResult<GiftCard>> {
    if (!code || code.trim() === '') {
      return { success: false, error: 'Gift card code is required' };
    }

    const giftCard = await giftCardRepository.getByCode(code.toUpperCase());
    
    if (!giftCard) {
      return { success: false, error: 'Gift card not found' };
    }

    return { success: true, data: giftCard };
  }

  async function checkBalance(code: string): Promise<GiftCardServiceResult<{ balance: number; currency: string; status: GiftCardStatus }>> {
    if (!code || code.trim() === '') {
      return { success: false, error: 'Gift card code is required' };
    }

    const giftCard = await giftCardRepository.getByCode(code.toUpperCase());
    
    if (!giftCard) {
      return { success: false, error: 'Gift card not found' };
    }

    return { 
      success: true, 
      data: { 
        balance: giftCard.currentBalance, 
        currency: giftCard.currency,
        status: giftCard.status,
      } 
    };
  }

  async function redeemGiftCard(input: RedeemGiftCardInput): Promise<GiftCardServiceResult<{ giftCard: GiftCard; transaction: GiftCardTransaction }>> {
    // Validate code
    if (!input.code || input.code.trim() === '') {
      return { success: false, error: 'Gift card code is required' };
    }

    // Validate amount
    if (typeof input.amount !== 'number' || input.amount <= 0) {
      return { success: false, error: 'Redemption amount must be positive' };
    }

    // Validate redeemer
    if (!input.redeemedBy || !isValidUUID(input.redeemedBy)) {
      return { success: false, error: 'Invalid redeemer ID' };
    }

    // Get gift card
    const giftCard = await giftCardRepository.getByCode(input.code.toUpperCase());
    
    if (!giftCard) {
      return { success: false, error: 'Gift card not found' };
    }

    // Check status
    if (giftCard.status !== 'active') {
      return { success: false, error: `Gift card is ${giftCard.status}` };
    }

    // Check expiry
    if (new Date(giftCard.expiresAt) < new Date()) {
      // Update status to expired
      await giftCardRepository.update(giftCard.id, { status: 'expired' });
      return { success: false, error: 'Gift card has expired' };
    }

    // Check balance
    if (input.amount > giftCard.currentBalance) {
      return { success: false, error: `Insufficient balance. Available: ${giftCard.currentBalance}` };
    }

    const balanceBefore = giftCard.currentBalance;
    const balanceAfter = balanceBefore - input.amount;
    const isFullyRedeemed = balanceAfter === 0;

    // Update gift card
    const updatedCard = await giftCardRepository.update(giftCard.id, {
      currentBalance: balanceAfter,
      status: isFullyRedeemed ? 'redeemed' : 'active',
      redeemedAt: isFullyRedeemed ? new Date().toISOString() : giftCard.redeemedAt,
    });

    // Log transaction
    const transaction = await giftCardRepository.logTransaction({
      giftCardId: giftCard.id,
      type: 'redemption',
      amount: input.amount,
      balanceBefore,
      balanceAfter,
      reference: input.reference,
      description: input.description || 'Gift card redemption',
      createdBy: input.redeemedBy,
    });

    return { success: true, data: { giftCard: updatedCard, transaction } };
  }

  async function refundToGiftCard(input: RefundGiftCardInput): Promise<GiftCardServiceResult<{ giftCard: GiftCard; transaction: GiftCardTransaction }>> {
    // Validate gift card ID
    if (!isValidUUID(input.giftCardId)) {
      return { success: false, error: 'Invalid gift card ID' };
    }

    // Validate amount
    if (typeof input.amount !== 'number' || input.amount <= 0) {
      return { success: false, error: 'Refund amount must be positive' };
    }

    // Validate refunder
    if (!input.refundedBy || !isValidUUID(input.refundedBy)) {
      return { success: false, error: 'Invalid refunder ID' };
    }

    // Get gift card
    const giftCard = await giftCardRepository.getById(input.giftCardId);
    
    if (!giftCard) {
      return { success: false, error: 'Gift card not found' };
    }

    // Cannot refund to cancelled card
    if (giftCard.status === 'cancelled') {
      return { success: false, error: 'Cannot refund to cancelled gift card' };
    }

    // Cannot exceed initial balance
    if (giftCard.currentBalance + input.amount > giftCard.initialBalance) {
      return { success: false, error: 'Refund would exceed initial balance' };
    }

    const balanceBefore = giftCard.currentBalance;
    const balanceAfter = balanceBefore + input.amount;

    // Update gift card
    const updatedCard = await giftCardRepository.update(giftCard.id, {
      currentBalance: balanceAfter,
      status: 'active', // Reactivate if was redeemed
    });

    // Log transaction
    const transaction = await giftCardRepository.logTransaction({
      giftCardId: giftCard.id,
      type: 'refund',
      amount: input.amount,
      balanceBefore,
      balanceAfter,
      description: input.reason || 'Refund to gift card',
      createdBy: input.refundedBy,
    });

    return { success: true, data: { giftCard: updatedCard, transaction } };
  }

  async function adjustBalance(input: AdjustBalanceInput): Promise<GiftCardServiceResult<{ giftCard: GiftCard; transaction: GiftCardTransaction }>> {
    // Validate gift card ID
    if (!isValidUUID(input.giftCardId)) {
      return { success: false, error: 'Invalid gift card ID' };
    }

    // Validate amount (can be negative for deductions)
    if (typeof input.amount !== 'number' || input.amount === 0) {
      return { success: false, error: 'Adjustment amount cannot be zero' };
    }

    // Validate reason
    if (!input.reason || input.reason.trim() === '') {
      return { success: false, error: 'Reason is required for adjustments' };
    }

    // Validate adjuster
    if (!input.adjustedBy || !isValidUUID(input.adjustedBy)) {
      return { success: false, error: 'Invalid adjuster ID' };
    }

    // Get gift card
    const giftCard = await giftCardRepository.getById(input.giftCardId);
    
    if (!giftCard) {
      return { success: false, error: 'Gift card not found' };
    }

    // Check result would be valid
    const newBalance = giftCard.currentBalance + input.amount;
    if (newBalance < 0) {
      return { success: false, error: 'Adjustment would result in negative balance' };
    }

    const balanceBefore = giftCard.currentBalance;
    const balanceAfter = newBalance;

    // Update gift card
    const updatedCard = await giftCardRepository.update(giftCard.id, {
      currentBalance: balanceAfter,
      status: balanceAfter === 0 ? 'redeemed' : 'active',
    });

    // Log transaction
    const transaction = await giftCardRepository.logTransaction({
      giftCardId: giftCard.id,
      type: 'adjustment',
      amount: Math.abs(input.amount),
      balanceBefore,
      balanceAfter,
      description: `${input.amount > 0 ? 'Credit' : 'Debit'}: ${input.reason}`,
      createdBy: input.adjustedBy,
    });

    return { success: true, data: { giftCard: updatedCard, transaction } };
  }

  async function cancelGiftCard(id: string, cancelledBy: string): Promise<GiftCardServiceResult<GiftCard>> {
    if (!isValidUUID(id)) {
      return { success: false, error: 'Invalid gift card ID' };
    }

    if (!isValidUUID(cancelledBy)) {
      return { success: false, error: 'Invalid canceller ID' };
    }

    const giftCard = await giftCardRepository.getById(id);
    
    if (!giftCard) {
      return { success: false, error: 'Gift card not found' };
    }

    if (giftCard.status === 'cancelled') {
      return { success: false, error: 'Gift card is already cancelled' };
    }

    if (giftCard.status === 'redeemed') {
      return { success: false, error: 'Cannot cancel fully redeemed gift card' };
    }

    const updated = await giftCardRepository.update(id, { status: 'cancelled' });

    // Log the cancellation
    await giftCardRepository.logTransaction({
      giftCardId: id,
      type: 'adjustment',
      amount: 0,
      balanceBefore: giftCard.currentBalance,
      balanceAfter: giftCard.currentBalance,
      description: 'Gift card cancelled',
      createdBy: cancelledBy,
    });

    return { success: true, data: updated };
  }

  async function suspendGiftCard(id: string, suspendedBy: string): Promise<GiftCardServiceResult<GiftCard>> {
    if (!isValidUUID(id)) {
      return { success: false, error: 'Invalid gift card ID' };
    }

    if (!isValidUUID(suspendedBy)) {
      return { success: false, error: 'Invalid suspender ID' };
    }

    const giftCard = await giftCardRepository.getById(id);
    
    if (!giftCard) {
      return { success: false, error: 'Gift card not found' };
    }

    if (giftCard.status !== 'active') {
      return { success: false, error: `Cannot suspend ${giftCard.status} gift card` };
    }

    const updated = await giftCardRepository.update(id, { status: 'suspended' });

    return { success: true, data: updated };
  }

  async function reactivateGiftCard(id: string, reactivatedBy: string): Promise<GiftCardServiceResult<GiftCard>> {
    if (!isValidUUID(id)) {
      return { success: false, error: 'Invalid gift card ID' };
    }

    if (!isValidUUID(reactivatedBy)) {
      return { success: false, error: 'Invalid reactivator ID' };
    }

    const giftCard = await giftCardRepository.getById(id);
    
    if (!giftCard) {
      return { success: false, error: 'Gift card not found' };
    }

    if (giftCard.status !== 'suspended') {
      return { success: false, error: 'Only suspended gift cards can be reactivated' };
    }

    // Check if expired
    if (new Date(giftCard.expiresAt) < new Date()) {
      return { success: false, error: 'Cannot reactivate expired gift card' };
    }

    const updated = await giftCardRepository.update(id, { status: 'active' });

    return { success: true, data: updated };
  }

  async function extendExpiry(id: string, additionalDays: number, extendedBy: string): Promise<GiftCardServiceResult<GiftCard>> {
    if (!isValidUUID(id)) {
      return { success: false, error: 'Invalid gift card ID' };
    }

    if (!isValidUUID(extendedBy)) {
      return { success: false, error: 'Invalid extender ID' };
    }

    if (typeof additionalDays !== 'number' || additionalDays <= 0) {
      return { success: false, error: 'Additional days must be positive' };
    }

    const giftCard = await giftCardRepository.getById(id);
    
    if (!giftCard) {
      return { success: false, error: 'Gift card not found' };
    }

    if (giftCard.status === 'cancelled' || giftCard.status === 'redeemed') {
      return { success: false, error: `Cannot extend ${giftCard.status} gift card` };
    }

    const currentExpiry = new Date(giftCard.expiresAt);
    const newExpiry = new Date(Math.max(currentExpiry.getTime(), Date.now()));
    newExpiry.setDate(newExpiry.getDate() + additionalDays);

    // Also reactivate if expired
    const updated = await giftCardRepository.update(id, { 
      expiresAt: newExpiry.toISOString(),
      status: giftCard.status === 'expired' ? 'active' : giftCard.status,
    });

    return { success: true, data: updated };
  }

  // ============================================
  // QUERY OPERATIONS
  // ============================================

  async function getByPurchaser(purchaserId: string): Promise<GiftCardServiceResult<GiftCard[]>> {
    if (!isValidUUID(purchaserId)) {
      return { success: false, error: 'Invalid purchaser ID' };
    }

    const cards = await giftCardRepository.getByPurchaser(purchaserId);
    return { success: true, data: cards };
  }

  async function getByRecipient(recipientEmail: string): Promise<GiftCardServiceResult<GiftCard[]>> {
    if (!isValidEmail(recipientEmail)) {
      return { success: false, error: 'Invalid email address' };
    }

    const cards = await giftCardRepository.getByRecipient(recipientEmail);
    return { success: true, data: cards };
  }

  async function getExpiringCards(withinDays: number = 30): Promise<GiftCardServiceResult<GiftCard[]>> {
    if (withinDays <= 0) {
      return { success: false, error: 'Days must be positive' };
    }

    const beforeDate = new Date();
    beforeDate.setDate(beforeDate.getDate() + withinDays);
    
    const cards = await giftCardRepository.getExpiring(beforeDate.toISOString());
    return { success: true, data: cards };
  }

  async function getTransactions(giftCardId: string): Promise<GiftCardServiceResult<GiftCardTransaction[]>> {
    if (!isValidUUID(giftCardId)) {
      return { success: false, error: 'Invalid gift card ID' };
    }

    const transactions = await giftCardRepository.getTransactions(giftCardId);
    return { success: true, data: transactions };
  }

  // ============================================
  // UTILITY FUNCTIONS
  // ============================================

  function isExpired(giftCard: GiftCard): boolean {
    return new Date(giftCard.expiresAt) < new Date();
  }

  function isRedeemable(giftCard: GiftCard): boolean {
    return (
      giftCard.status === 'active' &&
      giftCard.currentBalance > 0 &&
      !isExpired(giftCard)
    );
  }

  function getUsagePercentage(giftCard: GiftCard): number {
    if (giftCard.initialBalance === 0) return 0;
    return Math.round((1 - giftCard.currentBalance / giftCard.initialBalance) * 100);
  }

  function formatGiftCardCode(code: string): string {
    // Format as XXXX-XXXX-XXXX-XXXX
    const clean = code.replace(/-/g, '').toUpperCase();
    return clean.match(/.{1,4}/g)?.join('-') || code;
  }

  function maskGiftCardCode(code: string): string {
    // Show only last 4 characters
    const clean = code.replace(/-/g, '');
    const masked = '*'.repeat(clean.length - 4) + clean.slice(-4);
    return masked.match(/.{1,4}/g)?.join('-') || masked;
  }

  function getGiftCardStatuses(): GiftCardStatus[] {
    return [...GIFT_CARD_STATUSES];
  }

  // ============================================
  // RETURN SERVICE
  // ============================================

  return {
    // Gift card operations
    purchaseGiftCard,
    getGiftCard,
    getGiftCardByCode,
    checkBalance,
    redeemGiftCard,
    refundToGiftCard,
    adjustBalance,
    cancelGiftCard,
    suspendGiftCard,
    reactivateGiftCard,
    extendExpiry,
    
    // Query operations
    getByPurchaser,
    getByRecipient,
    getExpiringCards,
    getTransactions,
    
    // Utilities
    isExpired,
    isRedeemable,
    getUsagePercentage,
    formatGiftCardCode,
    maskGiftCardCode,
    getGiftCardStatuses,
  };
}

/**
 * Guest Profile Service
 *
 * Manages guest profiles, preferences, and visit history.
 * Follows DI pattern for testability.
 */

import type { Container, GuestProfile, GuestPreferences, GuestFilters, GuestStatus } from '../container/types.js';

// ============================================
// CONSTANTS
// ============================================

const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const PHONE_REGEX = /^\+?[1-9]\d{6,14}$/;

const GUEST_STATUSES: GuestStatus[] = ['active', 'inactive', 'vip', 'banned'];
const MIN_NAME_LENGTH = 2;
const MAX_NAME_LENGTH = 100;

// ============================================
// TYPES
// ============================================

export interface CreateGuestInput {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  userId?: string;
  dateOfBirth?: string;
  nationality?: string;
  idType?: string;
  idNumber?: string;
  preferences?: GuestPreferences;
  notes?: string;
  tags?: string[];
}

export interface UpdateGuestInput {
  firstName?: string;
  lastName?: string;
  email?: string;
  phone?: string;
  dateOfBirth?: string | null;
  nationality?: string | null;
  idType?: string | null;
  idNumber?: string | null;
  preferences?: Partial<GuestPreferences>;
  notes?: string | null;
  tags?: string[];
}

export interface RecordVisitInput {
  guestId: string;
  amountSpent: number;
}

export interface GuestStats {
  totalGuests: number;
  activeGuests: number;
  vipGuests: number;
  inactiveGuests: number;
  bannedGuests: number;
  totalRevenue: number;
  avgSpentPerGuest: number;
  avgStaysPerGuest: number;
}

export interface GuestService {
  createGuest(input: CreateGuestInput): Promise<GuestProfile>;
  getGuest(id: string): Promise<GuestProfile | null>;
  getGuestByEmail(email: string): Promise<GuestProfile | null>;
  getGuestByPhone(phone: string): Promise<GuestProfile | null>;
  getGuestByUserId(userId: string): Promise<GuestProfile | null>;
  updateGuest(id: string, input: UpdateGuestInput): Promise<GuestProfile>;
  deleteGuest(id: string): Promise<void>;
  setStatus(id: string, status: GuestStatus): Promise<GuestProfile>;
  recordVisit(input: RecordVisitInput): Promise<GuestProfile>;
  addTags(id: string, tags: string[]): Promise<GuestProfile>;
  removeTags(id: string, tags: string[]): Promise<GuestProfile>;
  listGuests(filters?: GuestFilters): Promise<GuestProfile[]>;
  searchGuests(query: string): Promise<GuestProfile[]>;
  getVipGuests(): Promise<GuestProfile[]>;
  getStats(): Promise<GuestStats>;
  getStatuses(): GuestStatus[];
  mergeProfiles(primaryId: string, secondaryId: string): Promise<GuestProfile>;
}

// ============================================
// ERROR CLASS
// ============================================

export class GuestServiceError extends Error {
  constructor(
    message: string,
    public readonly code: string,
    public readonly statusCode: number = 400
  ) {
    super(message);
    this.name = 'GuestServiceError';
  }
}

// ============================================
// VALIDATION HELPERS
// ============================================

function isValidUUID(id: string): boolean {
  return UUID_REGEX.test(id);
}

function isValidEmail(email: string): boolean {
  return EMAIL_REGEX.test(email);
}

function isValidPhone(phone: string): boolean {
  return PHONE_REGEX.test(phone.replace(/[\s\-\(\)]/g, ''));
}

function validateName(name: string, field: string): void {
  if (!name || name.trim().length < MIN_NAME_LENGTH) {
    throw new GuestServiceError(
      `${field} must be at least ${MIN_NAME_LENGTH} characters`,
      `INVALID_${field.toUpperCase()}`
    );
  }
  if (name.length > MAX_NAME_LENGTH) {
    throw new GuestServiceError(
      `${field} cannot exceed ${MAX_NAME_LENGTH} characters`,
      `INVALID_${field.toUpperCase()}`
    );
  }
}

function validateEmail(email: string): void {
  if (!email || !isValidEmail(email)) {
    throw new GuestServiceError('Invalid email format', 'INVALID_EMAIL');
  }
}

function validatePhone(phone: string): void {
  if (!phone || !isValidPhone(phone)) {
    throw new GuestServiceError('Invalid phone format', 'INVALID_PHONE');
  }
}

function validateDateOfBirth(dob: string): void {
  const date = new Date(dob);
  if (isNaN(date.getTime())) {
    throw new GuestServiceError('Invalid date of birth format', 'INVALID_DATE_OF_BIRTH');
  }
  if (date > new Date()) {
    throw new GuestServiceError('Date of birth cannot be in the future', 'INVALID_DATE_OF_BIRTH');
  }
}

// ============================================
// SERVICE FACTORY
// ============================================

export function createGuestService(container: Container): GuestService {
  const { guestRepository, logger } = container;

  async function createGuest(input: CreateGuestInput): Promise<GuestProfile> {
    logger?.info?.('Creating guest profile', { email: input.email });

    // Validate required fields
    validateName(input.firstName, 'first name');
    validateName(input.lastName, 'last name');
    validateEmail(input.email);
    validatePhone(input.phone);

    if (input.userId && !isValidUUID(input.userId)) {
      throw new GuestServiceError('Invalid user ID', 'INVALID_USER_ID');
    }

    if (input.dateOfBirth) {
      validateDateOfBirth(input.dateOfBirth);
    }

    // Check for existing guest with same email
    const existingByEmail = await guestRepository.getByEmail(input.email);
    if (existingByEmail) {
      throw new GuestServiceError('Guest with this email already exists', 'EMAIL_EXISTS');
    }

    // Check for existing guest with same phone
    const existingByPhone = await guestRepository.getByPhone(input.phone);
    if (existingByPhone) {
      throw new GuestServiceError('Guest with this phone already exists', 'PHONE_EXISTS');
    }

    const guest = await guestRepository.create({
      userId: input.userId || null,
      firstName: input.firstName.trim(),
      lastName: input.lastName.trim(),
      email: input.email.toLowerCase().trim(),
      phone: input.phone.replace(/[\s\-\(\)]/g, ''),
      dateOfBirth: input.dateOfBirth || null,
      nationality: input.nationality?.trim() || null,
      idType: input.idType?.trim() || null,
      idNumber: input.idNumber?.trim() || null,
      status: 'active',
      preferences: input.preferences || {},
      notes: input.notes?.trim() || null,
      tags: input.tags || [],
      totalStays: 0,
      totalSpent: 0,
      lastVisit: null,
    });

    return guest;
  }

  async function getGuest(id: string): Promise<GuestProfile | null> {
    if (!isValidUUID(id)) {
      throw new GuestServiceError('Invalid guest ID', 'INVALID_GUEST_ID');
    }

    return guestRepository.getById(id);
  }

  async function getGuestByEmail(email: string): Promise<GuestProfile | null> {
    if (!isValidEmail(email)) {
      throw new GuestServiceError('Invalid email format', 'INVALID_EMAIL');
    }

    return guestRepository.getByEmail(email.toLowerCase().trim());
  }

  async function getGuestByPhone(phone: string): Promise<GuestProfile | null> {
    if (!isValidPhone(phone)) {
      throw new GuestServiceError('Invalid phone format', 'INVALID_PHONE');
    }

    return guestRepository.getByPhone(phone.replace(/[\s\-\(\)]/g, ''));
  }

  async function getGuestByUserId(userId: string): Promise<GuestProfile | null> {
    if (!isValidUUID(userId)) {
      throw new GuestServiceError('Invalid user ID', 'INVALID_USER_ID');
    }

    return guestRepository.getByUserId(userId);
  }

  async function updateGuest(id: string, input: UpdateGuestInput): Promise<GuestProfile> {
    if (!isValidUUID(id)) {
      throw new GuestServiceError('Invalid guest ID', 'INVALID_GUEST_ID');
    }

    const guest = await guestRepository.getById(id);
    if (!guest) {
      throw new GuestServiceError('Guest not found', 'GUEST_NOT_FOUND', 404);
    }

    const updates: Partial<GuestProfile> = {};

    if (input.firstName !== undefined) {
      validateName(input.firstName, 'first name');
      updates.firstName = input.firstName.trim();
    }

    if (input.lastName !== undefined) {
      validateName(input.lastName, 'last name');
      updates.lastName = input.lastName.trim();
    }

    if (input.email !== undefined) {
      validateEmail(input.email);
      const normalizedEmail = input.email.toLowerCase().trim();
      if (normalizedEmail !== guest.email) {
        const existing = await guestRepository.getByEmail(normalizedEmail);
        if (existing) {
          throw new GuestServiceError('Guest with this email already exists', 'EMAIL_EXISTS');
        }
        updates.email = normalizedEmail;
      }
    }

    if (input.phone !== undefined) {
      validatePhone(input.phone);
      const normalizedPhone = input.phone.replace(/[\s\-\(\)]/g, '');
      if (normalizedPhone !== guest.phone) {
        const existing = await guestRepository.getByPhone(normalizedPhone);
        if (existing) {
          throw new GuestServiceError('Guest with this phone already exists', 'PHONE_EXISTS');
        }
        updates.phone = normalizedPhone;
      }
    }

    if (input.dateOfBirth !== undefined) {
      if (input.dateOfBirth !== null) {
        validateDateOfBirth(input.dateOfBirth);
      }
      updates.dateOfBirth = input.dateOfBirth;
    }

    if (input.nationality !== undefined) {
      updates.nationality = input.nationality?.trim() || null;
    }

    if (input.idType !== undefined) {
      updates.idType = input.idType?.trim() || null;
    }

    if (input.idNumber !== undefined) {
      updates.idNumber = input.idNumber?.trim() || null;
    }

    if (input.preferences !== undefined) {
      updates.preferences = { ...guest.preferences, ...input.preferences };
    }

    if (input.notes !== undefined) {
      updates.notes = input.notes?.trim() || null;
    }

    if (input.tags !== undefined) {
      updates.tags = input.tags;
    }

    return guestRepository.update(id, updates);
  }

  async function deleteGuest(id: string): Promise<void> {
    if (!isValidUUID(id)) {
      throw new GuestServiceError('Invalid guest ID', 'INVALID_GUEST_ID');
    }

    const guest = await guestRepository.getById(id);
    if (!guest) {
      throw new GuestServiceError('Guest not found', 'GUEST_NOT_FOUND', 404);
    }

    await guestRepository.delete(id);
  }

  async function setStatus(id: string, status: GuestStatus): Promise<GuestProfile> {
    if (!isValidUUID(id)) {
      throw new GuestServiceError('Invalid guest ID', 'INVALID_GUEST_ID');
    }

    if (!GUEST_STATUSES.includes(status)) {
      throw new GuestServiceError(`Invalid status: ${status}`, 'INVALID_STATUS');
    }

    const guest = await guestRepository.getById(id);
    if (!guest) {
      throw new GuestServiceError('Guest not found', 'GUEST_NOT_FOUND', 404);
    }

    return guestRepository.update(id, { status });
  }

  async function recordVisit(input: RecordVisitInput): Promise<GuestProfile> {
    if (!isValidUUID(input.guestId)) {
      throw new GuestServiceError('Invalid guest ID', 'INVALID_GUEST_ID');
    }

    if (input.amountSpent < 0) {
      throw new GuestServiceError('Amount spent cannot be negative', 'INVALID_AMOUNT');
    }

    const guest = await guestRepository.getById(input.guestId);
    if (!guest) {
      throw new GuestServiceError('Guest not found', 'GUEST_NOT_FOUND', 404);
    }

    return guestRepository.update(input.guestId, {
      totalStays: guest.totalStays + 1,
      totalSpent: guest.totalSpent + input.amountSpent,
      lastVisit: new Date().toISOString(),
    });
  }

  async function addTags(id: string, tags: string[]): Promise<GuestProfile> {
    if (!isValidUUID(id)) {
      throw new GuestServiceError('Invalid guest ID', 'INVALID_GUEST_ID');
    }

    if (!tags || tags.length === 0) {
      throw new GuestServiceError('Tags array is required', 'INVALID_TAGS');
    }

    const guest = await guestRepository.getById(id);
    if (!guest) {
      throw new GuestServiceError('Guest not found', 'GUEST_NOT_FOUND', 404);
    }

    const newTags = [...new Set([...guest.tags, ...tags])];

    return guestRepository.update(id, { tags: newTags });
  }

  async function removeTags(id: string, tags: string[]): Promise<GuestProfile> {
    if (!isValidUUID(id)) {
      throw new GuestServiceError('Invalid guest ID', 'INVALID_GUEST_ID');
    }

    if (!tags || tags.length === 0) {
      throw new GuestServiceError('Tags array is required', 'INVALID_TAGS');
    }

    const guest = await guestRepository.getById(id);
    if (!guest) {
      throw new GuestServiceError('Guest not found', 'GUEST_NOT_FOUND', 404);
    }

    const newTags = guest.tags.filter((t) => !tags.includes(t));

    return guestRepository.update(id, { tags: newTags });
  }

  async function listGuests(filters?: GuestFilters): Promise<GuestProfile[]> {
    return guestRepository.list(filters);
  }

  async function searchGuests(query: string): Promise<GuestProfile[]> {
    if (!query || query.trim().length === 0) {
      return [];
    }

    return guestRepository.search(query.trim());
  }

  async function getVipGuests(): Promise<GuestProfile[]> {
    return guestRepository.list({ status: 'vip' });
  }

  async function getStats(): Promise<GuestStats> {
    const allGuests = await guestRepository.list();

    const stats: GuestStats = {
      totalGuests: allGuests.length,
      activeGuests: 0,
      vipGuests: 0,
      inactiveGuests: 0,
      bannedGuests: 0,
      totalRevenue: 0,
      avgSpentPerGuest: 0,
      avgStaysPerGuest: 0,
    };

    let totalStays = 0;

    for (const guest of allGuests) {
      switch (guest.status) {
        case 'active':
          stats.activeGuests++;
          break;
        case 'vip':
          stats.vipGuests++;
          break;
        case 'inactive':
          stats.inactiveGuests++;
          break;
        case 'banned':
          stats.bannedGuests++;
          break;
      }

      stats.totalRevenue += guest.totalSpent;
      totalStays += guest.totalStays;
    }

    stats.avgSpentPerGuest = allGuests.length > 0
      ? Math.round((stats.totalRevenue / allGuests.length) * 100) / 100
      : 0;

    stats.avgStaysPerGuest = allGuests.length > 0
      ? Math.round((totalStays / allGuests.length) * 100) / 100
      : 0;

    return stats;
  }

  function getStatuses(): GuestStatus[] {
    return [...GUEST_STATUSES];
  }

  async function mergeProfiles(primaryId: string, secondaryId: string): Promise<GuestProfile> {
    if (!isValidUUID(primaryId)) {
      throw new GuestServiceError('Invalid primary guest ID', 'INVALID_GUEST_ID');
    }

    if (!isValidUUID(secondaryId)) {
      throw new GuestServiceError('Invalid secondary guest ID', 'INVALID_GUEST_ID');
    }

    if (primaryId === secondaryId) {
      throw new GuestServiceError('Cannot merge guest with itself', 'SAME_GUEST');
    }

    const primary = await guestRepository.getById(primaryId);
    if (!primary) {
      throw new GuestServiceError('Primary guest not found', 'GUEST_NOT_FOUND', 404);
    }

    const secondary = await guestRepository.getById(secondaryId);
    if (!secondary) {
      throw new GuestServiceError('Secondary guest not found', 'GUEST_NOT_FOUND', 404);
    }

    // Merge data
    const mergedTags = [...new Set([...primary.tags, ...secondary.tags])];
    const mergedNotes = primary.notes && secondary.notes
      ? `${primary.notes}\n---\nMerged from: ${secondary.notes}`
      : primary.notes || secondary.notes;

    const updated = await guestRepository.update(primaryId, {
      totalStays: primary.totalStays + secondary.totalStays,
      totalSpent: primary.totalSpent + secondary.totalSpent,
      tags: mergedTags,
      notes: mergedNotes,
      lastVisit: primary.lastVisit && secondary.lastVisit
        ? new Date(primary.lastVisit) > new Date(secondary.lastVisit)
          ? primary.lastVisit
          : secondary.lastVisit
        : primary.lastVisit || secondary.lastVisit,
    });

    // Delete secondary profile
    await guestRepository.delete(secondaryId);

    return updated;
  }

  return {
    createGuest,
    getGuest,
    getGuestByEmail,
    getGuestByPhone,
    getGuestByUserId,
    updateGuest,
    deleteGuest,
    setStatus,
    recordVisit,
    addTags,
    removeTags,
    listGuests,
    searchGuests,
    getVipGuests,
    getStats,
    getStatuses,
    mergeProfiles,
  };
}

/**
 * Housekeeping Service
 *
 * Business logic for room cleaning and housekeeping with DI.
 */

import { v4 as uuidv4 } from 'uuid';
import type {
  Container,
  HousekeepingRepository,
  RoomCleaningTask,
  CleaningSupply,
  RoomStatus,
  CleaningPriority,
  HousekeepingFilters,
  LoggerService,
} from '../container/types.js';

// ============================================
// TYPES
// ============================================

export interface CreateTaskInput {
  roomId: string;
  roomNumber: string;
  floor: number;
  priority?: CleaningPriority;
  checkoutDate?: string;
  checkinDate?: string;
  notes?: string;
}

export interface UpdateTaskInput {
  priority?: CleaningPriority;
  notes?: string;
  checkoutDate?: string;
  checkinDate?: string;
}

export interface CreateSupplyInput {
  name: string;
  quantity: number;
  minQuantity: number;
  unit: string;
}

export interface UpdateSupplyInput {
  name?: string;
  quantity?: number;
  minQuantity?: number;
  unit?: string;
}

export interface HousekeepingStats {
  totalTasks: number;
  byStatus: Record<RoomStatus, number>;
  byPriority: Record<CleaningPriority, number>;
  byFloor: Record<number, number>;
  avgCleaningTimeMinutes: number;
  lowSuppliesCount: number;
}

export interface HousekeepingService {
  // Task operations
  createTask(input: CreateTaskInput): Promise<RoomCleaningTask>;
  getTask(id: string): Promise<RoomCleaningTask | null>;
  getTaskByRoom(roomId: string): Promise<RoomCleaningTask | null>;
  updateTask(id: string, input: UpdateTaskInput): Promise<RoomCleaningTask>;
  deleteTask(id: string): Promise<void>;
  listTasks(filters?: HousekeepingFilters): Promise<RoomCleaningTask[]>;
  
  // Workflow
  assignTask(id: string, assignedTo: string): Promise<RoomCleaningTask>;
  unassignTask(id: string): Promise<RoomCleaningTask>;
  startCleaning(id: string): Promise<RoomCleaningTask>;
  completeCleaning(id: string): Promise<RoomCleaningTask>;
  inspectRoom(id: string, inspectedBy: string, passed: boolean): Promise<RoomCleaningTask>;
  markOutOfOrder(id: string, reason: string): Promise<RoomCleaningTask>;
  markDirty(roomId: string): Promise<RoomCleaningTask>;
  
  // Supply operations
  createSupply(input: CreateSupplyInput): Promise<CleaningSupply>;
  getSupply(id: string): Promise<CleaningSupply | null>;
  updateSupply(id: string, input: UpdateSupplyInput): Promise<CleaningSupply>;
  deleteSupply(id: string): Promise<void>;
  listSupplies(): Promise<CleaningSupply[]>;
  getLowSupplies(): Promise<CleaningSupply[]>;
  restockSupply(id: string, quantity: number): Promise<CleaningSupply>;
  useSupply(id: string, quantity: number): Promise<CleaningSupply>;
  
  // Reporting
  getByAssignee(assigneeId: string): Promise<RoomCleaningTask[]>;
  getByFloor(floor: number): Promise<RoomCleaningTask[]>;
  getPendingTasks(): Promise<RoomCleaningTask[]>;
  getUrgentTasks(): Promise<RoomCleaningTask[]>;
  getStats(): Promise<HousekeepingStats>;
  
  // Utility
  getRoomStatuses(): RoomStatus[];
  getPriorities(): CleaningPriority[];
}

// ============================================
// ERROR CLASS
// ============================================

export class HousekeepingServiceError extends Error {
  constructor(
    message: string,
    public code: string,
    public statusCode: number = 400
  ) {
    super(message);
    this.name = 'HousekeepingServiceError';
  }
}

// ============================================
// CONSTANTS
// ============================================

const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const ROOM_STATUSES: RoomStatus[] = ['clean', 'dirty', 'in_progress', 'inspected', 'out_of_order'];
const PRIORITIES: CleaningPriority[] = ['low', 'medium', 'high', 'urgent'];

// ============================================
// FACTORY
// ============================================

export function createHousekeepingService(container: Container): HousekeepingService {
  const repository: HousekeepingRepository = container.housekeepingRepository;
  const logger: LoggerService = container.logger;

  // ============================================
  // VALIDATION HELPERS
  // ============================================

  function validateUUID(id: string, field: string): void {
    if (!UUID_REGEX.test(id)) {
      throw new HousekeepingServiceError(`Invalid ${field} format`, `INVALID_${field.toUpperCase()}_ID`);
    }
  }

  function validateRoomNumber(roomNumber: string): void {
    if (!roomNumber || roomNumber.trim().length === 0) {
      throw new HousekeepingServiceError('Room number is required', 'INVALID_ROOM_NUMBER');
    }
  }

  function validateFloor(floor: number): void {
    if (!Number.isInteger(floor) || floor < 0) {
      throw new HousekeepingServiceError('Floor must be a non-negative integer', 'INVALID_FLOOR');
    }
  }

  function validatePriority(priority: CleaningPriority): void {
    if (!PRIORITIES.includes(priority)) {
      throw new HousekeepingServiceError(`Invalid priority: ${priority}`, 'INVALID_PRIORITY');
    }
  }

  function validateQuantity(quantity: number, fieldName: string): void {
    if (!Number.isInteger(quantity) || quantity < 0) {
      throw new HousekeepingServiceError(`${fieldName} must be a non-negative integer`, 'INVALID_QUANTITY');
    }
  }

  // ============================================
  // TASK OPERATIONS
  // ============================================

  async function createTask(input: CreateTaskInput): Promise<RoomCleaningTask> {
    validateUUID(input.roomId, 'room');
    validateRoomNumber(input.roomNumber);
    validateFloor(input.floor);

    if (input.priority !== undefined) {
      validatePriority(input.priority);
    }

    // Check if task already exists for this room
    const existing = await repository.getTaskByRoomId(input.roomId);
    if (existing && !['clean', 'inspected'].includes(existing.status)) {
      throw new HousekeepingServiceError('Active task already exists for this room', 'TASK_ALREADY_EXISTS');
    }

    const task = await repository.createTask({
      roomId: input.roomId,
      roomNumber: input.roomNumber.trim(),
      floor: input.floor,
      assignedTo: null,
      status: 'dirty',
      priority: input.priority ?? 'medium',
      checkoutDate: input.checkoutDate ?? null,
      checkinDate: input.checkinDate ?? null,
      notes: input.notes?.trim() ?? null,
      startedAt: null,
      completedAt: null,
      inspectedBy: null,
      inspectedAt: null,
    });

    logger.info('Cleaning task created', { taskId: task.id, roomNumber: task.roomNumber });
    return task;
  }

  async function getTask(id: string): Promise<RoomCleaningTask | null> {
    validateUUID(id, 'task');
    return repository.getTaskById(id);
  }

  async function getTaskByRoom(roomId: string): Promise<RoomCleaningTask | null> {
    validateUUID(roomId, 'room');
    return repository.getTaskByRoomId(roomId);
  }

  async function updateTask(id: string, input: UpdateTaskInput): Promise<RoomCleaningTask> {
    validateUUID(id, 'task');

    const task = await repository.getTaskById(id);
    if (!task) {
      throw new HousekeepingServiceError('Task not found', 'TASK_NOT_FOUND', 404);
    }

    if (input.priority !== undefined) {
      validatePriority(input.priority);
    }

    const updated = await repository.updateTask(id, {
      ...(input.priority && { priority: input.priority }),
      ...(input.notes !== undefined && { notes: input.notes?.trim() ?? null }),
      ...(input.checkoutDate !== undefined && { checkoutDate: input.checkoutDate }),
      ...(input.checkinDate !== undefined && { checkinDate: input.checkinDate }),
    });

    logger.info('Task updated', { taskId: id });
    return updated;
  }

  async function deleteTask(id: string): Promise<void> {
    validateUUID(id, 'task');

    const task = await repository.getTaskById(id);
    if (!task) {
      throw new HousekeepingServiceError('Task not found', 'TASK_NOT_FOUND', 404);
    }

    await repository.deleteTask(id);
    logger.info('Task deleted', { taskId: id });
  }

  async function listTasks(filters?: HousekeepingFilters): Promise<RoomCleaningTask[]> {
    return repository.listTasks(filters);
  }

  // ============================================
  // WORKFLOW
  // ============================================

  async function assignTask(id: string, assignedTo: string): Promise<RoomCleaningTask> {
    validateUUID(id, 'task');
    validateUUID(assignedTo, 'assignee');

    const task = await repository.getTaskById(id);
    if (!task) {
      throw new HousekeepingServiceError('Task not found', 'TASK_NOT_FOUND', 404);
    }

    if (!['dirty', 'in_progress'].includes(task.status)) {
      throw new HousekeepingServiceError(
        `Cannot assign task with status: ${task.status}`,
        'INVALID_STATUS_TRANSITION'
      );
    }

    const updated = await repository.updateTask(id, { assignedTo });
    logger.info('Task assigned', { taskId: id, assignedTo });
    return updated;
  }

  async function unassignTask(id: string): Promise<RoomCleaningTask> {
    validateUUID(id, 'task');

    const task = await repository.getTaskById(id);
    if (!task) {
      throw new HousekeepingServiceError('Task not found', 'TASK_NOT_FOUND', 404);
    }

    if (!task.assignedTo) {
      throw new HousekeepingServiceError('Task is not assigned', 'NOT_ASSIGNED');
    }

    if (task.status === 'in_progress') {
      throw new HousekeepingServiceError('Cannot unassign in-progress task', 'TASK_IN_PROGRESS');
    }

    const updated = await repository.updateTask(id, { assignedTo: null });
    logger.info('Task unassigned', { taskId: id });
    return updated;
  }

  async function startCleaning(id: string): Promise<RoomCleaningTask> {
    validateUUID(id, 'task');

    const task = await repository.getTaskById(id);
    if (!task) {
      throw new HousekeepingServiceError('Task not found', 'TASK_NOT_FOUND', 404);
    }

    if (task.status !== 'dirty') {
      throw new HousekeepingServiceError(
        `Cannot start cleaning for status: ${task.status}`,
        'INVALID_STATUS_TRANSITION'
      );
    }

    const updated = await repository.updateTask(id, {
      status: 'in_progress',
      startedAt: new Date().toISOString(),
    });

    logger.info('Cleaning started', { taskId: id, roomNumber: task.roomNumber });
    return updated;
  }

  async function completeCleaning(id: string): Promise<RoomCleaningTask> {
    validateUUID(id, 'task');

    const task = await repository.getTaskById(id);
    if (!task) {
      throw new HousekeepingServiceError('Task not found', 'TASK_NOT_FOUND', 404);
    }

    if (task.status !== 'in_progress') {
      throw new HousekeepingServiceError(
        'Only in-progress tasks can be completed',
        'INVALID_STATUS_TRANSITION'
      );
    }

    const updated = await repository.updateTask(id, {
      status: 'clean',
      completedAt: new Date().toISOString(),
    });

    logger.info('Cleaning completed', { taskId: id, roomNumber: task.roomNumber });
    return updated;
  }

  async function inspectRoom(id: string, inspectedBy: string, passed: boolean): Promise<RoomCleaningTask> {
    validateUUID(id, 'task');
    validateUUID(inspectedBy, 'inspector');

    const task = await repository.getTaskById(id);
    if (!task) {
      throw new HousekeepingServiceError('Task not found', 'TASK_NOT_FOUND', 404);
    }

    if (task.status !== 'clean') {
      throw new HousekeepingServiceError(
        'Only clean rooms can be inspected',
        'INVALID_STATUS_TRANSITION'
      );
    }

    const updated = await repository.updateTask(id, {
      status: passed ? 'inspected' : 'dirty',
      inspectedBy,
      inspectedAt: new Date().toISOString(),
      startedAt: passed ? task.startedAt : null,
      completedAt: passed ? task.completedAt : null,
    });

    logger.info('Room inspected', { taskId: id, passed });
    return updated;
  }

  async function markOutOfOrder(id: string, reason: string): Promise<RoomCleaningTask> {
    validateUUID(id, 'task');

    const task = await repository.getTaskById(id);
    if (!task) {
      throw new HousekeepingServiceError('Task not found', 'TASK_NOT_FOUND', 404);
    }

    const notes = reason
      ? (task.notes ? `${task.notes}\n\nOut of order: ${reason}` : `Out of order: ${reason}`)
      : task.notes;

    const updated = await repository.updateTask(id, {
      status: 'out_of_order',
      notes,
    });

    logger.info('Room marked out of order', { taskId: id, reason });
    return updated;
  }

  async function markDirty(roomId: string): Promise<RoomCleaningTask> {
    validateUUID(roomId, 'room');

    const existing = await repository.getTaskByRoomId(roomId);
    if (!existing) {
      throw new HousekeepingServiceError('No task found for this room', 'TASK_NOT_FOUND', 404);
    }

    const updated = await repository.updateTask(existing.id, {
      status: 'dirty',
      startedAt: null,
      completedAt: null,
      inspectedBy: null,
      inspectedAt: null,
    });

    logger.info('Room marked dirty', { roomId, taskId: existing.id });
    return updated;
  }

  // ============================================
  // SUPPLY OPERATIONS
  // ============================================

  async function createSupply(input: CreateSupplyInput): Promise<CleaningSupply> {
    if (!input.name || input.name.trim().length === 0) {
      throw new HousekeepingServiceError('Supply name is required', 'INVALID_SUPPLY_NAME');
    }

    validateQuantity(input.quantity, 'Quantity');
    validateQuantity(input.minQuantity, 'Minimum quantity');

    if (!input.unit || input.unit.trim().length === 0) {
      throw new HousekeepingServiceError('Unit is required', 'INVALID_UNIT');
    }

    const supply = await repository.createSupply({
      name: input.name.trim(),
      quantity: input.quantity,
      minQuantity: input.minQuantity,
      unit: input.unit.trim(),
      lastRestocked: null,
    });

    logger.info('Supply created', { supplyId: supply.id, name: supply.name });
    return supply;
  }

  async function getSupply(id: string): Promise<CleaningSupply | null> {
    validateUUID(id, 'supply');
    return repository.getSupplyById(id);
  }

  async function updateSupply(id: string, input: UpdateSupplyInput): Promise<CleaningSupply> {
    validateUUID(id, 'supply');

    const supply = await repository.getSupplyById(id);
    if (!supply) {
      throw new HousekeepingServiceError('Supply not found', 'SUPPLY_NOT_FOUND', 404);
    }

    if (input.quantity !== undefined) {
      validateQuantity(input.quantity, 'Quantity');
    }

    if (input.minQuantity !== undefined) {
      validateQuantity(input.minQuantity, 'Minimum quantity');
    }

    const updated = await repository.updateSupply(id, {
      ...(input.name && { name: input.name.trim() }),
      ...(input.quantity !== undefined && { quantity: input.quantity }),
      ...(input.minQuantity !== undefined && { minQuantity: input.minQuantity }),
      ...(input.unit && { unit: input.unit.trim() }),
    });

    logger.info('Supply updated', { supplyId: id });
    return updated;
  }

  async function deleteSupply(id: string): Promise<void> {
    validateUUID(id, 'supply');

    const supply = await repository.getSupplyById(id);
    if (!supply) {
      throw new HousekeepingServiceError('Supply not found', 'SUPPLY_NOT_FOUND', 404);
    }

    await repository.deleteSupply(id);
    logger.info('Supply deleted', { supplyId: id });
  }

  async function listSupplies(): Promise<CleaningSupply[]> {
    return repository.listSupplies();
  }

  async function getLowSupplies(): Promise<CleaningSupply[]> {
    return repository.getLowSupplies();
  }

  async function restockSupply(id: string, quantity: number): Promise<CleaningSupply> {
    validateUUID(id, 'supply');

    if (!Number.isInteger(quantity) || quantity < 1) {
      throw new HousekeepingServiceError('Restock quantity must be a positive integer', 'INVALID_QUANTITY');
    }

    const supply = await repository.getSupplyById(id);
    if (!supply) {
      throw new HousekeepingServiceError('Supply not found', 'SUPPLY_NOT_FOUND', 404);
    }

    const updated = await repository.updateSupply(id, {
      quantity: supply.quantity + quantity,
      lastRestocked: new Date().toISOString(),
    });

    logger.info('Supply restocked', { supplyId: id, quantity, newTotal: updated.quantity });
    return updated;
  }

  async function useSupply(id: string, quantity: number): Promise<CleaningSupply> {
    validateUUID(id, 'supply');

    if (!Number.isInteger(quantity) || quantity < 1) {
      throw new HousekeepingServiceError('Usage quantity must be a positive integer', 'INVALID_QUANTITY');
    }

    const supply = await repository.getSupplyById(id);
    if (!supply) {
      throw new HousekeepingServiceError('Supply not found', 'SUPPLY_NOT_FOUND', 404);
    }

    if (supply.quantity < quantity) {
      throw new HousekeepingServiceError('Insufficient supply quantity', 'INSUFFICIENT_QUANTITY');
    }

    const updated = await repository.updateSupply(id, {
      quantity: supply.quantity - quantity,
    });

    logger.info('Supply used', { supplyId: id, quantity, remaining: updated.quantity });
    return updated;
  }

  // ============================================
  // REPORTING
  // ============================================

  async function getByAssignee(assigneeId: string): Promise<RoomCleaningTask[]> {
    validateUUID(assigneeId, 'assignee');
    return repository.getTasksByAssignee(assigneeId);
  }

  async function getByFloor(floor: number): Promise<RoomCleaningTask[]> {
    validateFloor(floor);
    return repository.getTasksByFloor(floor);
  }

  async function getPendingTasks(): Promise<RoomCleaningTask[]> {
    const allTasks = await repository.listTasks();
    return allTasks.filter(t => ['dirty', 'in_progress'].includes(t.status));
  }

  async function getUrgentTasks(): Promise<RoomCleaningTask[]> {
    const allTasks = await repository.listTasks({ priority: 'urgent' });
    return allTasks.filter(t => !['clean', 'inspected'].includes(t.status));
  }

  async function getStats(): Promise<HousekeepingStats> {
    const tasks = await repository.listTasks();
    const lowSupplies = await repository.getLowSupplies();

    const byStatus: Record<RoomStatus, number> = {
      clean: 0,
      dirty: 0,
      in_progress: 0,
      inspected: 0,
      out_of_order: 0,
    };

    const byPriority: Record<CleaningPriority, number> = {
      low: 0,
      medium: 0,
      high: 0,
      urgent: 0,
    };

    const byFloor: Record<number, number> = {};

    let totalCleaningTime = 0;
    let completedCount = 0;

    for (const task of tasks) {
      byStatus[task.status]++;
      byPriority[task.priority]++;
      byFloor[task.floor] = (byFloor[task.floor] || 0) + 1;

      if (task.startedAt && task.completedAt) {
        const start = new Date(task.startedAt).getTime();
        const end = new Date(task.completedAt).getTime();
        totalCleaningTime += (end - start) / 60000; // minutes
        completedCount++;
      }
    }

    return {
      totalTasks: tasks.length,
      byStatus,
      byPriority,
      byFloor,
      avgCleaningTimeMinutes: completedCount > 0 ? totalCleaningTime / completedCount : 0,
      lowSuppliesCount: lowSupplies.length,
    };
  }

  // ============================================
  // UTILITY
  // ============================================

  function getRoomStatuses(): RoomStatus[] {
    return [...ROOM_STATUSES];
  }

  function getPriorities(): CleaningPriority[] {
    return [...PRIORITIES];
  }

  return {
    createTask,
    getTask,
    getTaskByRoom,
    updateTask,
    deleteTask,
    listTasks,
    assignTask,
    unassignTask,
    startCleaning,
    completeCleaning,
    inspectRoom,
    markOutOfOrder,
    markDirty,
    createSupply,
    getSupply,
    updateSupply,
    deleteSupply,
    listSupplies,
    getLowSupplies,
    restockSupply,
    useSupply,
    getByAssignee,
    getByFloor,
    getPendingTasks,
    getUrgentTasks,
    getStats,
    getRoomStatuses,
    getPriorities,
  };
}

import { 
  Container, 
  Invoice, 
  InvoiceStatus,
  InvoiceLineItem,
  InvoicePayment,
  InvoicePaymentMethod
} from '../container/types';

export interface CreateInvoiceInput {
  guestId: string;
  guestName: string;
  guestEmail: string;
  reservationId?: string;
  dueDate: string;
  notes?: string;
  currency?: string;
  createdBy: string;
}

export interface AddLineItemInput {
  description: string;
  quantity: number;
  unitPrice: number;
  discount?: number;
  taxRate?: number;
}

export interface RecordPaymentInput {
  invoiceId: string;
  amount: number;
  paymentMethod: InvoicePaymentMethod;
  reference?: string;
  processedBy: string;
}

export interface InvoiceService {
  // CRUD Operations
  createInvoice(input: CreateInvoiceInput): Promise<Invoice>;
  getInvoice(id: string): Promise<Invoice | null>;
  getInvoiceByNumber(invoiceNumber: string): Promise<Invoice | null>;
  getInvoices(): Promise<Invoice[]>;
  getInvoicesByGuest(guestId: string): Promise<Invoice[]>;
  getInvoicesByStatus(status: InvoiceStatus): Promise<Invoice[]>;
  getInvoicesForDateRange(startDate: string, endDate: string): Promise<Invoice[]>;
  updateInvoice(id: string, updates: Partial<Pick<Invoice, 'notes' | 'dueDate'>>): Promise<Invoice>;
  deleteInvoice(id: string): Promise<void>;
  
  // Line Items
  addLineItem(invoiceId: string, item: AddLineItemInput): Promise<Invoice>;
  removeLineItem(invoiceId: string, lineItemId: string): Promise<Invoice>;
  updateLineItem(invoiceId: string, lineItemId: string, updates: Partial<AddLineItemInput>): Promise<Invoice>;
  
  // Status Operations
  sendInvoice(id: string): Promise<Invoice>;
  markAsPaid(id: string): Promise<Invoice>;
  cancelInvoice(id: string): Promise<Invoice>;
  refundInvoice(id: string): Promise<Invoice>;
  
  // Payment Operations
  recordPayment(input: RecordPaymentInput): Promise<Invoice>;
  getPayments(invoiceId: string): Promise<InvoicePayment[]>;
  getTotalPaid(invoiceId: string): Promise<number>;
  
  // Queries
  getOverdueInvoices(): Promise<Invoice[]>;
  getPendingInvoices(): Promise<Invoice[]>;
  getUnpaidTotal(guestId: string): Promise<number>;
  
  // Utilities
  generateInvoiceNumber(): string;
  calculateTotals(lineItems: InvoiceLineItem[]): { subtotal: number; taxAmount: number; discountAmount: number; totalAmount: number };
  isOverdue(invoice: Invoice): boolean;
  canEdit(invoice: Invoice): boolean;
  canCancel(invoice: Invoice): boolean;
  canRefund(invoice: Invoice): boolean;
  formatCurrency(amount: number, currency: string): string;
}

export function createInvoiceService(container: Container): InvoiceService {
  const { invoiceRepository, logger } = container;
  
  let invoiceCounter = 1000;
  
  function generateInvoiceNumber(): string {
    invoiceCounter++;
    const date = new Date();
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    return `INV-${year}${month}-${String(invoiceCounter).padStart(5, '0')}`;
  }
  
  function calculateTotals(lineItems: InvoiceLineItem[]): { 
    subtotal: number; 
    taxAmount: number; 
    discountAmount: number; 
    totalAmount: number 
  } {
    let subtotal = 0;
    let taxAmount = 0;
    let discountAmount = 0;
    
    for (const item of lineItems) {
      const itemSubtotal = item.quantity * item.unitPrice;
      const itemDiscount = itemSubtotal * (item.discount / 100);
      const itemAfterDiscount = itemSubtotal - itemDiscount;
      const itemTax = itemAfterDiscount * (item.taxRate / 100);
      
      subtotal += itemSubtotal;
      discountAmount += itemDiscount;
      taxAmount += itemTax;
    }
    
    const totalAmount = subtotal - discountAmount + taxAmount;
    
    return {
      subtotal: Math.round(subtotal * 100) / 100,
      taxAmount: Math.round(taxAmount * 100) / 100,
      discountAmount: Math.round(discountAmount * 100) / 100,
      totalAmount: Math.round(totalAmount * 100) / 100
    };
  }
  
  function isOverdue(invoice: Invoice): boolean {
    if (['paid', 'cancelled', 'refunded'].includes(invoice.status)) {
      return false;
    }
    return new Date(invoice.dueDate) < new Date() && invoice.balanceDue > 0;
  }
  
  function canEdit(invoice: Invoice): boolean {
    return ['draft', 'pending'].includes(invoice.status);
  }
  
  function canCancel(invoice: Invoice): boolean {
    return ['draft', 'pending', 'sent', 'overdue'].includes(invoice.status);
  }
  
  function canRefund(invoice: Invoice): boolean {
    return invoice.status === 'paid' && invoice.paidAmount > 0;
  }
  
  function formatCurrency(amount: number, currency: string): string {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: currency
    }).format(amount);
  }
  
  function updateInvoiceStatus(invoice: Invoice): InvoiceStatus {
    if (invoice.status === 'cancelled' || invoice.status === 'refunded') {
      return invoice.status;
    }
    
    if (invoice.balanceDue <= 0 && invoice.paidAmount >= invoice.totalAmount) {
      return 'paid';
    }
    
    if (invoice.paidAmount > 0 && invoice.balanceDue > 0) {
      return 'partial';
    }
    
    if (isOverdue(invoice)) {
      return 'overdue';
    }
    
    return invoice.status;
  }
  
  async function createInvoice(input: CreateInvoiceInput): Promise<Invoice> {
    const invoiceNumber = generateInvoiceNumber();
    
    const invoice = await invoiceRepository.create({
      invoiceNumber,
      guestId: input.guestId,
      guestName: input.guestName,
      guestEmail: input.guestEmail,
      reservationId: input.reservationId,
      lineItems: [],
      subtotal: 0,
      taxAmount: 0,
      discountAmount: 0,
      totalAmount: 0,
      paidAmount: 0,
      balanceDue: 0,
      status: 'draft',
      dueDate: input.dueDate,
      issueDate: new Date().toISOString(),
      notes: input.notes,
      currency: input.currency || 'USD',
      createdBy: input.createdBy
    });
    
    logger.info('Invoice created', { 
      invoiceId: invoice.id, 
      invoiceNumber 
    });
    
    return invoice;
  }
  
  async function getInvoice(id: string): Promise<Invoice | null> {
    return invoiceRepository.getById(id);
  }
  
  async function getInvoiceByNumber(invoiceNumber: string): Promise<Invoice | null> {
    return invoiceRepository.getByInvoiceNumber(invoiceNumber);
  }
  
  async function getInvoices(): Promise<Invoice[]> {
    return invoiceRepository.getAll();
  }
  
  async function getInvoicesByGuest(guestId: string): Promise<Invoice[]> {
    return invoiceRepository.getByGuestId(guestId);
  }
  
  async function getInvoicesByStatus(status: InvoiceStatus): Promise<Invoice[]> {
    return invoiceRepository.getByStatus(status);
  }
  
  async function getInvoicesForDateRange(startDate: string, endDate: string): Promise<Invoice[]> {
    return invoiceRepository.getByDateRange(startDate, endDate);
  }
  
  async function updateInvoice(
    id: string, 
    updates: Partial<Pick<Invoice, 'notes' | 'dueDate'>>
  ): Promise<Invoice> {
    const invoice = await invoiceRepository.getById(id);
    
    if (!invoice) {
      throw new Error('Invoice not found');
    }
    
    if (!canEdit(invoice)) {
      throw new Error('Cannot edit invoice in current status');
    }
    
    const updated = await invoiceRepository.update(id, updates);
    
    logger.info('Invoice updated', { invoiceId: id });
    
    return updated;
  }
  
  async function deleteInvoice(id: string): Promise<void> {
    const invoice = await invoiceRepository.getById(id);
    
    if (!invoice) {
      throw new Error('Invoice not found');
    }
    
    if (invoice.status !== 'draft') {
      throw new Error('Only draft invoices can be deleted');
    }
    
    await invoiceRepository.delete(id);
    
    logger.info('Invoice deleted', { invoiceId: id });
  }
  
  async function addLineItem(invoiceId: string, item: AddLineItemInput): Promise<Invoice> {
    const invoice = await invoiceRepository.getById(invoiceId);
    
    if (!invoice) {
      throw new Error('Invoice not found');
    }
    
    if (!canEdit(invoice)) {
      throw new Error('Cannot add items to invoice in current status');
    }
    
    if (item.quantity <= 0) {
      throw new Error('Quantity must be greater than 0');
    }
    
    if (item.unitPrice < 0) {
      throw new Error('Unit price cannot be negative');
    }
    
    const discount = item.discount || 0;
    const taxRate = item.taxRate || 0;
    const itemSubtotal = item.quantity * item.unitPrice;
    const itemDiscount = itemSubtotal * (discount / 100);
    const itemAfterDiscount = itemSubtotal - itemDiscount;
    const itemTax = itemAfterDiscount * (taxRate / 100);
    const itemTotal = itemAfterDiscount + itemTax;
    
    const lineItem: InvoiceLineItem = {
      id: crypto.randomUUID(),
      description: item.description,
      quantity: item.quantity,
      unitPrice: item.unitPrice,
      discount,
      taxRate,
      total: Math.round(itemTotal * 100) / 100
    };
    
    const newLineItems = [...invoice.lineItems, lineItem];
    const totals = calculateTotals(newLineItems);
    
    const updated = await invoiceRepository.update(invoiceId, {
      lineItems: newLineItems,
      ...totals,
      balanceDue: totals.totalAmount - invoice.paidAmount
    });
    
    logger.info('Line item added to invoice', { invoiceId, lineItemId: lineItem.id });
    
    return updated;
  }
  
  async function removeLineItem(invoiceId: string, lineItemId: string): Promise<Invoice> {
    const invoice = await invoiceRepository.getById(invoiceId);
    
    if (!invoice) {
      throw new Error('Invoice not found');
    }
    
    if (!canEdit(invoice)) {
      throw new Error('Cannot remove items from invoice in current status');
    }
    
    const newLineItems = invoice.lineItems.filter(item => item.id !== lineItemId);
    
    if (newLineItems.length === invoice.lineItems.length) {
      throw new Error('Line item not found');
    }
    
    const totals = calculateTotals(newLineItems);
    
    const updated = await invoiceRepository.update(invoiceId, {
      lineItems: newLineItems,
      ...totals,
      balanceDue: totals.totalAmount - invoice.paidAmount
    });
    
    logger.info('Line item removed from invoice', { invoiceId, lineItemId });
    
    return updated;
  }
  
  async function updateLineItem(
    invoiceId: string, 
    lineItemId: string, 
    updates: Partial<AddLineItemInput>
  ): Promise<Invoice> {
    const invoice = await invoiceRepository.getById(invoiceId);
    
    if (!invoice) {
      throw new Error('Invoice not found');
    }
    
    if (!canEdit(invoice)) {
      throw new Error('Cannot update items on invoice in current status');
    }
    
    const itemIndex = invoice.lineItems.findIndex(item => item.id === lineItemId);
    
    if (itemIndex === -1) {
      throw new Error('Line item not found');
    }
    
    const existingItem = invoice.lineItems[itemIndex];
    const quantity = updates.quantity ?? existingItem.quantity;
    const unitPrice = updates.unitPrice ?? existingItem.unitPrice;
    const discount = updates.discount ?? existingItem.discount;
    const taxRate = updates.taxRate ?? existingItem.taxRate;
    
    if (quantity <= 0) {
      throw new Error('Quantity must be greater than 0');
    }
    
    const itemSubtotal = quantity * unitPrice;
    const itemDiscount = itemSubtotal * (discount / 100);
    const itemAfterDiscount = itemSubtotal - itemDiscount;
    const itemTax = itemAfterDiscount * (taxRate / 100);
    const itemTotal = itemAfterDiscount + itemTax;
    
    const updatedItem: InvoiceLineItem = {
      id: lineItemId,
      description: updates.description ?? existingItem.description,
      quantity,
      unitPrice,
      discount,
      taxRate,
      total: Math.round(itemTotal * 100) / 100
    };
    
    const newLineItems = [...invoice.lineItems];
    newLineItems[itemIndex] = updatedItem;
    
    const totals = calculateTotals(newLineItems);
    
    const updated = await invoiceRepository.update(invoiceId, {
      lineItems: newLineItems,
      ...totals,
      balanceDue: totals.totalAmount - invoice.paidAmount
    });
    
    logger.info('Line item updated on invoice', { invoiceId, lineItemId });
    
    return updated;
  }
  
  async function sendInvoice(id: string): Promise<Invoice> {
    const invoice = await invoiceRepository.getById(id);
    
    if (!invoice) {
      throw new Error('Invoice not found');
    }
    
    if (invoice.status !== 'draft' && invoice.status !== 'pending') {
      throw new Error('Can only send draft or pending invoices');
    }
    
    if (invoice.lineItems.length === 0) {
      throw new Error('Cannot send invoice with no line items');
    }
    
    const updated = await invoiceRepository.update(id, {
      status: 'sent'
    });
    
    logger.info('Invoice sent', { invoiceId: id });
    
    return updated;
  }
  
  async function markAsPaid(id: string): Promise<Invoice> {
    const invoice = await invoiceRepository.getById(id);
    
    if (!invoice) {
      throw new Error('Invoice not found');
    }
    
    if (invoice.status === 'cancelled' || invoice.status === 'refunded') {
      throw new Error('Cannot mark cancelled or refunded invoice as paid');
    }
    
    const updated = await invoiceRepository.update(id, {
      status: 'paid',
      paidAmount: invoice.totalAmount,
      balanceDue: 0,
      paidDate: new Date().toISOString()
    });
    
    logger.info('Invoice marked as paid', { invoiceId: id });
    
    return updated;
  }
  
  async function cancelInvoice(id: string): Promise<Invoice> {
    const invoice = await invoiceRepository.getById(id);
    
    if (!invoice) {
      throw new Error('Invoice not found');
    }
    
    if (!canCancel(invoice)) {
      throw new Error('Cannot cancel invoice in current status');
    }
    
    const updated = await invoiceRepository.update(id, {
      status: 'cancelled'
    });
    
    logger.info('Invoice cancelled', { invoiceId: id });
    
    return updated;
  }
  
  async function refundInvoice(id: string): Promise<Invoice> {
    const invoice = await invoiceRepository.getById(id);
    
    if (!invoice) {
      throw new Error('Invoice not found');
    }
    
    if (!canRefund(invoice)) {
      throw new Error('Can only refund paid invoices');
    }
    
    const updated = await invoiceRepository.update(id, {
      status: 'refunded'
    });
    
    logger.info('Invoice refunded', { invoiceId: id });
    
    return updated;
  }
  
  async function recordPayment(input: RecordPaymentInput): Promise<Invoice> {
    const invoice = await invoiceRepository.getById(input.invoiceId);
    
    if (!invoice) {
      throw new Error('Invoice not found');
    }
    
    if (['cancelled', 'refunded', 'paid'].includes(invoice.status)) {
      throw new Error('Cannot record payment on invoice in current status');
    }
    
    if (input.amount <= 0) {
      throw new Error('Payment amount must be greater than 0');
    }
    
    if (input.amount > invoice.balanceDue) {
      throw new Error('Payment amount exceeds balance due');
    }
    
    await invoiceRepository.addPayment({
      invoiceId: input.invoiceId,
      amount: input.amount,
      paymentMethod: input.paymentMethod,
      reference: input.reference,
      processedBy: input.processedBy
    });
    
    const newPaidAmount = invoice.paidAmount + input.amount;
    const newBalanceDue = invoice.totalAmount - newPaidAmount;
    const newStatus = newBalanceDue <= 0 ? 'paid' : 'partial';
    
    const updated = await invoiceRepository.update(input.invoiceId, {
      paidAmount: newPaidAmount,
      balanceDue: newBalanceDue,
      status: newStatus,
      paidDate: newBalanceDue <= 0 ? new Date().toISOString() : undefined
    });
    
    logger.info('Payment recorded', { 
      invoiceId: input.invoiceId, 
      amount: input.amount,
      newStatus 
    });
    
    return updated;
  }
  
  async function getPayments(invoiceId: string): Promise<InvoicePayment[]> {
    return invoiceRepository.getPayments(invoiceId);
  }
  
  async function getTotalPaid(invoiceId: string): Promise<number> {
    const payments = await invoiceRepository.getPayments(invoiceId);
    return payments.reduce((total, payment) => total + payment.amount, 0);
  }
  
  async function getOverdueInvoices(): Promise<Invoice[]> {
    return invoiceRepository.getOverdue();
  }
  
  async function getPendingInvoices(): Promise<Invoice[]> {
    const pending = await invoiceRepository.getByStatus('pending');
    const sent = await invoiceRepository.getByStatus('sent');
    return [...pending, ...sent];
  }
  
  async function getUnpaidTotal(guestId: string): Promise<number> {
    const invoices = await invoiceRepository.getByGuestId(guestId);
    return invoices
      .filter(i => !['paid', 'cancelled', 'refunded'].includes(i.status))
      .reduce((total, invoice) => total + invoice.balanceDue, 0);
  }
  
  return {
    createInvoice,
    getInvoice,
    getInvoiceByNumber,
    getInvoices,
    getInvoicesByGuest,
    getInvoicesByStatus,
    getInvoicesForDateRange,
    updateInvoice,
    deleteInvoice,
    addLineItem,
    removeLineItem,
    updateLineItem,
    sendInvoice,
    markAsPaid,
    cancelInvoice,
    refundInvoice,
    recordPayment,
    getPayments,
    getTotalPaid,
    getOverdueInvoices,
    getPendingInvoices,
    getUnpaidTotal,
    generateInvoiceNumber,
    calculateTotals,
    isOverdue,
    canEdit,
    canCancel,
    canRefund,
    formatCurrency
  };
}

/**
 * Loyalty Service with Dependency Injection
 *
 * This service handles all loyalty/rewards operations including:
 * - Account management
 * - Points earning and redemption
 * - Tier management
 * - Transaction history
 * - Expiration handling
 *
 * All dependencies are injected via the container for testability.
 */

import type {
  Container,
  LoyaltyAccount,
  LoyaltyTransaction,
  LoyaltyTransactionType,
  LoyaltyTier,
  LoyaltyTierConfig,
  LoyaltyFilters,
} from '../container/types';

// Custom error class
export class LoyaltyServiceError extends Error {
  constructor(
    message: string,
    public code: string
  ) {
    super(message);
    this.name = 'LoyaltyServiceError';
  }
}

// UUID validation
const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

// Valid types and tiers
const VALID_TRANSACTION_TYPES: LoyaltyTransactionType[] = ['earn', 'redeem', 'expire', 'adjust', 'bonus'];
const VALID_TIERS: LoyaltyTier[] = ['bronze', 'silver', 'gold', 'platinum'];

// Tier configuration
const TIER_CONFIG: LoyaltyTierConfig[] = [
  { tier: 'bronze', minPoints: 0, multiplier: 1.0, benefits: ['Basic member discounts'] },
  { tier: 'silver', minPoints: 1000, multiplier: 1.25, benefits: ['5% extra on orders', 'Priority support'] },
  { tier: 'gold', minPoints: 5000, multiplier: 1.5, benefits: ['10% extra on orders', 'Free upgrades', 'Early access'] },
  { tier: 'platinum', minPoints: 15000, multiplier: 2.0, benefits: ['15% extra on orders', 'VIP support', 'Exclusive events'] },
];

// Points per dollar spent
const POINTS_PER_DOLLAR = 10;

// Points expiration (days)
const POINTS_EXPIRATION_DAYS = 365;

export interface EarnPointsInput {
  userId: string;
  amount: number;
  referenceType?: string;
  referenceId?: string;
  description?: string;
}

export interface RedeemPointsInput {
  userId: string;
  points: number;
  referenceType?: string;
  referenceId?: string;
  description?: string;
}

export interface BonusPointsInput {
  userId: string;
  points: number;
  description: string;
  expiresInDays?: number;
}

export interface LoyaltyStats {
  totalAccounts: number;
  totalPointsIssued: number;
  totalPointsRedeemed: number;
  accountsByTier: Record<LoyaltyTier, number>;
}

export interface LoyaltyService {
  createAccount(userId: string): Promise<LoyaltyAccount>;
  getAccount(userId: string): Promise<LoyaltyAccount | null>;
  getAccountById(id: string): Promise<LoyaltyAccount | null>;
  earnPoints(input: EarnPointsInput): Promise<LoyaltyTransaction>;
  redeemPoints(input: RedeemPointsInput): Promise<LoyaltyTransaction>;
  addBonusPoints(input: BonusPointsInput): Promise<LoyaltyTransaction>;
  adjustPoints(userId: string, points: number, reason: string): Promise<LoyaltyTransaction>;
  getTransactions(userId: string, limit?: number): Promise<LoyaltyTransaction[]>;
  getBalance(userId: string): Promise<number>;
  calculatePointsForPurchase(amount: number, tier?: LoyaltyTier): number;
  calculateRedemptionValue(points: number): number;
  getTierForPoints(lifetimePoints: number): LoyaltyTier;
  upgradeTierIfNeeded(userId: string): Promise<LoyaltyAccount | null>;
  expireOldPoints(userId: string): Promise<number>;
  getStats(): Promise<LoyaltyStats>;
  getTierConfig(): LoyaltyTierConfig[];
  getTiers(): LoyaltyTier[];
  getTransactionTypes(): LoyaltyTransactionType[];
}

/**
 * Creates a LoyaltyService instance with injected dependencies.
 */
export function createLoyaltyService(container: Container): LoyaltyService {
  const { loyaltyRepository, logger } = container;

  // ----------------------------------------
  // VALIDATION HELPERS
  // ----------------------------------------

  function isValidUuid(id: string): boolean {
    return UUID_REGEX.test(id);
  }

  // ----------------------------------------
  // SERVICE METHODS
  // ----------------------------------------

  async function createAccount(userId: string): Promise<LoyaltyAccount> {
    if (!isValidUuid(userId)) {
      throw new LoyaltyServiceError('Invalid user ID format', 'INVALID_USER_ID');
    }

    // Check if account already exists
    const existing = await loyaltyRepository.getAccountByUserId(userId);
    if (existing) {
      throw new LoyaltyServiceError('Loyalty account already exists for this user', 'ACCOUNT_EXISTS');
    }

    const account = await loyaltyRepository.createAccount(userId);
    logger.info(`Loyalty account created for user ${userId}`);
    return account;
  }

  async function getAccount(userId: string): Promise<LoyaltyAccount | null> {
    if (!isValidUuid(userId)) {
      throw new LoyaltyServiceError('Invalid user ID format', 'INVALID_USER_ID');
    }
    return loyaltyRepository.getAccountByUserId(userId);
  }

  async function getAccountById(id: string): Promise<LoyaltyAccount | null> {
    if (!isValidUuid(id)) {
      throw new LoyaltyServiceError('Invalid account ID format', 'INVALID_ACCOUNT_ID');
    }
    return loyaltyRepository.getAccountById(id);
  }

  async function earnPoints(input: EarnPointsInput): Promise<LoyaltyTransaction> {
    if (!isValidUuid(input.userId)) {
      throw new LoyaltyServiceError('Invalid user ID format', 'INVALID_USER_ID');
    }

    if (input.amount <= 0) {
      throw new LoyaltyServiceError('Amount must be positive', 'INVALID_AMOUNT');
    }

    if (input.referenceId && !isValidUuid(input.referenceId)) {
      throw new LoyaltyServiceError('Invalid reference ID format', 'INVALID_REFERENCE_ID');
    }

    let account = await loyaltyRepository.getAccountByUserId(input.userId);
    if (!account) {
      // Auto-create account if it doesn't exist
      account = await createAccount(input.userId);
    }

    // Calculate points based on tier
    const points = calculatePointsForPurchase(input.amount, account.tier);

    // Create expiration date
    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + POINTS_EXPIRATION_DAYS);

    // Atomic update of account points
    const updatedAccount = await loyaltyRepository.adjustPointsAtomic(account.id, points);

    // Record transaction
    const transaction = await loyaltyRepository.addTransaction({
      accountId: account.id,
      type: 'earn',
      points,
      balanceAfter: updatedAccount.availablePoints,
      description: input.description || `Earned ${points} points for $${input.amount.toFixed(2)} purchase`,
      referenceType: input.referenceType || null,
      referenceId: input.referenceId || null,
      expiresAt: expiresAt.toISOString(),
    });

    // Check for tier upgrade
    await upgradeTierIfNeeded(input.userId);

    logger.info(`User ${input.userId} earned ${points} points`);
    return transaction;
  }

  async function redeemPoints(input: RedeemPointsInput): Promise<LoyaltyTransaction> {
    if (!isValidUuid(input.userId)) {
      throw new LoyaltyServiceError('Invalid user ID format', 'INVALID_USER_ID');
    }

    if (input.points <= 0) {
      throw new LoyaltyServiceError('Points must be positive', 'INVALID_POINTS');
    }

    if (!Number.isInteger(input.points)) {
      throw new LoyaltyServiceError('Points must be a whole number', 'INVALID_POINTS');
    }

    if (input.referenceId && !isValidUuid(input.referenceId)) {
      throw new LoyaltyServiceError('Invalid reference ID format', 'INVALID_REFERENCE_ID');
    }

    const account = await loyaltyRepository.getAccountByUserId(input.userId);
    if (!account) {
      throw new LoyaltyServiceError('Loyalty account not found', 'ACCOUNT_NOT_FOUND');
    }

    if (account.availablePoints < input.points) {
      throw new LoyaltyServiceError(
        `Insufficient points. Available: ${account.availablePoints}, Requested: ${input.points}`,
        'INSUFFICIENT_POINTS'
      );
    }

    // Atomic update of account points
    const updatedAccount = await loyaltyRepository.adjustPointsAtomic(account.id, -input.points);

    // Record transaction
    const transaction = await loyaltyRepository.addTransaction({
      accountId: account.id,
      type: 'redeem',
      points: -input.points, // Negative for redemption
      balanceAfter: updatedAccount.availablePoints,
      description: input.description || `Redeemed ${input.points} points`,
      referenceType: input.referenceType || null,
      referenceId: input.referenceId || null,
      expiresAt: null,
    });

    logger.info(`User ${input.userId} redeemed ${input.points} points`);
    return transaction;
  }

  async function addBonusPoints(input: BonusPointsInput): Promise<LoyaltyTransaction> {
    if (!isValidUuid(input.userId)) {
      throw new LoyaltyServiceError('Invalid user ID format', 'INVALID_USER_ID');
    }

    if (input.points <= 0) {
      throw new LoyaltyServiceError('Points must be positive', 'INVALID_POINTS');
    }

    if (!input.description.trim()) {
      throw new LoyaltyServiceError('Description is required for bonus points', 'MISSING_DESCRIPTION');
    }

    let account = await loyaltyRepository.getAccountByUserId(input.userId);
    if (!account) {
      account = await createAccount(input.userId);
    }

    // Create expiration date
    const expirationDays = input.expiresInDays || POINTS_EXPIRATION_DAYS;
    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + expirationDays);

    // Atomic update of account points
    const updatedAccount = await loyaltyRepository.adjustPointsAtomic(account.id, input.points);

    // Record transaction
    const transaction = await loyaltyRepository.addTransaction({
      accountId: account.id,
      type: 'bonus',
      points: input.points,
      balanceAfter: updatedAccount.availablePoints,
      description: input.description.trim(),
      referenceType: null,
      referenceId: null,
      expiresAt: expiresAt.toISOString(),
    });

    logger.info(`User ${input.userId} received ${input.points} bonus points`);
    return transaction;
  }

  async function adjustPoints(userId: string, points: number, reason: string): Promise<LoyaltyTransaction> {
    if (!isValidUuid(userId)) {
      throw new LoyaltyServiceError('Invalid user ID format', 'INVALID_USER_ID');
    }

    if (points === 0) {
      throw new LoyaltyServiceError('Adjustment points cannot be zero', 'INVALID_POINTS');
    }

    if (!reason.trim()) {
      throw new LoyaltyServiceError('Reason is required for adjustments', 'MISSING_REASON');
    }

    // We use the new atomic adjustment method in the repository
    const account = await loyaltyRepository.getAccountByUserId(userId);
    if (!account) {
      throw new LoyaltyServiceError('Loyalty account not found', 'ACCOUNT_NOT_FOUND');
    }

    // Still check locally for immediate feedback, but the atomic update is the source of truth
    if (account.availablePoints + points < 0) {
      throw new LoyaltyServiceError(
        `Adjustment would result in negative balance`,
        'NEGATIVE_BALANCE'
      );
    }

    // Update account ATOMICALLY
    const updatedAccount = await loyaltyRepository.adjustPointsAtomic(account.id, points);

    // Record transaction
    const transaction = await loyaltyRepository.addTransaction({
      accountId: account.id,
      type: 'adjust',
      points,
      balanceAfter: updatedAccount.availablePoints,
      description: reason.trim(),
      referenceType: null,
      referenceId: null,
      expiresAt: null,
    });

    logger.info(`User ${userId} points adjusted by ${points}: ${reason}`);
    return transaction;
  }

  async function getTransactions(userId: string, limit?: number): Promise<LoyaltyTransaction[]> {
    if (!isValidUuid(userId)) {
      throw new LoyaltyServiceError('Invalid user ID format', 'INVALID_USER_ID');
    }

    const account = await loyaltyRepository.getAccountByUserId(userId);
    if (!account) {
      return [];
    }

    if (limit !== undefined && (limit < 1 || limit > 1000)) {
      throw new LoyaltyServiceError('Limit must be between 1 and 1000', 'INVALID_LIMIT');
    }

    return loyaltyRepository.getTransactions(account.id, limit);
  }

  async function getBalance(userId: string): Promise<number> {
    if (!isValidUuid(userId)) {
      throw new LoyaltyServiceError('Invalid user ID format', 'INVALID_USER_ID');
    }

    const account = await loyaltyRepository.getAccountByUserId(userId);
    return account?.availablePoints || 0;
  }

  function calculatePointsForPurchase(amount: number, tier?: LoyaltyTier): number {
    if (amount <= 0) return 0;

    const basePoints = Math.floor(amount * POINTS_PER_DOLLAR);
    const tierConfig = TIER_CONFIG.find((t) => t.tier === tier) || TIER_CONFIG[0];
    return Math.floor(basePoints * tierConfig.multiplier);
  }

  function calculateRedemptionValue(points: number): number {
    // 100 points = $1
    return Math.floor(points / 100);
  }

  function getTierForPoints(lifetimePoints: number): LoyaltyTier {
    // Find highest tier that matches
    for (let i = TIER_CONFIG.length - 1; i >= 0; i--) {
      if (lifetimePoints >= TIER_CONFIG[i].minPoints) {
        return TIER_CONFIG[i].tier;
      }
    }
    return 'bronze';
  }

  async function upgradeTierIfNeeded(userId: string): Promise<LoyaltyAccount | null> {
    const account = await loyaltyRepository.getAccountByUserId(userId);
    if (!account) return null;

    const newTier = getTierForPoints(account.lifetimePoints);
    if (newTier !== account.tier) {
      const tierOrder = VALID_TIERS.indexOf(newTier);
      const currentOrder = VALID_TIERS.indexOf(account.tier);

      if (tierOrder > currentOrder) {
        // Tier upgrade
        const tierExpiresAt = new Date();
        tierExpiresAt.setFullYear(tierExpiresAt.getFullYear() + 1);

        const updated = await loyaltyRepository.updateAccount(account.id, {
          tier: newTier,
          tierExpiresAt: tierExpiresAt.toISOString(),
        });

        logger.info(`User ${userId} upgraded to ${newTier} tier`);
        return updated;
      }
    }

    return account;
  }

  async function expireOldPoints(userId: string): Promise<number> {
    if (!isValidUuid(userId)) {
      throw new LoyaltyServiceError('Invalid user ID format', 'INVALID_USER_ID');
    }

    const account = await loyaltyRepository.getAccountByUserId(userId);
    if (!account) {
      return 0;
    }

    const now = new Date().toISOString();
    const expiring = await loyaltyRepository.getExpiringPoints(account.id, now);

    if (expiring.length === 0) {
      return 0;
    }

    let currentBalance = account.availablePoints;
    let totalExpired = 0;
    for (const txn of expiring) {
      if (txn.points > 0) {
        totalExpired += txn.points;
        currentBalance -= txn.points;

        // Record expiration transaction
        await loyaltyRepository.addTransaction({
          accountId: account.id,
          type: 'expire',
          points: -txn.points,
          balanceAfter: Math.max(0, currentBalance),
          description: `Points expired from: ${txn.description}`,
          referenceType: null,
          referenceId: null,
          expiresAt: null,
        });
      }
    }

    if (totalExpired > 0) {
      await loyaltyRepository.updateAccount(account.id, {
        totalPoints: account.totalPoints - totalExpired,
        availablePoints: Math.max(0, account.availablePoints - totalExpired),
      });

      logger.info(`User ${userId} had ${totalExpired} points expired`);
    }

    return totalExpired;
  }

  async function getStats(): Promise<LoyaltyStats> {
    const allAccounts = await loyaltyRepository.listAccounts();

    const stats: LoyaltyStats = {
      totalAccounts: allAccounts.length,
      totalPointsIssued: 0,
      totalPointsRedeemed: 0,
      accountsByTier: {
        bronze: 0,
        silver: 0,
        gold: 0,
        platinum: 0,
      },
    };

    for (const account of allAccounts) {
      stats.totalPointsIssued += account.lifetimePoints;
      stats.totalPointsRedeemed += account.lifetimePoints - account.availablePoints;
      stats.accountsByTier[account.tier]++;
    }

    return stats;
  }

  function getTierConfig(): LoyaltyTierConfig[] {
    return [...TIER_CONFIG];
  }

  function getTiers(): LoyaltyTier[] {
    return [...VALID_TIERS];
  }

  function getTransactionTypes(): LoyaltyTransactionType[] {
    return [...VALID_TRANSACTION_TYPES];
  }

  return {
    createAccount,
    getAccount,
    getAccountById,
    earnPoints,
    redeemPoints,
    addBonusPoints,
    adjustPoints,
    getTransactions,
    getBalance,
    calculatePointsForPurchase,
    calculateRedemptionValue,
    getTierForPoints,
    upgradeTierIfNeeded,
    expireOldPoints,
    getStats,
    getTierConfig,
    getTiers,
    getTransactionTypes,
  };
}

/**
 * Maintenance Service
 *
 * Business logic for work order management with DI.
 */

import { v4 as uuidv4 } from 'uuid';
import type {
  Container,
  MaintenanceRepository,
  WorkOrder,
  WorkOrderPart,
  WorkOrderPriority,
  WorkOrderStatus,
  WorkOrderCategory,
  WorkOrderFilters,
  LoggerService,
} from '../container/types.js';

// ============================================
// TYPES
// ============================================

export interface CreateWorkOrderInput {
  title: string;
  description: string;
  category: WorkOrderCategory;
  priority: WorkOrderPriority;
  locationId: string;
  locationType: string;
  reportedBy: string;
  scheduledDate?: string;
  estimatedHours?: number;
  notes?: string;
}

export interface UpdateWorkOrderInput {
  title?: string;
  description?: string;
  priority?: WorkOrderPriority;
  scheduledDate?: string;
  estimatedHours?: number;
  notes?: string;
}

export interface AddPartInput {
  workOrderId: string;
  partName: string;
  partNumber?: string;
  quantity: number;
  unitCost: number;
}

export interface CompleteWorkOrderInput {
  actualHours: number;
  laborCost?: number;
  notes?: string;
}

export interface MaintenanceStats {
  totalWorkOrders: number;
  byStatus: Record<WorkOrderStatus, number>;
  byPriority: Record<WorkOrderPriority, number>;
  byCategory: Record<WorkOrderCategory, number>;
  avgCompletionHours: number;
  totalLaborCost: number;
  totalPartsCost: number;
}

export interface MaintenanceService {
  // Work order operations
  createWorkOrder(input: CreateWorkOrderInput): Promise<WorkOrder>;
  getWorkOrder(id: string): Promise<WorkOrder | null>;
  updateWorkOrder(id: string, input: UpdateWorkOrderInput): Promise<WorkOrder>;
  deleteWorkOrder(id: string): Promise<void>;
  listWorkOrders(filters?: WorkOrderFilters): Promise<WorkOrder[]>;
  
  // Workflow
  assignWorkOrder(id: string, assignedTo: string): Promise<WorkOrder>;
  unassignWorkOrder(id: string): Promise<WorkOrder>;
  startWorkOrder(id: string): Promise<WorkOrder>;
  setPendingParts(id: string): Promise<WorkOrder>;
  completeWorkOrder(id: string, input: CompleteWorkOrderInput): Promise<WorkOrder>;
  cancelWorkOrder(id: string, reason?: string): Promise<WorkOrder>;
  reopenWorkOrder(id: string): Promise<WorkOrder>;
  
  // Parts management
  addPart(input: AddPartInput): Promise<WorkOrderPart>;
  getParts(workOrderId: string): Promise<WorkOrderPart[]>;
  removePart(partId: string): Promise<void>;
  
  // Reporting
  getByLocation(locationId: string): Promise<WorkOrder[]>;
  getByAssignee(assigneeId: string): Promise<WorkOrder[]>;
  getOpenWorkOrders(): Promise<WorkOrder[]>;
  getCriticalWorkOrders(): Promise<WorkOrder[]>;
  getStats(): Promise<MaintenanceStats>;
  
  // Utility
  getPriorities(): WorkOrderPriority[];
  getStatuses(): WorkOrderStatus[];
  getCategories(): WorkOrderCategory[];
}

// ============================================
// ERROR CLASS
// ============================================

export class MaintenanceServiceError extends Error {
  constructor(
    message: string,
    public code: string,
    public statusCode: number = 400
  ) {
    super(message);
    this.name = 'MaintenanceServiceError';
  }
}

// ============================================
// CONSTANTS
// ============================================

const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const PRIORITIES: WorkOrderPriority[] = ['low', 'medium', 'high', 'critical'];
const STATUSES: WorkOrderStatus[] = ['open', 'assigned', 'in_progress', 'pending_parts', 'completed', 'cancelled'];
const CATEGORIES: WorkOrderCategory[] = ['electrical', 'plumbing', 'hvac', 'structural', 'appliance', 'general'];

// ============================================
// FACTORY
// ============================================

export function createMaintenanceService(container: Container): MaintenanceService {
  const repository: MaintenanceRepository = container.maintenanceRepository;
  const logger: LoggerService = container.logger;

  // ============================================
  // VALIDATION HELPERS
  // ============================================

  function validateUUID(id: string, field: string): void {
    if (!UUID_REGEX.test(id)) {
      throw new MaintenanceServiceError(`Invalid ${field} format`, `INVALID_${field.toUpperCase()}_ID`);
    }
  }

  function validateTitle(title: string): void {
    if (!title || title.trim().length < 3) {
      throw new MaintenanceServiceError('Title must be at least 3 characters', 'INVALID_TITLE');
    }
  }

  function validateDescription(description: string): void {
    if (!description || description.trim().length === 0) {
      throw new MaintenanceServiceError('Description is required', 'INVALID_DESCRIPTION');
    }
  }

  function validateCategory(category: WorkOrderCategory): void {
    if (!CATEGORIES.includes(category)) {
      throw new MaintenanceServiceError(`Invalid category: ${category}`, 'INVALID_CATEGORY');
    }
  }

  function validatePriority(priority: WorkOrderPriority): void {
    if (!PRIORITIES.includes(priority)) {
      throw new MaintenanceServiceError(`Invalid priority: ${priority}`, 'INVALID_PRIORITY');
    }
  }

  function validateLocationType(type: string): void {
    if (!type || type.trim().length === 0) {
      throw new MaintenanceServiceError('Location type is required', 'INVALID_LOCATION_TYPE');
    }
  }

  // ============================================
  // WORK ORDER OPERATIONS
  // ============================================

  async function createWorkOrder(input: CreateWorkOrderInput): Promise<WorkOrder> {
    validateTitle(input.title);
    validateDescription(input.description);
    validateCategory(input.category);
    validatePriority(input.priority);
    validateUUID(input.locationId, 'location');
    validateLocationType(input.locationType);
    validateUUID(input.reportedBy, 'reporter');

    if (input.estimatedHours !== undefined && input.estimatedHours < 0) {
      throw new MaintenanceServiceError('Estimated hours cannot be negative', 'INVALID_HOURS');
    }

    const workOrder = await repository.create({
      title: input.title.trim(),
      description: input.description.trim(),
      category: input.category,
      priority: input.priority,
      status: 'open',
      locationId: input.locationId,
      locationType: input.locationType.trim(),
      reportedBy: input.reportedBy,
      assignedTo: null,
      scheduledDate: input.scheduledDate ?? null,
      startedAt: null,
      completedAt: null,
      estimatedHours: input.estimatedHours ?? null,
      actualHours: null,
      laborCost: null,
      partsCost: null,
      notes: input.notes?.trim() ?? null,
    });

    logger.info('Work order created', { workOrderId: workOrder.id, title: workOrder.title });
    return workOrder;
  }

  async function getWorkOrder(id: string): Promise<WorkOrder | null> {
    validateUUID(id, 'work_order');
    return repository.getById(id);
  }

  async function updateWorkOrder(id: string, input: UpdateWorkOrderInput): Promise<WorkOrder> {
    validateUUID(id, 'work_order');

    const order = await repository.getById(id);
    if (!order) {
      throw new MaintenanceServiceError('Work order not found', 'WORK_ORDER_NOT_FOUND', 404);
    }

    if (['completed', 'cancelled'].includes(order.status)) {
      throw new MaintenanceServiceError('Cannot update finalized work order', 'WORK_ORDER_FINALIZED');
    }

    if (input.title !== undefined) {
      validateTitle(input.title);
    }

    if (input.priority !== undefined) {
      validatePriority(input.priority);
    }

    const updated = await repository.update(id, {
      ...(input.title && { title: input.title.trim() }),
      ...(input.description && { description: input.description.trim() }),
      ...(input.priority && { priority: input.priority }),
      ...(input.scheduledDate !== undefined && { scheduledDate: input.scheduledDate }),
      ...(input.estimatedHours !== undefined && { estimatedHours: input.estimatedHours }),
      ...(input.notes !== undefined && { notes: input.notes?.trim() ?? null }),
    });

    logger.info('Work order updated', { workOrderId: id });
    return updated;
  }

  async function deleteWorkOrder(id: string): Promise<void> {
    validateUUID(id, 'work_order');

    const order = await repository.getById(id);
    if (!order) {
      throw new MaintenanceServiceError('Work order not found', 'WORK_ORDER_NOT_FOUND', 404);
    }

    await repository.delete(id);
    logger.info('Work order deleted', { workOrderId: id });
  }

  async function listWorkOrders(filters?: WorkOrderFilters): Promise<WorkOrder[]> {
    return repository.list(filters);
  }

  // ============================================
  // WORKFLOW
  // ============================================

  async function assignWorkOrder(id: string, assignedTo: string): Promise<WorkOrder> {
    validateUUID(id, 'work_order');
    validateUUID(assignedTo, 'assignee');

    const order = await repository.getById(id);
    if (!order) {
      throw new MaintenanceServiceError('Work order not found', 'WORK_ORDER_NOT_FOUND', 404);
    }

    if (!['open', 'assigned'].includes(order.status)) {
      throw new MaintenanceServiceError(
        `Cannot assign work order with status: ${order.status}`,
        'INVALID_STATUS_TRANSITION'
      );
    }

    const updated = await repository.update(id, {
      assignedTo,
      status: 'assigned',
    });

    logger.info('Work order assigned', { workOrderId: id, assignedTo });
    return updated;
  }

  async function unassignWorkOrder(id: string): Promise<WorkOrder> {
    validateUUID(id, 'work_order');

    const order = await repository.getById(id);
    if (!order) {
      throw new MaintenanceServiceError('Work order not found', 'WORK_ORDER_NOT_FOUND', 404);
    }

    if (order.status !== 'assigned') {
      throw new MaintenanceServiceError(
        'Only assigned work orders can be unassigned',
        'INVALID_STATUS_TRANSITION'
      );
    }

    const updated = await repository.update(id, {
      assignedTo: null,
      status: 'open',
    });

    logger.info('Work order unassigned', { workOrderId: id });
    return updated;
  }

  async function startWorkOrder(id: string): Promise<WorkOrder> {
    validateUUID(id, 'work_order');

    const order = await repository.getById(id);
    if (!order) {
      throw new MaintenanceServiceError('Work order not found', 'WORK_ORDER_NOT_FOUND', 404);
    }

    if (!['assigned', 'pending_parts'].includes(order.status)) {
      throw new MaintenanceServiceError(
        `Cannot start work order with status: ${order.status}`,
        'INVALID_STATUS_TRANSITION'
      );
    }

    const updated = await repository.update(id, {
      status: 'in_progress',
      startedAt: order.startedAt ?? new Date().toISOString(),
    });

    logger.info('Work order started', { workOrderId: id });
    return updated;
  }

  async function setPendingParts(id: string): Promise<WorkOrder> {
    validateUUID(id, 'work_order');

    const order = await repository.getById(id);
    if (!order) {
      throw new MaintenanceServiceError('Work order not found', 'WORK_ORDER_NOT_FOUND', 404);
    }

    if (!['assigned', 'in_progress'].includes(order.status)) {
      throw new MaintenanceServiceError(
        `Cannot set pending parts for status: ${order.status}`,
        'INVALID_STATUS_TRANSITION'
      );
    }

    const updated = await repository.update(id, {
      status: 'pending_parts',
    });

    logger.info('Work order waiting for parts', { workOrderId: id });
    return updated;
  }

  async function completeWorkOrder(id: string, input: CompleteWorkOrderInput): Promise<WorkOrder> {
    validateUUID(id, 'work_order');

    if (input.actualHours < 0) {
      throw new MaintenanceServiceError('Actual hours cannot be negative', 'INVALID_HOURS');
    }

    const order = await repository.getById(id);
    if (!order) {
      throw new MaintenanceServiceError('Work order not found', 'WORK_ORDER_NOT_FOUND', 404);
    }

    if (order.status !== 'in_progress') {
      throw new MaintenanceServiceError(
        'Only in-progress work orders can be completed',
        'INVALID_STATUS_TRANSITION'
      );
    }

    // Calculate parts cost
    const parts = await repository.getParts(id);
    const partsCost = parts.reduce((sum, p) => sum + p.totalCost, 0);

    const updated = await repository.update(id, {
      status: 'completed',
      completedAt: new Date().toISOString(),
      actualHours: input.actualHours,
      laborCost: input.laborCost ?? null,
      partsCost,
      notes: input.notes ? (order.notes ? `${order.notes}\n${input.notes}` : input.notes) : order.notes,
    });

    logger.info('Work order completed', { workOrderId: id, actualHours: input.actualHours });
    return updated;
  }

  async function cancelWorkOrder(id: string, reason?: string): Promise<WorkOrder> {
    validateUUID(id, 'work_order');

    const order = await repository.getById(id);
    if (!order) {
      throw new MaintenanceServiceError('Work order not found', 'WORK_ORDER_NOT_FOUND', 404);
    }

    if (order.status === 'cancelled') {
      throw new MaintenanceServiceError('Work order is already cancelled', 'ALREADY_CANCELLED');
    }

    if (order.status === 'completed') {
      throw new MaintenanceServiceError('Cannot cancel completed work order', 'WORK_ORDER_COMPLETED');
    }

    const notes = reason
      ? (order.notes ? `${order.notes}\n\nCancellation: ${reason}` : `Cancellation: ${reason}`)
      : order.notes;

    const updated = await repository.update(id, {
      status: 'cancelled',
      notes,
    });

    logger.info('Work order cancelled', { workOrderId: id, reason });
    return updated;
  }

  async function reopenWorkOrder(id: string): Promise<WorkOrder> {
    validateUUID(id, 'work_order');

    const order = await repository.getById(id);
    if (!order) {
      throw new MaintenanceServiceError('Work order not found', 'WORK_ORDER_NOT_FOUND', 404);
    }

    if (order.status !== 'cancelled') {
      throw new MaintenanceServiceError('Only cancelled work orders can be reopened', 'INVALID_STATUS_TRANSITION');
    }

    const updated = await repository.update(id, {
      status: 'open',
      assignedTo: null,
    });

    logger.info('Work order reopened', { workOrderId: id });
    return updated;
  }

  // ============================================
  // PARTS MANAGEMENT
  // ============================================

  async function addPart(input: AddPartInput): Promise<WorkOrderPart> {
    validateUUID(input.workOrderId, 'work_order');

    const order = await repository.getById(input.workOrderId);
    if (!order) {
      throw new MaintenanceServiceError('Work order not found', 'WORK_ORDER_NOT_FOUND', 404);
    }

    if (!input.partName || input.partName.trim().length === 0) {
      throw new MaintenanceServiceError('Part name is required', 'INVALID_PART_NAME');
    }

    if (!Number.isInteger(input.quantity) || input.quantity < 1) {
      throw new MaintenanceServiceError('Quantity must be a positive integer', 'INVALID_QUANTITY');
    }

    if (typeof input.unitCost !== 'number' || input.unitCost < 0) {
      throw new MaintenanceServiceError('Unit cost must be non-negative', 'INVALID_UNIT_COST');
    }

    const totalCost = input.quantity * input.unitCost;

    const part = await repository.addPart({
      workOrderId: input.workOrderId,
      partName: input.partName.trim(),
      partNumber: input.partNumber?.trim() ?? null,
      quantity: input.quantity,
      unitCost: input.unitCost,
      totalCost,
    });

    logger.info('Part added to work order', { workOrderId: input.workOrderId, partId: part.id });
    return part;
  }

  async function getParts(workOrderId: string): Promise<WorkOrderPart[]> {
    validateUUID(workOrderId, 'work_order');

    const order = await repository.getById(workOrderId);
    if (!order) {
      throw new MaintenanceServiceError('Work order not found', 'WORK_ORDER_NOT_FOUND', 404);
    }

    return repository.getParts(workOrderId);
  }

  async function removePart(partId: string): Promise<void> {
    validateUUID(partId, 'part');
    await repository.deletePart(partId);
    logger.info('Part removed from work order', { partId });
  }

  // ============================================
  // REPORTING
  // ============================================

  async function getByLocation(locationId: string): Promise<WorkOrder[]> {
    validateUUID(locationId, 'location');
    return repository.getByLocation(locationId);
  }

  async function getByAssignee(assigneeId: string): Promise<WorkOrder[]> {
    validateUUID(assigneeId, 'assignee');
    return repository.getByAssignee(assigneeId);
  }

  async function getOpenWorkOrders(): Promise<WorkOrder[]> {
    const allOrders = await repository.list();
    return allOrders.filter(o => !['completed', 'cancelled'].includes(o.status));
  }

  async function getCriticalWorkOrders(): Promise<WorkOrder[]> {
    const allOrders = await repository.list({ priority: 'critical' });
    return allOrders.filter(o => !['completed', 'cancelled'].includes(o.status));
  }

  async function getStats(): Promise<MaintenanceStats> {
    const orders = await repository.list();

    const byStatus: Record<WorkOrderStatus, number> = {
      open: 0,
      assigned: 0,
      in_progress: 0,
      pending_parts: 0,
      completed: 0,
      cancelled: 0,
    };

    const byPriority: Record<WorkOrderPriority, number> = {
      low: 0,
      medium: 0,
      high: 0,
      critical: 0,
    };

    const byCategory: Record<WorkOrderCategory, number> = {
      electrical: 0,
      plumbing: 0,
      hvac: 0,
      structural: 0,
      appliance: 0,
      general: 0,
    };

    let totalHours = 0;
    let hoursCount = 0;
    let totalLaborCost = 0;
    let totalPartsCost = 0;

    for (const order of orders) {
      byStatus[order.status]++;
      byPriority[order.priority]++;
      byCategory[order.category]++;

      if (order.actualHours !== null) {
        totalHours += order.actualHours;
        hoursCount++;
      }

      if (order.laborCost !== null) {
        totalLaborCost += order.laborCost;
      }

      if (order.partsCost !== null) {
        totalPartsCost += order.partsCost;
      }
    }

    return {
      totalWorkOrders: orders.length,
      byStatus,
      byPriority,
      byCategory,
      avgCompletionHours: hoursCount > 0 ? totalHours / hoursCount : 0,
      totalLaborCost,
      totalPartsCost,
    };
  }

  // ============================================
  // UTILITY
  // ============================================

  function getPriorities(): WorkOrderPriority[] {
    return [...PRIORITIES];
  }

  function getStatuses(): WorkOrderStatus[] {
    return [...STATUSES];
  }

  function getCategories(): WorkOrderCategory[] {
    return [...CATEGORIES];
  }

  return {
    createWorkOrder,
    getWorkOrder,
    updateWorkOrder,
    deleteWorkOrder,
    listWorkOrders,
    assignWorkOrder,
    unassignWorkOrder,
    startWorkOrder,
    setPendingParts,
    completeWorkOrder,
    cancelWorkOrder,
    reopenWorkOrder,
    addPart,
    getParts,
    removePart,
    getByLocation,
    getByAssignee,
    getOpenWorkOrders,
    getCriticalWorkOrders,
    getStats,
    getPriorities,
    getStatuses,
    getCategories,
  };
}

/**
 * Order Service
 *
 * Business logic for restaurant order operations with dependency injection.
 * Handles order creation, status updates, and cancellations.
 */

import type {
  RestaurantRepository,
  RestaurantOrder,
  RestaurantOrderItem,
  RestaurantMenuItem,
  EmailService,
  LoggerService,
  ActivityLoggerService,
  SocketEmitter,
  AppConfig,
} from '../container/types.js';

// ============================================
// ERROR TYPES
// ============================================

export class OrderServiceError extends Error {
  constructor(
    message: string,
    public code: string,
    public statusCode: number = 400
  ) {
    super(message);
    this.name = 'OrderServiceError';
  }
}

// ============================================
// SERVICE TYPES
// ============================================

export interface CreateOrderInput {
  customerId?: string;
  customerName: string;
  customerEmail?: string;
  customerPhone?: string;
  orderType: 'dine_in' | 'takeaway' | 'delivery' | 'room_service';
  tableId?: string;
  items: Array<{
    menuItemId: string;
    quantity: number;
    specialInstructions?: string;
  }>;
  specialInstructions?: string;
  paymentMethod?: string;
}

export interface OrderResult {
  order: RestaurantOrder;
  items: RestaurantOrderItem[];
}

export interface OrderServiceDeps {
  restaurantRepository: RestaurantRepository;
  emailService: EmailService;
  logger: LoggerService;
  activityLogger: ActivityLoggerService;
  socketEmitter: SocketEmitter;
  config: AppConfig;
}

// Valid status transitions
const VALID_TRANSITIONS: Record<RestaurantOrder['status'], RestaurantOrder['status'][]> = {
  pending: ['confirmed', 'cancelled'],
  confirmed: ['preparing', 'cancelled'],
  preparing: ['ready', 'cancelled'],
  ready: ['served', 'completed', 'delivered', 'cancelled'],
  served: ['completed', 'cancelled'],
  delivered: ['completed'],
  completed: [],
  cancelled: [],
};

// Tax and fee constants
const TAX_RATE = 0.11;
const SERVICE_CHARGE_RATE = 0.10;
const DELIVERY_FEE = 5;

function generateOrderNumber(): string {
  const date = new Date();
  const dateStr = date.toISOString().slice(2, 10).replace(/-/g, '');
  const random = Math.floor(Math.random() * 1000000).toString().padStart(6, '0');
  const suffix = Date.now().toString(36).slice(-4);
  return `R-${dateStr}-${random}${suffix}`;
}

// ============================================
// SERVICE INTERFACE
// ============================================

export interface OrderService {
  createOrder(input: CreateOrderInput): Promise<OrderResult>;
  getOrderById(id: string): Promise<OrderResult | null>;
  getOrderByNumber(orderNumber: string): Promise<RestaurantOrder | null>;
  getOrders(filters: { status?: string; orderType?: string }): Promise<RestaurantOrder[]>;
  getLiveOrders(): Promise<RestaurantOrder[]>;
  getOrdersByCustomer(customerId: string): Promise<RestaurantOrder[]>;
  updateOrderStatus(id: string, status: RestaurantOrder['status'], userId?: string): Promise<RestaurantOrder>;
  cancelOrder(id: string, reason: string, userId?: string): Promise<RestaurantOrder>;
}

// ============================================
// SERVICE FACTORY
// ============================================

export function createOrderService(deps: OrderServiceDeps): OrderService {
  const { restaurantRepository, emailService, logger, activityLogger, socketEmitter, config } = deps;

  return {
    async createOrder(input: CreateOrderInput): Promise<OrderResult> {
      // Validate items
      if (!input.items || input.items.length === 0) {
        throw new OrderServiceError('Order must have at least one item', 'EMPTY_ORDER');
      }

      // Validate quantities
      for (const item of input.items) {
        if (!item.quantity || item.quantity < 1) {
          throw new OrderServiceError('Item quantity must be at least 1', 'INVALID_QUANTITY');
        }
      }

      // Fetch all menu items
      const menuItemIds = input.items.map(i => i.menuItemId);
      const menuItems = await restaurantRepository.getMenuItemsByIds(menuItemIds);
      const menuItemMap = new Map<string, RestaurantMenuItem>();
      for (const mi of menuItems) {
        menuItemMap.set(mi.id, mi);
      }

      // Validate all items exist and are available
      for (const item of input.items) {
        const menuItem = menuItemMap.get(item.menuItemId);
        if (!menuItem) {
          throw new OrderServiceError(
            `Menu item ${item.menuItemId} not found`,
            'MENU_ITEM_NOT_FOUND',
            404
          );
        }
        if (!menuItem.is_available) {
          throw new OrderServiceError(
            `Menu item ${menuItem.name} is not available`,
            'ITEM_UNAVAILABLE'
          );
        }
      }

      // Calculate totals
      let subtotal = 0;
      for (const item of input.items) {
        const menuItem = menuItemMap.get(item.menuItemId)!;
        subtotal += parseFloat(menuItem.price) * item.quantity;
      }

      const taxAmount = Math.round(subtotal * TAX_RATE * 100) / 100;
      const serviceCharge = input.orderType === 'dine_in'
        ? Math.round(subtotal * SERVICE_CHARGE_RATE * 100) / 100
        : 0;
      const deliveryFee = input.orderType === 'delivery' ? DELIVERY_FEE : 0;
      const totalAmount = Math.round((subtotal + taxAmount + serviceCharge + deliveryFee) * 100) / 100;

      const orderNumber = generateOrderNumber();

      // Create order in repository
      const order = await restaurantRepository.createOrder({
        order_number: orderNumber,
        customer_id: input.customerId,
        customer_name: input.customerName,
        customer_email: input.customerEmail,
        customer_phone: input.customerPhone,
        module_id: 'restaurant',
        order_type: input.orderType,
        table_id: input.tableId,
        status: 'pending',
        subtotal: subtotal.toFixed(2),
        tax_amount: taxAmount.toFixed(2),
        service_charge: serviceCharge.toFixed(2),
        delivery_fee: deliveryFee.toFixed(2),
        discount_amount: '0',
        total_amount: totalAmount.toFixed(2),
        payment_status: 'pending',
        payment_method: input.paymentMethod,
        special_instructions: input.specialInstructions,
      } as Omit<RestaurantOrder, 'id' | 'created_at' | 'updated_at'>);

      // Create order items
      const orderItemsData = input.items.map(item => {
        const menuItem = menuItemMap.get(item.menuItemId)!;
        return {
          order_id: order.id,
          menu_item_id: item.menuItemId,
          quantity: item.quantity,
          unit_price: menuItem.price,
          subtotal: (parseFloat(menuItem.price) * item.quantity).toFixed(2),
          special_instructions: item.specialInstructions,
        } as Omit<RestaurantOrderItem, 'id' | 'created_at'>;
      });

      const items = await restaurantRepository.createOrderItems(orderItemsData);

      // Emit socket event
      socketEmitter.emitToUnit('restaurant', 'order:new', {
        orderId: order.id,
        orderNumber: order.order_number,
        orderType: input.orderType,
        customerName: input.customerName,
        totalAmount,
      });

      // Log activity
      await activityLogger.log(
        'CREATE_ORDER',
        {
          orderId: order.id,
          orderNumber: order.order_number,
          itemCount: input.items.length,
          totalAmount,
        },
        input.customerId
      );

      logger.info('Order created', { orderId: order.id, orderNumber: order.order_number });

      return { order, items };
    },

    async getOrderById(id: string): Promise<OrderResult | null> {
      const order = await restaurantRepository.getOrderById(id);
      if (!order) return null;
      const items = await restaurantRepository.getOrderItems(order.id);
      return { order, items };
    },

    async getOrderByNumber(orderNumber: string): Promise<RestaurantOrder | null> {
      return restaurantRepository.getOrderByNumber(orderNumber);
    },

    async getOrders(filters: { status?: string; orderType?: string }): Promise<RestaurantOrder[]> {
      return restaurantRepository.getOrders({ status: filters.status });
    },

    async getLiveOrders(): Promise<RestaurantOrder[]> {
      return restaurantRepository.getLiveOrders();
    },

    async getOrdersByCustomer(customerId: string): Promise<RestaurantOrder[]> {
      return restaurantRepository.getOrdersByCustomer(customerId);
    },

    async updateOrderStatus(id: string, status: RestaurantOrder['status'], userId?: string): Promise<RestaurantOrder> {
      const order = await restaurantRepository.getOrderById(id);
      if (!order) {
        throw new OrderServiceError('Order not found', 'ORDER_NOT_FOUND', 404);
      }

      // Validate status transition
      const allowedTransitions = VALID_TRANSITIONS[order.status];
      if (!allowedTransitions || !allowedTransitions.includes(status)) {
        throw new OrderServiceError(
          `Cannot transition from ${order.status} to ${status}`,
          'INVALID_STATUS_TRANSITION'
        );
      }

      const previousStatus = order.status;
      const updated = await restaurantRepository.updateOrder(id, { status });

      // Emit socket event
      socketEmitter.emitToUnit('restaurant', 'order:status', {
        orderId: id,
        status,
        previousStatus,
      });

      // Log activity
      await activityLogger.log(
        'UPDATE_ORDER_STATUS',
        { orderId: id, from: previousStatus, to: status },
        userId
      );

      logger.info('Order status updated', { orderId: id, from: previousStatus, to: status });

      return updated;
    },

    async cancelOrder(id: string, reason: string, userId?: string): Promise<RestaurantOrder> {
      const order = await restaurantRepository.getOrderById(id);
      if (!order) {
        throw new OrderServiceError('Order not found', 'ORDER_NOT_FOUND', 404);
      }

      if (order.status === 'completed') {
        throw new OrderServiceError('Cannot cancel a completed order', 'CANNOT_CANCEL');
      }
      if (order.status === 'cancelled') {
        throw new OrderServiceError('Order is already cancelled', 'ALREADY_CANCELLED');
      }

      const updated = await restaurantRepository.updateOrder(id, {
        status: 'cancelled',
        cancellation_reason: reason,
        cancelled_at: new Date().toISOString(),
      });

      // Emit socket event
      socketEmitter.emitToUnit('restaurant', 'order:cancelled', {
        orderId: id,
        reason,
      });

      // Log activity
      await activityLogger.log(
        'CANCEL_ORDER',
        { orderId: id, reason },
        userId
      );

      logger.info('Order cancelled', { orderId: id, reason });

      return updated;
    },
  };
}

/**
 * Package/Promotion Service
 *
 * Manages promotional packages and bundled offers.
 */

import type {
  Container,
  Package,
  PackageRedemption,
  PackageFilters,
  PackageType,
  PackageStatus,
} from '../container/types.js';

// Error handling
export class PackageServiceError extends Error {
  constructor(
    message: string,
    public code: string,
    public statusCode: number = 400
  ) {
    super(message);
    this.name = 'PackageServiceError';
  }
}

// Input types
export interface CreatePackageInput {
  name: string;
  code: string;
  type: PackageType;
  description: string;
  shortDescription?: string;
  includes: string[];
  basePrice: number;
  discountPercentage?: number;
  minNights?: number;
  maxNights?: number;
  validFrom: string;
  validTo: string;
  maxRedemptions?: number;
  roomTypeIds?: string[];
  imageUrl?: string;
  termsAndConditions?: string;
}

export interface UpdatePackageInput {
  name?: string;
  description?: string;
  shortDescription?: string;
  includes?: string[];
  basePrice?: number;
  discountPercentage?: number;
  minNights?: number;
  maxNights?: number;
  validFrom?: string;
  validTo?: string;
  maxRedemptions?: number;
  roomTypeIds?: string[];
  imageUrl?: string;
  termsAndConditions?: string;
}

export interface RedeemPackageInput {
  packageId: string;
  bookingId: string;
  guestId: string;
}

export interface PackageStats {
  totalPackages: number;
  activePackages: number;
  totalRedemptions: number;
  totalRevenue: number;
  totalDiscounts: number;
  byType: Record<PackageType, number>;
  byStatus: Record<PackageStatus, number>;
  topPackages: { id: string; name: string; redemptions: number }[];
}

// Validation helpers
const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const PACKAGE_TYPES: PackageType[] = ['room_only', 'bed_and_breakfast', 'half_board', 'full_board', 'all_inclusive', 'spa', 'romantic', 'family', 'adventure', 'custom'];
const PACKAGE_STATUSES: PackageStatus[] = ['draft', 'active', 'inactive', 'expired', 'sold_out'];

export interface PackageService {
  // Package operations
  createPackage(input: CreatePackageInput): Promise<Package>;
  getPackage(id: string): Promise<Package | null>;
  getPackageByCode(code: string): Promise<Package | null>;
  updatePackage(id: string, input: UpdatePackageInput): Promise<Package>;
  deletePackage(id: string): Promise<void>;
  listPackages(filters?: PackageFilters): Promise<Package[]>;
  
  // Status management
  activatePackage(id: string): Promise<Package>;
  deactivatePackage(id: string): Promise<Package>;
  publishPackage(id: string): Promise<Package>;
  
  // Availability
  checkAvailability(id: string, checkIn: string, nights: number): Promise<boolean>;
  getAvailablePackages(checkIn: string, nights: number): Promise<Package[]>;
  
  // Redemption
  redeemPackage(input: RedeemPackageInput): Promise<PackageRedemption>;
  getPackageRedemptions(packageId: string): Promise<PackageRedemption[]>;
  getGuestRedemptions(guestId: string): Promise<PackageRedemption[]>;
  
  // Pricing
  calculatePrice(id: string, nights: number): Promise<{ baseTotal: number; discount: number; finalTotal: number }>;
  applyDiscount(id: string, discountPercentage: number): Promise<Package>;
  
  // Analytics
  getStats(): Promise<PackageStats>;
  
  // Utilities
  getPackageTypes(): PackageType[];
  getPackageStatuses(): PackageStatus[];
}

export function createPackageService(container: Container): PackageService {
  const { packageRepository, logger } = container;

  // ============================================
  // PACKAGE OPERATIONS
  // ============================================
  async function createPackage(input: CreatePackageInput): Promise<Package> {
    // Validate name
    if (!input.name || input.name.trim().length === 0) {
      throw new PackageServiceError('Package name is required', 'INVALID_NAME');
    }

    // Validate code
    if (!input.code || input.code.trim().length === 0) {
      throw new PackageServiceError('Package code is required', 'INVALID_CODE');
    }

    // Check for duplicate code
    const existing = await packageRepository.getByCode(input.code.toUpperCase());
    if (existing) {
      throw new PackageServiceError('Package code already exists', 'DUPLICATE_CODE');
    }

    // Validate type
    if (!PACKAGE_TYPES.includes(input.type)) {
      throw new PackageServiceError('Invalid package type', 'INVALID_TYPE');
    }

    // Validate description
    if (!input.description || input.description.trim().length < 10) {
      throw new PackageServiceError('Description must be at least 10 characters', 'INVALID_DESCRIPTION');
    }

    // Validate includes
    if (!input.includes || input.includes.length === 0) {
      throw new PackageServiceError('Package must include at least one item', 'INVALID_INCLUDES');
    }

    // Validate base price
    if (input.basePrice <= 0) {
      throw new PackageServiceError('Base price must be positive', 'INVALID_PRICE');
    }

    // Validate discount
    if (input.discountPercentage !== undefined && (input.discountPercentage < 0 || input.discountPercentage > 100)) {
      throw new PackageServiceError('Discount must be between 0 and 100', 'INVALID_DISCOUNT');
    }

    // Validate dates
    const validFrom = new Date(input.validFrom);
    const validTo = new Date(input.validTo);
    if (isNaN(validFrom.getTime()) || isNaN(validTo.getTime())) {
      throw new PackageServiceError('Invalid validity dates', 'INVALID_DATES');
    }
    if (validTo <= validFrom) {
      throw new PackageServiceError('End date must be after start date', 'INVALID_DATE_RANGE');
    }

    // Validate nights
    const minNights = input.minNights ?? 1;
    const maxNights = input.maxNights ?? 30;
    if (minNights < 1) {
      throw new PackageServiceError('Minimum nights must be at least 1', 'INVALID_MIN_NIGHTS');
    }
    if (maxNights < minNights) {
      throw new PackageServiceError('Maximum nights must be at least minimum nights', 'INVALID_MAX_NIGHTS');
    }

    // Calculate final price
    const discountPercentage = input.discountPercentage ?? 0;
    const finalPrice = input.basePrice * (1 - discountPercentage / 100);

    const pkg = await packageRepository.create({
      name: input.name.trim(),
      code: input.code.trim().toUpperCase(),
      type: input.type,
      status: 'draft',
      description: input.description.trim(),
      shortDescription: input.shortDescription || null,
      includes: input.includes,
      basePrice: input.basePrice,
      discountPercentage,
      finalPrice: Math.round(finalPrice * 100) / 100,
      minNights,
      maxNights,
      validFrom: input.validFrom,
      validTo: input.validTo,
      maxRedemptions: input.maxRedemptions ?? null,
      currentRedemptions: 0,
      roomTypeIds: input.roomTypeIds || [],
      imageUrl: input.imageUrl || null,
      termsAndConditions: input.termsAndConditions || null,
    });

    logger?.info?.(`Package created: ${pkg.name} (${pkg.code})`);
    return pkg;
  }

  async function getPackage(id: string): Promise<Package | null> {
    if (!UUID_REGEX.test(id)) {
      throw new PackageServiceError('Invalid package ID format', 'INVALID_PACKAGE_ID');
    }
    return packageRepository.getById(id);
  }

  async function getPackageByCode(code: string): Promise<Package | null> {
    return packageRepository.getByCode(code.toUpperCase());
  }

  async function updatePackage(id: string, input: UpdatePackageInput): Promise<Package> {
    const pkg = await getPackageOrThrow(id);

    // Validate discount if provided
    if (input.discountPercentage !== undefined && (input.discountPercentage < 0 || input.discountPercentage > 100)) {
      throw new PackageServiceError('Discount must be between 0 and 100', 'INVALID_DISCOUNT');
    }

    // Recalculate final price if base price or discount changed
    let updates: Partial<Package> = { ...input };
    const basePrice = input.basePrice ?? pkg.basePrice;
    const discount = input.discountPercentage ?? pkg.discountPercentage;
    updates.finalPrice = Math.round(basePrice * (1 - discount / 100) * 100) / 100;

    return packageRepository.update(id, updates);
  }

  async function deletePackage(id: string): Promise<void> {
    const pkg = await getPackageOrThrow(id);

    if (pkg.status === 'active') {
      throw new PackageServiceError('Cannot delete active package', 'CANNOT_DELETE_ACTIVE');
    }

    // Check for redemptions
    const redemptions = await packageRepository.getRedemptionsForPackage(id);
    if (redemptions.length > 0) {
      throw new PackageServiceError('Cannot delete package with redemptions', 'HAS_REDEMPTIONS');
    }

    await packageRepository.delete(id);
    logger?.info?.(`Package deleted: ${pkg.name} (${pkg.code})`);
  }

  async function listPackages(filters?: PackageFilters): Promise<Package[]> {
    return packageRepository.list(filters);
  }

  // ============================================
  // STATUS MANAGEMENT
  // ============================================
  async function activatePackage(id: string): Promise<Package> {
    const pkg = await getPackageOrThrow(id);

    if (pkg.status === 'active') {
      throw new PackageServiceError('Package is already active', 'ALREADY_ACTIVE');
    }

    // Check if package is valid
    const now = new Date();
    const validTo = new Date(pkg.validTo);
    if (validTo < now) {
      throw new PackageServiceError('Cannot activate expired package', 'PACKAGE_EXPIRED');
    }

    return packageRepository.update(id, { status: 'active' });
  }

  async function deactivatePackage(id: string): Promise<Package> {
    const pkg = await getPackageOrThrow(id);

    if (pkg.status === 'inactive') {
      throw new PackageServiceError('Package is already inactive', 'ALREADY_INACTIVE');
    }

    return packageRepository.update(id, { status: 'inactive' });
  }

  async function publishPackage(id: string): Promise<Package> {
    const pkg = await getPackageOrThrow(id);

    if (pkg.status !== 'draft') {
      throw new PackageServiceError('Only draft packages can be published', 'INVALID_STATUS');
    }

    return packageRepository.update(id, { status: 'active' });
  }

  // ============================================
  // AVAILABILITY
  // ============================================
  async function checkAvailability(id: string, checkIn: string, nights: number): Promise<boolean> {
    const pkg = await getPackageOrThrow(id);

    // Check status
    if (pkg.status !== 'active') {
      return false;
    }

    // Check date range
    const checkInDate = new Date(checkIn);
    const validFrom = new Date(pkg.validFrom);
    const validTo = new Date(pkg.validTo);
    if (checkInDate < validFrom || checkInDate > validTo) {
      return false;
    }

    // Check nights
    if (nights < pkg.minNights || nights > pkg.maxNights) {
      return false;
    }

    // Check redemption limit
    if (pkg.maxRedemptions !== null && pkg.currentRedemptions >= pkg.maxRedemptions) {
      return false;
    }

    return true;
  }

  async function getAvailablePackages(checkIn: string, nights: number): Promise<Package[]> {
    const allPackages = await packageRepository.list({ status: 'active' });
    const available: Package[] = [];

    for (const pkg of allPackages) {
      const isAvailable = await checkAvailability(pkg.id, checkIn, nights);
      if (isAvailable) {
        available.push(pkg);
      }
    }

    return available;
  }

  // ============================================
  // REDEMPTION
  // ============================================
  async function redeemPackage(input: RedeemPackageInput): Promise<PackageRedemption> {
    if (!UUID_REGEX.test(input.packageId)) {
      throw new PackageServiceError('Invalid package ID format', 'INVALID_PACKAGE_ID');
    }

    if (!UUID_REGEX.test(input.bookingId)) {
      throw new PackageServiceError('Invalid booking ID format', 'INVALID_BOOKING_ID');
    }

    if (!UUID_REGEX.test(input.guestId)) {
      throw new PackageServiceError('Invalid guest ID format', 'INVALID_GUEST_ID');
    }

    const pkg = await getPackageOrThrow(input.packageId);

    if (pkg.status !== 'active') {
      throw new PackageServiceError('Package is not active', 'PACKAGE_NOT_ACTIVE');
    }

    // Check redemption limit
    if (pkg.maxRedemptions !== null && pkg.currentRedemptions >= pkg.maxRedemptions) {
      throw new PackageServiceError('Package redemption limit reached', 'REDEMPTION_LIMIT_REACHED');
    }

    const discountAmount = pkg.basePrice - pkg.finalPrice;

    const redemption = await packageRepository.createRedemption({
      packageId: input.packageId,
      bookingId: input.bookingId,
      guestId: input.guestId,
      redeemedAt: new Date().toISOString(),
      totalAmount: pkg.finalPrice,
      discountAmount,
    });

    // Update redemption count
    await packageRepository.update(input.packageId, {
      currentRedemptions: pkg.currentRedemptions + 1,
    });

    // Mark as sold out if limit reached
    if (pkg.maxRedemptions !== null && pkg.currentRedemptions + 1 >= pkg.maxRedemptions) {
      await packageRepository.update(input.packageId, { status: 'sold_out' });
    }

    logger?.info?.(`Package redeemed: ${pkg.name} for booking ${input.bookingId}`);
    return redemption;
  }

  async function getPackageRedemptions(packageId: string): Promise<PackageRedemption[]> {
    if (!UUID_REGEX.test(packageId)) {
      throw new PackageServiceError('Invalid package ID format', 'INVALID_PACKAGE_ID');
    }
    return packageRepository.getRedemptionsForPackage(packageId);
  }

  async function getGuestRedemptions(guestId: string): Promise<PackageRedemption[]> {
    if (!UUID_REGEX.test(guestId)) {
      throw new PackageServiceError('Invalid guest ID format', 'INVALID_GUEST_ID');
    }
    return packageRepository.getRedemptionsForGuest(guestId);
  }

  // ============================================
  // PRICING
  // ============================================
  async function calculatePrice(id: string, nights: number): Promise<{ baseTotal: number; discount: number; finalTotal: number }> {
    const pkg = await getPackageOrThrow(id);

    if (nights < pkg.minNights) {
      throw new PackageServiceError(`Minimum ${pkg.minNights} nights required`, 'BELOW_MIN_NIGHTS');
    }

    if (nights > pkg.maxNights) {
      throw new PackageServiceError(`Maximum ${pkg.maxNights} nights allowed`, 'ABOVE_MAX_NIGHTS');
    }

    const baseTotal = pkg.basePrice * nights;
    const discount = baseTotal * (pkg.discountPercentage / 100);
    const finalTotal = baseTotal - discount;

    return {
      baseTotal: Math.round(baseTotal * 100) / 100,
      discount: Math.round(discount * 100) / 100,
      finalTotal: Math.round(finalTotal * 100) / 100,
    };
  }

  async function applyDiscount(id: string, discountPercentage: number): Promise<Package> {
    await getPackageOrThrow(id);

    if (discountPercentage < 0 || discountPercentage > 100) {
      throw new PackageServiceError('Discount must be between 0 and 100', 'INVALID_DISCOUNT');
    }

    return updatePackage(id, { discountPercentage });
  }

  // ============================================
  // ANALYTICS
  // ============================================
  async function getStats(): Promise<PackageStats> {
    const packages = await packageRepository.list();

    const byType: Record<PackageType, number> = {
      room_only: 0,
      bed_and_breakfast: 0,
      half_board: 0,
      full_board: 0,
      all_inclusive: 0,
      spa: 0,
      romantic: 0,
      family: 0,
      adventure: 0,
      custom: 0,
    };

    const byStatus: Record<PackageStatus, number> = {
      draft: 0,
      active: 0,
      inactive: 0,
      expired: 0,
      sold_out: 0,
    };

    let totalRevenue = 0;
    let totalDiscounts = 0;
    let totalRedemptions = 0;

    const packageRedemptionCounts: { id: string; name: string; redemptions: number }[] = [];

    for (const pkg of packages) {
      byType[pkg.type]++;
      byStatus[pkg.status]++;

      const redemptions = await packageRepository.getRedemptionsForPackage(pkg.id);
      totalRedemptions += redemptions.length;

      packageRedemptionCounts.push({
        id: pkg.id,
        name: pkg.name,
        redemptions: redemptions.length,
      });

      for (const r of redemptions) {
        totalRevenue += r.totalAmount;
        totalDiscounts += r.discountAmount;
      }
    }

    // Top packages by redemptions
    const topPackages = packageRedemptionCounts
      .sort((a, b) => b.redemptions - a.redemptions)
      .slice(0, 5);

    return {
      totalPackages: packages.length,
      activePackages: byStatus.active,
      totalRedemptions,
      totalRevenue: Math.round(totalRevenue * 100) / 100,
      totalDiscounts: Math.round(totalDiscounts * 100) / 100,
      byType,
      byStatus,
      topPackages,
    };
  }

  // ============================================
  // UTILITIES
  // ============================================
  function getPackageTypes(): PackageType[] {
    return [...PACKAGE_TYPES];
  }

  function getPackageStatuses(): PackageStatus[] {
    return [...PACKAGE_STATUSES];
  }

  // Helper
  async function getPackageOrThrow(id: string): Promise<Package> {
    if (!UUID_REGEX.test(id)) {
      throw new PackageServiceError('Invalid package ID format', 'INVALID_PACKAGE_ID');
    }

    const pkg = await packageRepository.getById(id);
    if (!pkg) {
      throw new PackageServiceError('Package not found', 'PACKAGE_NOT_FOUND', 404);
    }

    return pkg;
  }

  return {
    createPackage,
    getPackage,
    getPackageByCode,
    updatePackage,
    deletePackage,
    listPackages,
    activatePackage,
    deactivatePackage,
    publishPackage,
    checkAvailability,
    getAvailablePackages,
    redeemPackage,
    getPackageRedemptions,
    getGuestRedemptions,
    calculatePrice,
    applyDiscount,
    getStats,
    getPackageTypes,
    getPackageStatuses,
  };
}

/**
 * Weather Service
 * 
 * Provides weather data, forecasts, alerts, and activity recommendations
 * for resort guests. Supports multiple locations, weather history, and
 * smart activity suggestions based on current conditions.
 */

import type { 
  Container,
  WeatherRepository,
  WeatherData,
  WeatherAlert,
  WeatherForecast,
  ActivityRecommendation,
  WeatherCondition,
} from '../container/types';

// ============================================
// TYPES
// ============================================

export interface RecordWeatherInput {
  location: string;
  date: string;
  condition: string;
  temperatureHigh: number;
  temperatureLow: number;
  temperatureCurrent: number;
  humidity: number;
  windSpeed: number;
  windDirection?: string;
  uvIndex?: number;
  precipitation?: number;
  visibility?: number;
  sunrise?: string;
  sunset?: string;
}

export interface UpdateWeatherInput {
  condition?: string;
  temperatureHigh?: number;
  temperatureLow?: number;
  temperatureCurrent?: number;
  humidity?: number;
  windSpeed?: number;
  windDirection?: string;
  uvIndex?: number;
  precipitation?: number;
  visibility?: number;
}

export interface CreateAlertInput {
  type: string;
  severity: string;
  title: string;
  description: string;
  location: string;
  startTime: string;
  endTime: string;
}

export interface CreateActivityInput {
  name: string;
  description: string;
  category: string;
  suitableConditions: string[];
  minTemperature?: number;
  maxTemperature?: number;
  maxWindSpeed?: number;
  maxPrecipitation?: number;
  duration?: number;
  difficulty?: string;
}

export interface UpdateActivityInput {
  name?: string;
  description?: string;
  category?: string;
  suitableConditions?: string[];
  minTemperature?: number;
  maxTemperature?: number;
  maxWindSpeed?: number;
  maxPrecipitation?: number;
  duration?: number;
  difficulty?: string;
  isActive?: boolean;
}

export interface WeatherServiceResult<T> {
  success: boolean;
  data?: T;
  error?: string;
}

// ============================================
// VALIDATION
// ============================================

const WEATHER_CONDITIONS: WeatherCondition[] = [
  'sunny', 'partly_cloudy', 'cloudy', 'rainy', 'stormy', 'snowy', 'foggy', 'windy'
];

const ALERT_TYPES = ['warning', 'watch', 'advisory'] as const;
const ALERT_SEVERITIES = ['minor', 'moderate', 'severe', 'extreme'] as const;
const ACTIVITY_CATEGORIES = ['outdoor', 'indoor', 'water', 'sports', 'relaxation', 'dining'] as const;
const DIFFICULTY_LEVELS = ['easy', 'moderate', 'challenging'] as const;
const WIND_DIRECTIONS = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'] as const;

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function isValidUUID(id: string): boolean {
  return UUID_PATTERN.test(id);
}

function isValidDate(dateStr: string): boolean {
  if (!dateStr) return false;
  const date = new Date(dateStr);
  return !isNaN(date.getTime());
}

function isValidCondition(condition: string): condition is WeatherCondition {
  return WEATHER_CONDITIONS.includes(condition as WeatherCondition);
}

function isValidAlertType(type: string): boolean {
  return ALERT_TYPES.includes(type as typeof ALERT_TYPES[number]);
}

function isValidSeverity(severity: string): boolean {
  return ALERT_SEVERITIES.includes(severity as typeof ALERT_SEVERITIES[number]);
}

function isValidCategory(category: string): boolean {
  return ACTIVITY_CATEGORIES.includes(category as typeof ACTIVITY_CATEGORIES[number]);
}

function isValidDifficulty(difficulty: string): boolean {
  return DIFFICULTY_LEVELS.includes(difficulty as typeof DIFFICULTY_LEVELS[number]);
}

// ============================================
// SERVICE FACTORY
// ============================================

export function createWeatherService(container: Container) {
  const { weatherRepository } = container;

  // ============================================
  // WEATHER DATA OPERATIONS
  // ============================================

  async function recordWeather(input: RecordWeatherInput): Promise<WeatherServiceResult<WeatherData>> {
    // Validate location
    if (!input.location || input.location.trim() === '') {
      return { success: false, error: 'Location is required' };
    }

    // Validate date
    if (!isValidDate(input.date)) {
      return { success: false, error: 'Invalid date format' };
    }

    // Validate condition
    if (!isValidCondition(input.condition)) {
      return { success: false, error: `Invalid condition. Must be one of: ${WEATHER_CONDITIONS.join(', ')}` };
    }

    // Validate temperature
    if (typeof input.temperatureHigh !== 'number' || typeof input.temperatureLow !== 'number') {
      return { success: false, error: 'Temperature high and low are required' };
    }

    if (input.temperatureHigh < input.temperatureLow) {
      return { success: false, error: 'High temperature cannot be lower than low temperature' };
    }

    if (input.temperatureCurrent < input.temperatureLow || input.temperatureCurrent > input.temperatureHigh) {
      return { success: false, error: 'Current temperature must be between low and high' };
    }

    // Validate humidity
    if (typeof input.humidity !== 'number' || input.humidity < 0 || input.humidity > 100) {
      return { success: false, error: 'Humidity must be between 0 and 100' };
    }

    // Validate wind speed
    if (typeof input.windSpeed !== 'number' || input.windSpeed < 0) {
      return { success: false, error: 'Wind speed must be non-negative' };
    }

    // Validate UV index if provided
    if (input.uvIndex !== undefined && (input.uvIndex < 0 || input.uvIndex > 15)) {
      return { success: false, error: 'UV index must be between 0 and 15' };
    }

    // Validate precipitation if provided
    if (input.precipitation !== undefined && input.precipitation < 0) {
      return { success: false, error: 'Precipitation cannot be negative' };
    }

    // Validate visibility if provided
    if (input.visibility !== undefined && input.visibility < 0) {
      return { success: false, error: 'Visibility cannot be negative' };
    }

    const weather = await weatherRepository.saveWeather({
      location: input.location.trim(),
      date: input.date,
      condition: input.condition as WeatherCondition,
      temperatureHigh: input.temperatureHigh,
      temperatureLow: input.temperatureLow,
      temperatureCurrent: input.temperatureCurrent,
      humidity: input.humidity,
      windSpeed: input.windSpeed,
      windDirection: input.windDirection || 'N',
      uvIndex: input.uvIndex ?? 5,
      precipitation: input.precipitation ?? 0,
      visibility: input.visibility ?? 10,
      sunrise: input.sunrise || '06:00',
      sunset: input.sunset || '18:00',
    });

    return { success: true, data: weather };
  }

  async function getCurrentWeather(location: string): Promise<WeatherServiceResult<WeatherData>> {
    if (!location || location.trim() === '') {
      return { success: false, error: 'Location is required' };
    }

    const weather = await weatherRepository.getCurrentWeather(location.trim());
    
    if (!weather) {
      return { success: false, error: 'No weather data found for location' };
    }

    return { success: true, data: weather };
  }

  async function updateWeather(id: string, input: UpdateWeatherInput): Promise<WeatherServiceResult<WeatherData>> {
    if (!isValidUUID(id)) {
      return { success: false, error: 'Invalid weather ID' };
    }

    // Validate condition if provided
    if (input.condition !== undefined && !isValidCondition(input.condition)) {
      return { success: false, error: `Invalid condition. Must be one of: ${WEATHER_CONDITIONS.join(', ')}` };
    }

    // Validate humidity if provided
    if (input.humidity !== undefined && (input.humidity < 0 || input.humidity > 100)) {
      return { success: false, error: 'Humidity must be between 0 and 100' };
    }

    // Validate wind speed if provided
    if (input.windSpeed !== undefined && input.windSpeed < 0) {
      return { success: false, error: 'Wind speed must be non-negative' };
    }

    // Validate UV index if provided
    if (input.uvIndex !== undefined && (input.uvIndex < 0 || input.uvIndex > 15)) {
      return { success: false, error: 'UV index must be between 0 and 15' };
    }

    try {
      const updated = await weatherRepository.updateWeather(id, {
        ...input,
        condition: input.condition as WeatherCondition | undefined,
      });
      return { success: true, data: updated };
    } catch (error) {
      return { success: false, error: 'Weather data not found' };
    }
  }

  async function getWeatherHistory(
    location: string, 
    startDate: string, 
    endDate: string
  ): Promise<WeatherServiceResult<WeatherData[]>> {
    if (!location || location.trim() === '') {
      return { success: false, error: 'Location is required' };
    }

    if (!isValidDate(startDate)) {
      return { success: false, error: 'Invalid start date' };
    }

    if (!isValidDate(endDate)) {
      return { success: false, error: 'Invalid end date' };
    }

    if (new Date(endDate) < new Date(startDate)) {
      return { success: false, error: 'End date cannot be before start date' };
    }

    const history = await weatherRepository.getWeatherHistory(location.trim(), startDate, endDate);
    return { success: true, data: history };
  }

  // ============================================
  // WEATHER ALERTS
  // ============================================

  async function createAlert(input: CreateAlertInput): Promise<WeatherServiceResult<WeatherAlert>> {
    // Validate type
    if (!isValidAlertType(input.type)) {
      return { success: false, error: `Invalid alert type. Must be one of: ${ALERT_TYPES.join(', ')}` };
    }

    // Validate severity
    if (!isValidSeverity(input.severity)) {
      return { success: false, error: `Invalid severity. Must be one of: ${ALERT_SEVERITIES.join(', ')}` };
    }

    // Validate title
    if (!input.title || input.title.trim() === '') {
      return { success: false, error: 'Title is required' };
    }

    // Validate description
    if (!input.description || input.description.trim() === '') {
      return { success: false, error: 'Description is required' };
    }

    // Validate location
    if (!input.location || input.location.trim() === '') {
      return { success: false, error: 'Location is required' };
    }

    // Validate times
    if (!isValidDate(input.startTime)) {
      return { success: false, error: 'Invalid start time' };
    }

    if (!isValidDate(input.endTime)) {
      return { success: false, error: 'Invalid end time' };
    }

    if (new Date(input.endTime) <= new Date(input.startTime)) {
      return { success: false, error: 'End time must be after start time' };
    }

    const alert = await weatherRepository.createAlert({
      type: input.type as 'warning' | 'watch' | 'advisory',
      severity: input.severity as 'minor' | 'moderate' | 'severe' | 'extreme',
      title: input.title.trim(),
      description: input.description.trim(),
      location: input.location.trim(),
      startTime: input.startTime,
      endTime: input.endTime,
      isActive: true,
    });

    return { success: true, data: alert };
  }

  async function getAlerts(location: string): Promise<WeatherServiceResult<WeatherAlert[]>> {
    if (!location || location.trim() === '') {
      return { success: false, error: 'Location is required' };
    }

    const alerts = await weatherRepository.getAlerts(location.trim());
    return { success: true, data: alerts };
  }

  async function deactivateAlert(id: string): Promise<WeatherServiceResult<WeatherAlert>> {
    if (!isValidUUID(id)) {
      return { success: false, error: 'Invalid alert ID' };
    }

    try {
      const updated = await weatherRepository.updateAlert(id, { isActive: false });
      return { success: true, data: updated };
    } catch (error) {
      return { success: false, error: 'Alert not found' };
    }
  }

  async function deleteAlert(id: string): Promise<WeatherServiceResult<void>> {
    if (!isValidUUID(id)) {
      return { success: false, error: 'Invalid alert ID' };
    }

    await weatherRepository.deleteAlert(id);
    return { success: true };
  }

  // ============================================
  // ACTIVITY RECOMMENDATIONS
  // ============================================

  async function createActivity(input: CreateActivityInput): Promise<WeatherServiceResult<ActivityRecommendation>> {
    // Validate name
    if (!input.name || input.name.trim() === '') {
      return { success: false, error: 'Name is required' };
    }

    // Validate description
    if (!input.description || input.description.trim() === '') {
      return { success: false, error: 'Description is required' };
    }

    // Validate category
    if (!isValidCategory(input.category)) {
      return { success: false, error: `Invalid category. Must be one of: ${ACTIVITY_CATEGORIES.join(', ')}` };
    }

    // Validate suitable conditions
    if (!input.suitableConditions || input.suitableConditions.length === 0) {
      return { success: false, error: 'At least one suitable condition is required' };
    }

    for (const cond of input.suitableConditions) {
      if (!isValidCondition(cond)) {
        return { success: false, error: `Invalid condition: ${cond}` };
      }
    }

    // Validate difficulty if provided
    if (input.difficulty !== undefined && !isValidDifficulty(input.difficulty)) {
      return { success: false, error: `Invalid difficulty. Must be one of: ${DIFFICULTY_LEVELS.join(', ')}` };
    }

    // Validate duration if provided
    if (input.duration !== undefined && input.duration <= 0) {
      return { success: false, error: 'Duration must be positive' };
    }

    // Validate temperature range
    const minTemp = input.minTemperature ?? -10;
    const maxTemp = input.maxTemperature ?? 40;
    if (minTemp > maxTemp) {
      return { success: false, error: 'Min temperature cannot be greater than max temperature' };
    }

    // Validate wind speed if provided
    if (input.maxWindSpeed !== undefined && input.maxWindSpeed < 0) {
      return { success: false, error: 'Max wind speed must be non-negative' };
    }

    // Validate precipitation if provided
    if (input.maxPrecipitation !== undefined && input.maxPrecipitation < 0) {
      return { success: false, error: 'Max precipitation must be non-negative' };
    }

    const activity = await weatherRepository.createActivity({
      name: input.name.trim(),
      description: input.description.trim(),
      category: input.category as 'outdoor' | 'indoor' | 'water' | 'sports' | 'relaxation' | 'dining',
      suitableConditions: input.suitableConditions as WeatherCondition[],
      minTemperature: minTemp,
      maxTemperature: maxTemp,
      maxWindSpeed: input.maxWindSpeed ?? 50,
      maxPrecipitation: input.maxPrecipitation ?? 10,
      duration: input.duration ?? 60,
      difficulty: (input.difficulty || 'easy') as 'easy' | 'moderate' | 'challenging',
      isActive: true,
    });

    return { success: true, data: activity };
  }

  async function getActivity(id: string): Promise<WeatherServiceResult<ActivityRecommendation>> {
    if (!isValidUUID(id)) {
      return { success: false, error: 'Invalid activity ID' };
    }

    const activity = await weatherRepository.getActivityById(id);
    
    if (!activity) {
      return { success: false, error: 'Activity not found' };
    }

    return { success: true, data: activity };
  }

  async function updateActivity(id: string, input: UpdateActivityInput): Promise<WeatherServiceResult<ActivityRecommendation>> {
    if (!isValidUUID(id)) {
      return { success: false, error: 'Invalid activity ID' };
    }

    // Validate name if provided
    if (input.name !== undefined && input.name.trim() === '') {
      return { success: false, error: 'Name cannot be empty' };
    }

    // Validate category if provided
    if (input.category !== undefined && !isValidCategory(input.category)) {
      return { success: false, error: `Invalid category. Must be one of: ${ACTIVITY_CATEGORIES.join(', ')}` };
    }

    // Validate conditions if provided
    if (input.suitableConditions !== undefined) {
      if (input.suitableConditions.length === 0) {
        return { success: false, error: 'At least one suitable condition is required' };
      }
      for (const cond of input.suitableConditions) {
        if (!isValidCondition(cond)) {
          return { success: false, error: `Invalid condition: ${cond}` };
        }
      }
    }

    // Validate difficulty if provided
    if (input.difficulty !== undefined && !isValidDifficulty(input.difficulty)) {
      return { success: false, error: `Invalid difficulty. Must be one of: ${DIFFICULTY_LEVELS.join(', ')}` };
    }

    // Validate duration if provided
    if (input.duration !== undefined && input.duration <= 0) {
      return { success: false, error: 'Duration must be positive' };
    }

    try {
      const updated = await weatherRepository.updateActivity(id, {
        ...(input.name !== undefined && { name: input.name.trim() }),
        ...(input.description !== undefined && { description: input.description.trim() }),
        ...(input.category !== undefined && { category: input.category as 'outdoor' | 'indoor' | 'water' | 'sports' | 'relaxation' | 'dining' }),
        ...(input.suitableConditions !== undefined && { suitableConditions: input.suitableConditions as WeatherCondition[] }),
        ...(input.minTemperature !== undefined && { minTemperature: input.minTemperature }),
        ...(input.maxTemperature !== undefined && { maxTemperature: input.maxTemperature }),
        ...(input.maxWindSpeed !== undefined && { maxWindSpeed: input.maxWindSpeed }),
        ...(input.maxPrecipitation !== undefined && { maxPrecipitation: input.maxPrecipitation }),
        ...(input.duration !== undefined && { duration: input.duration }),
        ...(input.difficulty !== undefined && { difficulty: input.difficulty as 'easy' | 'moderate' | 'challenging' }),
        ...(input.isActive !== undefined && { isActive: input.isActive }),
      });
      return { success: true, data: updated };
    } catch (error) {
      return { success: false, error: 'Activity not found' };
    }
  }

  async function deleteActivity(id: string): Promise<WeatherServiceResult<void>> {
    if (!isValidUUID(id)) {
      return { success: false, error: 'Invalid activity ID' };
    }

    await weatherRepository.deleteActivity(id);
    return { success: true };
  }

  async function getRecommendedActivities(location: string): Promise<WeatherServiceResult<ActivityRecommendation[]>> {
    if (!location || location.trim() === '') {
      return { success: false, error: 'Location is required' };
    }

    // Get current weather
    const weather = await weatherRepository.getCurrentWeather(location.trim());
    
    if (!weather) {
      return { success: false, error: 'No weather data available for recommendations' };
    }

    // Get all activities
    const allActivities = await weatherRepository.getActivities();

    // Filter activities suitable for current conditions
    const recommended = allActivities.filter(activity => {
      // Check if weather condition is suitable
      if (!activity.suitableConditions.includes(weather.condition)) {
        return false;
      }

      // Check temperature range
      if (weather.temperatureCurrent < activity.minTemperature || 
          weather.temperatureCurrent > activity.maxTemperature) {
        return false;
      }

      // Check wind speed
      if (weather.windSpeed > activity.maxWindSpeed) {
        return false;
      }

      // Check precipitation
      if (weather.precipitation > activity.maxPrecipitation) {
        return false;
      }

      return true;
    });

    return { success: true, data: recommended };
  }

  // ============================================
  // WEATHER CALCULATIONS
  // ============================================

  function calculateHeatIndex(temperature: number, humidity: number): number {
    // Heat index formula (Fahrenheit-based, then convert to Celsius if needed)
    // Using Steadman's approximation
    if (temperature < 27) {
      return temperature; // Heat index not meaningful below 27°C
    }

    const T = temperature;
    const R = humidity;

    // Rothfusz regression
    let HI = -8.78469475556 + 
             1.61139411 * T + 
             2.33854883889 * R +
             -0.14611605 * T * R +
             -0.012308094 * T * T +
             -0.0164248277778 * R * R +
             0.002211732 * T * T * R +
             0.00072546 * T * R * R +
             -0.000003582 * T * T * R * R;

    return Math.round(HI * 10) / 10;
  }

  function calculateWindChill(temperature: number, windSpeed: number): number {
    // Wind chill formula (valid for temps below 10°C and wind > 4.8 km/h)
    if (temperature > 10 || windSpeed < 4.8) {
      return temperature;
    }

    const T = temperature;
    const V = windSpeed;

    const WC = 13.12 + 0.6215 * T - 11.37 * Math.pow(V, 0.16) + 0.3965 * T * Math.pow(V, 0.16);
    return Math.round(WC * 10) / 10;
  }

  function calculateFeelsLike(temperature: number, humidity: number, windSpeed: number): number {
    if (temperature >= 27) {
      return calculateHeatIndex(temperature, humidity);
    } else if (temperature <= 10 && windSpeed >= 4.8) {
      return calculateWindChill(temperature, windSpeed);
    }
    return temperature;
  }

  function getUVRiskLevel(uvIndex: number): string {
    if (uvIndex <= 2) return 'Low';
    if (uvIndex <= 5) return 'Moderate';
    if (uvIndex <= 7) return 'High';
    if (uvIndex <= 10) return 'Very High';
    return 'Extreme';
  }

  function getSunProtectionAdvice(uvIndex: number): string[] {
    const advice: string[] = [];
    
    if (uvIndex <= 2) {
      advice.push('Minimal sun protection needed for normal activities');
    } else if (uvIndex <= 5) {
      advice.push('Wear sunscreen SPF 30+');
      advice.push('Seek shade during midday hours');
    } else if (uvIndex <= 7) {
      advice.push('Wear sunscreen SPF 30+ and reapply every 2 hours');
      advice.push('Wear protective clothing and a hat');
      advice.push('Seek shade between 10am and 4pm');
    } else if (uvIndex <= 10) {
      advice.push('Wear sunscreen SPF 50+ and reapply frequently');
      advice.push('Wear protective clothing, hat, and UV-blocking sunglasses');
      advice.push('Avoid sun exposure between 10am and 4pm');
      advice.push('Stay in shade whenever possible');
    } else {
      advice.push('Avoid sun exposure if possible');
      advice.push('If outdoors, wear maximum protection');
      advice.push('Apply SPF 50+ every hour');
      advice.push('Stay in shade at all times');
    }
    
    return advice;
  }

  function isGoodBeachDay(weather: WeatherData): boolean {
    return (
      ['sunny', 'partly_cloudy'].includes(weather.condition) &&
      weather.temperatureCurrent >= 25 &&
      weather.temperatureCurrent <= 35 &&
      weather.windSpeed < 20 &&
      weather.precipitation < 5
    );
  }

  function isGoodPoolDay(weather: WeatherData): boolean {
    return (
      !['rainy', 'stormy', 'snowy'].includes(weather.condition) &&
      weather.temperatureCurrent >= 22 &&
      weather.windSpeed < 25 &&
      weather.precipitation < 10
    );
  }

  function isGoodHikingDay(weather: WeatherData): boolean {
    return (
      !['rainy', 'stormy', 'foggy'].includes(weather.condition) &&
      weather.temperatureCurrent >= 10 &&
      weather.temperatureCurrent <= 30 &&
      weather.windSpeed < 30 &&
      weather.precipitation < 5 &&
      weather.visibility >= 5
    );
  }

  // ============================================
  // UTILITY FUNCTIONS
  // ============================================

  function getWeatherConditions(): WeatherCondition[] {
    return [...WEATHER_CONDITIONS];
  }

  function getActivityCategories(): string[] {
    return [...ACTIVITY_CATEGORIES];
  }

  function getDifficultyLevels(): string[] {
    return [...DIFFICULTY_LEVELS];
  }

  function formatTemperature(celsius: number, unit: 'C' | 'F' = 'C'): string {
    if (unit === 'F') {
      const fahrenheit = (celsius * 9/5) + 32;
      return `${Math.round(fahrenheit)}°F`;
    }
    return `${Math.round(celsius)}°C`;
  }

  function formatWindSpeed(kmh: number, unit: 'kmh' | 'mph' | 'knots' = 'kmh'): string {
    switch (unit) {
      case 'mph':
        return `${Math.round(kmh * 0.621371)} mph`;
      case 'knots':
        return `${Math.round(kmh * 0.539957)} knots`;
      default:
        return `${Math.round(kmh)} km/h`;
    }
  }

  function getWeatherIcon(condition: WeatherCondition): string {
    const icons: Record<WeatherCondition, string> = {
      'sunny': '☀️',
      'partly_cloudy': '⛅',
      'cloudy': '☁️',
      'rainy': '🌧️',
      'stormy': '⛈️',
      'snowy': '🌨️',
      'foggy': '🌫️',
      'windy': '💨',
    };
    return icons[condition];
  }

  function getWeatherDescription(condition: WeatherCondition): string {
    const descriptions: Record<WeatherCondition, string> = {
      'sunny': 'Clear skies with plenty of sunshine',
      'partly_cloudy': 'Mix of sun and clouds',
      'cloudy': 'Overcast with gray skies',
      'rainy': 'Expect rain throughout the day',
      'stormy': 'Severe weather with thunder and lightning possible',
      'snowy': 'Snow expected, dress warmly',
      'foggy': 'Reduced visibility due to fog',
      'windy': 'Strong winds expected',
    };
    return descriptions[condition];
  }

  // ============================================
  // RETURN SERVICE
  // ============================================

  return {
    // Weather data
    recordWeather,
    getCurrentWeather,
    updateWeather,
    getWeatherHistory,
    
    // Alerts
    createAlert,
    getAlerts,
    deactivateAlert,
    deleteAlert,
    
    // Activities
    createActivity,
    getActivity,
    updateActivity,
    deleteActivity,
    getRecommendedActivities,
    
    // Calculations
    calculateHeatIndex,
    calculateWindChill,
    calculateFeelsLike,
    getUVRiskLevel,
    getSunProtectionAdvice,
    isGoodBeachDay,
    isGoodPoolDay,
    isGoodHikingDay,
    
    // Utilities
    getWeatherConditions,
    getActivityCategories,
    getDifficultyLevels,
    formatTemperature,
    formatWindSpeed,
    getWeatherIcon,
    getWeatherDescription,
  };
}

/**
 * V2 Resort - API Security Hardening Middleware
 * Comprehensive security middleware for API protection
 */

import { Request, Response, NextFunction } from 'express';
import crypto from 'crypto';
import rateLimit from 'express-rate-limit';
import helmet from 'helmet';
import hpp from 'hpp';
import xss from 'xss';
import securityAuditLogger from "../services/security-audit.service.js";

// Security configuration
const SECURITY_CONFIG = {
  rateLimit: {
    window: 15 * 60 * 1000, // 15 minutes
    maxRequests: 100,
    skipSuccessfulRequests: false,
    skipFailedRequests: false,
  },
  strictRateLimit: {
    window: 60 * 1000, // 1 minute
    maxRequests: 10,
  },
  bodyLimit: '10mb',
  parameterLimit: 100,
  trustedProxies: ['127.0.0.1', '::1'],
  allowedOrigins: (process.env.CORS_ORIGINS || 'http://localhost:3000').split(','),
};

/**
 * Enhanced security headers using Helmet
 */
export const securityHeaders = helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", 'https://fonts.googleapis.com'],
      fontSrc: ["'self'", 'https://fonts.gstatic.com'],
      imgSrc: ["'self'", 'data:', 'https:', 'blob:'],
      scriptSrc: ["'self'", "'strict-dynamic'", 'https://js.stripe.com'],
      connectSrc: ["'self'", 'https:', 'wss:'],
      frameSrc: ["'self'", 'https://js.stripe.com'],
      objectSrc: ["'none'"],
      upgradeInsecureRequests: [],
    },
  },
  crossOriginEmbedderPolicy: false, // May need to adjust for some resources
  crossOriginResourcePolicy: { policy: 'cross-origin' },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
});

/**
 * HTTP Parameter Pollution protection
 */
export const parameterPollutionProtection = hpp({
  whitelist: ['sort', 'filter', 'fields', 'include'], // Allow these as arrays
});

/**
 * Request size limiter
 */
export function requestSizeLimiter(maxSize: string = '10mb') {
  return (req: Request, res: Response, next: NextFunction) => {
    const contentLength = parseInt(req.headers['content-length'] || '0', 10);
    const maxBytes = parseSize(maxSize);

    if (contentLength > maxBytes) {
      securityAuditLogger.logSecurityEvent({
        eventType: securityAuditLogger.SecurityEventType.SUSPICIOUS_ACTIVITY,
        severity: securityAuditLogger.SecurityEventSeverity.WARNING,
        ipAddress: req.ip,
        userAgent: req.headers['user-agent'],
        description: 'Request too large',
        metadata: {
          outcome: 'blocked',
          details: {
            reason: 'Request too large',
            size: contentLength,
            max: maxBytes,
          }
        },
      });

      return res.status(413).json({
        error: 'Payload Too Large',
        message: `Request body exceeds ${maxSize}`,
      });
    }

    next();
  };
}

/**
 * XSS sanitization middleware
 */
export function xssSanitizer(req: Request, res: Response, next: NextFunction) {
  if (req.body && typeof req.body === 'object') {
    req.body = sanitizeObject(req.body);
  }

  if (req.query && typeof req.query === 'object') {
    req.query = sanitizeObject(req.query as Record<string, any>);
  }

  if (req.params && typeof req.params === 'object') {
    req.params = sanitizeObject(req.params);
  }

  next();
}

function sanitizeObject(obj: Record<string, any>): Record<string, any> {
  const sanitized: Record<string, any> = {};

  for (const [key, value] of Object.entries(obj)) {
    if (typeof value === 'string') {
      sanitized[key] = xss(value);
    } else if (Array.isArray(value)) {
      sanitized[key] = value.map((v) =>
        typeof v === 'string' ? xss(v) : v
      );
    } else if (typeof value === 'object' && value !== null) {
      sanitized[key] = sanitizeObject(value);
    } else {
      sanitized[key] = value;
    }
  }

  return sanitized;
}

/**
 * SQL injection pattern detector
 */
const SQL_INJECTION_PATTERNS = [
  /(\b(SELECT|INSERT|UPDATE|DELETE|DROP|UNION|ALTER|CREATE|TRUNCATE)\b.*\b(FROM|INTO|WHERE|TABLE|DATABASE)\b)/i,
  /('|").*(--)|(\/\*.*\*\/)/i,
  /(\bOR\b.*=.*\bOR\b)/i,
  /(;.*(\bDROP\b|\bDELETE\b|\bINSERT\b|\bUPDATE\b))/i,
];

export function sqlInjectionDetector(
  req: Request,
  res: Response,
  next: NextFunction
) {
  const checkValue = (value: any): boolean => {
    if (typeof value !== 'string') return false;
    return SQL_INJECTION_PATTERNS.some((pattern) => pattern.test(value));
  };

  const checkObject = (obj: Record<string, any>): boolean => {
    for (const value of Object.values(obj)) {
      if (checkValue(value)) return true;
      if (typeof value === 'object' && value !== null) {
        if (checkObject(value)) return true;
      }
    }
    return false;
  };

  const suspicious =
    checkObject(req.body || {}) ||
    checkObject(req.query || {}) ||
    checkObject(req.params || {});

  if (suspicious) {
    securityAuditLogger.logSecurityEvent({
      eventType: securityAuditLogger.SecurityEventType.SUSPICIOUS_ACTIVITY,
      severity: securityAuditLogger.SecurityEventSeverity.WARNING,
      ipAddress: req.ip,
      userAgent: req.headers['user-agent'],
      description: 'Potential SQL injection pattern detected (log-only)',
      metadata: {
        outcome: 'logged',
        details: {
          reason: 'Potential SQL injection pattern detected (log-only, ORM uses parameterized queries)',
          path: req.path,
          method: req.method,
        }
      },
    });
    // Log only — do not block. The ORM uses parameterized queries,
    // so regex-based detection causes false positives on legitimate inputs.
  }

  next();
}

/**
 * Path traversal protection
 */
export function pathTraversalProtection(
  req: Request,
  res: Response,
  next: NextFunction
) {
  const DANGEROUS_PATTERNS = [
    /\.\.\//,
    /\.\.\\/, 
    /%2e%2e%2f/i,
    /%2e%2e\//i,
    /\.%2e\//i,
    /%2e\.\//i,
    /\.\.\%5c/i,
    /etc\/passwd/i,
    /etc\/shadow/i,
    /proc\/self/i,
  ];

  const fullUrl = req.originalUrl || req.url;

  for (const pattern of DANGEROUS_PATTERNS) {
    if (pattern.test(fullUrl)) {
      securityAuditLogger.logSecurityEvent({
        eventType: securityAuditLogger.SecurityEventType.SUSPICIOUS_ACTIVITY,
        severity: securityAuditLogger.SecurityEventSeverity.WARNING,
        ipAddress: req.ip,
        userAgent: req.headers['user-agent'],
        description: 'Path traversal attempt detected',
        metadata: {
          outcome: 'blocked',
          details: {
            reason: 'Path traversal attempt detected',
            path: fullUrl,
          }
        },
      });

      return res.status(400).json({
        error: 'Bad Request',
        message: 'Invalid path',
      });
    }
  }

  next();
}

/**
 * Create rate limiter for specific routes
 */
export function createRateLimiter(options: {
  windowMs?: number;
  max?: number;
  message?: string;
  skipSuccessfulRequests?: boolean;
  keyGenerator?: (req: Request) => string;
}) {
  return rateLimit({
    windowMs: options.windowMs || SECURITY_CONFIG.rateLimit.window,
    max: options.max || SECURITY_CONFIG.rateLimit.maxRequests,
    message: {
      error: 'Too Many Requests',
      message: options.message || 'Please try again later',
      retryAfter: Math.ceil((options.windowMs || SECURITY_CONFIG.rateLimit.window) / 1000),
    },
    skipSuccessfulRequests: options.skipSuccessfulRequests || false,
    keyGenerator: options.keyGenerator || ((req) => req.ip || 'unknown'),
    handler: async (req, res) => {
      await securityAuditLogger.logSecurityEvent({
        eventType: securityAuditLogger.SecurityEventType.SUSPICIOUS_ACTIVITY,
        severity: securityAuditLogger.SecurityEventSeverity.WARNING,
        userId: req.user?.id,
        ipAddress: req.ip,
        userAgent: req.headers['user-agent'],
        description: 'Rate limit exceeded',
        metadata: {
          outcome: 'blocked',
          details: {
            path: req.path,
            method: req.method,
            limit: options.max || SECURITY_CONFIG.rateLimit.maxRequests,
          }
        },
      });

      res.status(429).json({
        error: 'Too Many Requests',
        message: options.message || 'Please try again later',
        retryAfter: Math.ceil((options.windowMs || SECURITY_CONFIG.rateLimit.window) / 1000),
      });
    },
  });
}

/**
 * Authentication rate limiter (stricter)
 */
export const authRateLimiter = createRateLimiter({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 attempts per window
  message: 'Too many login attempts, please try again later',
  skipSuccessfulRequests: true,
});

/**
 * Password reset rate limiter
 */
export const passwordResetRateLimiter = createRateLimiter({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 3, // 3 attempts per hour
  message: 'Too many password reset requests',
});

/**
 * API key validation middleware
 */
export async function apiKeyValidator(
  req: Request,
  res: Response,
  next: NextFunction
): Promise<void> {
  const apiKey = req.headers['x-api-key'] as string;

  if (!apiKey) {
    // Allow if user is authenticated via JWT
    if (req.user) {
      next();
      return;
    }

    res.status(401).json({
      error: 'Unauthorized',
      message: 'API key required',
    });
    return;
  }

  // Validate API key format
  if (!/^v2_[a-zA-Z0-9]{32,64}$/.test(apiKey)) {
    res.status(401).json({
      error: 'Unauthorized',
      message: 'Invalid API key format',
    });
    return;
  }

  try {
    // Validate API key against database
    const { getSupabase } = await import('../database/connection.js');
    const supabase = getSupabase();
    const { data: keyRecord, error } = await supabase
      .from('api_keys')
      .select('id, user_id, scopes, is_active, expires_at')
      .eq('key_hash', crypto.createHash('sha256').update(apiKey).digest('hex'))
      .eq('is_active', true)
      .single();

    if (error || !keyRecord) {
      res.status(401).json({
        error: 'Unauthorized',
        message: 'Invalid API key',
      });
      return;
    }

    // Check expiry
    if (keyRecord.expires_at && new Date(keyRecord.expires_at) < new Date()) {
      res.status(401).json({
        error: 'Unauthorized',
        message: 'API key expired',
      });
      return;
    }

    // Attach key info for downstream use
    (req as any).apiKeyId = keyRecord.id;
    (req as any).apiKeyUserId = keyRecord.user_id;
    (req as any).apiKeyScopes = keyRecord.scopes;
    next();
  } catch {
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'API key validation failed',
    });
  }
}

/**
 * Request ID injection
 */
export function requestIdInjector(
  req: Request,
  res: Response,
  next: NextFunction
) {
  const requestId = req.headers['x-request-id'] as string ||
    `req_${Date.now()}_${crypto.randomBytes(6).toString('hex')}`;

  req.requestId = requestId;
  res.setHeader('X-Request-ID', requestId);

  next();
}

/**
 * Sensitive data masking in responses
 */
export function sensitiveDataMasker(
  req: Request,
  res: Response,
  next: NextFunction
) {
  const originalJson = res.json.bind(res);

  res.json = (data: any) => {
    const maskedData = maskSensitiveFields(data);
    return originalJson(maskedData);
  };

  next();
}

const SENSITIVE_FIELDS = [
  'password',
  'password_hash',
  'secret',
  'api_key',
  'token',
  'refresh_token',
  'ssn',
  'credit_card',
  'cvv',
];

function maskSensitiveFields(obj: any): any {
  if (obj === null || typeof obj !== 'object') {
    return obj;
  }

  if (Array.isArray(obj)) {
    return obj.map(maskSensitiveFields);
  }

  const masked: Record<string, any> = {};

  for (const [key, value] of Object.entries(obj)) {
    const lowerKey = key.toLowerCase();

    if (SENSITIVE_FIELDS.some((f) => lowerKey.includes(f))) {
      masked[key] = '[REDACTED]';
    } else if (typeof value === 'object') {
      masked[key] = maskSensitiveFields(value);
    } else {
      masked[key] = value;
    }
  }

  return masked;
}

/**
 * Parse size string to bytes
 */
function parseSize(size: string): number {
  const units: Record<string, number> = {
    b: 1,
    kb: 1024,
    mb: 1024 * 1024,
    gb: 1024 * 1024 * 1024,
  };

  const match = size.toLowerCase().match(/^(\d+)\s*(b|kb|mb|gb)?$/);
  if (!match) return 10 * 1024 * 1024; // Default 10MB

  const value = parseInt(match[1], 10);
  const unit = match[2] || 'b';

  return value * (units[unit] || 1);
}

/**
 * Combined security middleware stack
 */
export function applySecurityMiddleware(app: any): void {
  // Basic security headers
  app.use(securityHeaders);

  // Request ID for tracking
  app.use(requestIdInjector);

  // Request size limiting (before body parsing)
  app.use(requestSizeLimiter('10mb'));

  // Parameter pollution protection
  app.use(parameterPollutionProtection);

  // Path traversal protection
  app.use(pathTraversalProtection);

  // SQL injection detection
  app.use(sqlInjectionDetector);

  // XSS sanitization
  app.use(xssSanitizer);

  // Sensitive data masking
  app.use(sensitiveDataMasker);

  console.log('[Security] API security middleware applied');
}

/**
 * V2 Resort - Request Correlation ID Tracking Middleware
 * Enables distributed tracing across services
 */

import { Request, Response, NextFunction } from 'express';
import { v4 as uuidv4 } from 'uuid';
import { AsyncLocalStorage } from 'async_hooks';

// Header name for correlation ID
export const CORRELATION_ID_HEADER = 'X-Correlation-ID';
export const REQUEST_ID_HEADER = 'X-Request-ID';

// Async local storage for correlation context
interface CorrelationContext {
  correlationId: string;
  requestId: string;
  startTime: number;
  userId?: string;
  sessionId?: string;
  clientIp?: string;
  userAgent?: string;
  path?: string;
  method?: string;
}

const correlationStorage = new AsyncLocalStorage<CorrelationContext>();

/**
 * Get current correlation context
 */
export const getCorrelationContext = (): CorrelationContext | undefined => {
  return correlationStorage.getStore();
};

/**
 * Get correlation ID from current context
 */
export const getCorrelationId = (): string | undefined => {
  return correlationStorage.getStore()?.correlationId;
};

/**
 * Get request ID from current context
 */
export const getRequestId = (): string | undefined => {
  return correlationStorage.getStore()?.requestId;
};

/**
 * Run a function within a correlation context
 */
export const runWithCorrelation = <T>(
  context: Partial<CorrelationContext>,
  fn: () => T
): T => {
  const fullContext: CorrelationContext = {
    correlationId: context.correlationId || uuidv4(),
    requestId: context.requestId || uuidv4(),
    startTime: context.startTime || Date.now(),
    ...context,
  };
  
  return correlationStorage.run(fullContext, fn);
};

/**
 * Express middleware for correlation ID tracking
 */
export const correlationIdMiddleware = (
  req: Request,
  res: Response,
  next: NextFunction
): void => {
  // Get or generate correlation ID
  const correlationId = 
    req.headers[CORRELATION_ID_HEADER.toLowerCase()] as string || 
    uuidv4();
  
  // Always generate a new request ID for this specific request
  const requestId = uuidv4();
  
  // Extract user information if available
  const userId = req.user?.id;
  const sessionId = req.sessionID;
  
  // Extract client information
  const clientIp = 
    req.headers['x-forwarded-for'] as string || 
    req.headers['x-real-ip'] as string || 
    req.socket.remoteAddress || 
    'unknown';
  
  const userAgent = req.headers['user-agent'] || 'unknown';
  
  // Create correlation context
  const context: CorrelationContext = {
    correlationId,
    requestId,
    startTime: Date.now(),
    userId,
    sessionId,
    clientIp: typeof clientIp === 'string' ? clientIp.split(',')[0].trim() : clientIp,
    userAgent,
    path: req.path,
    method: req.method,
  };
  
  // Set response headers
  res.setHeader(CORRELATION_ID_HEADER, correlationId);
  res.setHeader(REQUEST_ID_HEADER, requestId);
  
  // Log request start
  console.log(JSON.stringify({
    level: 'info',
    message: 'Request started',
    correlationId,
    requestId,
    method: req.method,
    path: req.path,
    clientIp: context.clientIp,
    userAgent: context.userAgent,
    userId,
  }));
  
  // Log response on finish
  res.on('finish', () => {
    const duration = Date.now() - context.startTime;
    console.log(JSON.stringify({
      level: res.statusCode >= 400 ? 'error' : 'info',
      message: 'Request completed',
      correlationId,
      requestId,
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration,
      clientIp: context.clientIp,
      userId,
    }));
  });
  
  // Run the rest of the request in correlation context
  correlationStorage.run(context, () => {
    next();
  });
};

/**
 * Logger wrapper that automatically includes correlation ID
 */
export const correlatedLogger = {
  info: (message: string, data?: Record<string, any>) => {
    const context = getCorrelationContext();
    console.log(JSON.stringify({
      level: 'info',
      message,
      correlationId: context?.correlationId,
      requestId: context?.requestId,
      timestamp: new Date().toISOString(),
      ...data,
    }));
  },
  
  error: (message: string, error?: Error, data?: Record<string, any>) => {
    const context = getCorrelationContext();
    console.error(JSON.stringify({
      level: 'error',
      message,
      correlationId: context?.correlationId,
      requestId: context?.requestId,
      timestamp: new Date().toISOString(),
      error: error ? {
        name: error.name,
        message: error.message,
        stack: error.stack,
      } : undefined,
      ...data,
    }));
  },
  
  warn: (message: string, data?: Record<string, any>) => {
    const context = getCorrelationContext();
    console.warn(JSON.stringify({
      level: 'warn',
      message,
      correlationId: context?.correlationId,
      requestId: context?.requestId,
      timestamp: new Date().toISOString(),
      ...data,
    }));
  },
  
  debug: (message: string, data?: Record<string, any>) => {
    if (process.env.NODE_ENV === 'development' || process.env.DEBUG === 'true') {
      const context = getCorrelationContext();
      console.debug(JSON.stringify({
        level: 'debug',
        message,
        correlationId: context?.correlationId,
        requestId: context?.requestId,
        timestamp: new Date().toISOString(),
        ...data,
      }));
    }
  },
};

/**
 * Axios interceptor to pass correlation ID to downstream services
 */
export const axiosCorrelationInterceptor = (config: any) => {
  const correlationId = getCorrelationId();
  const requestId = getRequestId();
  
  if (correlationId) {
    config.headers = config.headers || {};
    config.headers[CORRELATION_ID_HEADER] = correlationId;
  }
  
  if (requestId) {
    config.headers = config.headers || {};
    config.headers['X-Parent-Request-ID'] = requestId;
  }
  
  return config;
};

/**
 * Fetch wrapper that includes correlation ID
 */
export const correlatedFetch = async (
  url: string,
  options: RequestInit = {}
): Promise<any> => {
  const correlationId = getCorrelationId();
  const requestId = getRequestId();
  
  const headers = new Headers(options.headers);
  
  if (correlationId) {
    headers.set(CORRELATION_ID_HEADER, correlationId);
  }
  
  if (requestId) {
    headers.set('X-Parent-Request-ID', requestId);
  }
  
  return fetch(url, {
    ...options,
    headers,
  });
};

/**
 * Add correlation context to error for Sentry/error tracking
 */
export const enrichErrorWithCorrelation = (error: Error): Error & { correlationId?: string; requestId?: string } => {
  const context = getCorrelationContext();
  const enrichedError = error as Error & { correlationId?: string; requestId?: string };
  
  if (context) {
    enrichedError.correlationId = context.correlationId;
    enrichedError.requestId = context.requestId;
  }
  
  return enrichedError;
};

export default correlationIdMiddleware;

/**
 * Device Authentication Middleware
 * 
 * Verifies kiosk device identity via device token in the X-Device-Token header.
 * Kiosk devices authenticate using a token issued during device registration
 * rather than user JWT, since they operate without human login.
 */

import { Request, Response, NextFunction } from 'express';
import { getSupabase } from '../database/connection.js';
import { logger } from '../utils/logger.js';

/**
 * Middleware that verifies the X-Device-Token header against registered kiosk devices.
 * Sets req.deviceId on success for downstream handlers.
 */
export async function authenticateDevice(req: Request, res: Response, next: NextFunction): Promise<void> {
  const deviceToken = req.headers['x-device-token'] as string;

  if (!deviceToken) {
    res.status(401).json({ success: false, error: 'Device token required' });
    return;
  }

  // Validate token format (UUID v4)
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(deviceToken)) {
    res.status(401).json({ success: false, error: 'Invalid device token format' });
    return;
  }

  // Verify against database
  const supabase = getSupabase();
  try {
    const { data: device, error } = await supabase
      .from('kiosk_devices')
      .select('id, property_id, status')
      .eq('device_token', deviceToken)
      .eq('is_active', true)
      .single();

    if (error || !device) {
      logger.warn('Device authentication failed', {
        token: deviceToken.substring(0, 8) + '...',
        ip: req.ip,
      });
      res.status(401).json({ success: false, error: 'Invalid or inactive device' });
      return;
    }

    // Attach device info to request for downstream use
    (req as any).deviceId = device.id;
    (req as any).devicePropertyId = device.property_id;
    next();
  } catch (err: unknown) {
    logger.error('Device auth error:', err);
    res.status(500).json({ success: false, error: 'Device authentication failed' });
  }
}

/**
 * Performance Monitoring Middleware
 * 
 * Tracks request timing, slow queries, and system metrics.
 */

import { Request, Response, NextFunction } from 'express';
import { logger } from '../utils/logger.js';

// In-memory metrics store (could be replaced with Redis or external metrics service)
interface RequestMetrics {
  totalRequests: number;
  totalErrors: number;
  avgResponseTime: number;
  p95ResponseTime: number;
  p99ResponseTime: number;
  responseTimes: number[];
  statusCodes: Record<string, number>;
  endpoints: Record<string, {
    count: number;
    totalTime: number;
    errors: number;
  }>;
  lastReset: number;
}

const MAX_RESPONSE_TIMES = 1000; // Keep last N response times for percentile calculation
const SLOW_REQUEST_THRESHOLD_MS = 1000; // Log requests slower than this

const metrics: RequestMetrics = {
  totalRequests: 0,
  totalErrors: 0,
  avgResponseTime: 0,
  p95ResponseTime: 0,
  p99ResponseTime: 0,
  responseTimes: [],
  statusCodes: {},
  endpoints: {},
  lastReset: Date.now(),
};

/**
 * Calculate percentile from sorted array
 */
function calculatePercentile(arr: number[], percentile: number): number {
  if (arr.length === 0) return 0;
  const sorted = [...arr].sort((a, b) => a - b);
  const index = Math.ceil((percentile / 100) * sorted.length) - 1;
  return sorted[Math.max(0, index)];
}

/**
 * Update metrics with new response time
 */
function updateMetrics(responseTime: number, statusCode: number, endpoint: string): void {
  metrics.totalRequests++;
  
  // Track response times for percentile calculations
  metrics.responseTimes.push(responseTime);
  if (metrics.responseTimes.length > MAX_RESPONSE_TIMES) {
    metrics.responseTimes.shift();
  }
  
  // Update average
  metrics.avgResponseTime = 
    metrics.responseTimes.reduce((a, b) => a + b, 0) / metrics.responseTimes.length;
  
  // Update percentiles
  metrics.p95ResponseTime = calculatePercentile(metrics.responseTimes, 95);
  metrics.p99ResponseTime = calculatePercentile(metrics.responseTimes, 99);
  
  // Track status codes
  const statusGroup = `${Math.floor(statusCode / 100)}xx`;
  metrics.statusCodes[statusGroup] = (metrics.statusCodes[statusGroup] || 0) + 1;
  
  if (statusCode >= 500) {
    metrics.totalErrors++;
  }
  
  // Track endpoint metrics
  if (!metrics.endpoints[endpoint]) {
    metrics.endpoints[endpoint] = { count: 0, totalTime: 0, errors: 0 };
  }
  metrics.endpoints[endpoint].count++;
  metrics.endpoints[endpoint].totalTime += responseTime;
  if (statusCode >= 400) {
    metrics.endpoints[endpoint].errors++;
  }
}

/**
 * Request timing middleware
 */
export function requestTiming(req: Request, res: Response, next: NextFunction): void {
  const startTime = process.hrtime.bigint();
  
  // Track if we've already processed this response
  let hasProcessed = false;
  
  // Override res.end to capture timing
  const originalEnd = res.end.bind(res);
  
  // Use proper overloaded function type for res.end
  type EndCallback = () => void;
  type EndChunk = Buffer | string | undefined;
  type EndEncoding = BufferEncoding | undefined;
  
  res.end = function(
    chunkOrCb?: EndChunk | EndCallback,
    encodingOrCb?: EndEncoding | EndCallback,
    callback?: EndCallback
  ): Response {
    // Only process once to avoid double-send errors
    if (!hasProcessed) {
      hasProcessed = true;
      const endTime = process.hrtime.bigint();
      const durationNs = Number(endTime - startTime);
      const durationMs = durationNs / 1_000_000;
      
      // Set timing header only if headers haven't been sent yet
      if (!res.headersSent) {
        res.setHeader('X-Response-Time', `${durationMs.toFixed(2)}ms`);
      }
      
      // Normalize endpoint for grouping (replace UUIDs and IDs with placeholders)
      const endpoint = `${req.method} ${req.route?.path || req.path}`
        .replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi, ':uuid')
        .replace(/\/\d+/g, '/:id');
      
      // Update metrics
      updateMetrics(durationMs, res.statusCode, endpoint);
      
      // Log slow requests
      if (durationMs > SLOW_REQUEST_THRESHOLD_MS) {
        logger.warn('Slow request detected', {
          method: req.method,
          path: req.path,
          duration: `${durationMs.toFixed(2)}ms`,
          statusCode: res.statusCode,
          requestId: req.requestId,
        });
      }
    }
    
    // Handle overloaded signatures
    if (typeof chunkOrCb === 'function') {
      return originalEnd(chunkOrCb);
    } else if (typeof encodingOrCb === 'function') {
      return originalEnd(chunkOrCb, encodingOrCb);
    } else if (encodingOrCb !== undefined) {
      return originalEnd(chunkOrCb, encodingOrCb as BufferEncoding, callback);
    } else {
      return originalEnd(chunkOrCb, callback);
    }
  };
  
  next();
}

/**
 * Get current metrics
 */
export function getMetrics(): Record<string, any> {
  const uptime = Date.now() - metrics.lastReset;
  const requestsPerSecond = metrics.totalRequests / (uptime / 1000) || 0;
  
  // Calculate slowest endpoints
  const slowestEndpoints = Object.entries(metrics.endpoints)
    .map(([endpoint, data]) => ({
      endpoint,
      avgTime: data.totalTime / data.count,
      count: data.count,
      errorRate: (data.errors / data.count) * 100,
    }))
    .sort((a, b) => b.avgTime - a.avgTime)
    .slice(0, 10);
  
  return {
    uptime: `${Math.floor(uptime / 1000)}s`,
    requests: {
      total: metrics.totalRequests,
      perSecond: requestsPerSecond.toFixed(2),
      errors: metrics.totalErrors,
      errorRate: ((metrics.totalErrors / metrics.totalRequests) * 100 || 0).toFixed(2) + '%',
    },
    responseTime: {
      avg: `${metrics.avgResponseTime.toFixed(2)}ms`,
      p95: `${metrics.p95ResponseTime.toFixed(2)}ms`,
      p99: `${metrics.p99ResponseTime.toFixed(2)}ms`,
    },
    statusCodes: metrics.statusCodes,
    slowestEndpoints,
    memory: {
      heapUsed: `${(process.memoryUsage().heapUsed / 1024 / 1024).toFixed(2)}MB`,
      heapTotal: `${(process.memoryUsage().heapTotal / 1024 / 1024).toFixed(2)}MB`,
      rss: `${(process.memoryUsage().rss / 1024 / 1024).toFixed(2)}MB`,
    },
  };
}

/**
 * Reset metrics
 */
export function resetMetrics(): void {
  metrics.totalRequests = 0;
  metrics.totalErrors = 0;
  metrics.avgResponseTime = 0;
  metrics.p95ResponseTime = 0;
  metrics.p99ResponseTime = 0;
  metrics.responseTimes = [];
  metrics.statusCodes = {};
  metrics.endpoints = {};
  metrics.lastReset = Date.now();
}

/**
 * Metrics endpoint handler
 */
export function metricsHandler(req: Request, res: Response): void {
  res.json({
    success: true,
    data: getMetrics(),
  });
}

/**
 * Property Access Validation Middleware
 * 
 * Validates that the x-property-id header value corresponds to a property
 * the authenticated user has access to, preventing cross-property data access.
 */

import { Request, Response, NextFunction } from 'express';
import { getSupabase } from '../database/connection.js';
import { logger } from '../utils/logger.js';

/**
 * Middleware that validates the x-property-id header against the user's
 * property assignments. Super admins bypass the check.
 */
export async function validatePropertyAccess(req: Request, res: Response, next: NextFunction): Promise<void> {
  const propertyId = req.headers['x-property-id'] as string;

  // If no property header, allow (some endpoints don't require it)
  if (!propertyId) {
    return next();
  }

  // Validate UUID format
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(propertyId)) {
    res.status(400).json({ success: false, error: 'Invalid property ID format' });
    return;
  }

  // Super admins can access any property
  if (req.user?.roles?.includes('super_admin')) {
    (req as any).propertyId = propertyId;
    return next();
  }

  if (!req.user?.userId) {
    res.status(401).json({ success: false, error: 'Authentication required for property access' });
    return;
  }

  // Check user's property access in the database
  const supabase = getSupabase();
  try {
    const { data, error } = await supabase
      .from('user_properties')
      .select('property_id')
      .eq('user_id', req.user.userId)
      .eq('property_id', propertyId)
      .single();

    if (error || !data) {
      logger.warn('Property access denied', {
        userId: req.user?.userId,
        propertyId,
        path: req.path,
      });
      res.status(403).json({ success: false, error: 'Access denied for this property' });
      return;
    }

    (req as any).propertyId = propertyId;
    next();
  } catch (err: unknown) {
    logger.error('Property access check error:', err);
    res.status(500).json({ success: false, error: 'Property access validation failed' });
  }
}

/**
 * Input Validation Middleware
 * Comprehensive input sanitization and validation for security hardening
 */
import { Request, Response, NextFunction } from 'express';
import { z, ZodSchema, ZodError } from 'zod';
import xss from 'xss';

// XSS sanitization options
const xssOptions = {
  whiteList: {}, // No HTML tags allowed
  stripIgnoreTag: true,
  stripIgnoreTagBody: ['script', 'style'],
};

/**
 * Sanitize string input
 */
export function sanitizeString(input: string): string {
  if (typeof input !== 'string') return input;
  
  // Remove XSS
  let sanitized = xss(input, xssOptions);
  
  // Trim whitespace
  sanitized = sanitized.trim();
  
  // Remove null bytes
  sanitized = sanitized.replace(/\0/g, '');
  
  // Normalize unicode
  sanitized = sanitized.normalize('NFC');
  
  return sanitized;
}

/**
 * Deep sanitize object
 */
export function sanitizeObject(obj: any): any {
  if (obj === null || obj === undefined) return obj;
  
  if (typeof obj === 'string') {
    return sanitizeString(obj);
  }
  
  if (Array.isArray(obj)) {
    return obj.map(item => sanitizeObject(item));
  }
  
  if (typeof obj === 'object') {
    const sanitized: any = {};
    for (const [key, value] of Object.entries(obj)) {
      // Sanitize key as well
      const sanitizedKey = sanitizeString(key);
      sanitized[sanitizedKey] = sanitizeObject(value);
    }
    return sanitized;
  }
  
  return obj;
}

/**
 * Input sanitization middleware
 */
export function sanitizeInput() {
  return (req: Request, _res: Response, next: NextFunction) => {
    // Sanitize body
    if (req.body) {
      req.body = sanitizeObject(req.body);
    }
    
    // Sanitize query params
    if (req.query) {
      req.query = sanitizeObject(req.query);
    }
    
    // Sanitize URL params
    if (req.params) {
      req.params = sanitizeObject(req.params);
    }
    
    next();
  };
}

/**
 * Zod validation middleware factory
 */
export function validate(schema: ZodSchema, source: 'body' | 'query' | 'params' = 'body') {
  return (req: Request, res: Response, next: NextFunction) => {
    try {
      const data = source === 'body' ? req.body : source === 'query' ? req.query : req.params;
      const validated = schema.parse(data);
      
      // Replace with validated data
      if (source === 'body') req.body = validated;
      else if (source === 'query') req.query = validated;
      else req.params = validated;
      
      next();
    } catch (error) {
      if (error instanceof ZodError) {
        return res.status(400).json({
          error: 'Validation failed',
          details: error.errors.map(e => ({
            path: e.path.join('.'),
            message: e.message,
          })),
        });
      }
      next(error);
    }
  };
}

/**
 * Common validation schemas
 */
export const schemas = {
  // UUID validation
  uuid: z.string().uuid('Invalid ID format'),
  
  // Email validation
  email: z.string().email('Invalid email format').toLowerCase().trim(),
  
  // Password validation (matches frontend requirements)
  password: z.string()
    .min(8, 'Password must be at least 8 characters')
    .max(128, 'Password must be less than 128 characters')
    .regex(/[A-Z]/, 'Password must contain at least one uppercase letter')
    .regex(/[a-z]/, 'Password must contain at least one lowercase letter')
    .regex(/[0-9]/, 'Password must contain at least one number')
    .regex(/[!@#$%^&*(),.?":{}|<>]/, 'Password must contain at least one special character'),
  
  // Phone validation (international format)
  phone: z.string()
    .regex(/^\+?[1-9]\d{1,14}$/, 'Invalid phone number format')
    .optional(),
  
  // Date validation
  date: z.string().refine((val) => !isNaN(Date.parse(val)), 'Invalid date format'),
  
