/**
 * Audit Controller
 * Handles audit log retrieval and management
 */

import { Request, Response, NextFunction } from 'express';
import { asyncHandler } from '../../../middleware/async-handler.js';
import { getSupabase } from '../../../database/connection';

interface ActivityLogRow {
  id: string;
  user_id: string;
  action: string;
  resource: string;
  resource_id?: string;
  old_value?: string | Record<string, unknown>;
  new_value?: string | Record<string, unknown>;
  created_at: string;
  users?: { full_name: string; email: string };
}

function safeParseJson(value: unknown): unknown {
  if (value === null || value === undefined) return null;
  if (typeof value !== 'string') return value;

  try {
    return JSON.parse(value);
  } catch {
    return value;
  }
}

export const getAuditLogs = asyncHandler(async (req: Request, res: Response) => {
    const supabase = getSupabase();
    const { limit = 50, offset = 0 } = req.query;

    const { data: logs, error } = await supabase
      .from('audit_logs')
      .select('*')
      .order('created_at', { ascending: false })
      .range(Number(offset), Number(offset) + Number(limit) - 1);

    if (error) throw error;

    const logRows = (logs || []) as ActivityLogRow[];
    const userIds = [...new Set(
      logRows
        .map((log) => log.user_id)
        .filter((id): id is string => typeof id === 'string' && id.length > 0)
    )];

    let usersById: Record<string, { full_name: string; email: string }> = {};
    if (userIds.length > 0) {
      const { data: users } = await supabase
        .from('users')
        .select('id, full_name, email')
        .in('id', userIds);

      usersById = Object.fromEntries(
        (users || []).map((user: any) => [
          user.id,
          {
            full_name: user.full_name,
            email: user.email,
          },
        ])
      );
    }

    // Map to frontend expected format
    const mappedLogs = logRows.map((log: ActivityLogRow) => ({
      ...log,
      users: log.user_id ? (usersById[log.user_id] || undefined) : undefined,
      entity_type: log.resource,
      entity_id: log.resource_id,
      old_values: safeParseJson(log.old_value),
      new_values: safeParseJson(log.new_value),
    }));

    res.json({ success: true, data: mappedLogs });
});

export const getAuditLogsByResource = asyncHandler(async (req: Request, res: Response) => {
    const supabase = getSupabase();
    const { resource, resourceId } = req.params;
    const { limit = 20 } = req.query;

    const query = supabase
      .from('activity_logs')
      .select(`
        *,
        users:user_id (
          full_name,
          email
        )
      `)
      .eq('resource', resource)
      .order('created_at', { ascending: false })
      .limit(Number(limit));

    if (resourceId) {
      query.eq('resource_id', resourceId);
    }

    const { data: logs, error } = await query;

    if (error) throw error;

    res.json({ success: true, data: logs || [] });
});

/**
 * Dashboard Controller
 * 
 * Handles dashboard statistics, revenue stats, and overview reports.
 * Extracted from admin.controller.ts for better maintainability.
 */

import { Request, Response, NextFunction } from 'express';
import { asyncHandler } from '../../../middleware/async-handler.js';
import { getSupabase } from '../../../database/connection';
import { logger } from '../../../utils/logger.js';
import dayjs from 'dayjs';
import { 
  DashboardStats, 
  RecentOrderSummary, 
  RestaurantOrderRow,
  sumAmounts, 
  calculateTrend 
} from '../types';

interface AmountRecord {
  total_amount?: string | null;
}

interface RecentOrderQuery {
  id: string;
  order_number: string;
  customer_name?: string | null;
  status: string;
  total_amount: string;
  created_at: string;
  items?: Array<{ id: string }>;
}

/**
 * GET /api/admin/dashboard
 * Get comprehensive dashboard statistics
 */
export const getDashboard = asyncHandler(async (req: Request, res: Response) => {
    const supabase = getSupabase();
    const today = dayjs().startOf('day').toISOString();
    const endOfDay = dayjs().endOf('day').toISOString();
    const yesterday = dayjs().subtract(1, 'day').startOf('day').toISOString();
    const endOfYesterday = dayjs().subtract(1, 'day').endOf('day').toISOString();
    const lastWeekStart = dayjs().subtract(7, 'day').startOf('day').toISOString();
    const lastWeekEnd = dayjs().subtract(7, 'day').endOf('day').toISOString();

    // Today's stats - run queries in parallel
    const [
      restaurantOrdersResult,
      restaurantRevenueResult,
      snackOrdersResult,
      snackRevenueResult,
      chaletBookingsResult,
      chaletRevenueResult,
      poolTicketsResult,
      poolRevenueResult,
      usersResult,
      recentOrdersResult,
      yesterdayOrdersResult,
      yesterdayRevenueResult,
      lastWeekBookingsResult,
      yesterdayTicketsResult
    ] = await Promise.all([
      // Restaurant orders count
      supabase.from('restaurant_orders')
        .select('id', { count: 'exact', head: true })
        .gte('created_at', today)
        .lte('created_at', endOfDay),
      // Restaurant revenue
      supabase.from('restaurant_orders')
        .select('total_amount')
        .gte('created_at', today)
        .lte('created_at', endOfDay)
        .eq('payment_status', 'paid'),
      // Snack orders count
      supabase.from('snack_orders')
        .select('id', { count: 'exact', head: true })
        .gte('created_at', today)
        .lte('created_at', endOfDay),
      // Snack revenue
      supabase.from('snack_orders')
        .select('total_amount')
        .gte('created_at', today)
        .lte('created_at', endOfDay)
        .eq('payment_status', 'paid'),
      // Chalet bookings count
      supabase.from('chalet_bookings')
        .select('id', { count: 'exact', head: true })
        .gte('check_in_date', today)
        .lte('check_in_date', endOfDay),
      // Chalet revenue
      supabase.from('chalet_bookings')
        .select('total_amount')
        .gte('check_in_date', today)
        .lte('check_in_date', endOfDay)
        .eq('payment_status', 'paid'),
      // Pool tickets count
      supabase.from('pool_tickets')
        .select('id', { count: 'exact', head: true })
        .gte('ticket_date', today)
        .lte('ticket_date', endOfDay),
      // Pool revenue
      supabase.from('pool_tickets')
        .select('total_amount')
        .gte('ticket_date', today)
        .lte('ticket_date', endOfDay)
        .eq('payment_status', 'paid'),
      // Total users
      supabase.from('users')
        .select('id', { count: 'exact', head: true }),
      // Recent orders (with item count)
      supabase.from('restaurant_orders')
        .select('id, order_number, customer_name, status, total_amount, created_at, items:restaurant_order_items(id)')
        .order('created_at', { ascending: false })
        .limit(5),
      // Yesterday orders
      supabase.from('restaurant_orders')
        .select('id', { count: 'exact', head: true })
        .gte('created_at', yesterday)
        .lte('created_at', endOfYesterday),
      // Yesterday revenue
      supabase.from('restaurant_orders')
        .select('total_amount')
        .gte('created_at', yesterday)
        .lte('created_at', endOfYesterday)
        .eq('payment_status', 'paid'),
      // Last week bookings
      supabase.from('chalet_bookings')
        .select('id', { count: 'exact', head: true })
        .gte('check_in_date', lastWeekStart)
        .lte('check_in_date', lastWeekEnd),
      // Yesterday tickets
      supabase.from('pool_tickets')
        .select('id', { count: 'exact', head: true })
        .gte('ticket_date', yesterday)
        .lte('ticket_date', endOfYesterday)
    ]);

    // Calculate totals using type-safe function
    const restaurantRevenue = sumAmounts((restaurantRevenueResult.data || []) as AmountRecord[]);
    const snackRevenue = sumAmounts((snackRevenueResult.data || []) as AmountRecord[]);
    const chaletRevenue = sumAmounts((chaletRevenueResult.data || []) as AmountRecord[]);
    const poolRevenue = sumAmounts((poolRevenueResult.data || []) as AmountRecord[]);

    const totalOrders = (restaurantOrdersResult.count || 0) + (snackOrdersResult.count || 0);
    const totalRevenue = restaurantRevenue + snackRevenue + chaletRevenue + poolRevenue;

    // Yesterday's calculations
    const yesterdayOrders = yesterdayOrdersResult.count || 0;
    const yesterdayRevenue = sumAmounts((yesterdayRevenueResult.data || []) as AmountRecord[]);
    const lastWeekBookings = lastWeekBookingsResult.count || 0;
    const yesterdayTickets = yesterdayTicketsResult.count || 0;

    // Calculate trends
    const ordersTrend = calculateTrend(totalOrders, yesterdayOrders);
    const revenueTrend = calculateTrend(totalRevenue, yesterdayRevenue);
    const bookingsTrend = calculateTrend(chaletBookingsResult.count || 0, lastWeekBookings);
    const ticketsTrend = calculateTrend(poolTicketsResult.count || 0, yesterdayTickets);

    // Transform recent orders to camelCase
    const recentOrders: RecentOrderSummary[] = ((recentOrdersResult.data || []) as RecentOrderQuery[]).map((order) => ({
      id: order.id,
      orderNumber: order.order_number,
      customerName: order.customer_name || 'Guest',
      status: order.status,
      totalAmount: order.total_amount,
      itemCount: order.items?.length || 0,
      createdAt: order.created_at,
    }));

    res.json({
      success: true,
      data: {
        todayOrders: totalOrders,
        todayRevenue: totalRevenue,
        todayBookings: chaletBookingsResult.count || 0,
        todayTickets: poolTicketsResult.count || 0,
        totalUsers: usersResult.count || 0,
        recentOrders: recentOrders,
        revenueByUnit: {
          restaurant: restaurantRevenue,
          snackBar: snackRevenue,
          chalets: chaletRevenue,
          pool: poolRevenue,
        },
        breakdown: {
          restaurantOrders: restaurantOrdersResult.count || 0,
          snackOrders: snackOrdersResult.count || 0,
          chaletBookings: chaletBookingsResult.count || 0,
          poolTickets: poolTicketsResult.count || 0,
        },
        trends: {
          orders: ordersTrend,
          revenue: revenueTrend,
          bookings: bookingsTrend,
          tickets: ticketsTrend,
        }
      },
    });
});

/**
 * GET /api/admin/revenue-stats
 * Get revenue statistics for a date range
 */
export const getRevenueStats = asyncHandler(async (req: Request, res: Response) => {
    const supabase = getSupabase();
    const { startDate, endDate } = req.query;
    
    const start = startDate ? dayjs(startDate as string).toISOString() : dayjs().subtract(30, 'day').toISOString();
    const end = endDate ? dayjs(endDate as string).toISOString() : dayjs().toISOString();

    const [
      restaurantResult,
      snackResult,
      chaletResult,
      poolResult
    ] = await Promise.all([
      supabase.from('restaurant_orders')
        .select('total_amount, created_at')
        .gte('created_at', start)
        .lte('created_at', end)
        .eq('payment_status', 'paid'),
      supabase.from('snack_orders')
        .select('total_amount, created_at')
        .gte('created_at', start)
        .lte('created_at', end)
        .eq('payment_status', 'paid'),
      supabase.from('chalet_bookings')
        .select('total_amount, created_at')
        .gte('created_at', start)
        .lte('created_at', end)
        .eq('payment_status', 'paid'),
      supabase.from('pool_tickets')
        .select('total_amount, created_at')
        .gte('created_at', start)
        .lte('created_at', end)
        .eq('payment_status', 'paid')
    ]);

    // Group by day
    interface DailyRevenue {
      restaurant: number;
      snack: number;
      chalets: number;
      pool: number;
      total: number;
    }
    
    const dailyRevenue: Record<string, DailyRevenue> = {};

    const addToDaily = (records: AmountRecord[] | null, key: keyof Omit<DailyRevenue, 'total'>, dateField: string) => {
      (records || []).forEach((r: AmountRecord & { created_at?: string }) => {
        const date = dayjs(r.created_at).format('YYYY-MM-DD');
        if (!dailyRevenue[date]) {
          dailyRevenue[date] = { restaurant: 0, snack: 0, chalets: 0, pool: 0, total: 0 };
        }
        const amount = parseFloat(r.total_amount || '0');
        dailyRevenue[date][key] += amount;
        dailyRevenue[date].total += amount;
      });
    };

    addToDaily(restaurantResult.data as (AmountRecord & { created_at?: string })[], 'restaurant', 'created_at');
    addToDaily(snackResult.data as (AmountRecord & { created_at?: string })[], 'snack', 'created_at');
    addToDaily(chaletResult.data as (AmountRecord & { created_at?: string })[], 'chalets', 'created_at');
    addToDaily(poolResult.data as (AmountRecord & { created_at?: string })[], 'pool', 'created_at');

    // Convert to array and sort by date
    const chartData = Object.entries(dailyRevenue)
      .map(([date, data]) => ({ date, ...data }))
      .sort((a, b) => a.date.localeCompare(b.date));

    const totals = {
      restaurant: sumAmounts((restaurantResult.data || []) as AmountRecord[]),
      snack: sumAmounts((snackResult.data || []) as AmountRecord[]),
      chalets: sumAmounts((chaletResult.data || []) as AmountRecord[]),
      pool: sumAmounts((poolResult.data || []) as AmountRecord[]),
    };

    res.json({
      success: true,
      data: {
        chartData,
        totals,
        grandTotal: totals.restaurant + totals.snack + totals.chalets + totals.pool,
        dateRange: { start, end }
      }
    });
});

import { Request, Response } from 'express';
import { asyncHandler } from '../../../middleware/async-handler.js';
import { getSupabase } from '../../../database/connection.js';
import { logger } from '../../../utils/logger.js';

/**
 * Delete Preview Controller
 * Provides impact analysis before deleting resources
 * Shows all affected/related data that would be impacted
 */

type EntityType = 'user' | 'booking' | 'staff' | 'chalet' | 'menu_item' | 'table' | 'module';

interface RelatedEntity {
  table: string;
  count: number;
  examples?: Array<{ id: string; identifier: string }>;
}

interface DeletePreviewResult {
  entity: {
    type: EntityType;
    id: string;
    identifier: string; // Human-readable name/number
    created_at?: string;
  };
  impact: {
    severity: 'low' | 'medium' | 'high' | 'critical';
    message: string;
    warnings: string[];
  };
  relatedEntities: RelatedEntity[];
  recommendations: string[];
  canDelete: boolean;
  requiresForce: boolean;
}

/**
 * GET /api/admin/delete-preview/:entityType/:entityId
 * Returns impact analysis for deleting an entity
 */
export const getDeletePreview = asyncHandler(async (req: Request, res: Response) => {
    const { entityType, entityId } = req.params;
    const supabase = getSupabase();

    // Validate entity type
    const validTypes: EntityType[] = ['user', 'booking', 'staff', 'chalet', 'menu_item', 'table', 'module'];
    if (!validTypes.includes(entityType as EntityType)) {
      res.status(400).json({
        success: false,
        error: `Invalid entity type. Valid types: ${validTypes.join(', ')}`,
      });
      return;
    }

    let result: DeletePreviewResult;

    switch (entityType as EntityType) {
      case 'user':
        result = await getUserDeletePreview(supabase, entityId);
        break;
      case 'booking':
        result = await getBookingDeletePreview(supabase, entityId);
        break;
      case 'staff':
        result = await getStaffDeletePreview(supabase, entityId);
        break;
      case 'chalet':
        result = await getChaletDeletePreview(supabase, entityId);
        break;
      case 'menu_item':
        result = await getMenuItemDeletePreview(supabase, entityId);
        break;
      case 'table':
        result = await getTableDeletePreview(supabase, entityId);
        break;
      case 'module':
        result = await getModuleDeletePreview(supabase, entityId);
        break;
      default:
        res.status(400).json({ success: false, error: 'Unsupported entity type' });
        return;
    }

    logger.info(`Delete preview requested for ${entityType}:${entityId}`, {
      severity: result.impact.severity,
      canDelete: result.canDelete,
    });

    res.json({ success: true, data: result });
});

/**
 * User delete preview
 */
async function getUserDeletePreview(supabase: any, userId: string): Promise<DeletePreviewResult> {
  // Get user info
  const { data: user, error: userError } = await supabase
    .from('users')
    .select('id, email, full_name, created_at')
    .eq('id', userId)
    .single();

  if (userError || !user) {
    throw new Error('User not found');
  }

  // Count related data
  const [
    bookingsResult,
    ordersResult,
    poolTicketsResult,
    reviewsResult,
    sessionsResult,
    rolesResult,
  ] = await Promise.all([
    supabase.from('chalet_bookings').select('id, booking_number', { count: 'exact' }).eq('user_id', userId).limit(5),
    supabase.from('restaurant_orders').select('id, order_number', { count: 'exact' }).eq('user_id', userId).limit(5),
    supabase.from('pool_tickets').select('id, ticket_number', { count: 'exact' }).eq('user_id', userId).limit(5),
    supabase.from('reviews').select('id, rating', { count: 'exact' }).eq('user_id', userId).limit(5),
    supabase.from('user_sessions').select('id', { count: 'exact' }).eq('user_id', userId),
    supabase.from('user_roles').select('role_id', { count: 'exact' }).eq('user_id', userId),
  ]);

  const relatedEntities: RelatedEntity[] = [
    { table: 'chalet_bookings', count: bookingsResult.count || 0, examples: bookingsResult.data?.map((b: any) => ({ id: b.id, identifier: b.booking_number })) },
    { table: 'restaurant_orders', count: ordersResult.count || 0, examples: ordersResult.data?.map((o: any) => ({ id: o.id, identifier: o.order_number })) },
    { table: 'pool_tickets', count: poolTicketsResult.count || 0, examples: poolTicketsResult.data?.map((t: any) => ({ id: t.id, identifier: t.ticket_number })) },
    { table: 'reviews', count: reviewsResult.count || 0 },
    { table: 'user_sessions', count: sessionsResult.count || 0 },
    { table: 'user_roles', count: rolesResult.count || 0 },
  ].filter(e => e.count > 0);

  const totalRelated = relatedEntities.reduce((sum, e) => sum + e.count, 0);
  const hasActiveBookings = bookingsResult.data?.some((b: any) => ['pending', 'confirmed', 'checked_in'].includes(b.status));

  // Determine severity
  let severity: 'low' | 'medium' | 'high' | 'critical' = 'low';
  const warnings: string[] = [];
  const recommendations: string[] = [];

  if (hasActiveBookings) {
    severity = 'critical';
    warnings.push('User has active bookings that must be cancelled or completed first');
    recommendations.push('Complete or cancel all active bookings before deleting');
  } else if (totalRelated > 100) {
    severity = 'high';
    warnings.push(`User has ${totalRelated} related records that will be affected`);
    recommendations.push('Consider anonymizing instead of deleting (GDPR compliant)');
  } else if (totalRelated > 10) {
    severity = 'medium';
    warnings.push(`User has ${totalRelated} related records`);
  }

  recommendations.push('User data can be anonymized via GDPR endpoint instead');

  return {
    entity: {
      type: 'user',
      id: userId,
      identifier: user.email || user.full_name,
      created_at: user.created_at,
    },
    impact: {
      severity,
      message: `Deleting this user will affect ${totalRelated} related records`,
      warnings,
    },
    relatedEntities,
    recommendations,
    canDelete: !hasActiveBookings,
    requiresForce: totalRelated > 50,
  };
}

/**
 * Booking delete preview
 */
async function getBookingDeletePreview(supabase: any, bookingId: string): Promise<DeletePreviewResult> {
  const { data: booking, error } = await supabase
    .from('chalet_bookings')
    .select('id, booking_number, status, check_in_date, check_out_date, total_amount, user_id, created_at')
    .eq('id', bookingId)
    .single();

  if (error || !booking) {
    throw new Error('Booking not found');
  }

  const [paymentsResult, addOnsResult] = await Promise.all([
    supabase.from('payments').select('id, amount', { count: 'exact' }).eq('booking_id', bookingId),
    supabase.from('chalet_booking_addons').select('id', { count: 'exact' }).eq('booking_id', bookingId),
  ]);

  const relatedEntities: RelatedEntity[] = [
    { table: 'payments', count: paymentsResult.count || 0 },
    { table: 'booking_addons', count: addOnsResult.count || 0 },
  ].filter(e => e.count > 0);

  const warnings: string[] = [];
  const recommendations: string[] = [];
  let severity: 'low' | 'medium' | 'high' | 'critical' = 'low';
  
  const activeStatuses = ['pending', 'confirmed', 'checked_in'];
  if (activeStatuses.includes(booking.status)) {
    severity = 'critical';
    warnings.push(`Booking is currently ${booking.status} - cannot delete active booking`);
    recommendations.push('Cancel the booking first using the status update endpoint');
  }

  if (paymentsResult.count > 0) {
    severity = severity === 'critical' ? 'critical' : 'high';
    warnings.push(`${paymentsResult.count} payment record(s) will be orphaned`);
    recommendations.push('Ensure refunds are processed before deletion');
  }

  return {
    entity: {
      type: 'booking',
      id: bookingId,
      identifier: booking.booking_number,
      created_at: booking.created_at,
    },
    impact: {
      severity,
      message: `Booking ${booking.booking_number} (${booking.status})`,
      warnings,
    },
    relatedEntities,
    recommendations,
    canDelete: !activeStatuses.includes(booking.status),
    requiresForce: paymentsResult.count > 0,
  };
}

