 */
async function getModuleDeletePreview(supabase: any, moduleId: string): Promise<DeletePreviewResult> {
  const { data: module, error } = await supabase
    .from('modules')
    .select('id, name, type, created_at')
    .eq('id', moduleId)
    .single();

  if (error || !module) {
    throw new Error('Module not found');
  }

  // Different related data based on module type
  let relatedEntities: RelatedEntity[] = [];
  const warnings: string[] = [];
  const recommendations: string[] = [];
  let severity: 'low' | 'medium' | 'high' | 'critical' = 'low';
  let canDelete = true;

  if (module.type === 'multi_day') {
    const { count: bookingsCount } = await supabase
      .from('chalet_bookings')
      .select('id', { count: 'exact' })
      .eq('module_id', moduleId);
    
    const { count: unitsCount } = await supabase
      .from('chalets')
      .select('id', { count: 'exact' })
      .eq('module_id', moduleId);

    relatedEntities = [
      { table: 'units/chalets', count: unitsCount || 0 },
      { table: 'bookings', count: bookingsCount || 0 },
    ].filter(e => e.count > 0);

    if (bookingsCount && bookingsCount > 0) {
      severity = 'critical';
      warnings.push(`Module has ${bookingsCount} booking(s)`);
      canDelete = false;
    }
  } else if (module.type === 'restaurant') {
    const [ordersResult, tablesResult, menuResult] = await Promise.all([
      supabase.from('restaurant_orders').select('id', { count: 'exact' }).eq('module_id', moduleId),
      supabase.from('restaurant_tables').select('id', { count: 'exact' }).eq('module_id', moduleId),
      supabase.from('menu_items').select('id', { count: 'exact' }).eq('module_id', moduleId),
    ]);

    relatedEntities = [
      { table: 'orders', count: ordersResult.count || 0 },
      { table: 'tables', count: tablesResult.count || 0 },
      { table: 'menu_items', count: menuResult.count || 0 },
    ].filter(e => e.count > 0);

    if (ordersResult.count && ordersResult.count > 0) {
      severity = 'high';
      warnings.push(`Module has ${ordersResult.count} order(s)`);
    }
  }

  recommendations.push('Consider disabling the module instead of deleting');
  recommendations.push('All related data will be cascade deleted');

  return {
    entity: {
      type: 'module',
      id: moduleId,
      identifier: module.name,
      created_at: module.created_at,
    },
    impact: {
      severity,
      message: `Deleting module will remove all associated data`,
      warnings,
    },
    relatedEntities,
    recommendations,
    canDelete,
    requiresForce: true,
  };
}

/**
 * Notifications Controller
 * Handles notification retrieval and management with templates, scheduling, and priorities
 */

import { Request, Response, NextFunction } from 'express';
import { asyncHandler } from '../../../middleware/async-handler.js';
import { getSupabase } from '../../../database/connection';
import { logger } from '../../../utils/logger';
import { getContainer } from '../../../lib/container';
import type { NotificationPriority, NotificationTargetType, NotificationType } from '../../../lib/container/types';

export const getNotifications = asyncHandler(async (req: Request, res: Response) => {
    const container = getContainer();
    const notificationService = container.notificationService();
    const { userId } = req.query;
    
    // Get notifications from the service
    const notifications = await notificationService.getForUser(
      userId as string || req.user?.userId || '',
      {
        unreadOnly: req.query.unreadOnly === 'true',
        type: req.query.type as NotificationType,
        limit: parseInt(req.query.limit as string) || 20
      }
    );
    
    // Also get recent system events as real-time notifications
    const supabase = getSupabase();
    const now = new Date();
    const oneDayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);

    const systemNotifications: Array<{ 
      id: string; 
      title: string; 
      message: string; 
      type: string;
      target_type: string;
      created_at: string; 
      is_read: boolean;
      priority: string;
    }> = [];

    // Get recent restaurant orders with error handling
    try {
      const { data: recentOrders } = await supabase
        .from('restaurant_orders')
        .select('id, order_number, status, created_at')
        .gte('created_at', oneDayAgo.toISOString())
        .order('created_at', { ascending: false })
        .limit(5);

      (recentOrders || []).forEach(order => {
        systemNotifications.push({
          id: `order-${order.id}`,
          title: 'New Order',
          message: `Order #${order.order_number} - ${order.status}`,
          type: 'info',
          target_type: 'staff',
          created_at: order.created_at,
          is_read: order.status !== 'pending',
          priority: order.status === 'pending' ? 'high' : 'normal',
        });
      });
    } catch (error) {
      logger.warn('Failed to fetch recent restaurant orders for notifications:', error);
    }

    // Get recent chalet bookings with error handling
    try {
      const { data: recentBookings } = await supabase
        .from('chalet_bookings')
        .select('id, chalet_id, check_in_date, status, created_at')
        .gte('created_at', oneDayAgo.toISOString())
        .order('created_at', { ascending: false })
        .limit(5);

      (recentBookings || []).forEach(booking => {
        systemNotifications.push({
          id: `booking-${booking.id}`,
          title: 'Chalet Booking',
          message: `New booking for ${booking.check_in_date}`,
          type: 'info',
          target_type: 'staff',
          created_at: booking.created_at,
          is_read: booking.status !== 'pending',
          priority: 'normal',
        });
      });
    } catch (error) {
      logger.warn('Failed to fetch recent chalet bookings for notifications:', error);
    }

    // Get pending reviews with error handling
    try {
      const { data: pendingReviews } = await supabase
        .from('reviews')
        .select('id, rating, created_at')
        .eq('is_approved', false)
        .order('created_at', { ascending: false })
        .limit(5);

      (pendingReviews || []).forEach(review => {
        systemNotifications.push({
          id: `review-${review.id}`,
          title: 'Review Pending',
          message: `New ${review.rating}-star review awaiting approval`,
          type: 'warning',
          target_type: 'admin',
          created_at: review.created_at,
          is_read: false,
          priority: 'normal',
        });
      });
    } catch (error) {
      logger.warn('Failed to fetch pending reviews for notifications:', error);
    }

    // Combine stored notifications with system notifications
    const allNotifications = [
