import { Request, Response } from 'express';
import { asyncHandler } from '../../../middleware/async-handler.js';
import { getSupabase } from '../../../database/connection.js';
import { logger } from '../../../utils/logger.js';
import { logActivity } from '../../../utils/activityLogger.js';

/**
 * Soft Delete Controller
 * Provides soft delete and restore functionality for critical entities
 */

type SoftDeleteEntity = 'users' | 'chalet_bookings' | 'restaurant_orders' | 'pool_tickets' | 'chalets';

interface SoftDeletedRecord {
  id: string;
  identifier: string;
  deleted_at: string;
  deleted_by: string | null;
}

/**
 * GET /api/admin/deleted/:entityType
 * Returns list of soft-deleted records for an entity type
 */
export const getDeletedRecords = asyncHandler(async (req: Request, res: Response) => {
    const { entityType } = req.params;
    const { limit = 50, offset = 0 } = req.query;
    const supabase = getSupabase();

    // Validate entity type
    const validTypes: SoftDeleteEntity[] = ['users', 'chalet_bookings', 'restaurant_orders', 'pool_tickets', 'chalets'];
    if (!validTypes.includes(entityType as SoftDeleteEntity)) {
      res.status(400).json({
        success: false,
        error: `Invalid entity type. Valid types: ${validTypes.join(', ')}`,
      });
      return;
    }

    // Get select fields based on entity type
    let selectFields = 'id, deleted_at, deleted_by';
    switch (entityType) {
      case 'users':
        selectFields += ', email, full_name';
        break;
      case 'chalet_bookings':
        selectFields += ', booking_number, customer_name';
        break;
      case 'restaurant_orders':
        selectFields += ', order_number, customer_name';
        break;
      case 'pool_tickets':
        selectFields += ', ticket_number, guest_name';
        break;
      case 'chalets':
        selectFields += ', name';
        break;
    }

    const { data, error, count } = await supabase
      .from(entityType)
      .select(selectFields, { count: 'exact' })
      .not('deleted_at', 'is', null)
      .order('deleted_at', { ascending: false })
      .range(Number(offset), Number(offset) + Number(limit) - 1);

    if (error) throw error;

    // Map to consistent format
    const records: SoftDeletedRecord[] = (data || []).map((record: any) => {
      let identifier = '';
      switch (entityType) {
        case 'users':
          identifier = record.email || record.full_name;
          break;
        case 'chalet_bookings':
          identifier = record.booking_number;
          break;
        case 'restaurant_orders':
          identifier = record.order_number;
          break;
        case 'pool_tickets':
          identifier = record.ticket_number;
          break;
        case 'chalets':
          identifier = record.name;
          break;
      }
      return {
        id: record.id,
        identifier,
        deleted_at: record.deleted_at,
        deleted_by: record.deleted_by,
      };
    });

    res.json({
      success: true,
      data: records,
      pagination: { total: count, limit: Number(limit), offset: Number(offset) },
    });
});

/**
 * POST /api/admin/deleted/:entityType/:entityId/restore
 * Restores a soft-deleted record
 */
export const restoreRecord = asyncHandler(async (req: Request, res: Response) => {
    const { entityType, entityId } = req.params;
    const userId = req.user?.userId;
    if (!userId) throw new Error('Authentication required');
    const supabase = getSupabase();

    // Validate entity type
    const validTypes: SoftDeleteEntity[] = ['users', 'chalet_bookings', 'restaurant_orders', 'pool_tickets', 'chalets'];
    if (!validTypes.includes(entityType as SoftDeleteEntity)) {
      res.status(400).json({
        success: false,
        error: `Invalid entity type. Valid types: ${validTypes.join(', ')}`,
      });
      return;
    }

    // Verify record exists and is deleted
    const { data: existing, error: fetchError } = await supabase
      .from(entityType)
      .select('id, deleted_at')
      .eq('id', entityId)
      .single();

    if (fetchError || !existing) {
      res.status(404).json({ success: false, error: 'Record not found' });
      return;
    }

    if (!existing.deleted_at) {
      res.status(400).json({ success: false, error: 'Record is not deleted' });
      return;
    }

    // Restore the record
    const { data, error } = await supabase
      .from(entityType)
      .update({
        deleted_at: null,
        deleted_by: null,
        is_active: true, // Also reactivate if applicable
      })
      .eq('id', entityId)
      .select()
      .single();

    if (error) throw error;

    await logActivity({
      user_id: userId,
      action: 'RESTORE_RECORD',
      resource: entityType,
      resource_id: entityId,
      details: { restored_by: userId },
    });

    logger.info(`Record restored: ${entityType}:${entityId}`, { userId });

    res.json({
      success: true,
      message: 'Record restored successfully',
      data,
    });
});

/**
 * DELETE /api/admin/deleted/:entityType/:entityId/permanent
 * Permanently deletes a soft-deleted record (requires force=true query param)
 */
export const permanentDelete = asyncHandler(async (req: Request, res: Response) => {
    const { entityType, entityId } = req.params;
    const { force } = req.query;
    const userId = req.user?.userId;
    if (!userId) throw new Error('Authentication required');
    const supabase = getSupabase();

    if (force !== 'true') {
      res.status(400).json({
        success: false,
        error: 'Permanent deletion requires force=true query parameter',
      });
      return;
    }

    // Validate entity type
    const validTypes: SoftDeleteEntity[] = ['users', 'chalet_bookings', 'restaurant_orders', 'pool_tickets', 'chalets'];
    if (!validTypes.includes(entityType as SoftDeleteEntity)) {
      res.status(400).json({
        success: false,
        error: `Invalid entity type. Valid types: ${validTypes.join(', ')}`,
      });
      return;
    }

    // Verify record is already soft-deleted
    const { data: existing, error: fetchError } = await supabase
      .from(entityType)
      .select('id, deleted_at')
      .eq('id', entityId)
      .single();

    if (fetchError || !existing) {
      res.status(404).json({ success: false, error: 'Record not found' });
      return;
    }

    if (!existing.deleted_at) {
      res.status(400).json({ 
        success: false, 
        error: 'Record must be soft-deleted first before permanent deletion',
      });
      return;
    }

    // Permanently delete the record
    const { error } = await supabase
      .from(entityType)
      .delete()
      .eq('id', entityId);

    if (error) throw error;

    await logActivity({
      user_id: userId,
      action: 'PERMANENT_DELETE',
      resource: entityType,
      resource_id: entityId,
      details: { deleted_by: userId },
    });

    logger.warn(`Record permanently deleted: ${entityType}:${entityId}`, { userId });

    res.json({
      success: true,
      message: 'Record permanently deleted',
    });
});

/**
 * POST /api/admin/soft-delete/:entityType/:entityId
 * Soft deletes a record
 */
export const softDelete = asyncHandler(async (req: Request, res: Response) => {
    const { entityType, entityId } = req.params;
    const userId = req.user?.userId;
    if (!userId) throw new Error('Authentication required');
    const supabase = getSupabase();

    // Validate entity type
    const validTypes: SoftDeleteEntity[] = ['users', 'chalet_bookings', 'restaurant_orders', 'pool_tickets', 'chalets'];
    if (!validTypes.includes(entityType as SoftDeleteEntity)) {
      res.status(400).json({
        success: false,
        error: `Invalid entity type. Valid types: ${validTypes.join(', ')}`,
      });
      return;
    }

    // Verify record exists and is not already deleted
    const { data: existing, error: fetchError } = await supabase
      .from(entityType)
      .select('id, deleted_at')
      .eq('id', entityId)
      .single();

    if (fetchError || !existing) {
      res.status(404).json({ success: false, error: 'Record not found' });
      return;
    }

    if (existing.deleted_at) {
      res.status(400).json({ success: false, error: 'Record is already deleted' });
      return;
    }

    // Soft delete the record
    const { data, error } = await supabase
      .from(entityType)
      .update({
        deleted_at: new Date().toISOString(),
        deleted_by: userId,
        is_active: false,
      })
      .eq('id', entityId)
      .select()
      .single();

    if (error) throw error;

    await logActivity({
      user_id: userId,
      action: 'SOFT_DELETE',
      resource: entityType,
      resource_id: entityId,
      details: { deleted_by: userId },
    });

    logger.info(`Record soft deleted: ${entityType}:${entityId}`, { userId });

    res.json({
      success: true,
      message: 'Record soft deleted successfully',
      data,
    });
});

/**
 * File Upload Controller
 * Handles logo, favicon, and image uploads to Supabase Storage
 */

import { Request, Response, NextFunction } from 'express';
import { asyncHandler } from '../../../middleware/async-handler.js';
import { getSupabase } from '../../../database/connection.js';
import { logActivity } from '../../../utils/activityLogger.js';
import { logger } from '../../../utils/logger.js';
import { emitToAll } from '../../../socket/index.js';

// Allowed file types for different upload categories
const ALLOWED_TYPES: Record<string, string[]> = {
  logo: ['image/png', 'image/jpeg', 'image/svg+xml', 'image/webp'],
  favicon: ['image/png', 'image/x-icon', 'image/svg+xml', 'image/vnd.microsoft.icon'],
  image: ['image/png', 'image/jpeg', 'image/webp', 'image/gif'],
};

// Max file sizes in bytes
const MAX_SIZES: Record<string, number> = {
  logo: 2 * 1024 * 1024, // 2MB
  favicon: 512 * 1024, // 512KB
  image: 5 * 1024 * 1024, // 5MB
};

// Storage bucket name
const BUCKET_NAME = 'assets';

/**
 * Ensure the assets bucket exists
 */
async function ensureBucket() {
  const supabase = getSupabase();
  
  const { data: buckets } = await supabase.storage.listBuckets();
  const bucketExists = buckets?.some(b => b.name === BUCKET_NAME);
  
  if (!bucketExists) {
    const { error } = await supabase.storage.createBucket(BUCKET_NAME, {
      public: true,
      fileSizeLimit: 10 * 1024 * 1024, // 10MB max
      allowedMimeTypes: [
        'image/png',
        'image/jpeg',
        'image/svg+xml',
        'image/webp',
        'image/gif',
        'image/x-icon',
        'image/vnd.microsoft.icon',
      ],
    });
    
    if (error && !error.message.includes('already exists')) {
      throw error;
    }
  }
}

/**
 * Upload a file (logo, favicon, or general image)
 * Expects multipart/form-data with:
 * - file: The file buffer
 * - type: 'logo' | 'favicon' | 'image'
 * - filename: Original filename
 */
export const uploadFile = asyncHandler(async (req: Request, res: Response) => {
    const supabase = getSupabase();
    const userId = req.user?.userId;
    
    // Check if we have file data in body (from middleware)
    const { file, type = 'image', filename } = req.body;
    
    if (!file) {
      return res.status(400).json({
        success: false,
        error: 'No file provided',
      });
    }
    
    // Validate type
    const uploadType = type as string;
    if (!ALLOWED_TYPES[uploadType]) {
      return res.status(400).json({
        success: false,
        error: `Invalid upload type. Must be one of: ${Object.keys(ALLOWED_TYPES).join(', ')}`,
      });
    }
    
    // Convert base64 to buffer if needed
    let fileBuffer: Buffer;
    let mimeType: string;
    
    if (typeof file === 'string' && file.includes('base64')) {
      // Extract base64 data and mime type
      const matches = file.match(/^data:([^;]+);base64,(.+)$/);
      if (!matches) {
        return res.status(400).json({
          success: false,
          error: 'Invalid base64 file format',
        });
      }
      mimeType = matches[1];
      fileBuffer = Buffer.from(matches[2], 'base64');
    } else if (Buffer.isBuffer(file)) {
      fileBuffer = file;
      mimeType = req.headers['content-type'] || 'application/octet-stream';
    } else {
      return res.status(400).json({
        success: false,
        error: 'Invalid file format. Send base64 encoded data.',
      });
    }
    
    // Validate mime type
    if (!ALLOWED_TYPES[uploadType].includes(mimeType)) {
      return res.status(400).json({
        success: false,
        error: `Invalid file type for ${uploadType}. Allowed: ${ALLOWED_TYPES[uploadType].join(', ')}`,
      });
    }
    
    // Validate file size
    if (fileBuffer.length > MAX_SIZES[uploadType]) {
      return res.status(400).json({
        success: false,
        error: `File too large. Max size for ${uploadType}: ${MAX_SIZES[uploadType] / 1024 / 1024}MB`,
      });
    }
    
    // Ensure bucket exists
    await ensureBucket();
    
    // Generate unique filename
    const ext = mimeType.split('/')[1]?.replace('svg+xml', 'svg').replace('x-icon', 'ico').replace('vnd.microsoft.icon', 'ico') || 'png';
    const timestamp = Date.now();
    const safeName = (filename || 'file').replace(/[^a-zA-Z0-9.-]/g, '_').substring(0, 50);
    const storagePath = `${uploadType}/${timestamp}-${safeName}.${ext}`;
    
    // Upload to Supabase Storage
    const { data, error } = await supabase.storage
      .from(BUCKET_NAME)
      .upload(storagePath, fileBuffer, {
        contentType: mimeType,
        upsert: true,
      });
    
    if (error) {
      logger.error('File upload failed', { error: error.message, path: storagePath });
      throw error;
    }
    
    // Get public URL
    const { data: urlData } = supabase.storage
      .from(BUCKET_NAME)
      .getPublicUrl(storagePath);
    
    const publicUrl = urlData.publicUrl;
    
    // If this is a logo or favicon, update site settings
    if (uploadType === 'logo' || uploadType === 'favicon') {
      const settingKey = uploadType === 'logo' ? 'logoUrl' : 'faviconUrl';
      
      // Get existing branding settings
      const { data: existing } = await supabase
        .from('site_settings')
        .select('value')
        .eq('key', 'branding')
        .single();
      
      const brandingSettings = (existing?.value as Record<string, unknown>) || {};
      brandingSettings[settingKey] = publicUrl;
      
      // Update settings
      const { error: updateError } = await supabase
        .from('site_settings')
        .upsert({
          key: 'branding',
          value: brandingSettings,
          updated_at: new Date().toISOString(),
        }, {
          onConflict: 'key',
        });
      
      if (updateError) {
        logger.error('Failed to update branding settings', { error: updateError.message });
      }
      
      // Emit real-time update
      emitToAll('settings:updated', { key: 'branding', value: brandingSettings });
    }
    
    // Log activity
    await logActivity({
      user_id: userId || 'system',
      action: 'UPLOAD',
      resource: 'file',
      resource_id: storagePath,
    });
    
    logger.info(`File uploaded successfully: ${storagePath}`);
    
    res.json({
      success: true,
      data: {
        url: publicUrl,
        path: storagePath,
        type: uploadType,
        size: fileBuffer.length,
      },
    });
});

/**
 * Delete an uploaded file
 */
export const deleteFile = asyncHandler(async (req: Request, res: Response) => {
    const supabase = getSupabase();
    const userId = req.user?.userId;
    const { path } = req.params;
    
    if (!path) {
      return res.status(400).json({
        success: false,
        error: 'File path required',
      });
    }
    
    // Delete from storage
    const { error } = await supabase.storage
      .from(BUCKET_NAME)
      .remove([path]);
    
    if (error) {
      logger.error('File deletion failed', { error: error.message, path });
      throw error;
    }
    
    // Log activity
    await logActivity({
      user_id: userId || 'system',
      action: 'DELETE',
      resource: 'file',
      resource_id: path,
    });
    
    logger.info(`File deleted: ${path}`);
    
    res.json({
      success: true,
      message: 'File deleted successfully',
    });
});

/**
 * List uploaded files by type
 */
export const listFiles = asyncHandler(async (req: Request, res: Response) => {
    const supabase = getSupabase();
    const { type } = req.query;
    
    const folder = (type as string) || '';
    
    const { data, error } = await supabase.storage
      .from(BUCKET_NAME)
      .list(folder, {
        limit: 100,
        sortBy: { column: 'created_at', order: 'desc' },
      });
    
    if (error) {
      throw error;
    }
    
    // Get public URLs for all files
    const files = (data || []).map(file => {
      const path = folder ? `${folder}/${file.name}` : file.name;
      const { data: urlData } = supabase.storage
        .from(BUCKET_NAME)
        .getPublicUrl(path);
      
      return {
        name: file.name,
        path,
        url: urlData.publicUrl,
        size: file.metadata?.size,
        createdAt: file.created_at,
      };
    });
    
    res.json({
      success: true,
      data: files,
    });
});

/**
 * Get current branding (logo/favicon URLs)
 */
export const getBranding = asyncHandler(async (req: Request, res: Response) => {
    const supabase = getSupabase();
    
    const { data, error } = await supabase
      .from('site_settings')
      .select('value')
      .eq('key', 'branding')
      .single();
    
    if (error && error.code !== 'PGRST116') { // Not found is OK
      throw error;
    }
    
    const branding = (data?.value as Record<string, unknown>) || {
      logoUrl: null,
      faviconUrl: null,
    };
    
    res.json({
      success: true,
      data: branding,
    });
});

/**
 * Email Settings Controller
 * 
 * API endpoints for managing email configuration.
 */

import { Router, Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import { authenticate } from '../../middleware/auth.middleware.js';
import { roleGuard } from '../../middleware/roleGuard.middleware';
import { getSupabase } from '../../database/connection.js';
import { logger } from '../../utils/logger.js';
import { emailService } from '../../services/email.service.js';
import { encrypt, decrypt } from '../../utils/encryption.js';
import { asyncHandler } from '../../middleware/async-handler.js';

const router = Router();

// Validation schema
const emailConfigSchema = z.object({
  provider: z.enum(['smtp', 'sendgrid', 'ses', 'mailgun', 'postmark']),
  smtpHost: z.string().optional(),
  smtpPort: z.number().min(1).max(65535).optional(),
  smtpSecure: z.boolean().optional(),
  smtpUser: z.string().optional(),
  smtpPassword: z.string().optional(),
  apiKey: z.string().optional(),
  fromEmail: z.string().email(),
  fromName: z.string().min(1),
  replyToEmail: z.string().email().optional().or(z.literal('')),
});

/**
 * GET /admin/settings/email
 * Get current email configuration (sensitive data masked)
 */
router.get(
  '/',
  authenticate,
  roleGuard(['admin', 'super_admin']),
  asyncHandler(async (req: Request, res: Response) => {
    const supabase = getSupabase();
    const { data: settings, error: settingsError } = await supabase
        .from('system_settings')
        .select('*')
        .eq('category', 'email');
      if (settingsError) throw settingsError;

      // Convert to object and mask sensitive fields
      const config: Record<string, any> = {};
      for (const setting of (settings || [])) {
        const key = setting.key.replace('email.', '');
        
        // Mask sensitive values
        if (key === 'smtpPassword' || key === 'apiKey') {
          config[key] = setting.value ? '••••••••' : '';
        } else {
          config[key] = setting.value;
        }
      }

      res.json({
        success: true,
        data: config
      });
  })
);

/**
 * PUT /admin/settings/email
 * Update email configuration
 */
router.put(
  '/',
  authenticate,
  roleGuard(['admin', 'super_admin']),
  asyncHandler(async (req: Request, res: Response) => {
    const validation = emailConfigSchema.safeParse(req.body);
      
      if (!validation.success) {
        return res.status(400).json({
          success: false,
          error: 'Validation failed',
          details: validation.error.flatten()
        });
      }

      const config = validation.data;
      const userId = req.user!.id;

      // Prepare settings to upsert
      const settingsToSave: { key: string; value: string; encrypted?: boolean }[] = [
        { key: 'email.provider', value: config.provider },
        { key: 'email.fromEmail', value: config.fromEmail },
        { key: 'email.fromName', value: config.fromName },
        { key: 'email.replyToEmail', value: config.replyToEmail || '' },
      ];

      // Add provider-specific settings
      if (config.provider === 'smtp') {
        settingsToSave.push(
          { key: 'email.smtpHost', value: config.smtpHost || '' },
          { key: 'email.smtpPort', value: String(config.smtpPort || 587) },
          { key: 'email.smtpSecure', value: String(config.smtpSecure ?? true) },
          { key: 'email.smtpUser', value: config.smtpUser || '' }
        );
        
        // Only update password if provided and not masked
        if (config.smtpPassword && !config.smtpPassword.includes('•')) {
          settingsToSave.push({
            key: 'email.smtpPassword',
            value: encrypt(config.smtpPassword),
            encrypted: true
          });
        }
      } else {
        // Only update API key if provided and not masked
        if (config.apiKey && !config.apiKey.includes('•')) {
          settingsToSave.push({
            key: 'email.apiKey',
            value: encrypt(config.apiKey),
            encrypted: true
          });
        }
      }

      // Upsert all settings
      const supabase = getSupabase();
      for (const setting of settingsToSave) {
        const { error: upsertError } = await supabase
          .from('system_settings')
          .upsert({
            key: setting.key,
            value: setting.value,
            category: 'email',
            updated_at: new Date().toISOString(),
            updated_by: userId,
            created_by: userId,
          }, { onConflict: 'key' });
        if (upsertError) throw upsertError;
      }

      // Reload email service with new configuration
      try {
        await reloadEmailService();
      } catch (reloadError) {
        logger.warn('Failed to reload email service with new config', { error: reloadError });
      }

      logger.info('Email configuration updated', { userId, provider: config.provider });

      res.json({
        success: true,
        message: 'Email configuration saved successfully'
      });
  })
);

/**
 * POST /admin/settings/email/test
 * Send a test email
 */
router.post(
  '/test',
  authenticate,
  roleGuard(['admin', 'super_admin']),
  async (req: Request, res: Response, next: NextFunction) => {
    try {
      const { testRecipient, ...config } = req.body;
      
      const validation = emailConfigSchema.safeParse(config);
      
      if (!validation.success) {
        return res.status(400).json({
          success: false,
          error: 'Invalid configuration',
          details: validation.error.flatten()
        });
      }

      const recipient = testRecipient || config.fromEmail;
      
      // Create a temporary email transport with the test configuration
      const testConfig = await buildTransportConfig(validation.data);
      
      // Send test email
      await emailService.sendEmail({
        to: recipient,
        subject: 'V2 Resort - Email Configuration Test',
        html: `
          <h2>Email Configuration Test</h2>
          <p>This is a test email from your V2 Resort system.</p>
          <p>If you received this email, your email configuration is working correctly!</p>
          <hr>
          <p style="color: #666; font-size: 12px;">
            Sent at: ${new Date().toLocaleString()}<br>
            Provider: ${config.provider}<br>
            From: ${config.fromName} &lt;${config.fromEmail}&gt;
          </p>
        `
      });

      logger.info('Test email sent successfully', { 
        recipient, 
        provider: config.provider,
        userId: req.user!.id 
      });

      res.json({
        success: true,
        message: `Test email sent to ${recipient}`
      });
    } catch (error: any) {
      logger.error('Failed to send test email', { error: error.message });
      
      res.status(400).json({
        success: false,
        error: 'Failed to send test email',
        details: error.message
      });
    }
  }
);

/**
 * Build transport configuration from settings
 */
async function buildTransportConfig(config: z.infer<typeof emailConfigSchema>) {
  if (config.provider === 'smtp') {
    return {
      host: config.smtpHost,
      port: config.smtpPort,
      secure: config.smtpSecure,
      auth: {
        user: config.smtpUser,
        pass: config.smtpPassword
      }
    };
  }
  
  // For other providers, return API-based config
  return {
    provider: config.provider,
    apiKey: config.apiKey
  };
}

/**
 * Reload email service with updated configuration
 */
async function reloadEmailService(): Promise<void> {
  const supabase = getSupabase();
  const { data: settings, error } = await supabase
    .from('system_settings')
    .select('*')
    .eq('category', 'email');
  if (error) throw error;

  const config: Record<string, string> = {};
  for (const setting of (settings || [])) {
    const key = setting.key.replace('email.', '');
    // Encrypted property not in schema currently
    // config[key] = setting.encrypted ? decrypt(setting.value) : setting.value;
    config[key] = setting.value;
  }

  // This would reload the email service - implementation depends on your email service
  logger.info('Email service configuration reloaded', { provider: config.provider });
}

export default router;

import { Request, Response, NextFunction } from 'express';
import { asyncHandler } from '../../middleware/async-handler.js';
import { getSupabase } from "../../database/connection";
import { emitToAll } from "../../socket";
import bcrypt from 'bcryptjs';
import { clearModuleCache } from "../../middleware/moduleGuard.middleware";
import { createModuleSchema, updateModuleSchema, validateBody } from "../../validation/schemas";
import { logActivity } from "../../utils/activityLogger";
import { logger } from "../../utils/logger.js";

export async function getModules(req: Request, res: Response, next: NextFunction) {
  try {
    const supabase = getSupabase();
    const { activeOnly } = req.query;

    let query = supabase
      .from('modules')
      .select('*')
      .order('sort_order', { ascending: true });

    if (activeOnly === 'true') {
      query = query.eq('is_active', true);
    }

    // Optionally filter by show_in_main if requested
    if (req.query.showInMain === 'true') {
      query = query.eq('show_in_main', true);
    }

    const { data, error } = await query;

    if (error) throw error;

    res.json({ success: true, data });
  } catch (error: unknown) {
    res.status(500).json({ success: false, error: 'Failed to fetch modules' });
  }
}

export const getModule = asyncHandler(async (req: Request, res: Response) => {
    const supabase = getSupabase();
    const { id } = req.params;

    // Try to fetch by id first
    const { data: initialData, error: initialError } = await supabase
      .from('modules')
      .select('*')
      .eq('id', id)
      .single();

    let data = initialData;
    const error = initialError;

    // If not found by id, try slug
    if ((error || !data) && id) {
      const { data: bySlug, error: slugErr } = await supabase
        .from('modules')
        .select('*')
        .eq('slug', id)
        .single();

      if (slugErr) throw slugErr;
      if (!bySlug) return res.status(404).json({ success: false, error: 'Module not found' });

      data = bySlug;
    }

    res.json({ success: true, data });
});


export const createModule = asyncHandler(async (req: Request, res: Response) => {
    const supabase = getSupabase();
    
    // Validate input using schema to prevent XSS and ensure data integrity
    const { template_type, name, slug, description, settings } = validateBody(createModuleSchema, req.body);

    // Generate slug if not provided
    const finalSlug = slug || name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');

    // Default settings version for new modules
    const SETTINGS_VERSION = 1; 

    const { data, error } = await supabase
      .from('modules')
      .insert({
        template_type,
        name,
        slug: finalSlug,
        description,
        settings: settings || {},
        settings_version: SETTINGS_VERSION,
        is_active: true,
        show_in_main: true 
      })
      .select()
      .single();

    if (error) throw error;

    // Dynamic Permission Generation (P0) using new app_permissions
    try {
        const permsToCreate = [
            { slug: `module:${finalSlug}:read`, description: `Read access for module ${name}`, module_slug: finalSlug },
            { slug: `module:${finalSlug}:manage`, description: `Management access for module ${name}`, module_slug: finalSlug },
            { slug: `module:${finalSlug}:publish`, description: `Publish access for module ${name}`, module_slug: finalSlug },
        ];
        
        await supabase.from('app_permissions').upsert(permsToCreate, { onConflict: 'slug' });

        // Assign to super_admin
        const rolePerms = [
            { role_name: 'super_admin', permission_slug: `module:${finalSlug}:read` },
            { role_name: 'super_admin', permission_slug: `module:${finalSlug}:manage` },
            { role_name: 'super_admin', permission_slug: `module:${finalSlug}:publish` },
        ];

        await supabase.from('app_role_permissions').upsert(rolePerms, { onConflict: 'role_name,permission_slug' });
        
    } catch (permError) {
        logger.error(`Failed to generate permissions for ${finalSlug}`, permError);
    }

    // --- Auto-add to navbar CMS if configured ---
    try {
      const { data: siteSettings } = await supabase
        .from('site_settings')
        .select('id, navbar')
        .single();

      const settings = siteSettings as { id?: number; navbar?: { links?: unknown[] } } | null;
      if (settings?.navbar?.links && Array.isArray(settings.navbar.links)) {
        // Navbar is CMS-configured, auto-add the new module
        const newNavLink = {
          type: 'module',
          moduleSlug: finalSlug,
          label: name,
          icon: template_type === 'menu_service' ? 'UtensilsCrossed' : 
                template_type === 'session_access' ? 'Waves' : 'Home'
        };
        
        const updatedLinks = [...settings.navbar.links, newNavLink];
        await supabase
          .from('site_settings')
          .update({ 
            navbar: { 
              ...settings.navbar, 
              links: updatedLinks 
            } 
          })
          .eq('id', settings.id || 1);

        logger.info(`[Modules] Auto-added ${finalSlug} to navbar CMS links`);
      }
    } catch (navError) {
      logger.error('Failed to auto-add module to navbar:', navError);
      // Non-fatal - module still created
    }

    // --- Auto-create Roles & Staff User ---
    try {
      // 1. Create Roles
      const roleNames = [`${finalSlug}_admin`, `${finalSlug}_staff`];
      const { data: rolesData, error: rolesError } = await supabase
        .from('roles')
        .insert(roleNames.map(r => ({ name: r, description: `Role for ${name}` })))
        .select();

      if (!rolesError && rolesData) {
        // 2. Create Module Permissions (granular)
        const modulePermissions = [
          { slug: `${finalSlug}:view`, description: `View ${name}`, module_slug: finalSlug },
          { slug: `${finalSlug}:manage`, description: `Manage ${name}`, module_slug: finalSlug },
          // ... add others as needed, matching the colon convention better
        ];

        await supabase.from('app_permissions').upsert(modulePermissions, { onConflict: 'slug' });

        // 3. Link Permissions to Roles using app_role_permissions
        const rolePermissions: { role_name: string; permission_slug: string }[] = [];
        
        const adminRoleName = `${finalSlug}_admin`; 
        const staffRoleName = `${finalSlug}_staff`;

        // Admin gets all
        modulePermissions.forEach(p => {
             rolePermissions.push({ role_name: adminRoleName, permission_slug: p.slug });
        });
        // Staff gets view
        modulePermissions.filter(p => p.slug.includes(':view')).forEach(p => {
             rolePermissions.push({ role_name: staffRoleName, permission_slug: p.slug });
        });

        if (rolePermissions.length > 0) {
            await supabase.from('app_role_permissions').upsert(rolePermissions, { onConflict: 'role_name,permission_slug' });
            logger.info(`[Modules] Created ${rolePermissions.length} role-permission links for ${finalSlug}`);
        }

        // 4. Create Default Staff User
        const staffEmail = `staff.${finalSlug}@v2resort.com`;
        const staffPassword = await bcrypt.hash(`Staff${finalSlug.charAt(0).toUpperCase() + finalSlug.slice(1)}123!`, 10);

        const { data: userData, error: userError } = await supabase
          .from('users')
          .insert({
            email: staffEmail,
            password: staffPassword,
            full_name: `${name} Staff`,
            phone: '',
            is_active: true,
            email_verified: true,
            roles: roleNames 
          })
          .select()
          .single();

        if (!userError && userData) {
          // 5. Link User to Roles (using user_roles junction table if it exists and uses UUIDs)
          // We fetched rolesData which has IDs.
          const userRolesInserts = rolesData.map((role: { id: string; name: string }) => ({
            user_id: userData.id,
            role_id: role.id
          }));
          await supabase.from('user_roles').insert(userRolesInserts);
          logger.info(`[Modules] Created staff user ${staffEmail} with roles for ${finalSlug}`);
        }
      }
    } catch (innerError) {
      logger.error('Failed to auto-create staff/roles/permissions for module:', innerError);
      // We don't fail the module creation itself, just log
    }

    emitToAll('modules.updated', data);

    await logActivity({
      user_id: (req.user as any)?.userId || 'system',
      action: 'CREATE_MODULE',
      resource: 'module',
      resource_id: data.id,
      new_value: data,
      ip_address: req.ip,
      user_agent: req.get('user-agent')
    });

    res.status(201).json({ success: true, data });
});

export const updateModule = asyncHandler(async (req: Request, res: Response) => {
    // Validate input (includes optional settings_version)
    const validatedData = validateBody(updateModuleSchema, req.body);

    const supabase = getSupabase();
    const { id } = req.params;

    // 1. Fetch current module to check permissions and version
    const { data: currentModule, error: fetchError } = await supabase
      .from('modules')
      .select('slug, template_type, settings_version') 
      .eq('id', id)
      .single();

    if (fetchError || !currentModule) {
      return res.status(404).json({ success: false, error: 'Module not found' });
    }

    // 2. Enforce Permissions (RBAC)
    // Check for `module:{slug}:manage` permission via app_role_permissions
    // Or super_admin bypass
    const user = req.user;
    if (!user) throw new Error('Authentication required');
    if (!user.roles.includes('super_admin')) {
         const requiredPerm = `module:${currentModule.slug}:manage`;
         const { data: permData, error: permError } = await supabase
            .from('app_role_permissions')
            .select('permission_slug')
            .eq('permission_slug', requiredPerm)
            .in('role_name', user.roles)
            .limit(1);

         if (permError || !permData || permData.length === 0) {
             logger.warn(`Unauthorized module update attempt by ${user.userId} on ${currentModule.slug}`);
             return res.status(403).json({ success: false, error: 'Insufficient permissions' });
         }
    }

    // 3. Optimistic Concurrency Control
    if (validatedData.settings_version !== undefined) {
         if (currentModule.settings_version !== validatedData.settings_version) {
             return res.status(409).json({ 
                 success: false, 
                 error: 'Version conflict', 
                 message: 'The module settings have been modified by another user. Please reload and try again.',
                 currentVersion: currentModule.settings_version
             });
         }
    }

    // Prepare update data
    const updateData: any = { ...validatedData };
    
    // Remove settings_version from the actual update payload as it's handled manually below if needed
    delete updateData.settings_version;

    // Increment version if settings are being updated
    if (validatedData.settings) {
        updateData.settings_version = (currentModule.settings_version || 0) + 1;
    }

    const { data, error } = await supabase
      .from('modules')
      .update(updateData)
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;

    // Clear module cache so changes take effect immediately
    clearModuleCache(data.slug);

    emitToAll('modules.updated', data);

    await logActivity({
      user_id: user.userId,
      action: 'UPDATE_MODULE',
      resource: 'module',
      resource_id: id,
      old_value: currentModule, 
      new_value: data,
      ip_address: req.ip,
      user_agent: req.get('user-agent')
    });

    res.json({ success: true, data });
});

export const deleteModule = asyncHandler(async (req: Request, res: Response) => {
    const supabase = getSupabase();
    const { id } = req.params;
    const force = req.query.force === 'true';

    // 1. Fetch module for Permission Check
    const { data: moduleData } = await supabase
      .from('modules')
      .select('id, slug, name')
      .eq('id', id)
      .single();

    if (!moduleData) {
      return res.status(404).json({ success: false, error: 'Module not found' });
    }

    // 2. Enforce Permissions
    const user = req.user;
    if (!user) throw new Error('Authentication required');
    const hasPermission = user.roles.includes('super_admin') || 
                         user.roles.includes(`${moduleData.slug}_admin`);

    if (!hasPermission) {
      logger.warn(`Unauthorized module delete attempt by ${user.userId} on ${moduleData.slug}`);
      return res.status(403).json({ success: false, error: 'Insufficient permissions to delete this module' });
    }

    if (force) {
      const deletedCounts: Record<string, number> = {};
      const errors: string[] = [];

      // Helper to safely delete from a table
      const safeDelete = async (table: string, column: string = 'module_id') => {
        try {
          const { count } = await supabase
            .from(table)
            .select('id', { count: 'exact', head: true })
            .eq(column, id);
          
          if (count && count > 0) {
            const { error: delError } = await supabase
              .from(table)
              .delete()
              .eq(column, id);
            
            if (delError) {
              errors.push(`${table}: ${delError.message}`);
            } else {
              deletedCounts[table] = count;
            }
          }
        } catch (e: any) {
          // Table might not exist or not have the column, skip it
        }
      };

      // Get menu item IDs for this module to delete orders referencing them
      const { data: menuItems } = await supabase
        .from('menu_items')
        .select('id')
        .eq('module_id', id);
      
      const menuItemIds = menuItems?.map(item => item.id) || [];
      
      // Delete order_items that reference menu items from this module
      if (menuItemIds.length > 0) {
        try {
          const { data: orderItems } = await supabase
            .from('order_items')
            .select('order_id')
            .in('menu_item_id', menuItemIds);
          
          const orderIds = [...new Set(orderItems?.map(oi => oi.order_id) || [])];
          
          if (orderIds.length > 0) {
            // Delete order items first
            const { error: oiError } = await supabase
              .from('order_items')
              .delete()
              .in('menu_item_id', menuItemIds);
            
            if (oiError) {
              errors.push(`order_items: ${oiError.message}`);
            } else {
              deletedCounts['order_items'] = orderIds.length;
            }
            
            // Then delete orders that have no remaining items
            // (checking each order)
            for (const orderId of orderIds) {
              const { count } = await supabase
                .from('order_items')
                .select('id', { count: 'exact', head: true })
                .eq('order_id', orderId);
              
              if (count === 0) {
                await supabase.from('restaurant_orders').delete().eq('id', orderId);
              }
            }
          }
        } catch (e: any) {
          errors.push(`order cascade: ${e.message}`);
        }
      }

      // CASCADE DELETE: Delete all dependent data in correct order
      // Tables that have direct module_id column
      const directModuleTables = [
        'menu_items',
        'menu_categories',
        'snack_items',
        'pool_tickets',
        'pool_sessions',
        'chalets',
        'chalet_bookings',
        'reviews',
        'pages',
      ];

      for (const table of directModuleTables) {
        await safeDelete(table);
      }

      // Also clean up roles and permissions created for this module
      if (moduleData?.slug) {
        try {
          // Delete permissions for this module (Cascades to app_role_permissions)
          const { data: perms } = await supabase
            .from('app_permissions')
            .delete()
            .eq('module_slug', moduleData.slug)
            .select('slug');
          
          if (perms && perms.length > 0) {
            deletedCounts['permissions'] = perms.length;
          }
          
          // Delete roles for this module
          const { error: rolesError } = await supabase
            .from('roles')
            .delete()
            .or(`name.eq.${moduleData.slug}_admin,name.eq.${moduleData.slug}_staff`);
          
          if (!rolesError) {
             deletedCounts['roles'] = 2;
          }
          
          // Remove from navbar CMS if present
          const { data: siteSettings } = await supabase
            .from('site_settings')
            .select('id, navbar')
            .single();
          
          const settings = siteSettings as { id?: number; navbar?: { links?: any[] } } | null;
          if (settings?.navbar?.links && Array.isArray(settings.navbar.links)) {
            const updatedLinks = settings.navbar.links.filter(
              (link: any) => link.moduleSlug !== moduleData.slug
            );
            await supabase
              .from('site_settings')
              .update({ navbar: { ...settings.navbar, links: updatedLinks } })
              .eq('id', settings.id || 1);
          }

        } catch (e: any) {
            errors.push(`cleanup: ${e.message}`);
        }
      }

      // Now delete the module itself
      const { error: delErr } = await supabase
        .from('modules')
        .delete()
        .eq('id', id);

      if (delErr) {
        return res.status(400).json({ 
          success: false, 
          error: 'Failed to hard-delete module after cleaning dependencies.', 
          details: delErr.message,
          cascadeResults: deletedCounts,
          cascadeErrors: errors.length > 0 ? errors : undefined
        });
      }

      // Clear cache if we had module data
      if (moduleData?.slug) {
        clearModuleCache(moduleData.slug);
      }
      
      emitToAll('modules.updated', { id, deleted: true });

      await logActivity({
        user_id: (req.user as any)?.userId || 'system',
        action: 'DELETE_MODULE_HARD',
        resource: 'module',
        resource_id: id,
        old_value: { deletedDependencies: deletedCounts },
        ip_address: req.ip,
        user_agent: req.get('user-agent')
      });

      return res.json({ 
        success: true, 
        message: 'Module and all dependencies hard-deleted',
        deletedDependencies: deletedCounts
      });
    }

    // Soft delete: mark as inactive
    const { data, error } = await supabase
      .from('modules')
      .update({ is_active: false })
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;

    // Clear cache and notify clients
    clearModuleCache(data.slug);
    emitToAll('modules.updated', data);

    await logActivity({
      user_id: (req.user as any)?.userId || 'system',
      action: 'DELETE_MODULE_SOFT',
      resource: 'module',
      resource_id: id,
      new_value: { is_active: false },
      ip_address: req.ip,
      user_agent: req.get('user-agent')
    });

    res.json({ success: true, message: 'Module deactivated (soft-deleted)', data });
});

import { Request, Response, NextFunction } from 'express';
import { asyncHandler } from '../../middleware/async-handler.js';
import { getSupabase } from "../../database/connection";
