 */
export const getSupportedLanguages = asyncHandler(async (req: Request, res: Response) => {
    const supabase = getSupabase();
    
    // Check if languages table exists, if not return defaults
    const { data, error } = await supabase
      .from('supported_languages')
      .select('*')
      .order('sort_order', { ascending: true });

    if (error) {
      // Table may not exist, return defaults
      return res.json({
        success: true,
        data: [
          { code: 'en', name: 'English', native_name: 'English', direction: 'ltr', is_default: true, is_active: true },
          { code: 'ar', name: 'Arabic', native_name: 'العربية', direction: 'rtl', is_default: false, is_active: true },
          { code: 'fr', name: 'French', native_name: 'Français', direction: 'ltr', is_default: false, is_active: true },
        ],
      });
    }

    res.json({ success: true, data: data || [] });
});

/**
 * Add a new supported language
 */
export const addLanguage = asyncHandler(async (req: Request, res: Response) => {
    const { code, name, native_name, direction = 'ltr' } = req.body;

    if (!code || !name) {
      return res.status(400).json({
        success: false,
        error: 'Language code and name are required',
      });
    }

    const supabase = getSupabase();

    // Check if language already exists
    const { data: existing } = await supabase
      .from('supported_languages')
      .select('code')
      .eq('code', code)
      .single();

    if (existing) {
      return res.status(400).json({
        success: false,
        error: `Language with code '${code}' already exists`,
      });
    }

    // Get max sort order
    const { data: maxOrder } = await supabase
      .from('supported_languages')
      .select('sort_order')
      .order('sort_order', { ascending: false })
      .limit(1)
      .single();

    const { data, error } = await supabase
      .from('supported_languages')
      .insert({
        code,
        name,
        native_name: native_name || name,
        direction,
        is_default: false,
        is_active: true,
        sort_order: (maxOrder?.sort_order || 0) + 1,
      })
      .select()
      .single();

    if (error) throw error;

    await logActivity({
      user_id: req.user!.userId,
      action: 'ADD_LANGUAGE',
      resource: 'supported_languages',
      resource_id: code,
      new_value: data,
      ip_address: req.ip,
      user_agent: req.get('user-agent'),
    });

    res.status(201).json({ success: true, data });
});

/**
 * Update a supported language
 */
export const updateLanguage = asyncHandler(async (req: Request, res: Response) => {
    const { code } = req.params;
    const { name, native_name, direction, is_active, is_default, sort_order } = req.body;

    const supabase = getSupabase();

    const updateData: Record<string, unknown> = {};
    if (name !== undefined) updateData.name = name;
    if (native_name !== undefined) updateData.native_name = native_name;
    if (direction !== undefined) updateData.direction = direction;
    if (is_active !== undefined) updateData.is_active = is_active;
    if (sort_order !== undefined) updateData.sort_order = sort_order;

    // If setting as default, unset other defaults first
    if (is_default === true) {
      await supabase
        .from('supported_languages')
        .update({ is_default: false })
        .neq('code', code);
      updateData.is_default = true;
    }

    const { data, error } = await supabase
      .from('supported_languages')
      .update(updateData)
      .eq('code', code)
      .select()
      .single();

    if (error) throw error;

    await logActivity({
      user_id: req.user!.userId,
      action: 'UPDATE_LANGUAGE',
      resource: 'supported_languages',
      resource_id: code,
      new_value: updateData,
      ip_address: req.ip,
      user_agent: req.get('user-agent'),
    });

    res.json({ success: true, data });
});

/**
 * Delete a supported language
 */
export const deleteLanguage = asyncHandler(async (req: Request, res: Response) => {
    const { code } = req.params;

    // Prevent deleting default language
    if (code === 'en') {
      return res.status(400).json({
        success: false,
        error: 'Cannot delete the default English language',
      });
    }

    const supabase = getSupabase();

    const { error } = await supabase
      .from('supported_languages')
      .delete()
      .eq('code', code);

    if (error) throw error;

    await logActivity({
      user_id: req.user!.userId,
      action: 'DELETE_LANGUAGE',
      resource: 'supported_languages',
      resource_id: code,
      ip_address: req.ip,
      user_agent: req.get('user-agent'),
    });

    res.json({ success: true, message: `Language '${code}' deleted` });
});

// ============== FRONTEND TRANSLATION KEY ANALYSIS ==============

/**
 * Compare frontend translation JSON files and find missing keys
 * This analyzes the actual translation files used by next-intl
 */
export const compareFrontendTranslations = asyncHandler(async (req: Request, res: Response) => {
    const fs = await import('fs').then(m => m.promises);
    const path = await import('path');
    
    // Path to frontend messages directory
    // In production (built), we are in dist/modules/admin/translations.controller.js
    // We need to go up to root and then to frontend/messages
    // Using process.cwd() is safer as it resolves relative to the backend root where the server is running
    const messagesDir = path.resolve(process.cwd(), '../frontend/messages');
    
    try {
      await fs.access(messagesDir);
    } catch {
       // If frontend/messages doesn't exist (e.g. Docker container), return empty
       return res.json({ 
         success: true, 
         data: { 
           en: { "note": "Frontend translations not available in this environment" },
           keys: []
         } 
       });
    }
    
    // Read all JSON files
    const files = await fs.readdir(messagesDir);
    const jsonFiles = files.filter(f => f.endsWith('.json'));
    
    const translations: Record<string, Record<string, unknown>> = {};
    const allKeys = new Set<string>();
    
    // Load all translation files
    for (const file of jsonFiles) {
      const lang = file.replace('.json', '');
      const content = await fs.readFile(path.join(messagesDir, file), 'utf-8');
      translations[lang] = JSON.parse(content);
      
      // Extract all keys recursively
      const extractKeys = (obj: unknown, prefix = ''): void => {
        if (typeof obj === 'object' && obj !== null) {
          for (const [key, value] of Object.entries(obj)) {
            const fullKey = prefix ? `${prefix}.${key}` : key;
            if (typeof value === 'string') {
              allKeys.add(fullKey);
            } else if (typeof value === 'object') {
              extractKeys(value, fullKey);
            }
          }
        }
      };
      
      extractKeys(translations[lang]);
    }
    
    // Find missing keys per language
    const missingByLanguage: Record<string, string[]> = {};
    const getNestedValue = (obj: unknown, path: string): string | undefined => {
      const keys = path.split('.');
      let current: unknown = obj;
      for (const key of keys) {
        if (current && typeof current === 'object' && key in current) {
          current = (current as Record<string, unknown>)[key];
        } else {
          return undefined;
        }
      }
      return typeof current === 'string' ? current : undefined;
    };
    
    for (const lang of Object.keys(translations)) {
      missingByLanguage[lang] = [];
      for (const key of allKeys) {
        const value = getNestedValue(translations[lang], key);
        if (!value) {
          missingByLanguage[lang].push(key);
        }
      }
    }
    
    // Calculate stats and build the response structure expected by frontend
    const totalKeys = allKeys.size;
    
    // Build languages object in the format frontend expects
    const languagesData: Record<string, { 
      file: string; 
      keyCount: number; 
      missingKeys: string[]; 
      missingCount: number;
      percentage: number;
    }> = {};
    
    for (const lang of Object.keys(translations)) {
      const missing = missingByLanguage[lang].length;
      const translated = totalKeys - missing;
      languagesData[lang] = {
        file: `${lang}.json`,
        keyCount: totalKeys,
        missingKeys: missingByLanguage[lang],
        missingCount: missing,
        percentage: totalKeys > 0 ? Math.round((translated / totalKeys) * 100) : 100,
      };
    }
    
    res.json({
      success: true,
      data: {
        totalKeys,
        languages: languagesData,
        allKeys: Array.from(allKeys).sort(),
      },
    });
});

/**
 * Update a specific frontend translation key
 */
export const updateFrontendTranslation = asyncHandler(async (req: Request, res: Response) => {
    const { language, key, value } = req.body;
    
    if (!language || !key || value === undefined) {
      return res.status(400).json({
        success: false,
        error: 'Language, key, and value are required',
      });
    }
    
    const fs = await import('fs').then(m => m.promises);
    const path = await import('path');
    
    const filePath = path.join(__dirname, '../../../../frontend/messages', `${language}.json`);
    
    // Read current file
    const content = await fs.readFile(filePath, 'utf-8');
    const translations = JSON.parse(content);
    
    // Set nested value
    const keys = key.split('.');
    let current = translations;
    for (let i = 0; i < keys.length - 1; i++) {
      if (!(keys[i] in current)) {
        current[keys[i]] = {};
      }
      current = current[keys[i]];
    }
    current[keys[keys.length - 1]] = value;
    
    // Write back
    await fs.writeFile(filePath, JSON.stringify(translations, null, 2), 'utf-8');
    
    await logActivity({
      user_id: req.user!.userId,
      action: 'UPDATE_FRONTEND_TRANSLATION',
      resource: 'frontend_translations',
      resource_id: `${language}:${key}`,
      new_value: { language, key, value },
      ip_address: req.ip,
      user_agent: req.get('user-agent'),
    });
    
    res.json({ success: true, message: 'Translation updated' });
});


/**
 * DB: Get UI Translations
 */
export const getUiTranslations = asyncHandler(async (req: Request, res: Response) => {
    const { page = 1, limit = 50, namespace, locale, status, search } = req.query;
    const offset = (Number(page) - 1) * Number(limit);
    const supabase = getSupabase();

    let query = supabase
      .from('translations')
      .select('*', { count: 'exact' });

    if (namespace) query = query.eq('namespace', namespace);
    if (locale) query = query.eq('locale', locale);
    if (status) query = query.eq('status', status);
    if (search) query = query.ilike('key', `%${search}%`);

    const { data, count, error } = await query
      .range(offset, offset + Number(limit) - 1)
      .order('updated_at', { ascending: false });

    if (error) throw error;

    res.json({
      success: true,
      data,
      meta: {
        total: count,
        page: Number(page),
        limit: Number(limit)
      }
    });
});

/**
 * DB: Upsert UI Translation
 */
export const upsertUiTranslation = asyncHandler(async (req: Request, res: Response) => {
    const { namespace = 'common', key, locale, value, status = 'draft' } = req.body;

    if (!key || !locale || !value) {
      return res.status(400).json({ success: false, error: 'Missing required fields' });
    }

    const supabase = getSupabase();

    const { data, error } = await supabase
      .from('translations')
      .upsert({
        namespace,
        key,
        locale,
        value,
        status,
        updated_at: new Date().toISOString(),
      }, {
        onConflict: 'namespace,key,locale'
      })
      .select()
      .single();

    if (error) throw error;

    await logActivity({
      user_id: req.user?.userId || 'system',
      action: 'UPSERT_UI_TRANSLATION',
      resource: 'translations',
      resource_id: data.id,
      new_value: { namespace, key, locale, value, status },
      ip_address: req.ip,
      user_agent: req.get('user-agent'),
    });

    res.json({ success: true, data });
});

/**
 * DB: Publish Translations (Sync DB -> Files)
 */
export const publishTranslations = asyncHandler(async (req: Request, res: Response) => {
    const supabase = getSupabase();

    // 1. Fetch all PUBLISHED translations
    const { data, error } = await supabase
      .from('translations')
      .select('*')
      .in('status', ['published', 'approved']);

    if (error) throw error;
    if (!data || data.length === 0) {
      return res.json({ success: true, message: 'No published translations found to sync.' });
    }

    // 2. Group by locale
    const byLocale: Record<string, Record<string, any>> = {};
    
    interface TranslationRow {
        namespace: string;
        key: string;
        locale: string;
        value: string;
    }

    for (const row of (data as TranslationRow[])) {
      if (!byLocale[row.locale]) {
        byLocale[row.locale] = {}; // Root for this locale
      }
      
      if (!byLocale[row.locale][row.namespace]) {
        byLocale[row.locale][row.namespace] = {};
      }

      // Handle nested keys within namespace
      const parts = row.key.split('.');
      let current = byLocale[row.locale][row.namespace];
      
      for (let i = 0; i < parts.length - 1; i++) {
        const part = parts[i];
        if (!current[part]) current[part] = {};
        current = current[part];
      }
      
      current[parts[parts.length - 1]] = row.value;
    }

    // 3. Write to files
    const fs = await import('fs').then(m => m.promises);
    const path = await import('path');
    const messagesDir = path.resolve(__dirname, '../../../../frontend/messages');

    const results = [];
    for (const locale of Object.keys(byLocale)) {
      const filePath = path.join(messagesDir, `${locale}.json`);
      const content = JSON.stringify(byLocale[locale], null, 2);
      await fs.writeFile(filePath, content, 'utf-8');
      results.push(locale);
    }

    await logActivity({
      user_id: req.user?.userId || 'system',
      action: 'PUBLISH_TRANSLATIONS',
      resource: 'frontend_messages',
      resource_id: 'batch',
      new_value: { locales: results },
      ip_address: req.ip,
      user_agent: req.get('user-agent'),
    });

    res.json({ success: true, message: 'Translations synced to frontend files', locales: results });
});

