});

// POST /api/auth/resend-verification
export const resendVerification = asyncHandler(async (req: Request, res: Response) => {
  const userId = req.user!.userId;

  const supabase = (await import('../../database/connection.js')).getSupabase();
  const { data: user } = await supabase
    .from('users')
    .select('id, email, full_name, email_verified')
    .eq('id', userId)
    .single();

  if (!user) {
    return res.status(404).json({ success: false, error: 'User not found' });
  }

  if (user.email_verified) {
    return res.json({ success: true, message: 'Email is already verified' });
  }

  await authService.sendVerificationEmail(user.id, user.email, user.full_name);
  res.json({ success: true, message: 'Verification email sent' });
});

import { Request, Response } from 'express';
import { getSupabase } from '../../database/connection.js';
import { generateTokens } from './auth.utils.js';
import { logger } from '../../utils/logger.js';
import { AppError } from '../../utils/AppError.js';
import { v4 as uuidv4 } from 'uuid';
import crypto from 'crypto';

/**
 * Biometric/WebAuthn Authentication Controller
 * 
 * Implements passkey/biometric authentication flows:
 * - Registration (begin/complete)
 * - Authentication (begin/complete)
 * - Credential management (list/delete)
 */

// In-memory challenge store (should use Redis in production)
const challengeStore = new Map<string, { challenge: string; userId?: string; expires: number }>();

// Clean up expired challenges every 5 minutes
setInterval(() => {
  const now = Date.now();
  for (const [key, value] of challengeStore.entries()) {
    if (value.expires < now) {
      challengeStore.delete(key);
    }
  }
}, 5 * 60 * 1000);

/**
 * POST /api/v1/auth/biometric/register-begin
 * Start biometric credential registration
 * Requires authenticated user
 */
export async function registerBegin(req: Request, res: Response) {
  try {
    const userId = req.user?.userId;
    if (!userId) {
      return res.status(401).json({ success: false, error: 'Authentication required' });
    }

    const supabase = getSupabase();
    
    // Get user details
    const { data: user, error: userError } = await supabase
      .from('users')
      .select('id, email, full_name')
      .eq('id', userId)
      .single();

    if (userError || !user) {
      return res.status(404).json({ success: false, error: 'User not found' });
    }

    // Get existing credentials to exclude
    const { data: existingCredentials } = await supabase
      .from('biometric_credentials')
      .select('credential_id')
      .eq('user_id', userId)
      .eq('is_active', true);

    // Generate challenge
    const challenge = crypto.randomBytes(32).toString('base64url');
    const sessionId = uuidv4();

    // Store challenge with 5 minute expiry
    challengeStore.set(sessionId, {
      challenge,
      userId,
      expires: Date.now() + 5 * 60 * 1000,
    });

    // WebAuthn registration options
    const options = {
      challenge,
      rp: {
        name: 'V2 Resort',
        id: process.env.WEBAUTHN_RP_ID || 'localhost',
      },
      user: {
        id: Buffer.from(userId).toString('base64url'),
        name: user.email,
        displayName: user.full_name || user.email,
      },
      pubKeyCredParams: [
        { alg: -7, type: 'public-key' },   // ES256
        { alg: -257, type: 'public-key' }, // RS256
      ],
      authenticatorSelection: {
        authenticatorAttachment: 'platform', // Prefer platform authenticators (Face ID, Touch ID)
        userVerification: 'required',
        residentKey: 'preferred',
      },
      timeout: 60000,
      attestation: 'none',
      excludeCredentials: (existingCredentials || []).map(cred => ({
        id: cred.credential_id,
        type: 'public-key',
        transports: ['internal'],
      })),
    };

    return res.json({
      success: true,
      sessionId,
      options,
    });
  } catch (error) {
    logger.error('Biometric register-begin error:', error);
    return res.status(500).json({ success: false, error: 'Registration failed' });
  }
}

/**
 * POST /api/v1/auth/biometric/register-complete
 * Complete biometric credential registration
 */
export async function registerComplete(req: Request, res: Response) {
  try {
    const { sessionId, credential, deviceType, deviceName } = req.body;

    if (!sessionId || !credential) {
      return res.status(400).json({ success: false, error: 'Missing required fields' });
    }

    // Verify session
    const session = challengeStore.get(sessionId);
    if (!session || session.expires < Date.now()) {
      return res.status(400).json({ success: false, error: 'Session expired or invalid' });
    }

    const userId = session.userId;
    if (!userId) {
      return res.status(400).json({ success: false, error: 'Invalid session' });
    }

    // Clean up session
    challengeStore.delete(sessionId);

    // In production, verify the credential response properly using a WebAuthn library
    // For now, we'll store the credential details
    const { id: credentialId, response } = credential;

    if (!credentialId || !response?.attestationObject || !response?.clientDataJSON) {
      return res.status(400).json({ success: false, error: 'Invalid credential format' });
    }

    // Extract public key (simplified - use @simplewebauthn/server in production)
    const publicKey = response.attestationObject; // Simplified

    const supabase = getSupabase();

    // Store credential
    const { data: stored, error: storeError } = await supabase
      .from('biometric_credentials')
      .insert({
        user_id: userId,
        credential_id: credentialId,
        public_key: publicKey,
        counter: 0,
        device_type: deviceType || 'unknown',
        device_name: deviceName || 'Unnamed Device',
      })
      .select('id, device_type, device_name, created_at')
      .single();

    if (storeError) {
      logger.error('Failed to store biometric credential:', storeError);
      return res.status(500).json({ success: false, error: 'Failed to store credential' });
    }

    logger.info(`Biometric credential registered for user ${userId}`);

    return res.json({
      success: true,
      credential: stored,
    });
  } catch (error) {
    logger.error('Biometric register-complete error:', error);
    return res.status(500).json({ success: false, error: 'Registration failed' });
  }
}

/**
 * POST /api/v1/auth/biometric/authenticate-begin
 * Start biometric authentication
 */
export async function authenticateBegin(req: Request, res: Response) {
  try {
    const { email } = req.body;

    const supabase = getSupabase();

    // Find user by email
    const { data: user, error: userError } = await supabase
      .from('users')
      .select('id')
      .eq('email', email?.toLowerCase())
      .single();

    if (userError || !user) {
      // Return valid-looking response to prevent user enumeration
      const challenge = crypto.randomBytes(32).toString('base64url');
      const sessionId = uuidv4();
      
      return res.json({
        success: true,
        sessionId,
        options: {
          challenge,
          timeout: 60000,
          userVerification: 'required',
          allowCredentials: [],
        },
      });
    }

    // Get user's active credentials
    const { data: credentials } = await supabase
      .from('biometric_credentials')
      .select('credential_id')
      .eq('user_id', user.id)
      .eq('is_active', true);

    if (!credentials || credentials.length === 0) {
      return res.status(400).json({ 
        success: false, 
        error: 'No biometric credentials registered for this account' 
      });
    }

    // Generate challenge
    const challenge = crypto.randomBytes(32).toString('base64url');
    const sessionId = uuidv4();

    // Store challenge
    challengeStore.set(sessionId, {
      challenge,
      userId: user.id,
      expires: Date.now() + 5 * 60 * 1000,
    });

    const options = {
      challenge,
      timeout: 60000,
      rpId: process.env.WEBAUTHN_RP_ID || 'localhost',
      userVerification: 'required',
      allowCredentials: credentials.map(cred => ({
        id: cred.credential_id,
        type: 'public-key',
        transports: ['internal'],
      })),
    };

    return res.json({
      success: true,
      sessionId,
      options,
    });
  } catch (error) {
    logger.error('Biometric authenticate-begin error:', error);
    return res.status(500).json({ success: false, error: 'Authentication failed' });
  }
}

/**
 * POST /api/v1/auth/biometric/authenticate-complete
 * Complete biometric authentication and return JWT
 */
export async function authenticateComplete(req: Request, res: Response) {
  try {
    const { sessionId, credential } = req.body;

    if (!sessionId || !credential) {
      return res.status(400).json({ success: false, error: 'Missing required fields' });
    }

    // Verify session
    const session = challengeStore.get(sessionId);
    if (!session || session.expires < Date.now()) {
      return res.status(400).json({ success: false, error: 'Session expired or invalid' });
    }

    const userId = session.userId;
    if (!userId) {
      return res.status(400).json({ success: false, error: 'Invalid session' });
    }

    // Clean up session
    challengeStore.delete(sessionId);

    const { id: credentialId, response } = credential;

    if (!credentialId || !response?.authenticatorData || !response?.signature) {
      return res.status(400).json({ success: false, error: 'Invalid credential format' });
    }

    const supabase = getSupabase();

    // Find the credential
    const { data: storedCredential, error: credError } = await supabase
      .from('biometric_credentials')
      .select('*')
      .eq('credential_id', credentialId)
      .eq('user_id', userId)
      .eq('is_active', true)
      .single();

    if (credError || !storedCredential) {
      return res.status(401).json({ success: false, error: 'Invalid credential' });
    }

    // SECURITY FIX (HIGH-005): Verify counter to detect cloned authenticators
    // The counter in authenticatorData should be greater than the stored counter.
    // If it's not, the authenticator may have been cloned.
    const authDataBuffer = Buffer.from(response.authenticatorData, 'base64url');
    // Counter is bytes 33-36 of authenticatorData (big-endian uint32)
    const presentedCounter = authDataBuffer.length >= 37
      ? authDataBuffer.readUInt32BE(33)
      : 0;

    if (storedCredential.counter > 0 && presentedCounter <= storedCredential.counter) {
      logger.warn(`WebAuthn counter mismatch for user ${userId} - possible authenticator clone`, {
        storedCounter: storedCredential.counter,
        presentedCounter,
        credentialId,
      });
      // Deactivate the credential as a precaution
      await supabase
        .from('biometric_credentials')
        .update({ is_active: false })
        .eq('id', storedCredential.id);

      return res.status(401).json({
        success: false,
        error: 'Credential security check failed. Please re-register your biometric.',
      });
    }

    // TODO: For full production security, integrate @simplewebauthn/server
    // to perform cryptographic signature verification against the stored public key.
    // The current implementation trusts credential ID match + counter validation.

    // Update counter and last_used_at
    await supabase
      .from('biometric_credentials')
      .update({
        counter: storedCredential.counter + 1,
        last_used_at: new Date().toISOString(),
      })
      .eq('id', storedCredential.id);

    // Get user details for token
    const { data: user, error: userError } = await supabase
      .from('users')
      .select('*')
      .eq('id', userId)
      .single();

    if (userError || !user) {
      return res.status(404).json({ success: false, error: 'User not found' });
    }

    // Get user roles
    const { data: userRolesList } = await supabase
      .from('user_roles')
      .select('roles (name)')
      .eq('user_id', userId);

    interface RoleJoinResult { roles?: { name?: string }[] | { name?: string } | null }
    const roleNames = ((userRolesList || []) as RoleJoinResult[]).map((r) => {
      const roles = r.roles;
      if (!roles) return undefined;
      if (Array.isArray(roles)) return roles[0]?.name;
      return (roles as { name?: string }).name;
    }).filter(Boolean) as string[];

    // Generate tokens
    const tokens = generateTokens({
      userId: user.id,
      email: user.email,
      roles: roleNames,
      tokenVersion: user.token_version ?? 0,
    });

    // Update last login
    await supabase
      .from('users')
      .update({ last_login_at: new Date().toISOString() })
      .eq('id', userId);

    logger.info(`Biometric authentication successful for user ${userId}`);

    return res.json({
      success: true,
      user: {
        id: user.id,
        email: user.email,
        fullName: user.full_name,
        profileImageUrl: user.profile_image_url,
        preferredLanguage: user.preferred_language,
        roles: roleNames,
      },
      tokens,
    });
  } catch (error) {
    logger.error('Biometric authenticate-complete error:', error);
    return res.status(500).json({ success: false, error: 'Authentication failed' });
  }
}

/**
 * GET /api/v1/auth/biometric/credentials
 * List user's biometric credentials
 */
export async function listCredentials(req: Request, res: Response) {
  try {
    const userId = req.user?.userId;
    if (!userId) {
      return res.status(401).json({ success: false, error: 'Authentication required' });
    }

    const supabase = getSupabase();

    const { data: credentials, error } = await supabase
      .from('biometric_credentials')
      .select('id, device_type, device_name, created_at, last_used_at, is_active')
      .eq('user_id', userId)
      .order('created_at', { ascending: false });

    if (error) {
      logger.error('Failed to list biometric credentials:', error);
      return res.status(500).json({ success: false, error: 'Failed to list credentials' });
    }

    return res.json({
      success: true,
      credentials: credentials || [],
    });
  } catch (error) {
    logger.error('Biometric list-credentials error:', error);
    return res.status(500).json({ success: false, error: 'Failed to list credentials' });
  }
}

/**
 * DELETE /api/v1/auth/biometric/credentials/:id
 * Remove a biometric credential
 */
export async function deleteCredential(req: Request, res: Response) {
  try {
    const userId = req.user?.userId;
    if (!userId) {
      return res.status(401).json({ success: false, error: 'Authentication required' });
    }

    const { id } = req.params;
    if (!id) {
      return res.status(400).json({ success: false, error: 'Credential ID required' });
    }

    const supabase = getSupabase();

    // Soft delete - mark as inactive
    const { data: updated, error } = await supabase
      .from('biometric_credentials')
      .update({ is_active: false })
      .eq('id', id)
      .eq('user_id', userId)
      .select('id')
      .single();

    if (error || !updated) {
      return res.status(404).json({ success: false, error: 'Credential not found' });
    }

    logger.info(`Biometric credential ${id} deleted for user ${userId}`);

    return res.json({
      success: true,
      message: 'Credential removed successfully',
    });
  } catch (error) {
    logger.error('Biometric delete-credential error:', error);
    return res.status(500).json({ success: false, error: 'Failed to delete credential' });
  }
}

/**
 * Account Lockout Service
 * 
 * Provides protection against brute force attacks by implementing
 * progressive delays and account lockouts after failed login attempts.
 */

import { cache } from '../../utils/cache';
import { logger } from '../../utils/logger';
import { emailService } from '../../services/email.service';

interface LockoutInfo {
  failedAttempts: number;
  lastAttempt: number;
  lockedUntil: number | null;
  notificationSent: boolean;
}

// Configuration
const LOCKOUT_CONFIG = {
  maxAttempts: 5,
  lockoutDurationMs: 15 * 60 * 1000, // 15 minutes
  attemptWindowMs: 15 * 60 * 1000, // 15 minutes
  progressiveDelays: [0, 2000, 5000, 15000, 30000], // ms delays after each attempt
  captchaThreshold: 3, // Require CAPTCHA after this many attempts
};

const LOCKOUT_KEY_PREFIX = 'lockout:';

/**
 * Get lockout info for an identifier (email or IP)
 */
async function getLockoutInfo(identifier: string): Promise<LockoutInfo | null> {
  try {
    const key = `${LOCKOUT_KEY_PREFIX}${identifier}`;
    return await cache.get<LockoutInfo>(key);
  } catch (error) {
    logger.warn('Failed to get lockout info from cache, allowing attempt', { identifier });
    return null;
  }
}

/**
 * Set lockout info for an identifier
 */
async function setLockoutInfo(identifier: string, info: LockoutInfo): Promise<void> {
  try {
    const key = `${LOCKOUT_KEY_PREFIX}${identifier}`;
    // Store for the lockout window duration plus some buffer
    const ttl = Math.ceil((LOCKOUT_CONFIG.lockoutDurationMs + LOCKOUT_CONFIG.attemptWindowMs) / 1000);
    await cache.set(key, info, ttl);
  } catch (error) {
    logger.warn('Failed to set lockout info in cache', { identifier });
  }
}

/**
 * Clear lockout info for an identifier (on successful login)
 */
async function clearLockoutInfo(identifier: string): Promise<void> {
  try {
    const key = `${LOCKOUT_KEY_PREFIX}${identifier}`;
    await cache.del(key);
  } catch (error) {
    logger.warn('Failed to clear lockout info from cache', { identifier });
  }
}

/**
 * Check if an account is currently locked
 */
export async function isAccountLocked(identifier: string): Promise<{
  locked: boolean;
  remainingMs?: number;
  message?: string;
}> {
  const info = await getLockoutInfo(identifier);
  
  if (!info) {
    return { locked: false };
  }
  
  // Check if locked and lock hasn't expired
  if (info.lockedUntil && Date.now() < info.lockedUntil) {
    const remainingMs = info.lockedUntil - Date.now();
    const remainingMinutes = Math.ceil(remainingMs / 60000);
    
    return {
      locked: true,
      remainingMs,
      message: `Account is locked due to too many failed login attempts. Please try again in ${remainingMinutes} minute${remainingMinutes === 1 ? '' : 's'}.`
    };
  }
  
  return { locked: false };
}

/**
 * Check if CAPTCHA is required for this identifier
 */
export async function isCaptchaRequired(identifier: string): Promise<boolean> {
  const info = await getLockoutInfo(identifier);
  
  if (!info) {
    return false;
  }
  
  // Check if attempts are within the window
  const withinWindow = Date.now() - info.lastAttempt < LOCKOUT_CONFIG.attemptWindowMs;
  
  return withinWindow && info.failedAttempts >= LOCKOUT_CONFIG.captchaThreshold;
}

/**
 * Get the progressive delay for the current attempt count
 */
export async function getProgressiveDelay(identifier: string): Promise<number> {
  const info = await getLockoutInfo(identifier);
  
  if (!info) {
    return 0;
  }
  
  // Check if attempts are within the window
  const withinWindow = Date.now() - info.lastAttempt < LOCKOUT_CONFIG.attemptWindowMs;
  
  if (!withinWindow) {
    return 0;
  }
  
  const delayIndex = Math.min(info.failedAttempts, LOCKOUT_CONFIG.progressiveDelays.length - 1);
  return LOCKOUT_CONFIG.progressiveDelays[delayIndex];
}

/**
 * Record a failed login attempt
 */
export async function recordFailedAttempt(
  identifier: string,
  email?: string,
  ipAddress?: string,
  userAgent?: string
): Promise<{
  locked: boolean;
  remainingAttempts: number;
  requiresCaptcha: boolean;
  delayMs: number;
}> {
  let info = await getLockoutInfo(identifier);
  const now = Date.now();
  
  if (!info) {
    info = {
      failedAttempts: 0,
      lastAttempt: now,
      lockedUntil: null,
      notificationSent: false
    };
  }
  
  // Reset if outside the window
  if (now - info.lastAttempt > LOCKOUT_CONFIG.attemptWindowMs) {
    info.failedAttempts = 0;
    info.notificationSent = false;
  }
  
  // Increment failed attempts
  info.failedAttempts++;
  info.lastAttempt = now;
  
  // Check if we should lock the account
  if (info.failedAttempts >= LOCKOUT_CONFIG.maxAttempts) {
    info.lockedUntil = now + LOCKOUT_CONFIG.lockoutDurationMs;
    
    // Send notification email (only once per lockout)
    if (!info.notificationSent && email) {
      try {
        await sendLockoutNotification(email, ipAddress, userAgent);
        info.notificationSent = true;
      } catch (error) {
        logger.error('Failed to send lockout notification email', { email, error });
      }
    }
    
    logger.warn('Account locked due to too many failed attempts', {
      identifier,
      attempts: info.failedAttempts,
      lockedUntil: new Date(info.lockedUntil).toISOString()
    });
  }
  
  await setLockoutInfo(identifier, info);
  
  const delayIndex = Math.min(info.failedAttempts - 1, LOCKOUT_CONFIG.progressiveDelays.length - 1);
  
  return {
    locked: info.lockedUntil !== null && now < info.lockedUntil,
    remainingAttempts: Math.max(0, LOCKOUT_CONFIG.maxAttempts - info.failedAttempts),
    requiresCaptcha: info.failedAttempts >= LOCKOUT_CONFIG.captchaThreshold,
    delayMs: LOCKOUT_CONFIG.progressiveDelays[delayIndex]
  };
}

/**
 * Record a successful login (clears lockout info)
 */
export async function recordSuccessfulLogin(identifier: string): Promise<void> {
  await clearLockoutInfo(identifier);
  logger.debug('Cleared lockout info after successful login', { identifier });
}

/**
 * Manually unlock an account (admin action)
 */
export async function unlockAccount(
  identifier: string,
  adminUserId: string
): Promise<{ success: boolean; message: string }> {
  const info = await getLockoutInfo(identifier);
  
  if (!info || !info.lockedUntil || Date.now() >= info.lockedUntil) {
    return { success: false, message: 'Account is not currently locked' };
  }
  
  await clearLockoutInfo(identifier);
  
  logger.info('Account manually unlocked by admin', {
    identifier,
    adminUserId,
    previousLockUntil: new Date(info.lockedUntil).toISOString()
  });
  
  return { success: true, message: 'Account has been unlocked successfully' };
}

/**
 * Get lockout status for admin view
 */
export async function getLockoutStatus(identifier: string): Promise<{
  failedAttempts: number;
  isLocked: boolean;
  lockedUntil: string | null;
  lastAttempt: string | null;
}> {
  const info = await getLockoutInfo(identifier);
  
  if (!info) {
    return {
      failedAttempts: 0,
      isLocked: false,
      lockedUntil: null,
      lastAttempt: null
    };
  }
  
  const now = Date.now();
  const isLocked = info.lockedUntil !== null && now < info.lockedUntil;
  
  return {
    failedAttempts: info.failedAttempts,
    isLocked,
    lockedUntil: isLocked && info.lockedUntil ? new Date(info.lockedUntil).toISOString() : null,
    lastAttempt: new Date(info.lastAttempt).toISOString()
  };
}

/**
 * Send lockout notification email
 */
async function sendLockoutNotification(
  email: string,
  ipAddress?: string,
  userAgent?: string
): Promise<void> {
  const html = `
    <h2>Account Security Alert</h2>
    <p>Your account has been temporarily locked due to multiple failed login attempts.</p>
    
    <h3>Details:</h3>
    <ul>
      <li><strong>Time:</strong> ${new Date().toLocaleString()}</li>
      ${ipAddress ? `<li><strong>IP Address:</strong> ${ipAddress}</li>` : ''}
      ${userAgent ? `<li><strong>Device:</strong> ${userAgent}</li>` : ''}
      <li><strong>Lock Duration:</strong> 15 minutes</li>
    </ul>
    
    <p>If this was you, please wait 15 minutes before trying again.</p>
    <p>If this wasn't you, we recommend changing your password immediately after regaining access.</p>
    
    <p style="color: #666; font-size: 12px;">
      This is an automated security notification. If you did not attempt to log in,
      someone may be trying to access your account.
    </p>
  `;
  
  await emailService.sendEmail({
    to: email,
    subject: 'Security Alert: Account Temporarily Locked',
    html
  });
}

/**
 * Apply progressive delay before allowing login attempt
 */
export async function applyProgressiveDelay(identifier: string): Promise<void> {
  const delayMs = await getProgressiveDelay(identifier);
  
  if (delayMs > 0) {
    logger.debug('Applying progressive delay', { identifier, delayMs });
    await new Promise(resolve => setTimeout(resolve, delayMs));
  }
}

export default {
  isAccountLocked,
  isCaptchaRequired,
  getProgressiveDelay,
  recordFailedAttempt,
  recordSuccessfulLogin,
  unlockAccount,
  getLockoutStatus,
  applyProgressiveDelay
};

/**
 * OAuth Controller
 * 
 * Handles OAuth authentication flows for Google and Facebook.
 * Implements the OAuth 2.0 authorization code flow.
 */

import { Request, Response, NextFunction } from 'express';
import { config } from '../../config/index.js';
import { logger } from '../../utils/logger.js';
import * as oauthService from './oauth.service.js';

const FRONTEND_URL = config.frontendUrl || 'http://localhost:3000';

/**
 * GET /api/auth/google
 * Redirects to Google OAuth consent screen
 */
export function googleAuth(req: Request, res: Response): void {
  try {
    const { clientId, callbackUrl } = config.oauth.google;

    if (!clientId) {
      logger.error('Google OAuth not configured: missing GOOGLE_CLIENT_ID');
      res.redirect(`${FRONTEND_URL}/login?error=oauth_not_configured`);
      return;
    }

    // Generate state for CSRF protection
    const state = oauthService.generateOAuthState();

    // Store state in session/cookie for validation
    // Use 'none' for sameSite in development to allow cross-site cookies during OAuth redirect
    res.cookie('oauth_state', state, {
      httpOnly: true,
      secure: config.env === 'production', // Must be secure in production with sameSite=none
      sameSite: config.env === 'production' ? 'lax' : 'lax',
      maxAge: 10 * 60 * 1000, // 10 minutes
      path: '/', // Ensure cookie is available on all paths
    });

    // Build Google OAuth URL
    const googleAuthUrl = new URL('https://accounts.google.com/o/oauth2/v2/auth');
    googleAuthUrl.searchParams.set('client_id', clientId);
    googleAuthUrl.searchParams.set('redirect_uri', callbackUrl);
    googleAuthUrl.searchParams.set('response_type', 'code');
    googleAuthUrl.searchParams.set('scope', 'email profile');
    googleAuthUrl.searchParams.set('state', state);
    googleAuthUrl.searchParams.set('access_type', 'offline');
    googleAuthUrl.searchParams.set('prompt', 'consent');

    res.redirect(googleAuthUrl.toString());
  } catch (error) {
    logger.error('Error initiating Google OAuth:', error);
    res.redirect(`${FRONTEND_URL}/login?error=oauth_error`);
  }
}

/**
 * GET /api/auth/google/callback
 * Handles Google OAuth callback after user consent
 */
export async function googleCallback(req: Request, res: Response, next: NextFunction): Promise<void> {
  try {
    const { code, state, error: oauthError } = req.query;

    // Handle OAuth errors
    if (oauthError) {
      logger.warn('Google OAuth error:', oauthError);
      res.redirect(`${FRONTEND_URL}/login?error=oauth_denied`);
      return;
    }

    // Validate state for CSRF protection
    const storedState = req.cookies?.oauth_state;
    
    if (!state || state !== storedState) {
      logger.warn('OAuth state mismatch - possible CSRF attack');
      res.redirect(`${FRONTEND_URL}/login?error=invalid_state`);
      return;
    }

    // Clear state cookie
    res.clearCookie('oauth_state');

    if (!code || typeof code !== 'string') {
      res.redirect(`${FRONTEND_URL}/login?error=missing_code`);
      return;
    }

    // Exchange code for tokens and get user info
    const result = await oauthService.handleGoogleCallback(code);

    // Redirect based on user role
    const roles = result.user.roles || [];
    let redirectPath = '/';

    if (roles.includes('super_admin') || roles.includes('admin')) {
      redirectPath = '/admin';
    } else if (roles.some((r: string) => r.includes('staff') || r.includes('manager'))) {
      redirectPath = '/staff';
    }

    // SECURITY FIX (HIGH-008): Set tokens in httpOnly cookies instead of URL params
    // This prevents tokens from leaking via browser history, Referer headers, and server logs
    res.cookie('accessToken', result.accessToken, {
      httpOnly: true,
      secure: config.env === 'production',
      sameSite: 'lax',
      maxAge: 15 * 60 * 1000, // 15 minutes
      path: '/',
    });

    res.cookie('refreshToken', result.refreshToken, {
      httpOnly: true,
      secure: config.env === 'production',
      sameSite: 'lax',
      maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
      path: '/',
    });

    res.redirect(`${FRONTEND_URL}${redirectPath}?oauth=success`);
  } catch (error) {
    logger.error('Error handling Google OAuth callback:', error);
    res.redirect(`${FRONTEND_URL}/login?error=oauth_failed`);
  }
}

