      action: 'LOGIN_2FA',
      resource: 'auth',
      ip_address: req.ip,
      user_agent: req.get('user-agent'),
    });
    
    logger.info(`2FA verification successful, login completed for user: ${userId}`);
    
    res.json({
      success: true,
      data: loginResult,
      message: 'Verification successful',
    });
});

/**
