  /**
   * Start a task
   */
  async startTask(req: Request, res: Response) {
    try {
      const { id } = req.params;
      const userId = req.user?.id;
      const isAdmin = req.user?.roles?.includes('admin') || req.user?.roles?.includes('super_admin');
      const supabase = getSupabase();

      // First check if the task exists and is assigned to this user
      const { data: existingTask } = await supabase
        .from('housekeeping_tasks')
        .select('id, assigned_to')
        .eq('id', id)
        .single();

      if (!existingTask) {
        return res.status(404).json({ success: false, error: 'Task not found' });
      }

      if (!isAdmin && existingTask.assigned_to !== userId) {
        return res.status(403).json({ success: false, error: 'Task not assigned to you' });
      }

      const { data: result, error } = await supabase
        .from('housekeeping_tasks')
        .update({ 
          status: 'in_progress', 
          started_at: new Date().toISOString(),
          updated_at: new Date().toISOString()
        })
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;

      await supabase.from('housekeeping_logs').insert({
        task_id: id,
        action: 'started',
        performed_by: userId,
        notes: 'Task started',
      });

      res.json({
        success: true,
        data: result,
      });
    } catch (error: any) {
      console.error('Error starting task:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to start task',
        message: error.message,
      });
    }
  }

  /**
   * Complete a task
   */
  async completeTask(req: Request, res: Response) {
    try {
      const { id } = req.params;
      const validation = completeTaskSchema.safeParse(req.body);
      
      if (!validation.success) {
        return res.status(400).json({
          success: false,
          error: 'Validation failed',
          details: validation.error.errors,
        });
      }

      const data = validation.data;
      const userId = req.user?.id;
      const isAdmin = req.user?.roles?.includes('admin') || req.user?.roles?.includes('super_admin');
      const supabase = getSupabase();

      // First check if the task exists and is assigned to this user
      const { data: existingTask } = await supabase
        .from('housekeeping_tasks')
        .select('id, assigned_to')
        .eq('id', id)
        .single();

      if (!existingTask) {
        return res.status(404).json({ success: false, error: 'Task not found' });
      }

      if (!isAdmin && existingTask.assigned_to !== userId) {
        return res.status(403).json({ success: false, error: 'Task not assigned to you' });
      }

      const updates: Record<string, any> = {
        status: 'completed',
        completed_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      };

      if (data.checklistCompleted) {
        updates.checklist_completed = data.checklistCompleted;
      }
      if (data.photosUrls) {
        updates.photos_urls = data.photosUrls;
      }

      const { data: result, error } = await supabase
        .from('housekeeping_tasks')
        .update(updates)
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;

      await supabase.from('housekeeping_logs').insert({
        task_id: id,
        action: 'completed',
        performed_by: userId,
        notes: data.notes || 'Task completed',
      });

      // FIX: Iteration 19 - Update chalet cleaning status when task is completed
      // Previously only the advanced controller did this; basic controller left chalet stale
      if (result.chalet_id) {
        await supabase
          .from('chalets')
          .update({
            cleaning_status: 'clean',
            last_cleaned: new Date().toISOString(),
            updated_at: new Date().toISOString(),
          })
          .eq('id', result.chalet_id);
      }

      res.json({
        success: true,
        data: result,
      });
    } catch (error: any) {
      console.error('Error completing task:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to complete task',
        message: error.message,
      });
    }
  }

