  async getGuestLanguage(guestId: string): Promise<string> {
    const { data: prefs } = await this.supabase
      .from('guest_language_preferences')
      .select('preferred_language')
      .eq('guest_id', guestId)
      .limit(1);

    return prefs && prefs.length > 0 ? prefs[0].preferred_language : 'en';
  }

  async detectGuestLanguage(
    acceptLanguageHeader: string
  ): Promise<string> {
    // Parse Accept-Language header
    const languages = acceptLanguageHeader
      .split(',')
      .map(lang => {
        const [code, q] = lang.trim().split(';q=');
        return {
          code: code.split('-')[0].toLowerCase(),
          quality: q ? parseFloat(q) : 1.0
        };
      })
      .sort((a, b) => b.quality - a.quality);

    // Return first supported language or default
    const supportedLanguages = ['en', 'es', 'fr', 'de', 'it', 'pt', 'zh', 'ja', 'ko', 'ar', 'ru'];
    for (const lang of languages) {
      if (supportedLanguages.includes(lang.code)) {
        return lang.code;
      }
    }
    return 'en';
  }

  // =============================================
  // TRANSLATION MEMORY
  // =============================================

  async addToTranslationMemory(
    sourceLanguage: string,
    targetLanguage: string,
    sourceText: string,
    translatedText: string,
    context?: string,
    domain?: string
  ): Promise<void> {
    await this.supabase
      .from('translation_memory')
      .upsert({
        source_language: sourceLanguage,
        target_language: targetLanguage,
        source_text: sourceText,
        translated_text: translatedText,
        context: context || null,
        domain: domain || 'hospitality'
      }, {
        onConflict: 'source_language,target_language,source_text',
        ignoreDuplicates: true
      });
  }

  async findTranslationMatch(
    sourceLanguage: string,
    targetLanguage: string,
    sourceText: string
  ): Promise<{ translatedText: string; quality: number } | null> {
    const { data: matches } = await this.supabase
      .from('translation_memory')
      .select('translated_text, quality_score, usage_count')
      .eq('source_language', sourceLanguage)
      .eq('target_language', targetLanguage)
      .eq('source_text', sourceText)
      .order('quality_score', { ascending: false, nullsFirst: false })
      .order('usage_count', { ascending: false })
      .limit(1);

    if (!matches || matches.length === 0) return null;

    // Increment usage count
    await this.supabase
      .from('translation_memory')
      .update({ 
        usage_count: (matches[0].usage_count || 0) + 1,
        updated_at: new Date().toISOString()
      })
      .eq('source_language', sourceLanguage)
      .eq('target_language', targetLanguage)
      .eq('source_text', sourceText);

    return {
      translatedText: matches[0].translated_text,
      quality: matches[0].quality_score || 0.8
    };
  }

  // =============================================
  // TRANSLATION PROGRESS
  // =============================================

  async updateTranslationProgress(
    propertyId: string,
    languageCode: string
  ): Promise<number> {
    // Calculate progress: approved translations / total keys * 100
    const { data: totalKeys } = await this.supabase
      .from('translation_keys')
      .select('id', { count: 'exact' })
      .eq('is_active', true);

    const totalCount = totalKeys?.length || 0;
    if (totalCount === 0) return 100;

    // Count approved translations for this language
    const { data: approvedTranslations } = await this.supabase
      .from('translations')
      .select('id', { count: 'exact' })
      .eq('language_code', languageCode)
      .eq('status', 'approved');

    const approvedCount = approvedTranslations?.length || 0;
    const progress = Math.round((approvedCount / totalCount) * 100);

    await this.supabase
      .from('property_languages')
      .update({ translation_progress: progress, updated_at: new Date().toISOString() })
      .eq('property_id', propertyId)
      .eq('language_code', languageCode);

    return progress;
  }

  async getMissingTranslations(
    languageCode: string,
    propertyId?: string,
    context?: string
  ): Promise<TranslationKey[]> {
    // Get all active keys
    let keysQuery = this.supabase
      .from('translation_keys')
      .select('*')
      .eq('is_active', true);

    if (context) {
      keysQuery = keysQuery.eq('context', context);
    }

    const { data: allKeys } = await keysQuery;
    if (!allKeys || allKeys.length === 0) return [];

    // Get existing approved translations
    const { data: existingTranslations } = await this.supabase
      .from('translations')
      .select('key_id')
      .eq('language_code', languageCode)
      .eq('status', 'approved');

    const translatedKeyIds = new Set(
      (existingTranslations || []).map(t => t.key_id)
    );

    // Filter to missing keys
    const missingKeys = allKeys.filter(k => !translatedKeyIds.has(k.id));

    return missingKeys.map(k => this.mapTranslationKey(k));
  }

  // =============================================
  // STRING INTERPOLATION
  // =============================================

  interpolate(
    template: string,
    values: Record<string, string | number>
  ): string {
    return template.replace(/\{\{(\w+)\}\}/g, (match, key) => {
      return values.hasOwnProperty(key) ? String(values[key]) : match;
    });
  }

  // =============================================
  // FORMATTING HELPERS
  // =============================================

  formatDate(
    date: Date,
    languageCode: string,
    format?: string
  ): string {
    const options: Intl.DateTimeFormatOptions = {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    };
    return new Intl.DateTimeFormat(languageCode, options).format(date);
  }

  formatCurrency(
    amount: number,
    currency: string,
    languageCode: string
  ): string {
    return new Intl.NumberFormat(languageCode, {
      style: 'currency',
      currency
    }).format(amount);
  }

  formatNumber(
    number: number,
    languageCode: string
  ): string {
    return new Intl.NumberFormat(languageCode).format(number);
  }

  // =============================================
  // HELPERS
  // =============================================

  private setNestedValue(obj: Record<string, any>, path: string, value: string): void {
    const keys = path.split('.');
    let current = obj;
    
    for (let i = 0; i < keys.length - 1; i++) {
      if (!current[keys[i]]) {
        current[keys[i]] = {};
      }
      current = current[keys[i]];
    }
    
    current[keys[keys.length - 1]] = value;
  }

  private mapTranslationKey(row: any): TranslationKey {
    return {
      id: row.id,
      keyPath: row.key_path,
      context: row.context,
      module: row.module,
      defaultValue: row.default_value,
      description: row.description,
      placeholders: row.placeholders || []
    };
  }
}

export const i18nService = new I18nService();

/**
 * QuickBooks Integration Controller
 * 
 * Handles HTTP endpoints for QuickBooks integration:
 * - OAuth flow (connect, callback, disconnect)
 * - Account mapping management
 * - Manual and scheduled sync operations
 * - Sync history and status
 */

import { Request, Response, NextFunction } from 'express';
import { asyncHandler } from '../../../middleware/async-handler.js';
import { getSupabase } from '../../../database/connection.js';
import * as quickbooksService from './quickbooks.service.js';

/**
 * Get current QuickBooks connection status
 */
export const getConnectionStatus = asyncHandler(async (req: Request, res: Response) => {
    const supabase = getSupabase();
    const propertyId = req.query.propertyId as string || req.body.propertyId;
    
    const { data: connection, error } = await supabase
      .from('quickbooks_connections')
      .select('id, realm_id, is_active, sync_enabled, last_sync_at, last_sync_status, last_sync_error, settings, created_at')
      .eq('property_id', propertyId)
      .single();
      
    if (error && error.code !== 'PGRST116') { // PGRST116 = no rows found
      throw error;
    }
    
    if (!connection) {
      return res.json({
        connected: false,
        message: 'QuickBooks is not connected',
      });
    }
    
    // Test if connection is still valid
    const testResult = await quickbooksService.testConnection(connection.id);
    
    res.json({
      connected: connection.is_active && testResult.success,
      connectionId: connection.id,
      companyId: connection.realm_id,
      companyName: testResult.companyName,
      syncEnabled: connection.sync_enabled,
      lastSync: connection.last_sync_at,
      lastSyncStatus: connection.last_sync_status,
      lastSyncError: connection.last_sync_error,
      settings: connection.settings,
      connectedAt: connection.created_at,
    });
});
/**
 * Initiate OAuth connection flow
 */
export const initiateConnection = asyncHandler(async (req: Request, res: Response) => {
    const propertyId = req.body.propertyId;
    const userId = req.user?.id;
    
    if (!propertyId) {
      return res.status(400).json({ error: 'Property ID is required' });
    }
    
    // Generate state token for security (includes property ID)
    const state = Buffer.from(JSON.stringify({
      propertyId,
      userId,
      timestamp: Date.now(),
    })).toString('base64');
    
    const authUrl = quickbooksService.getAuthorizationUrl(state);
    
    res.json({
      authorizationUrl: authUrl,
      message: 'Redirect user to this URL to connect QuickBooks',
    });
});
/**
 * Handle OAuth callback from QuickBooks
 */
export async function handleCallback(req: Request, res: Response, next: NextFunction) {
  try {
    const { code, realmId, state } = req.query;
    
    if (!code || !realmId || !state) {
      return res.status(400).json({ error: 'Missing required OAuth parameters' });
    }
    
    // Decode state
    let stateData: { propertyId: string; userId: string };
    try {
      stateData = JSON.parse(Buffer.from(state as string, 'base64').toString());
    } catch {
      return res.status(400).json({ error: 'Invalid state parameter' });
    }
    
    // Exchange code for tokens
    const tokens = await quickbooksService.exchangeCodeForTokens(
      code as string,
      realmId as string
    );
    
    const supabase = getSupabase();
    
    // Check for existing connection
    const { data: existing } = await supabase
      .from('quickbooks_connections')
      .select('id')
      .eq('property_id', stateData.propertyId)
      .single();
      
    if (existing) {
      // Update existing connection
      await supabase
        .from('quickbooks_connections')
        .update({
          realm_id: realmId,
          access_token: tokens.accessToken,
          refresh_token: tokens.refreshToken,
          token_expires_at: tokens.expiresAt.toISOString(),
          is_active: true,
        })
        .eq('id', existing.id);
    } else {
      // Create new connection
      await supabase
        .from('quickbooks_connections')
        .insert({
          property_id: stateData.propertyId,
          realm_id: realmId,
          access_token: tokens.accessToken,
          refresh_token: tokens.refreshToken,
          token_expires_at: tokens.expiresAt.toISOString(),
          is_active: true,
          sync_enabled: true,
          created_by: stateData.userId,
        });
    }
    
    // Redirect to frontend success page
    const frontendUrl = process.env.FRONTEND_URL || 'http://localhost:3001';
    res.redirect(`${frontendUrl}/admin/integrations/quickbooks?connected=true`);
    
  } catch (error) {
    console.error('QuickBooks callback error:', error);
    const frontendUrl = process.env.FRONTEND_URL || 'http://localhost:3001';
    res.redirect(`${frontendUrl}/admin/integrations/quickbooks?error=connection_failed`);
  }
}

