  /**
   * Get batches for an item (FIFO view)
   */
  async getItemBatches(req: Request, res: Response) {
    try {
      const { itemId } = req.params;
      const supabase = getSupabase();

      const { data: batches, error } = await supabase
        .from('inventory_batches')
        .select('*')
        .eq('item_id', itemId)
        .eq('status', 'active')
        .gt('remaining_quantity', 0)
        .order('received_date', { ascending: true });

      if (error) throw error;

      res.json({ success: true, data: batches || [] });
    } catch (error: any) {
      logger.error('Error fetching batches:', error);
      res.status(500).json({ success: false, error: 'Failed to fetch batches', message: error.message });
    }
  }

  // ============================================
  // BILL OF MATERIALS (BOM) / RECIPE SYSTEM
  // ============================================

  /**
   * Create a recipe (BOM) for a menu item
   */
  async createRecipe(req: Request, res: Response) {
    try {
      const { menuItemId, name, ingredients, yields, prepTime, notes } = req.body;
      const supabase = getSupabase();

      // Validate ingredients
      if (!ingredients || !Array.isArray(ingredients) || ingredients.length === 0) {
        return res.status(400).json({ success: false, error: 'At least one ingredient is required' });
      }

      // Create recipe
      const { data: recipe, error: recipeError } = await supabase
        .from('inventory_recipes')
        .insert({
          menu_item_id: menuItemId,
          name,
          yields: yields || 1,
          prep_time_minutes: prepTime,
          notes,
          is_active: true,
        })
        .select()
        .single();

      if (recipeError) throw recipeError;

      // Add ingredients
      const ingredientRecords = ingredients.map((ing: any) => ({
        recipe_id: recipe.id,
        inventory_item_id: ing.itemId,
        quantity: ing.quantity,
        unit: ing.unit,
        is_optional: ing.isOptional || false,
        notes: ing.notes,
      }));

      const { error: ingredientError } = await supabase
        .from('inventory_recipe_ingredients')
        .insert(ingredientRecords);

      if (ingredientError) throw ingredientError;

      // Fetch complete recipe
      const { data: completeRecipe } = await supabase
        .from('inventory_recipes')
        .select(`
          *,
          ingredients:inventory_recipe_ingredients(
            *,
            inventory_item:inventory_items(id, name, unit, current_stock, cost_per_unit)
          )
        `)
        .eq('id', recipe.id)
        .single();

      res.status(201).json({ success: true, data: completeRecipe });
    } catch (error: any) {
      logger.error('Error creating recipe:', error);
      res.status(500).json({ success: false, error: 'Failed to create recipe', message: error.message });
    }
  }

  /**
   * Get recipe for a menu item
   */
  async getRecipe(req: Request, res: Response) {
    try {
      const { menuItemId } = req.params;
      const supabase = getSupabase();

      const { data: recipe, error } = await supabase
        .from('inventory_recipes')
        .select(`
          *,
          ingredients:inventory_recipe_ingredients(
            *,
            inventory_item:inventory_items(id, name, unit, current_stock, cost_per_unit)
          )
        `)
        .eq('menu_item_id', menuItemId)
        .eq('is_active', true)
        .single();

      if (error && error.code !== 'PGRST116') throw error;

      if (!recipe) {
        return res.json({ success: true, data: null, message: 'No recipe found for this menu item' });
      }

      // Calculate total cost
      const totalCost = (recipe.ingredients || []).reduce((sum: number, ing: any) => {
        const unitCost = parseFloat(ing.inventory_item?.cost_per_unit) || 0;
        return sum + (ing.quantity * unitCost);
      }, 0);

      // Check stock availability
      const stockStatus = (recipe.ingredients || []).map((ing: any) => ({
        itemId: ing.inventory_item_id,
        itemName: ing.inventory_item?.name,
        required: ing.quantity * recipe.yields,
        available: parseFloat(ing.inventory_item?.current_stock) || 0,
        sufficient: (parseFloat(ing.inventory_item?.current_stock) || 0) >= ing.quantity * recipe.yields,
      }));

      res.json({
        success: true,
        data: {
          ...recipe,
          totalCost,
          stockStatus,
          canProduce: stockStatus.every((s: any) => s.sufficient),
        },
      });
    } catch (error: any) {
      logger.error('Error fetching recipe:', error);
      res.status(500).json({ success: false, error: 'Failed to fetch recipe', message: error.message });
    }
  }

  /**
   * Update recipe ingredients
   */
  async updateRecipe(req: Request, res: Response) {
    try {
      const { recipeId } = req.params;
      const { ingredients, yields, prepTime, notes } = req.body;
      const supabase = getSupabase();

      // Update recipe metadata
      const { error: updateError } = await supabase
        .from('inventory_recipes')
        .update({
          yields: yields,
          prep_time_minutes: prepTime,
          notes,
          updated_at: new Date().toISOString(),
        })
        .eq('id', recipeId);

      if (updateError) throw updateError;

      // Replace ingredients if provided
      if (ingredients && Array.isArray(ingredients)) {
        // Delete existing ingredients
        await supabase
          .from('inventory_recipe_ingredients')
          .delete()
          .eq('recipe_id', recipeId);

        // Insert new ingredients
        const ingredientRecords = ingredients.map((ing: any) => ({
          recipe_id: recipeId,
          inventory_item_id: ing.itemId,
          quantity: ing.quantity,
          unit: ing.unit,
          is_optional: ing.isOptional || false,
          notes: ing.notes,
        }));

        await supabase.from('inventory_recipe_ingredients').insert(ingredientRecords);
      }

      // Fetch updated recipe
      const { data: recipe } = await supabase
        .from('inventory_recipes')
        .select(`
          *,
          ingredients:inventory_recipe_ingredients(
            *,
            inventory_item:inventory_items(id, name, unit, current_stock)
          )
        `)
        .eq('id', recipeId)
        .single();

      res.json({ success: true, data: recipe });
    } catch (error: any) {
      logger.error('Error updating recipe:', error);
      res.status(500).json({ success: false, error: 'Failed to update recipe', message: error.message });
    }
  }

  /**
   * Deduct inventory based on order completion
   * Called when an order status changes to 'completed'
   */
  async deductForOrder(req: Request, res: Response) {
    try {
      const { orderId } = req.params;
      const userId = req.user?.userId;
      const supabase = getSupabase();

      // Get order items
      const { data: orderItems, error: orderError } = await supabase
        .from('order_items')
        .select('product_id, quantity')
        .eq('order_id', orderId);

      if (orderError) throw orderError;

      const deductionResults: any[] = [];

      for (const orderItem of orderItems || []) {
        // Get recipe for this product
        const { data: recipe } = await supabase
          .from('inventory_recipes')
          .select(`
            *,
            ingredients:inventory_recipe_ingredients(
              inventory_item_id,
              quantity,
              is_optional
            )
          `)
          .eq('menu_item_id', orderItem.product_id)
          .eq('is_active', true)
          .single();

        if (!recipe) continue; // No recipe = no deduction

        // Deduct each required ingredient
        for (const ingredient of recipe.ingredients || []) {
          if (ingredient.is_optional) continue;

          const deductQty = ingredient.quantity * orderItem.quantity;

          // Get current stock
          const { data: item } = await supabase
            .from('inventory_items')
            .select('current_stock, name')
            .eq('id', ingredient.inventory_item_id)
            .single();

          if (!item) continue;

          const currentStock = parseFloat(item.current_stock) || 0;
          const newStock = Math.max(0, currentStock - deductQty);

          // Update stock
          await supabase
            .from('inventory_items')
            .update({ current_stock: newStock })
            .eq('id', ingredient.inventory_item_id);

          // Record transaction
          await supabase.from('inventory_transactions').insert({
            item_id: ingredient.inventory_item_id,
            transaction_type: 'sale',
            quantity: -deductQty,
            stock_before: currentStock,
            stock_after: newStock,
            reference_type: 'order',
            reference_id: orderId,
            notes: `Auto-deducted for order`,
            performed_by: userId,
          });

          deductionResults.push({
            itemId: ingredient.inventory_item_id,
            itemName: item.name,
            deducted: deductQty,
            newStock,
          });

          // Check for low stock alert
          const { data: itemInfo } = await supabase
            .from('inventory_items')
            .select('min_stock_level')
            .eq('id', ingredient.inventory_item_id)
            .single();

          if (itemInfo && newStock <= (parseFloat(itemInfo.min_stock_level) || 0)) {
            await supabase.from('inventory_alerts').upsert({
              item_id: ingredient.inventory_item_id,
              alert_type: 'low_stock',
              message: `Low stock alert: ${item.name} is at ${newStock} units`,
              severity: newStock === 0 ? 'critical' : 'warning',
              is_resolved: false,
            }, { onConflict: 'item_id,alert_type' });
          }
        }
      }

      res.json({
        success: true,
        data: {
          orderId,
          deductions: deductionResults,
          message: `Deducted ${deductionResults.length} ingredient(s) from inventory`,
        },
      });
    } catch (error: any) {
      logger.error('Error deducting inventory for order:', error);
      res.status(500).json({ success: false, error: 'Failed to deduct inventory', message: error.message });
    }
  }

  /**
   * Get cost analysis for a menu item
   */
  async getMenuItemCostAnalysis(req: Request, res: Response) {
    try {
      const { menuItemId } = req.params;
      const supabase = getSupabase();

      // Get menu item
      const { data: menuItem, error: menuError } = await supabase
        .from('products')
        .select('id, name, price')
        .eq('id', menuItemId)
        .single();

      if (menuError || !menuItem) {
        return res.status(404).json({ success: false, error: 'Menu item not found' });
      }

      // Get recipe
      const { data: recipe } = await supabase
        .from('inventory_recipes')
        .select(`
          *,
          ingredients:inventory_recipe_ingredients(
            quantity,
            unit,
            inventory_item:inventory_items(id, name, cost_per_unit)
          )
        `)
        .eq('menu_item_id', menuItemId)
        .eq('is_active', true)
        .single();

      if (!recipe) {
        return res.json({
          success: true,
          data: {
            menuItem,
            hasRecipe: false,
            message: 'No recipe found - cost analysis unavailable',
          },
        });
      }

      // Calculate costs
      const ingredientCosts = (recipe.ingredients || []).map((ing: any) => {
        const unitCost = parseFloat(ing.inventory_item?.cost_per_unit) || 0;
        const totalCost = ing.quantity * unitCost;
        return {
          name: ing.inventory_item?.name,
          quantity: ing.quantity,
          unit: ing.unit,
          unitCost,
          totalCost,
        };
      });

      const totalCost = ingredientCosts.reduce((sum: number, i: { totalCost: number }) => sum + i.totalCost, 0);
      const sellingPrice = parseFloat(menuItem.price) || 0;
      const grossProfit = sellingPrice - totalCost;
      const grossMargin = sellingPrice > 0 ? (grossProfit / sellingPrice) * 100 : 0;

      res.json({
        success: true,
        data: {
          menuItem,
          hasRecipe: true,
          recipe: {
            id: recipe.id,
            yields: recipe.yields,
          },
          costAnalysis: {
            ingredientCosts,
            totalCost: totalCost.toFixed(2),
            sellingPrice: sellingPrice.toFixed(2),
            grossProfit: grossProfit.toFixed(2),
            grossMarginPercent: grossMargin.toFixed(1),
          },
        },
      });
    } catch (error: any) {
      logger.error('Error getting cost analysis:', error);
      res.status(500).json({ success: false, error: 'Failed to get cost analysis', message: error.message });
    }
  }

  /**
   * Get inventory dashboard stats
   */
  async getDashboardStats(req: Request, res: Response) {
    try {
      const supabase = getSupabase();

      // Get counts
      const [itemsResult, alertsResult, lowStockResult, expiringResult] = await Promise.all([
        supabase.from('inventory_items').select('id', { count: 'exact', head: true }),
        supabase.from('inventory_alerts').select('id', { count: 'exact', head: true }).eq('is_resolved', false),
        supabase.from('inventory_items').select('id', { count: 'exact', head: true }).lte('current_stock', 10), // Below 10 units
        supabase.from('inventory_items').select('id', { count: 'exact', head: true })
          .not('expiry_date', 'is', null)
          .lte('expiry_date', new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]),
      ]);

      // Get total inventory value
      const { data: items } = await supabase
        .from('inventory_items')
        .select('current_stock, cost_per_unit');

      const totalValue = (items || []).reduce((sum, item) => {
        return sum + ((parseFloat(item.current_stock) || 0) * (parseFloat(item.cost_per_unit) || 0));
      }, 0);

      // Get recent transactions count (last 24h)
      const { count: recentTransactions } = await supabase
        .from('inventory_transactions')
        .select('id', { count: 'exact', head: true })
        .gte('created_at', new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString());

      // Get wastage stats (last 30 days)
      const { data: wastageData } = await supabase
        .from('inventory_wastage')
        .select('cost_impact')
        .gte('created_at', new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString());

      const wastageTotal = (wastageData || []).reduce((sum, w) => sum + (parseFloat(w.cost_impact) || 0), 0);

      res.json({
        success: true,
        data: {
          totalItems: itemsResult.count || 0,
          activeAlerts: alertsResult.count || 0,
          lowStockItems: lowStockResult.count || 0,
          expiringItems: expiringResult.count || 0,
          totalInventoryValue: totalValue.toFixed(2),
          recentTransactions: recentTransactions || 0,
          wastage30Days: wastageTotal.toFixed(2),
        },
      });
    } catch (error: any) {
      logger.error('Error getting dashboard stats:', error);
      res.status(500).json({ success: false, error: 'Failed to get dashboard stats', message: error.message });
    }
  }
}

export const inventoryAdvancedController = new InventoryAdvancedController();

import { Request, Response } from 'express';
import { getSupabase } from '../../database/connection.js';
import { z } from 'zod';

// Validation schemas
const createItemSchema = z.object({
  name: z.string().min(1).max(200),
  sku: z.string().max(50).optional(),
  description: z.string().optional(),
  categoryId: z.string().uuid(),
  unit: z.enum(['piece', 'kg', 'liter', 'box', 'pack', 'bottle']).default('piece'),
  currentStock: z.number().min(0).default(0),
  minStockLevel: z.number().min(0).default(10),
  maxStockLevel: z.number().min(0).optional(),
  reorderPoint: z.number().min(0).default(5),
  costPerUnit: z.number().min(0).optional(),
  supplier: z.string().max(200).optional(),
  location: z.string().max(100).optional(),
  expiryDate: z.string().datetime().optional(),
  notes: z.string().optional(),
});

const updateItemSchema = createItemSchema.partial().extend({
  isActive: z.boolean().optional(),
});

const transactionSchema = z.object({
  itemId: z.string().uuid(),
  type: z.enum(['in', 'out', 'adjustment', 'waste', 'return']),
  quantity: z.number().positive(),
  reason: z.string().optional(),
  referenceType: z.enum(['purchase', 'order', 'manual', 'waste', 'return']).default('manual'),
  referenceId: z.string().uuid().optional(),
  notes: z.string().optional(),
});

const bulkTransactionSchema = z.object({
  transactions: z.array(transactionSchema),
});

const createCategorySchema = z.object({
  name: z.string().min(1).max(100),
  description: z.string().optional(),
  color: z.string().regex(/^#[0-9A-Fa-f]{6}$/).optional(),
});

export class InventoryController {
  /**
   * Get all categories
   */
  async getCategories(req: Request, res: Response) {
    try {
      const supabase = getSupabase();
      
      const { data: categories, error } = await supabase
        .from('inventory_categories')
        .select('*')
        .order('name', { ascending: true });

      if (error) throw error;

      // Get item counts for each category
      const { data: items } = await supabase
        .from('inventory_items')
        .select('category_id, current_stock')
        .eq('is_active', true);

      const categoryStats = (categories || []).map(cat => {
        const catItems = (items || []).filter(i => i.category_id === cat.id);
        return {
          ...cat,
          item_count: catItems.length,
          total_stock: catItems.reduce((sum, i) => sum + parseFloat(i.current_stock || 0), 0),
        };
      });

      res.json({
        success: true,
        data: categoryStats,
      });
    } catch (error: any) {
      console.error('Error fetching categories:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to fetch categories',
        message: error.message,
      });
    }
  }

  /**
   * Create a category
   */
  async createCategory(req: Request, res: Response) {
    try {
      const validation = createCategorySchema.safeParse(req.body);
      if (!validation.success) {
        return res.status(400).json({
          success: false,
          error: 'Validation failed',
          details: validation.error.errors,
        });
      }

      const data = validation.data;
      const supabase = getSupabase();

      const { data: result, error } = await supabase
        .from('inventory_categories')
        .insert({
          name: data.name,
          description: data.description,
          color: data.color,
        })
        .select()
        .single();

      if (error) throw error;

      res.status(201).json({
        success: true,
        data: result,
      });
    } catch (error: any) {
      console.error('Error creating category:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to create category',
        message: error.message,
      });
    }
  }

  /**
   * Update a category
   */
  async updateCategory(req: Request, res: Response) {
    try {
      const { id } = req.params;
      const validation = createCategorySchema.partial().safeParse(req.body);
      
      if (!validation.success) {
        return res.status(400).json({
          success: false,
          error: 'Validation failed',
          details: validation.error.errors,
        });
      }

      const data = validation.data;
      const supabase = getSupabase();

      const updates: Record<string, any> = {
        updated_at: new Date().toISOString(),
      };

      if (data.name) updates.name = data.name;
      if (data.description !== undefined) updates.description = data.description;
      if (data.color) updates.color = data.color;

      if (Object.keys(updates).length === 1) {
        return res.status(400).json({ success: false, error: 'No fields to update' });
      }

      const { data: result, error } = await supabase
        .from('inventory_categories')
        .update(updates)
        .eq('id', id)
        .select()
        .single();

      if (error || !result) {
        return res.status(404).json({ success: false, error: 'Category not found' });
      }

      res.json({
        success: true,
        data: result,
      });
    } catch (error: any) {
      console.error('Error updating category:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to update category',
        message: error.message,
      });
    }
  }

  /**
   * Delete a category (only if empty)
   */
  async deleteCategory(req: Request, res: Response) {
    try {
      const { id } = req.params;
      const supabase = getSupabase();

      // Check if category has items
      const { count, error: countError } = await supabase
        .from('inventory_items')
        .select('*', { count: 'exact', head: true })
        .eq('category_id', id)
        .eq('is_active', true);

      if (countError) {
        return res.status(500).json({ success: false, error: 'Failed to check category items' });
      }

      if (count && count > 0) {
        return res.status(400).json({
          success: false,
          error: `Cannot delete category with ${count} items. Please move or delete items first.`,
        });
      }

      const { error } = await supabase
        .from('inventory_categories')
        .delete()
        .eq('id', id);

      if (error) {
        return res.status(500).json({ success: false, error: 'Failed to delete category' });
      }

      res.json({ success: true, message: 'Category deleted successfully' });
    } catch (error: any) {
      console.error('Error deleting category:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to delete category',
        message: error.message,
      });
    }
  }

  /**
   * Get all inventory items
   */
  async getItems(req: Request, res: Response) {
    try {
      const { 
        page = '1', 
        limit = '50', 
        categoryId, 
        search, 
        lowStock,
        outOfStock,
        expiringSoon,
        sortBy = 'name',
        sortOrder = 'asc',
      } = req.query;
      
      const offset = (parseInt(page as string) - 1) * parseInt(limit as string);
      const supabase = getSupabase();

      let query = supabase
        .from('inventory_items')
        .select('*', { count: 'exact' })
        .eq('is_active', true);

      if (categoryId) {
        query = query.eq('category_id', categoryId as string);
      }

      if (search) {
        query = query.or(`name.ilike.%${search}%,sku.ilike.%${search}%`);
      }

      if (lowStock === 'true') {
        query = query.gt('current_stock', 0).lte('current_stock', 'reorder_point');
      }

      if (outOfStock === 'true') {
        query = query.eq('current_stock', 0);
      }

      if (expiringSoon === 'true') {
        const sevenDaysFromNow = new Date();
        sevenDaysFromNow.setDate(sevenDaysFromNow.getDate() + 7);
        query = query
          .not('expiry_date', 'is', null)
          .lte('expiry_date', sevenDaysFromNow.toISOString());
      }

      // Sorting
      const allowedSorts = ['name', 'current_stock', 'updated_at'];
      const sortField = allowedSorts.includes(sortBy as string) ? sortBy as string : 'name';
      
      const { data: items, error, count } = await query
        .order(sortField, { ascending: sortOrder !== 'desc' })
        .range(offset, offset + parseInt(limit as string) - 1);

      if (error) throw error;

      // Get category info
      const categoryIds = [...new Set((items || []).map(i => i.category_id).filter(Boolean))];
      let categoriesMap: Record<string, any> = {};
      if (categoryIds.length > 0) {
        const { data: categories } = await supabase
          .from('inventory_categories')
          .select('id, name, color')
          .in('id', categoryIds);
        categoriesMap = (categories || []).reduce((acc, c) => { acc[c.id] = c; return acc; }, {} as Record<string, any>);
      }

      // Add stock status and category info
      const enrichedItems = (items || []).map(item => ({
        ...item,
        category_name: categoriesMap[item.category_id]?.name,
        category_color: categoriesMap[item.category_id]?.color,
        stock_status: item.current_stock === 0 ? 'out_of_stock'
          : item.current_stock <= item.reorder_point ? 'low_stock'
          : item.max_stock_level && item.current_stock > item.max_stock_level ? 'overstock'
          : 'normal',
      }));

      res.json({
        success: true,
        data: enrichedItems,
        pagination: {
          page: parseInt(page as string),
          limit: parseInt(limit as string),
          total: count || 0,
          totalPages: Math.ceil((count || 0) / parseInt(limit as string)),
        },
      });
    } catch (error: any) {
      console.error('Error fetching items:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to fetch items',
        message: error.message,
      });
    }
  }

  /**
   * Get single item details
   */
  async getItem(req: Request, res: Response) {
    try {
      const { id } = req.params;
      const supabase = getSupabase();

      const { data: item, error } = await supabase
        .from('inventory_items')
        .select('*')
        .eq('id', id)
        .single();

      if (error || !item) {
        return res.status(404).json({ success: false, error: 'Item not found' });
      }

      // Get category
      let categoryInfo = null;
      if (item.category_id) {
        const { data: category } = await supabase
          .from('inventory_categories')
          .select('name, color')
          .eq('id', item.category_id)
          .single();
        categoryInfo = category;
      }

      // Get recent transactions
      const { data: transactions } = await supabase
        .from('inventory_transactions')
        .select('*')
        .eq('item_id', id)
        .order('created_at', { ascending: false })
        .limit(20);

      // Get user names for transactions
      const userIds = [...new Set((transactions || []).map(t => t.performed_by).filter(Boolean))];
      let usersMap: Record<string, any> = {};
      if (userIds.length > 0) {
        const { data: users } = await supabase.from('users').select('id, full_name').in('id', userIds);
        usersMap = (users || []).reduce((acc, u) => { acc[u.id] = u; return acc; }, {} as Record<string, any>);
      }

      // Map DB field names to frontend expected names
      const dbTypeToApiType: Record<string, string> = {
        purchase: 'in',
        sale: 'out',
        adjustment: 'adjustment',
        waste: 'waste',
        return: 'return',
      };

      const enrichedTransactions = (transactions || []).map(t => ({
        id: t.id,
        item_id: t.item_id,
        type: dbTypeToApiType[t.transaction_type] || t.transaction_type,
        quantity: Math.abs(t.quantity),
        previous_stock: t.stock_before,
        new_stock: t.stock_after,
        reference_type: t.reference_type,
        notes: t.notes,
        performed_by_name: usersMap[t.performed_by]?.full_name,
        created_at: t.created_at,
      }));

      // Get linked menu items
      const { data: linkedMenuItems } = await supabase
        .from('menu_item_ingredients')
        .select('menu_item_id, quantity_needed')
        .eq('inventory_item_id', id);

      let menuItemsInfo: any[] = [];
      if (linkedMenuItems && linkedMenuItems.length > 0) {
        const menuItemIds = linkedMenuItems.map(l => l.menu_item_id);
        const { data: menuItems } = await supabase
          .from('menu_items')
          .select('id, name')
          .in('id', menuItemIds);
        
        menuItemsInfo = (linkedMenuItems || []).map(link => ({
          id: link.menu_item_id,
          name: menuItems?.find(m => m.id === link.menu_item_id)?.name,
          quantity_needed: link.quantity_needed,
        }));
      }

      res.json({
        success: true,
        data: {
          ...item,
          category_name: categoryInfo?.name,
          category_color: categoryInfo?.color,
          transactions: enrichedTransactions,
          linkedMenuItems: menuItemsInfo,
        },
      });
    } catch (error: any) {
      console.error('Error fetching item:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to fetch item',
        message: error.message,
      });
    }
  }

  /**
   * Create an inventory item
   */
  async createItem(req: Request, res: Response) {
    try {
      const validation = createItemSchema.safeParse(req.body);
      if (!validation.success) {
        return res.status(400).json({
          success: false,
          error: 'Validation failed',
          details: validation.error.errors,
        });
      }

      const data = validation.data;
      const userId = req.user?.id;
      const supabase = getSupabase();

      // Generate SKU if not provided
      let sku = data.sku;
      if (!sku) {
        const prefix = data.name.substring(0, 3).toUpperCase();
        const random = Math.random().toString(36).substring(2, 6).toUpperCase();
        sku = `${prefix}-${random}`;
      }

      const { data: result, error } = await supabase
        .from('inventory_items')
        .insert({
          name: data.name,
          sku,
          description: data.description,
          category_id: data.categoryId,
          unit: data.unit,
          current_stock: data.currentStock,
          min_stock_level: data.minStockLevel,
          max_stock_level: data.maxStockLevel,
          reorder_point: data.reorderPoint,
          cost_per_unit: data.costPerUnit,
          supplier: data.supplier,
          location: data.location,
          expiry_date: data.expiryDate,
          notes: data.notes,
          created_by: userId,
        })
        .select()
        .single();

      if (error) throw error;

      // Record initial stock transaction if stock > 0
      if (data.currentStock > 0) {
        await supabase.from('inventory_transactions').insert({
          item_id: result.id,
          transaction_type: 'purchase',
          quantity: data.currentStock,
          stock_before: 0,
          stock_after: data.currentStock,
          reference_type: 'manual',
          notes: 'Initial stock',
          performed_by: userId,
        });
      }

      // Check for low stock alert
      if (data.currentStock <= data.reorderPoint) {
        await this.createStockAlert(result.id, 'low_stock', data.currentStock);
      }

      res.status(201).json({
        success: true,
        data: result,
      });
    } catch (error: any) {
      console.error('Error creating item:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to create item',
        message: error.message,
      });
    }
  }

  /**
   * Update an inventory item
   */
  async updateItem(req: Request, res: Response) {
    try {
      const { id } = req.params;
      const validation = updateItemSchema.safeParse(req.body);
      
      if (!validation.success) {
        return res.status(400).json({
          success: false,
          error: 'Validation failed',
          details: validation.error.errors,
        });
      }

      const data = validation.data;
      const supabase = getSupabase();

      const updates: Record<string, any> = {
        updated_at: new Date().toISOString(),
      };

      if (data.name !== undefined) updates.name = data.name;
      if (data.sku !== undefined) updates.sku = data.sku;
      if (data.description !== undefined) updates.description = data.description;
      if (data.categoryId !== undefined) updates.category_id = data.categoryId;
      if (data.unit !== undefined) updates.unit = data.unit;
      if (data.minStockLevel !== undefined) updates.min_stock_level = data.minStockLevel;
      if (data.maxStockLevel !== undefined) updates.max_stock_level = data.maxStockLevel;
      if (data.reorderPoint !== undefined) updates.reorder_point = data.reorderPoint;
      if (data.costPerUnit !== undefined) updates.cost_per_unit = data.costPerUnit;
      if (data.supplier !== undefined) updates.supplier = data.supplier;
      if (data.location !== undefined) updates.location = data.location;
      if (data.expiryDate !== undefined) updates.expiry_date = data.expiryDate;
      if (data.notes !== undefined) updates.notes = data.notes;
      if (data.isActive !== undefined) updates.is_active = data.isActive;

      if (Object.keys(updates).length === 1) {
        return res.status(400).json({ success: false, error: 'No fields to update' });
      }

      const { data: result, error } = await supabase
        .from('inventory_items')
        .update(updates)
        .eq('id', id)
        .select()
        .single();

      if (error || !result) {
        return res.status(404).json({ success: false, error: 'Item not found' });
      }

      res.json({
        success: true,
        data: result,
      });
    } catch (error: any) {
      console.error('Error updating item:', error);
      res.status(500).json({
        success: false,
        error: 'Failed to update item',
        message: error.message,
      });
    }
  }

