  property_id: string;
  deviceName: string;
  name: string;
  deviceCode: string;
  location?: string;
  deviceType: string;
  capabilities: any;
  status: string;
  config: Record<string, any>;
  last_heartbeat?: string;
  key_stock: number;
  is_active: boolean;
  error_count: number;
  [key: string]: any;
}

interface KioskCapabilities {
  hasIdScanner: boolean;
  hasCardReader: boolean;
  hasKeyEncoder: boolean;
  hasReceiptPrinter: boolean;
  hasSignaturePad: boolean;
  hasCamera: boolean;
  hasCashAcceptor: boolean;
  hasCardDispenser: boolean;
}

interface KioskSession {
  id: string;
  kioskId: string;
  sessionType: string;
  bookingId?: string;
  guestId?: string;
