  // =============================================
  // SESSION MANAGEMENT
  // =============================================

  async startSession(
    kioskId: string,
    sessionType: string,
    data?: {
      bookingId?: string;
      guestId?: string;
      confirmationNumber?: string;
    }
  ): Promise<KioskSession> {
    const device = await this.getDevice(kioskId);
    if (!device) {
      throw new Error('Kiosk device not found');
    }
    if (device.status !== 'online') {
      throw new Error(`Kiosk is not available (status: ${device.status})`);
    }

    const { data: session, error } = await this.supabase
      .from('kiosk_sessions')
      .insert({
        kiosk_id: kioskId,
        property_id: device.propertyId,
        session_type: sessionType,
        booking_id: data?.bookingId || null,
        guest_id: data?.guestId || null,
        confirmation_number: data?.confirmationNumber || null,
        status: 'started',
        current_step: 'welcome',
        steps_completed: [],
        input_data: {},
        last_activity_at: new Date().toISOString()
      })
      .select()
      .single();

    if (error) throw error;
    return this.mapSession(session);
  }

  async getSession(sessionId: string): Promise<KioskSession | null> {
    const { data: session, error } = await this.supabase
      .from('kiosk_sessions')
      .select('*')
      .eq('id', sessionId)
      .single();

    if (error || !session) return null;
    return this.mapSession(session);
  }

  async updateSessionStep(
    sessionId: string,
    step: string,
    data?: Record<string, any>
  ): Promise<void> {
    const session = await this.getSession(sessionId);
    if (!session) {
      throw new Error('Session not found');
    }

    const stepsCompleted = [...session.stepsCompleted];
    if (session.currentStep && !stepsCompleted.includes(session.currentStep)) {
      stepsCompleted.push(session.currentStep);
    }

    const inputData = {
      ...session.inputData,
      ...(data || {}),
      [`${step}_timestamp`]: new Date().toISOString()
    };

    await this.supabase
      .from('kiosk_sessions')
      .update({
        current_step: step,
        steps_completed: stepsCompleted,
        input_data: inputData,
        status: 'in_progress',
        last_activity_at: new Date().toISOString()
      })
      .eq('id', sessionId);
  }

  async completeSession(
    sessionId: string,
    resultStatus: string,
    resultData?: Record<string, any>
  ): Promise<void> {
    await this.supabase
      .from('kiosk_sessions')
      .update({
        status: 'completed',
        result_status: resultStatus,
        result_data: resultData || {},
        completed_at: new Date().toISOString(),
        last_activity_at: new Date().toISOString()
      })
      .eq('id', sessionId);
  }

  async abandonSession(sessionId: string, reason?: string): Promise<void> {
    await this.supabase
      .from('kiosk_sessions')
      .update({
        status: 'abandoned',
        result_status: 'abandoned',
        failure_reason: reason || 'User cancelled',
        completed_at: new Date().toISOString(),
        last_activity_at: new Date().toISOString()
      })
      .eq('id', sessionId);
  }

  async timeoutSession(sessionId: string): Promise<void> {
    await this.supabase
      .from('kiosk_sessions')
      .update({
        status: 'timeout',
        result_status: 'timeout',
        failure_reason: 'Session timed out due to inactivity',
        completed_at: new Date().toISOString()
      })
      .eq('id', sessionId);
  }

  async transferToDesk(
    sessionId: string,
    reason: string,
    staffId?: string
  ): Promise<void> {
    await this.supabase
      .from('kiosk_sessions')
      .update({
        transferred_to_desk: true,
        transfer_reason: reason,
        desk_staff_id: staffId || null,
        status: 'completed',
        result_status: 'transferred',
        completed_at: new Date().toISOString()
      })
      .eq('id', sessionId);
  }

  async processTimeouts(timeoutMinutes: number = 2): Promise<number> {
    const cutoffTime = new Date(Date.now() - timeoutMinutes * 60 * 1000).toISOString();
    
    const { data: sessions } = await this.supabase
      .from('kiosk_sessions')
      .select('id')
      .in('status', ['started', 'in_progress'])
      .lt('last_activity_at', cutoffTime);

    if (!sessions || sessions.length === 0) return 0;

    for (const session of sessions) {
      await this.timeoutSession(session.id);
    }

    return sessions.length;
  }

  // =============================================
  // KIOSK TRANSACTIONS
  // =============================================

  async createTransaction(
    sessionId: string,
    kioskId: string,
    transactionType: string,
    requestData?: Record<string, any>
  ): Promise<string> {
    const { data: transaction, error } = await this.supabase
      .from('kiosk_transactions')
      .insert({
        session_id: sessionId,
        kiosk_id: kioskId,
        transaction_type: transactionType,
        status: 'pending',
        request_data: requestData || {}
      })
      .select('id')
      .single();

    if (error) throw error;
    return transaction.id;
  }

  async updateTransaction(
    transactionId: string,
    status: string,
    responseData?: Record<string, any>,
    error?: { code?: string; message?: string }
  ): Promise<void> {
    const updateData: Record<string, any> = {
      status,
      response_data: responseData || {},
      error_code: error?.code || null,
      error_message: error?.message || null
    };

    if (status === 'completed' || status === 'failed') {
      updateData.completed_at = new Date().toISOString();
    }

    await this.supabase
      .from('kiosk_transactions')
      .update(updateData)
      .eq('id', transactionId);
  }

  // =============================================
  // ID SCANNING
  // =============================================

  async scanId(
    sessionId: string,
    kioskId: string,
    scanData: {
      documentType: string;
      frontImage: string;
      backImage?: string;
      rawData?: Record<string, any>;
    }
  ): Promise<{
    transactionId: string;
    extractedData?: Record<string, any>;
    verified: boolean;
  }> {
    const transactionId = await this.createTransaction(
      sessionId,
      kioskId,
      'id_scan',
      scanData
    );

    try {
      const extractedData = this.simulateIdExtraction(scanData);
      await this.updateTransaction(transactionId, 'completed', { extractedData });
      await this.updateSessionStep(sessionId, 'id_verified', {
        documentType: scanData.documentType,
        guestData: extractedData
      });

      return {
        transactionId,
        extractedData,
        verified: true
      };
    } catch (error) {
      await this.updateTransaction(transactionId, 'failed', undefined, {
        message: error instanceof Error ? error.message : 'ID scan failed'
      });
      throw error;
    }
  }

  private simulateIdExtraction(scanData: Record<string, any>): Record<string, any> {
    return {
      firstName: 'JOHN',
      lastName: 'DOE',
      dateOfBirth: '1985-06-15',
      documentNumber: 'AB1234567',
      expirationDate: '2028-06-15',
      nationality: 'US',
      extractedAt: new Date().toISOString()
    };
  }

  // =============================================
  // KEY ENCODING
  // =============================================

  async encodeKey(
    sessionId: string,
    kioskId: string,
    keyData: {
      roomNumber: string;
      guestName: string;
      checkInDate: Date;
      checkOutDate: Date;
      accessPoints?: string[];
    }
  ): Promise<{
    transactionId: string;
    keyNumber: string;
    success: boolean;
  }> {
    const stock = await this.getKeyStock(kioskId);
    if (stock && stock.currentStock <= 0) {
      throw new Error('Key stock depleted - please visit front desk');
    }

    const transactionId = await this.createTransaction(
      sessionId,
      kioskId,
      'key_encode',
      keyData
    );

    try {
      const keyNumber = this.generateKeyNumber();
      await new Promise(resolve => setTimeout(resolve, 500));

      await this.updateTransaction(transactionId, 'completed', {
        keyNumber,
        encodedAt: new Date().toISOString()
      });

      await this.decrementKeyStock(kioskId);

      return {
        transactionId,
        keyNumber,
        success: true
      };
    } catch (error) {
      await this.updateTransaction(transactionId, 'failed', undefined, {
        message: error instanceof Error ? error.message : 'Key encoding failed'
      });
      throw error;
    }
  }

  private generateKeyNumber(): string {
    return `K${Date.now().toString(36).toUpperCase()}`;
  }

  // =============================================
  // PAYMENT PROCESSING
  // =============================================

  async processPayment(
    sessionId: string,
    kioskId: string,
    paymentData: {
      amount: number;
      currency: string;
      paymentMethod: string;
      description?: string;
    }
  ): Promise<{
    transactionId: string;
    paymentReference: string;
    success: boolean;
  }> {
    const transactionId = await this.createTransaction(
      sessionId,
      kioskId,
      'payment',
      paymentData
    );

    try {
      const paymentReference = `PAY-${uuidv4().substring(0, 8).toUpperCase()}`;

      await this.supabase
        .from('kiosk_transactions')
        .update({
          amount: paymentData.amount,
          currency: paymentData.currency,
          payment_method: paymentData.paymentMethod
        })
        .eq('id', transactionId);

      await new Promise(resolve => setTimeout(resolve, 1000));

      await this.updateTransaction(transactionId, 'completed', {
        paymentReference,
        processedAt: new Date().toISOString()
      });

      await this.supabase
        .from('kiosk_transactions')
        .update({ payment_reference: paymentReference })
        .eq('id', transactionId);

      return {
        transactionId,
        paymentReference,
        success: true
      };
    } catch (error) {
      await this.updateTransaction(transactionId, 'failed', undefined, {
        message: error instanceof Error ? error.message : 'Payment failed'
      });
      throw error;
    }
  }

