  async trackUnsubscribe(
    guestId: string,
    propertyId: string,
    email: string,
    reason?: string,
    campaignId?: string
  ): Promise<void> {
    // Update preferences - upsert
    await this.supabase
      .from('guest_preferences')
      .upsert({
        guest_id: guestId,
        property_id: propertyId,
        email_marketing: false,
        unsubscribed_at: new Date().toISOString(),
