// Lazy-initialized Supabase client - use proxy to defer getSupabase() call
const supabase = new Proxy({} as ReturnType<typeof getSupabase>, {
  get(_, prop) { return getSupabase()[prop as keyof ReturnType<typeof getSupabase>]; }
});

