      res.json({
        success: true,
        data: {
          guestPasses: (guestPassUsage || []).map((g: any) => ({
            guestName: g.guest_name,
            usedAt: g.used_at,
          })),
          visits: (visits || []).map((v: any) => ({
            date: v.date,
            quantity: v.quantity,
            status: v.status,
          })),
        },
      });
  })
);

