        res.status(400).json({ error: 'Property ID required' });
        return;
      }

      const dashboards = await reportingService.getDashboards(propertyId);
      res.json({ dashboards });
  });
  getDashboard = asyncHandler(async (req: Request, res: Response) => {
      const { id } = req.params;
      const dashboard = await reportingService.getDashboardWithWidgets(id);

      if (!dashboard) {
        res.status(404).json({ error: 'Dashboard not found' });
        return;
      }

      res.json({ dashboard });
  });
  createDashboard = asyncHandler(async (req: Request, res: Response) => {
      const propertyId = req.headers['x-property-id'] as string;
      const userId = req.user?.id;
      if (!userId) throw new Error('Authentication required');

      if (!propertyId) {
        res.status(400).json({ error: 'Property ID required' });
        return;
      }

      const dashboard = await reportingService.createDashboard(propertyId, req.body, userId);
      res.status(201).json({ dashboard });
  });
  addWidget = asyncHandler(async (req: Request, res: Response) => {
      const { dashboardId } = req.params;
      const widget = await reportingService.addWidget(dashboardId, req.body);
      res.status(201).json({ widget });
  });
  updateWidgetLayout = asyncHandler(async (req: Request, res: Response) => {
      const { widgetId } = req.params;
      await reportingService.updateWidgetLayout(widgetId, req.body);
      res.json({ message: 'Widget layout updated' });
  });
  deleteWidget = asyncHandler(async (req: Request, res: Response) => {
      const { widgetId } = req.params;
      await reportingService.deleteWidget(widgetId);
      res.status(204).send();
  });
  // =============================================
  // DATA SNAPSHOTS
  // =============================================

  createSnapshot = asyncHandler(async (req: Request, res: Response) => {
      const propertyId = req.headers['x-property-id'] as string;
      const { date } = req.body;

      if (!propertyId) {
        res.status(400).json({ error: 'Property ID required' });
        return;
      }

      await reportingService.createDailySnapshot(propertyId, date ? new Date(date) : new Date());
      res.json({ message: 'Snapshot created' });
  });
  lockMonthSnapshot = asyncHandler(async (req: Request, res: Response) => {
      const propertyId = req.headers['x-property-id'] as string;
      const userId = req.user?.id;
      if (!userId) throw new Error('Authentication required');
      const { month } = req.body;

      if (!propertyId) {
        res.status(400).json({ error: 'Property ID required' });
        return;
      }

      await reportingService.lockMonthSnapshot(propertyId, new Date(month), userId);
      res.json({ message: 'Month snapshots locked' });
  });
}

export const reportingController = new ReportingController();

// Reporting Service - Converted to Supabase
import { getSupabase } from '../../database/connection.js';
import { logger } from '../../utils/logger.js';
import { v4 as uuidv4 } from 'uuid';
import dayjs from 'dayjs';
import nodemailer from 'nodemailer';
import cron from 'node-cron';
import PDFDocument from 'pdfkit';
import ExcelJS from 'exceljs';
import { Parser } from 'json2csv';

// =============================================
// TYPES
// =============================================

interface ReportResult {
  data: any[];
  totals?: Record<string, number>;
  metadata: {
    generatedAt: Date;
    rowCount: number;
    executionTimeMs: number;
  };
}

interface DateRange {
  start: Date;
  end: Date;
}

interface PaginationOptions {
  page?: number;
  pageSize?: number;
}

// =============================================
// REPORTING SERVICE
// =============================================

class ReportingService {
  private get supabase() {
    return getSupabase();
  }

  private emailTransporter: nodemailer.Transporter | null = null;

  constructor() {
    this.initEmailTransporter();
  }

  private initEmailTransporter(): void {
    if (process.env.SMTP_HOST) {
      this.emailTransporter = nodemailer.createTransport({
        host: process.env.SMTP_HOST,
        port: parseInt(process.env.SMTP_PORT || '587'),
        secure: process.env.SMTP_SECURE === 'true',
        auth: {
          user: process.env.SMTP_USER,
          pass: process.env.SMTP_PASS
        }
      });
    }
  }

  // =============================================
  // REPORT TEMPLATES
  // =============================================

  async getTemplates(propertyId: string, category?: string): Promise<any[]> {
    let query = this.supabase
      .from('report_templates')
      .select('*')
      .or(`property_id.eq.${propertyId},is_system.eq.true`)
      .eq('is_active', true);

    if (category) {
      query = query.eq('category', category);
    }

    const { data, error } = await query.order('sort_order').order('name');

    if (error) throw error;
    return data || [];
  }

  async getTemplateById(templateId: string): Promise<any> {
    const { data, error } = await this.supabase
      .from('report_templates')
      .select('*')
      .eq('id', templateId)
      .single();

    if (error && error.code !== 'PGRST116') throw error;
    return data;
  }

  async createTemplate(propertyId: string, data: {
    name: string;
    description?: string;
    category: string;
    queryConfig: any;
    defaultParams?: any;
    columnConfig?: any;
    chartConfig?: any;
    allowedRoles?: string[];
  }, userId: string): Promise<any> {
    const id = uuidv4();

    const { data: template, error } = await this.supabase
      .from('report_templates')
      .insert({
        id,
        property_id: propertyId,
        name: data.name,
        description: data.description || null,
        category: data.category,
        query_config: data.queryConfig,
        default_params: data.defaultParams || {},
        column_config: data.columnConfig || [],
        chart_config: data.chartConfig || null,
        allowed_roles: data.allowedRoles || ['admin', 'manager'],
        is_system: false,
        is_active: true,
        created_by: userId
      })
      .select()
      .single();

    if (error) throw error;
    return template;
  }

  async updateTemplate(templateId: string, data: Partial<{
    name: string;
    description: string;
    category: string;
    queryConfig: any;
    defaultParams: any;
    columnConfig: any;
    chartConfig: any;
    allowedRoles: string[];
    isActive: boolean;
  }>): Promise<any> {
    const updateData: any = { updated_at: new Date().toISOString() };

    if (data.name !== undefined) updateData.name = data.name;
    if (data.description !== undefined) updateData.description = data.description;
    if (data.category !== undefined) updateData.category = data.category;
    if (data.queryConfig !== undefined) updateData.query_config = data.queryConfig;
    if (data.defaultParams !== undefined) updateData.default_params = data.defaultParams;
    if (data.columnConfig !== undefined) updateData.column_config = data.columnConfig;
    if (data.chartConfig !== undefined) updateData.chart_config = data.chartConfig;
    if (data.allowedRoles !== undefined) updateData.allowed_roles = data.allowedRoles;
    if (data.isActive !== undefined) updateData.is_active = data.isActive;

    const { data: template, error } = await this.supabase
      .from('report_templates')
      .update(updateData)
      .eq('id', templateId)
      .eq('is_system', false)
      .select()
      .single();

    if (error) throw error;
    return template;
  }

  async deleteTemplate(templateId: string): Promise<void> {
    const { error } = await this.supabase
      .from('report_templates')
      .update({ is_active: false, updated_at: new Date().toISOString() })
      .eq('id', templateId)
      .eq('is_system', false);

    if (error) throw error;
  }

  // =============================================
  // REPORT EXECUTION
  // Controller calls: executeReport(propertyId, templateId, params, userId)
  // =============================================

  async executeReport(
    propertyId: string,
    templateId: string,
    params: Record<string, any> = {},
    userId: string
  ): Promise<ReportResult> {
    const startTime = Date.now();

    const template = await this.getTemplateById(templateId);
    if (!template) {
      throw new Error('Report template not found');
    }

    const mergedParams = { ...template.default_params, ...params };
    const queryConfig = template.query_config;

    // Build and execute the query
    const data = await this.buildReportQuery(propertyId, queryConfig, mergedParams);

    // Calculate totals if configured
    let totals: Record<string, number> = {};
    if (queryConfig.aggregateColumns && queryConfig.aggregateColumns.length > 0) {
      totals = this.calculateTotals(data, queryConfig.aggregateColumns);
    }

    const executionTime = Date.now() - startTime;

    // Log execution
    await this.supabase.from('report_execution_log').insert({
      id: uuidv4(),
      template_id: templateId,
      property_id: propertyId,
      executed_by: userId,
      params: mergedParams,
      execution_time_ms: executionTime,
      row_count: data.length
    });

    return {
      data,
      totals,
      metadata: {
        generatedAt: new Date(),
        rowCount: data.length,
        executionTimeMs: executionTime
      }
    };
  }

  private async buildReportQuery(
    propertyId: string,
    config: any,
    params: Record<string, any>
  ): Promise<any[]> {
    const tableName = config.table || 'bookings';
    const selectColumns = config.columns?.join(', ') || '*';

    let query = this.supabase
      .from(tableName)
      .select(selectColumns)
      .eq('property_id', propertyId);

    // Apply date filters
    if (params.dateRange?.start) {
      const dateCol = config.dateColumn || 'created_at';
      query = query.gte(dateCol, params.dateRange.start.toISOString());
    }
    if (params.dateRange?.end) {
      const dateCol = config.dateColumn || 'created_at';
      query = query.lte(dateCol, params.dateRange.end.toISOString());
    }

    // Apply additional filters
    if (params.filters) {
      for (const [key, value] of Object.entries(params.filters)) {
        if (value !== undefined && value !== null) {
          query = query.eq(key, value);
        }
      }
    }

    // Apply ordering
    if (params.sortBy) {
      query = query.order(params.sortBy, { ascending: false });
    } else if (config.orderBy) {
      query = query.order(config.orderBy, { ascending: config.orderAsc ?? false });
    }

    // Apply limit/offset
    if (params.limit) {
      query = query.limit(params.limit);
    }
    if (params.offset) {
      query = query.range(params.offset, params.offset + (params.limit || 100) - 1);
    }

    const { data, error } = await query;
    if (error) throw error;
    return data || [];
  }

  private calculateTotals(data: any[], aggregateColumns: string[]): Record<string, number> {
    const totals: Record<string, number> = {};

    for (const col of aggregateColumns) {
      totals[col] = data.reduce((sum, row) => sum + (Number(row[col]) || 0), 0);
    }

    return totals;
  }

  // =============================================
  // SAVED REPORTS
