  private async logYieldChange(
    propertyId: string,
    date: Date | null,
    roomTypeId: string | null,
    actionType: string,
    previousValue: any,
    newValue: any,
    reasonCode: string,
    triggeredBy: 'system' | 'user' | 'rule' | 'api',
