import { asyncHandler } from '../../middleware/async-handler.js';
import { getSupabase } from '../../database/connection.js';
import { logger } from '../../utils/logger.js';
import { logActivity } from '../../utils/activityLogger.js';

interface UserData {
  profile: {
    id: string;
    email: string;
    full_name: string;
    phone?: string;
    profile_image_url?: string;
    created_at: string;
    updated_at?: string;
  };
  orders: {
    restaurant_orders: unknown[];
    snack_orders: unknown[];
  };
  bookings: {
    chalet_bookings: unknown[];
    pool_tickets: unknown[];
  };
  reviews: unknown[];
  support_tickets: unknown[];
  activity_logs: unknown[];
}

/**
 * GET /api/users/me/data
 * GDPR Article 15 - Right of Access
 * Returns all personal data associated with the authenticated user
 */
export const exportUserData = asyncHandler(async (req: Request, res: Response) => {
    const userId = req.user?.userId;
    
    if (!userId) {
      res.status(401).json({ success: false, error: 'Authentication required' });
      return;
    }

    const supabase = getSupabase();

    // Fetch all user data in parallel
    const [
      userResult,
      restaurantOrdersResult,
      snackOrdersResult,
      chaletBookingsResult,
      poolTicketsResult,
      reviewsResult,
      supportTicketsResult,
      activityLogsResult
    ] = await Promise.all([
      // User profile
      supabase.from('users')
        .select('id, email, full_name, phone, profile_image_url, created_at, updated_at')
        .eq('id', userId)
        .single(),
      
      // Restaurant orders
      supabase.from('restaurant_orders')
        .select('id, order_number, status, total_amount, payment_status, customer_name, customer_phone, created_at')
        .eq('user_id', userId)
        .order('created_at', { ascending: false }),
      
      // Snack orders
      supabase.from('snack_orders')
        .select('id, order_number, status, total_amount, payment_status, customer_name, customer_phone, created_at')
        .eq('user_id', userId)
        .order('created_at', { ascending: false }),
      
      // Chalet bookings
      supabase.from('chalet_bookings')
        .select('id, confirmation_number, status, check_in_date, check_out_date, total_amount, payment_status, guest_name, guest_email, guest_phone, created_at')
        .eq('user_id', userId)
        .order('created_at', { ascending: false }),
      
      // Pool tickets
      supabase.from('pool_tickets')
        .select('id, ticket_number, status, ticket_date, number_of_guests, total_amount, payment_status, guest_name, guest_email, guest_phone, created_at')
        .eq('user_id', userId)
        .order('created_at', { ascending: false }),
      
      // Reviews
      supabase.from('reviews')
        .select('id, rating, text, service_type, created_at')
        .eq('user_id', userId)
        .order('created_at', { ascending: false }),
      
      // Support tickets
      supabase.from('support_tickets')
        .select('id, subject, status, priority, created_at')
        .eq('user_id', userId)
        .order('created_at', { ascending: false }),
      
      // Activity logs (last 1000)
      supabase.from('audit_logs')
        .select('id, action, resource, resource_id, old_value, new_value, ip_address, user_agent, created_at')
        .eq('user_id', userId)
        .order('created_at', { ascending: false })
        .limit(1000)
    ]);

    if (userResult.error || !userResult.data) {
      res.status(404).json({ success: false, error: 'User not found' });
      return;
    }

    const userData: UserData = {
      profile: userResult.data,
      orders: {
        restaurant_orders: restaurantOrdersResult.data || [],
        snack_orders: snackOrdersResult.data || []
      },
      bookings: {
        chalet_bookings: chaletBookingsResult.data || [],
        pool_tickets: poolTicketsResult.data || []
      },
      reviews: reviewsResult.data || [],
      support_tickets: supportTicketsResult.data || [],
      activity_logs: (activityLogsResult.data || []).map((log: {
        resource?: string;
        resource_id?: string;
        new_value?: Record<string, unknown>;
        old_value?: Record<string, unknown>;
        [key: string]: unknown;
      }) => ({
        ...log,
        entity_type: log.resource,
        entity_id: log.resource_id,
        details: log.new_value || log.old_value
      }))
    };

    // Log the data export
    await logActivity({
      user_id: userId,
      action: 'gdpr_data_export',
      resource: 'user',
      resource_id: userId,
      new_value: { timestamp: new Date().toISOString() },
      ip_address: req.ip,
      user_agent: req.get('user-agent')
    });

    logger.info('GDPR data export completed', { userId, requestId: req.requestId });

    res.json({
      success: true,
      data: userData,
      exportedAt: new Date().toISOString(),
      dataTypes: [
        'profile',
        'restaurant_orders',
        'snack_orders',
        'chalet_bookings',
        'pool_tickets',
        'reviews',
        'support_tickets',
        'activity_logs'
      ]
    });
});

/**
 * DELETE /api/users/me/data
 * GDPR Article 17 - Right to Erasure ("Right to be Forgotten")
 * Deletes all personal data associated with the authenticated user
 * 
 * Note: Some data may be retained for legal/compliance reasons (configurable)
 */
export const deleteUserData = asyncHandler(async (req: Request, res: Response) => {
    const userId = req.user?.userId;
    
    if (!userId) {
      res.status(401).json({ success: false, error: 'Authentication required' });
      return;
    }

    const { confirmDeletion } = req.body as { confirmDeletion?: boolean };
    
    if (!confirmDeletion) {
      res.status(400).json({
        success: false,
        error: 'Deletion must be explicitly confirmed',
        message: 'Set confirmDeletion: true in the request body to proceed with account deletion'
      });
      return;
    }

    const supabase = getSupabase();

    // First, get user email for confirmation
    const { data: user } = await supabase
      .from('users')
      .select('email, full_name')
      .eq('id', userId)
      .single();

    if (!user) {
      res.status(404).json({ success: false, error: 'User not found' });
      return;
    }

    // Log the deletion request before proceeding
    await logActivity({
      user_id: userId,
      action: 'gdpr_deletion_requested',
      resource: 'user',
      resource_id: userId,
      new_value: {
        email: user.email,
        timestamp: new Date().toISOString()
      },
      ip_address: req.ip,
      user_agent: req.get('user-agent')
    });

    // Delete user data in order (to respect foreign key constraints)
    const deletionResults: Record<string, { deleted: number; error?: string }> = {};

    // 1. Delete activity logs
    const { error: activityError, count: activityCount } = await supabase
      .from('audit_logs')
      .delete({ count: 'exact' })
      .eq('user_id', userId);
    deletionResults.activity_logs = { deleted: activityCount || 0, error: activityError?.message };

    // 2. Delete reviews
    const { error: reviewsError, count: reviewsCount } = await supabase
      .from('reviews')
      .delete({ count: 'exact' })
      .eq('user_id', userId);
    deletionResults.reviews = { deleted: reviewsCount || 0, error: reviewsError?.message };

    // 3. Delete support ticket messages first
    const { data: ticketIds } = await supabase
      .from('support_tickets')
      .select('id')
      .eq('user_id', userId);
    
    if (ticketIds && ticketIds.length > 0) {
      const ticketIdList = ticketIds.map(t => t.id);
      await supabase
        .from('support_messages')
        .delete()
        .in('ticket_id', ticketIdList);
    }

    // 4. Delete support tickets
    const { error: ticketsError, count: ticketsCount } = await supabase
      .from('support_tickets')
      .delete({ count: 'exact' })
      .eq('user_id', userId);
    deletionResults.support_tickets = { deleted: ticketsCount || 0, error: ticketsError?.message };

    // 5. Anonymize orders (keep for accounting but remove PII)
    const { error: restOrderError, count: restOrderCount } = await supabase
      .from('restaurant_orders')
      .update({
        customer_name: 'DELETED USER',
        customer_phone: null,
        customer_email: null,
        user_id: null
      })
      .eq('user_id', userId);
    deletionResults.restaurant_orders_anonymized = { deleted: restOrderCount || 0, error: restOrderError?.message };

    const { error: snackOrderError, count: snackOrderCount } = await supabase
      .from('snack_orders')
      .update({
        customer_name: 'DELETED USER',
        customer_phone: null,
        user_id: null
      })
      .eq('user_id', userId);
    deletionResults.snack_orders_anonymized = { deleted: snackOrderCount || 0, error: snackOrderError?.message };

    // 6. Anonymize bookings
    const { error: chaletError, count: chaletCount } = await supabase
      .from('chalet_bookings')
      .update({
        guest_name: 'DELETED USER',
        guest_email: null,
        guest_phone: null,
        user_id: null
      })
      .eq('user_id', userId);
    deletionResults.chalet_bookings_anonymized = { deleted: chaletCount || 0, error: chaletError?.message };

    const { error: poolError, count: poolCount } = await supabase
      .from('pool_tickets')
      .update({
        guest_name: 'DELETED USER',
        guest_email: null,
        guest_phone: null,
        user_id: null
      })
      .eq('user_id', userId);
    deletionResults.pool_tickets_anonymized = { deleted: poolCount || 0, error: poolError?.message };

    // 7. Delete user roles
    await supabase
      .from('user_roles')
      .delete()
      .eq('user_id', userId);

    // 8. Finally, delete the user
    const { error: userError } = await supabase
      .from('users')
      .delete()
      .eq('id', userId);

    if (userError) {
      logger.error('Failed to delete user account', { userId, error: userError });
      res.status(500).json({
        success: false,
        error: 'Failed to complete account deletion',
        partialResults: deletionResults
      });
      return;
    }

    deletionResults.user_account = { deleted: 1 };

    logger.info('GDPR account deletion completed', { 
      userId, 
      email: user.email,
      requestId: req.requestId 
    });

    res.json({
      success: true,
      message: 'Account and personal data have been deleted',
      deletedAt: new Date().toISOString(),
      summary: deletionResults,
      note: 'Financial records have been anonymized for compliance but retained for accounting purposes'
    });
});

/**
 * POST /api/users/me/data/portable
 * GDPR Article 20 - Right to Data Portability
 * Returns user data in a machine-readable format (JSON)
 */
export const getPortableData = asyncHandler(async (req: Request, res: Response) => {
    const userId = req.user?.userId;
    
    if (!userId) {
      res.status(401).json({ success: false, error: 'Authentication required' });
      return;
    }

    // Use the export function internally
    const tempReq = req;
    const tempRes = {
      json: (data: unknown) => {
        // Set headers for file download
        res.setHeader('Content-Type', 'application/json');
        res.setHeader('Content-Disposition', `attachment; filename="user-data-${userId}-${Date.now()}.json"`);
        res.json(data);
      },
      status: (code: number) => ({
        json: (data: unknown) => res.status(code).json(data)
      })
    };

    // Log the portability request
    await logActivity({
      user_id: userId,
      action: 'gdpr_data_portability',
      resource: 'user',
      resource_id: userId,
      new_value: { timestamp: new Date().toISOString(), format: 'json' },
      ip_address: req.ip,
      user_agent: req.get('user-agent')
    });

    await exportUserData(tempReq, tempRes as unknown as Response, ((err: unknown) => { if (err) throw err; }) as any);
});

/**
 * User Controller
 * 
 * Handles user profile management and admin user operations.
 */

import { Request, Response, NextFunction } from 'express';
import { asyncHandler } from '../../middleware/async-handler.js';
import { getSupabase } from '../../database/connection.js';
import { logActivity } from '../../utils/activityLogger.js';
import { logger } from '../../utils/logger.js';
import { z } from 'zod';

// Validation schemas
const updateProfileSchema = z.object({
  full_name: z.string().min(2).max(100).optional(),
  phone: z.preprocess(
    (val) => (val === '' ? null : val),
    z.string().regex(/^\+?[0-9\s\-()]{7,20}$/).nullable()
  ).optional(),
  preferred_language: z.enum(['en', 'ar', 'fr', 'de', 'it']).optional()
});

const updateUserRolesSchema = z.object({
  roleIds: z.array(z.string().uuid()).min(1, 'At least one role is required')
});

interface UserWithRoles {
  id: string;
  email: string;
  full_name: string;
  phone: string | null;
  profile_image_url: string | null;
  preferred_language: string;
  is_active: boolean;
  created_at: string;
  updated_at: string | null;
  roles: string[];
}

/**
 * GET /api/users/profile
 * Get current user's profile
 */
export const getProfile = asyncHandler(async (req: Request, res: Response) => {
    const userId = req.user?.userId;
    if (!userId) {
      res.status(401).json({ success: false, error: 'Authentication required' });
      return;
    }

    const supabase = getSupabase();
    
    const { data: user, error } = await supabase
      .from('users')
      .select(`
        id, email, full_name, phone, profile_image_url, preferred_language, 
        is_active, created_at, updated_at,
        user_roles!left(role:roles(name))
      `)
      .eq('id', userId)
      .single();

    if (error || !user) {
      res.status(404).json({ success: false, error: 'User not found' });
      return;
    }

    // Extract role names - Supabase joins return arrays
    interface RoleJoinData { role?: { name: string }[] | { name: string } | null }
    const userData = user as typeof user & { user_roles?: RoleJoinData[] };
    const roles = userData.user_roles?.map(ur => {
      const role = ur.role;
      if (!role) return undefined;
      if (Array.isArray(role)) return role[0]?.name;
      return (role as { name: string }).name;
    }).filter(Boolean) as string[] || [];

    res.json({
      success: true,
      data: {
        id: user.id,
        email: user.email,
        full_name: user.full_name,
        phone: user.phone,
        profile_image_url: user.profile_image_url,
        preferred_language: user.preferred_language,
        is_active: user.is_active,
        created_at: user.created_at,
        updated_at: user.updated_at,
        roles
      }
    });
});

/**
 * PUT /api/users/profile
 * Update current user's profile
 */
export const updateProfile = asyncHandler(async (req: Request, res: Response) => {
    const userId = req.user?.userId;
    if (!userId) {
      res.status(401).json({ success: false, error: 'Authentication required' });
      return;
    }

    const validation = updateProfileSchema.safeParse(req.body);
    if (!validation.success) {
      res.status(400).json({ 
        success: false, 
        error: 'Validation failed',
        details: validation.error.errors 
      });
      return;
    }

    const updateData = validation.data;
    
    if (Object.keys(updateData).length === 0) {
      res.status(400).json({ success: false, error: 'No fields to update' });
      return;
    }

    const supabase = getSupabase();
    
    const { data: updated, error } = await supabase
      .from('users')
      .update({
        ...updateData,
        updated_at: new Date().toISOString()
      })
      .eq('id', userId)
      .select('id, email, full_name, phone, profile_image_url, preferred_language')
      .single();

    if (error) {
      logger.error('Error updating profile:', error);
      res.status(500).json({ success: false, error: 'Failed to update profile' });
      return;
    }

    await logActivity({
      user_id: userId,
      action: 'UPDATE_PROFILE',
      resource: 'users',
      entity_id: userId,
      ip_address: req.ip,
      user_agent: req.get('user-agent'),
      new_value: updateData
    });

    res.json({ success: true, data: updated, message: 'Profile updated successfully' });
});

/**
 * GET /api/users (Admin only)
 * List all users with pagination
 */
export const listUsers = asyncHandler(async (req: Request, res: Response) => {
    const supabase = getSupabase();
    
    const page = parseInt(req.query.page as string) || 1;
    const limit = Math.min(parseInt(req.query.limit as string) || 20, 100);
    const search = req.query.search as string | undefined;
    const offset = (page - 1) * limit;

    let query = supabase
      .from('users')
      .select(`
        id, email, full_name, phone, profile_image_url, is_active, created_at, updated_at,
        user_roles!left(role:roles(id, name))
      `, { count: 'exact' });

    if (search) {
      // Sanitize search input to prevent SQL injection
      const sanitizedSearch = String(search)
        .replace(/[%_\\]/g, '\\$&')  // Escape SQL wildcards
        .replace(/['";]/g, '')           // Remove quotes and semicolons
        .slice(0, 100);                   // Limit length
      query = query.or(`email.ilike.%${sanitizedSearch}%,full_name.ilike.%${sanitizedSearch}%`);
    }

    const { data: users, error, count } = await query
      .order('created_at', { ascending: false })
      .range(offset, offset + limit - 1);

    if (error) {
      logger.error('Error listing users:', error);
      res.status(500).json({ success: false, error: 'Failed to list users' });
      return;
    }

    // Process users to extract roles - Supabase joins return arrays
    interface RoleJoinData { role?: { id: string; name: string }[] | { id: string; name: string } | null }
    const processedUsers = ((users || []) as Array<typeof users[0] & { user_roles?: RoleJoinData[] }>).map(user => ({
      id: user.id,
      email: user.email,
      full_name: user.full_name,
      phone: user.phone,
      profile_image_url: user.profile_image_url,
      is_active: user.is_active,
      created_at: user.created_at,
      updated_at: user.updated_at,
      roles: user.user_roles?.map(ur => {
        const role = ur.role;
        if (!role) return undefined;
        if (Array.isArray(role)) return role[0]?.name;
        return (role as { name: string }).name;
      }).filter(Boolean) || []
    }));

    res.json({
      success: true,
      data: processedUsers,
      pagination: {
        page,
        limit,
        total: count || 0,
        totalPages: Math.ceil((count || 0) / limit)
      }
    });
});

/**
 * GET /api/users/:id (Admin only)
 * Get user by ID
 */
export const getUserById = asyncHandler(async (req: Request, res: Response) => {
    const { id } = req.params;
    
    // Validate UUID
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    if (!uuidRegex.test(id)) {
      res.status(400).json({ success: false, error: 'Invalid user ID format' });
      return;
    }

    const supabase = getSupabase();
    
    const { data: user, error } = await supabase
      .from('users')
      .select(`
        id, email, full_name, phone, profile_image_url, preferred_language,
        is_active, created_at, updated_at, last_login_at,
        user_roles!left(role:roles(id, name, display_name))
      `)
      .eq('id', id)
      .single();

    if (error || !user) {
      res.status(404).json({ success: false, error: 'User not found' });
      return;
    }

    // Extract roles - Supabase joins return arrays
    interface RoleJoinData { role?: { id: string; name: string; display_name: string }[] | { id: string; name: string; display_name: string } | null }
    const userData = user as typeof user & { user_roles?: RoleJoinData[] };
    const roles = userData.user_roles
      ?.map(ur => {
        const role = Array.isArray(ur.role) ? ur.role[0] : ur.role;
        return role ? { id: role.id, name: role.name, displayName: role.display_name } : null;
      })
      .filter(Boolean) || [];

    res.json({
      success: true,
      data: {
        id: user.id,
        email: user.email,
        full_name: user.full_name,
        phone: user.phone,
        profile_image_url: user.profile_image_url,
        preferred_language: user.preferred_language,
        is_active: user.is_active,
        created_at: user.created_at,
        updated_at: user.updated_at,
        last_login_at: user.last_login_at,
        roles
      }
    });
});

/**
 * PUT /api/users/:id/roles (Super Admin only)
 * Update user roles
 */
export const updateUserRoles = asyncHandler(async (req: Request, res: Response) => {
    const { id } = req.params;
    
    // Validate UUID
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    if (!uuidRegex.test(id)) {
      res.status(400).json({ success: false, error: 'Invalid user ID format' });
      return;
    }

    const validation = updateUserRolesSchema.safeParse(req.body);
    if (!validation.success) {
      res.status(400).json({ 
        success: false, 
        error: 'Validation failed',
        details: validation.error.errors 
      });
      return;
    }

    const { roleIds } = validation.data;
    const supabase = getSupabase();

    // Check user exists
    const { data: user, error: userError } = await supabase
      .from('users')
      .select('id, email')
      .eq('id', id)
      .single();

    if (userError || !user) {
      res.status(404).json({ success: false, error: 'User not found' });
      return;
    }

    // Verify all role IDs are valid
    const { data: roles, error: rolesError } = await supabase
      .from('roles')
      .select('id, name')
      .in('id', roleIds);

    if (rolesError || !roles || roles.length !== roleIds.length) {
      res.status(400).json({ success: false, error: 'One or more invalid role IDs' });
      return;
    }

    // Get old roles for activity log
    const { data: oldRoles } = await supabase
      .from('user_roles')
      .select('role_id, roles(name)')
      .eq('user_id', id);

    // Delete existing roles
    await supabase
      .from('user_roles')
      .delete()
      .eq('user_id', id);

    // Insert new roles
    const roleAssignments = roleIds.map(roleId => ({
      user_id: id,
      role_id: roleId
    }));

    const { error: insertError } = await supabase
      .from('user_roles')
      .insert(roleAssignments);

    if (insertError) {
      logger.error('Error updating user roles:', insertError);
      res.status(500).json({ success: false, error: 'Failed to update roles' });
      return;
    }

    await logActivity({
      user_id: req.user!.userId,
      action: 'UPDATE_USER_ROLES',
      resource: 'users',
      entity_id: id,
      ip_address: req.ip,
      user_agent: req.get('user-agent'),
      old_value: { roles: oldRoles?.map(r => {
        const role = Array.isArray(r.roles) ? r.roles[0] : r.roles;
        return (role as { name?: string } | null)?.name;
      }) },
      new_value: { roles: roles.map(r => r.name) }
    });

    res.json({ 
      success: true, 
      message: 'Roles updated successfully',
      data: { roles: roles.map(r => r.name) }
    });
});

