  refund_policy?: string;
  refund_policy_disclosure?: string;
  uncategorized_text?: string;
  access_activity_log?: string;
  submitted_at?: string;
}

class ChargebackService {
  /**
   * Handle incoming Stripe dispute webhook
   */
  async handleDisputeCreated(dispute: Stripe.Dispute): Promise<Chargeback> {
    logger.info(`[ChargebackService] New dispute created: ${dispute.id}`);

    // Find the original payment
    const { data: payment, error: paymentError } = await supabase
      .from('payment_ledger')
      .select('*')
      .eq('stripe_payment_intent_id', dispute.payment_intent)
      .single();

    if (paymentError || !payment) {
      logger.error(`[ChargebackService] Payment not found for dispute: ${dispute.id}`);
      throw new Error(`Payment not found for charge ${dispute.charge}`);
    }

    // Create chargeback record
    const chargebackData = {
      payment_id: payment.id,
      stripe_dispute_id: dispute.id,
      stripe_charge_id: dispute.charge as string,
      amount: dispute.amount / 100, // Convert from cents
      currency: dispute.currency.toUpperCase(),
      reason: dispute.reason,
      status: 'needs_response' as ChargebackStatus,
      due_date: new Date((dispute.evidence_details.due_by ?? 0) * 1000).toISOString(),
      evidence_submitted: null as string | null,
      outcome: null as string | null,
    };

    const { data: chargeback, error: insertError } = await supabase
      .from('chargebacks')
      .insert(chargebackData)
      .select()
      .single();

    if (insertError) {
      logger.error('[ChargebackService] Failed to create chargeback:', insertError);
      throw insertError;
    }

    // Send alert to admin
    await this.alertAdmin(chargeback, payment);

    // Log activity
    await activityLogger.log({
      action: 'chargeback_created',
      entity_type: 'chargeback',
      entity_id: chargeback.id,
      details: {
        dispute_id: dispute.id,
        amount: chargebackData.amount,
        reason: dispute.reason,
      },
    });

    return chargeback;
  }

  /**
   * Handle dispute updated webhook
   */
  async handleDisputeUpdated(dispute: Stripe.Dispute): Promise<Chargeback | null> {
    logger.info(`[ChargebackService] Dispute updated: ${dispute.id}`);

    // Find chargeback record
    const { data: chargeback, error } = await supabase
      .from('chargebacks')
      .select('*')
      .eq('stripe_dispute_id', dispute.id)
      .single();

    if (error || !chargeback) {
      logger.error(`[ChargebackService] Chargeback not found: ${dispute.id}`);
      return null;
    }

    // Map Stripe status to our status
    let status: ChargebackStatus = chargeback.status;
    let outcome: ChargebackOutcome | null = null;

    switch (dispute.status as string) {
      case 'needs_response':
        status = 'needs_response';
        break;
      case 'under_review':
        status = 'under_review';
        break;
      case 'charge_refunded':
        status = 'charge_refunded' as any;
        outcome = 'refunded';
        break;
      case 'won':
        status = 'won';
        outcome = 'won';
        break;
      case 'lost':
        status = 'lost';
        outcome = 'lost';
        break;
    }

    // Update record
    const { data: updated, error: updateError } = await supabase
      .from('chargebacks')
      .update({
        status,
        outcome,
        resolved_at: outcome ? new Date().toISOString() : null,
        updated_at: new Date().toISOString(),
      })
      .eq('id', chargeback.id)
      .select()
      .single();

    if (updateError) {
      logger.error('[ChargebackService] Failed to update chargeback:', updateError);
      throw updateError;
    }

    // Log activity
    await activityLogger.log({
      action: 'chargeback_status_updated',
      entity_type: 'chargeback',
      entity_id: chargeback.id,
      details: {
        old_status: chargeback.status,
        new_status: status,
        outcome,
      },
    });

    // Notify admin if resolved
    if (outcome) {
      await this.notifyOutcome(updated);
    }

    return updated;
  }

  /**
   * Submit evidence for a chargeback
   */
  async submitEvidence(
    chargebackId: string,
    evidence: ChargebackEvidence,
    adminUserId: string
  ): Promise<Chargeback> {
    // Get chargeback
    const { data: chargeback, error } = await supabase
      .from('chargebacks')
      .select('*')
      .eq('id', chargebackId)
      .single();

    if (error || !chargeback) {
      throw new Error('Chargeback not found');
    }

    if (chargeback.status !== 'needs_response') {
      throw new Error('Cannot submit evidence for this dispute');
    }

    // Prepare evidence for Stripe
    const stripeEvidence: Stripe.DisputeUpdateParams.Evidence = {
      customer_name: evidence.customer_name,
      customer_email_address: evidence.customer_email,
      billing_address: evidence.billing_address,
      product_description: evidence.product_description,
      service_date: evidence.service_date,
      receipt: evidence.receipt,
      customer_signature: evidence.customer_signature,
      customer_communication: evidence.customer_communication,
      refund_policy: evidence.refund_policy,
      refund_policy_disclosure: evidence.refund_policy_disclosure,
      uncategorized_text: evidence.uncategorized_text,
      access_activity_log: evidence.access_activity_log,
    };

    // Submit to Stripe
    try {
      await stripe.disputes.update(chargeback.stripe_dispute_id, {
        evidence: stripeEvidence,
        submit: true, // This submits the evidence
      });
    } catch (stripeError: any) {
      logger.error('[ChargebackService] Failed to submit evidence to Stripe:', stripeError);
      throw new Error(`Stripe error: ${stripeError.message}`);
    }

    // Update our record
    const { data: updated, error: updateError } = await supabase
      .from('chargebacks')
      .update({
        status: 'under_review',
        evidence_submitted: {
          ...evidence,
          submitted_at: new Date().toISOString(),
        },
        updated_at: new Date().toISOString(),
      })
      .eq('id', chargebackId)
      .select()
      .single();

    if (updateError) {
      throw updateError;
    }

    // Log activity
    await activityLogger.log({
      action: 'chargeback_evidence_submitted',
      entity_type: 'chargeback',
      entity_id: chargebackId,
      user_id: adminUserId,
      details: {
        evidence_fields: Object.keys(evidence),
      },
    });

    return updated;
  }

  /**
   * Get chargeback by ID
   */
  async getById(chargebackId: string): Promise<Chargeback | null> {
    const { data, error } = await supabase
      .from('chargebacks')
      .select(`
        *,
        payment:payment_ledger(
          id,
          user_id,
          amount,
          description,
          stripe_payment_intent_id
        )
      `)
      .eq('id', chargebackId)
      .single();

    if (error) {
      return null;
    }

    return data;
  }

  /**
   * List all chargebacks with filters
   */
  async list(filters: {
    status?: ChargebackStatus;
    from_date?: string;
    to_date?: string;
    limit?: number;
    offset?: number;
  }): Promise<{ data: Chargeback[]; total: number }> {
    let query = supabase
      .from('chargebacks')
      .select(`
        *,
        payment:payment_ledger(
          id,
          user_id,
          amount,
          description
        )
      `, { count: 'exact' });

    if (filters.status) {
      query = query.eq('status', filters.status);
    }

    if (filters.from_date) {
      query = query.gte('created_at', filters.from_date);
    }

    if (filters.to_date) {
      query = query.lte('created_at', filters.to_date);
    }

    query = query
      .order('created_at', { ascending: false })
      .range(
        filters.offset || 0,
        (filters.offset || 0) + (filters.limit || 20) - 1
      );

    const { data, count, error } = await query;

    if (error) {
      throw error;
    }

    return {
      data: data || [],
      total: count || 0,
    };
  }

  /**
   * Get chargeback statistics
   */
  async getStats(period: 'month' | 'quarter' | 'year' = 'month'): Promise<{
    total_count: number;
    total_amount: number;
    needs_response: number;
    under_review: number;
    won: number;
    lost: number;
    win_rate: number;
    average_amount: number;
  }> {
    const now = new Date();
    let fromDate: Date;

    switch (period) {
      case 'month':
        fromDate = new Date(now.getFullYear(), now.getMonth(), 1);
        break;
      case 'quarter':
        fromDate = new Date(now.getFullYear(), Math.floor(now.getMonth() / 3) * 3, 1);
        break;
      case 'year':
        fromDate = new Date(now.getFullYear(), 0, 1);
        break;
    }

    const { data, error } = await supabase
      .from('chargebacks')
      .select('status, outcome, amount')
      .gte('created_at', fromDate.toISOString());

    if (error) {
      throw error;
    }

    interface ChargebackRecord {
      amount?: number;
      status?: string;
      outcome?: string;
    }

    const stats = {
      total_count: data.length,
      total_amount: data.reduce((sum: number, c: ChargebackRecord) => sum + (c.amount || 0), 0),
      needs_response: data.filter((c: ChargebackRecord) => c.status === 'needs_response').length,
      under_review: data.filter((c: ChargebackRecord) => c.status === 'under_review').length,
      won: data.filter((c: ChargebackRecord) => c.outcome === 'won').length,
      lost: data.filter((c: ChargebackRecord) => c.outcome === 'lost').length,
      win_rate: 0,
      average_amount: 0,
    };

    const resolved = stats.won + stats.lost;
    if (resolved > 0) {
      stats.win_rate = (stats.won / resolved) * 100;
    }

    if (stats.total_count > 0) {
      stats.average_amount = stats.total_amount / stats.total_count;
    }

    return stats;
  }

  /**
   * Alert admin about new chargeback
   */
  private async alertAdmin(chargeback: Chargeback, payment: any): Promise<void> {
    const dueDate = new Date(chargeback.due_date);
    const daysRemaining = Math.ceil(
      (dueDate.getTime() - Date.now()) / (1000 * 60 * 60 * 24)
    );

    await emailService.sendEmail({
      to: process.env.ADMIN_EMAIL || 'admin@v2resort.com',
      subject: `[URGENT] New Chargeback Dispute - ${chargeback.amount} ${chargeback.currency}`,
      template: 'admin-chargeback-alert',
      data: {
        chargeback_id: chargeback.id,
        dispute_id: chargeback.stripe_dispute_id,
        amount: chargeback.amount,
        currency: chargeback.currency,
        reason: chargeback.reason,
        due_date: dueDate.toLocaleDateString(),
        days_remaining: daysRemaining,
        payment_description: payment.description,
        admin_url: `${process.env.FRONTEND_URL}/admin/payments/chargebacks/${chargeback.id}`,
      },
    });
  }

  /**
   * Notify admin of chargeback outcome
   */
  private async notifyOutcome(chargeback: Chargeback): Promise<void> {
    const subject = chargeback.outcome === 'won'
      ? `[Resolved - WON] Chargeback ${chargeback.id}`
      : `[Resolved - LOST] Chargeback ${chargeback.id}`;

    await emailService.sendEmail({
      to: process.env.ADMIN_EMAIL || 'admin@v2resort.com',
      subject,
      template: 'admin-chargeback-outcome',
      data: {
        chargeback_id: chargeback.id,
        outcome: chargeback.outcome,
        amount: chargeback.amount,
        currency: chargeback.currency,
        reason: chargeback.reason,
      },
    });
  }

  /**
   * Generate evidence template based on reason
   */
  getEvidenceTemplate(reason: string): Partial<ChargebackEvidence> {
    const templates: Record<string, Partial<ChargebackEvidence>> = {
      fraudulent: {
        uncategorized_text: 'The customer authorized this transaction...',
        access_activity_log: 'Customer activity log showing legitimate access...',
      },
      duplicate: {
        product_description: 'This was not a duplicate charge...',
        uncategorized_text: 'Transaction details showing unique purchase...',
      },
      subscription_canceled: {
        refund_policy: 'Our cancellation policy states...',
        refund_policy_disclosure: 'Policy was disclosed at time of purchase...',
      },
      product_not_received: {
        service_date: 'Service was provided on...',
        customer_communication: 'Customer acknowledged receipt via...',
      },
      product_unacceptable: {
        product_description: 'The service/product met all stated specifications...',
        customer_communication: 'We offered resolution options...',
      },
      credit_not_processed: {
        refund_policy: 'Our refund policy states...',
        customer_communication: 'Refund was processed on...',
      },
      general: {
        uncategorized_text: 'This transaction was legitimate...',
      },
    };

    return templates[reason] || templates['general'];
  }
}

export const chargebackService = new ChargebackService();

/**
 * V2 Resort - Multi-Currency Support Service
 * Handles currency conversion and management
 */

import { supabase } from "../lib/supabase.js";
import Stripe from 'stripe';
import { logger } from "../utils/logger.js";

// Initialize Stripe
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, {
  apiVersion: '2023-10-16',
});

export interface Currency {
  code: string;
  symbol: string;
  name: string;
  name_ar?: string;
  name_fr?: string;
  exchange_rate: number;
  decimal_places: number;
  is_active: boolean;
  is_default: boolean;
  last_updated: string;
}

export interface PriceConversion {
  original_amount: number;
  original_currency: string;
  converted_amount: number;
  target_currency: string;
  exchange_rate: number;
  converted_at: string;
}

// Supported currencies with their properties
const SUPPORTED_CURRENCIES: Record<string, Omit<Currency, 'exchange_rate' | 'is_active' | 'is_default' | 'last_updated'>> = {
  EUR: { code: 'EUR', symbol: '€', name: 'Euro', name_ar: 'يورو', name_fr: 'Euro', decimal_places: 2 },
  USD: { code: 'USD', symbol: '$', name: 'US Dollar', name_ar: 'دولار أمريكي', name_fr: 'Dollar américain', decimal_places: 2 },
  GBP: { code: 'GBP', symbol: '£', name: 'British Pound', name_ar: 'جنيه إسترليني', name_fr: 'Livre sterling', decimal_places: 2 },
  AED: { code: 'AED', symbol: 'د.إ', name: 'UAE Dirham', name_ar: 'درهم إماراتي', name_fr: 'Dirham des EAU', decimal_places: 2 },
  SAR: { code: 'SAR', symbol: '﷼', name: 'Saudi Riyal', name_ar: 'ريال سعودي', name_fr: 'Riyal saoudien', decimal_places: 2 },
  QAR: { code: 'QAR', symbol: 'ر.ق', name: 'Qatari Riyal', name_ar: 'ريال قطري', name_fr: 'Riyal qatari', decimal_places: 2 },
  KWD: { code: 'KWD', symbol: 'د.ك', name: 'Kuwaiti Dinar', name_ar: 'دينار كويتي', name_fr: 'Dinar koweïtien', decimal_places: 3 },
  CHF: { code: 'CHF', symbol: 'CHF', name: 'Swiss Franc', name_ar: 'فرنك سويسري', name_fr: 'Franc suisse', decimal_places: 2 },
};

// Cache for exchange rates
let ratesCache: Map<string, { rate: number; timestamp: number }> = new Map();
const CACHE_TTL = 60 * 60 * 1000; // 1 hour

class CurrencyService {
  private defaultCurrency = 'EUR';

  /**
   * Get all active currencies
   */
  async getActiveCurrencies(): Promise<Currency[]> {
    const { data, error } = await supabase
      .from('currencies')
      .select('*')
      .eq('is_active', true)
      .order('code');

    if (error) {
      throw error;
    }

    return data || [];
  }

  /**
   * Get currency by code
   */
  async getCurrency(code: string): Promise<Currency | null> {
    const { data, error } = await supabase
      .from('currencies')
      .select('*')
      .eq('code', code.toUpperCase())
      .single();

    if (error) {
      return null;
    }

    return data;
  }

  /**
   * Get default currency
   */
  async getDefaultCurrency(): Promise<Currency> {
    const { data: settings } = await supabase
      .from('site_settings')
      .select('value')
      .eq('key', 'default_currency')
      .single();

    const defaultCode = settings?.value || this.defaultCurrency;

    const currency = await this.getCurrency(defaultCode);
    if (!currency) {
      throw new Error(`Default currency ${defaultCode} not found`);
    }

    return currency;
  }

  /**
   * Convert amount between currencies
   */
  async convert(
    amount: number,
    fromCurrency: string,
    toCurrency: string
  ): Promise<PriceConversion> {
    fromCurrency = fromCurrency.toUpperCase();
    toCurrency = toCurrency.toUpperCase();

    if (fromCurrency === toCurrency) {
      return {
        original_amount: amount,
        original_currency: fromCurrency,
        converted_amount: amount,
        target_currency: toCurrency,
        exchange_rate: 1,
        converted_at: new Date().toISOString(),
      };
    }

    // Get exchange rates relative to default currency
    const fromRate = await this.getExchangeRate(fromCurrency);
    const toRate = await this.getExchangeRate(toCurrency);

    // Convert: amount in from -> default -> to
    const amountInDefault = amount / fromRate;
    const convertedAmount = amountInDefault * toRate;
    const exchangeRate = toRate / fromRate;

    // Round to appropriate decimal places
    const toCurrencyInfo = SUPPORTED_CURRENCIES[toCurrency];
    const decimalPlaces = toCurrencyInfo?.decimal_places ?? 2;
    const roundedAmount = Math.round(convertedAmount * Math.pow(10, decimalPlaces)) / Math.pow(10, decimalPlaces);

    return {
      original_amount: amount,
      original_currency: fromCurrency,
      converted_amount: roundedAmount,
      target_currency: toCurrency,
      exchange_rate: exchangeRate,
      converted_at: new Date().toISOString(),
    };
  }

  /**
   * Get exchange rate for a currency (relative to default)
   */
  async getExchangeRate(currencyCode: string): Promise<number> {
    currencyCode = currencyCode.toUpperCase();

    // Check cache first
    const cached = ratesCache.get(currencyCode);
    if (cached && Date.now() - cached.timestamp < CACHE_TTL) {
      return cached.rate;
    }

    // Get from database
    const { data, error } = await supabase
      .from('currencies')
      .select('exchange_rate')
      .eq('code', currencyCode)
      .single();

    if (error || !data) {
      throw new Error(`Exchange rate not found for ${currencyCode}`);
    }

    // Update cache
    ratesCache.set(currencyCode, {
      rate: data.exchange_rate,
      timestamp: Date.now(),
    });

    return data.exchange_rate;
  }

  /**
   * Update exchange rate for a currency
   */
  async updateExchangeRate(
    currencyCode: string,
    rate: number,
    adminUserId?: string
  ): Promise<Currency> {
    currencyCode = currencyCode.toUpperCase();

    const { data, error } = await supabase
      .from('currencies')
      .update({
        exchange_rate: rate,
        last_updated: new Date().toISOString(),
      })
      .eq('code', currencyCode)
      .select()
      .single();

    if (error) {
      throw error;
    }

    // Clear cache
    ratesCache.delete(currencyCode);

    return data;
  }

  /**
   * Update all exchange rates from external API
   */
  async updateAllRatesFromAPI(): Promise<void> {
    const API_KEY = process.env.EXCHANGE_RATE_API_KEY;
    if (!API_KEY) {
      console.warn('[CurrencyService] No exchange rate API key configured');
      return;
    }

    try {
      const response = await fetch(
        `https://api.exchangerate-api.com/v4/latest/${this.defaultCurrency}`,
        { headers: { 'Authorization': `Bearer ${API_KEY}` } }
      );

      if (!response.ok) {
        throw new Error(`API error: ${response.status}`);
      }

      const data = await response.json() as any;
      const rates = data.rates as Record<string, number>;

      // Update each supported currency
      for (const code of Object.keys(SUPPORTED_CURRENCIES)) {
        if (rates[code]) {
          await this.updateExchangeRate(code, rates[code]);
        }
      }

      logger.info('[CurrencyService] Exchange rates updated successfully');
    } catch (error) {
      logger.error('[CurrencyService] Failed to update exchange rates:', error);
      throw error;
    }
  }

  /**
   * Format amount for display
   */
  formatAmount(amount: number, currencyCode: string, locale?: string): string {
    currencyCode = currencyCode.toUpperCase();
    locale = locale || 'en-US';

    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency: currencyCode,
    }).format(amount);
  }

  /**
   * Get currency for Stripe (lowercase)
   */
  getStripeCurrency(currencyCode: string): string {
    return currencyCode.toLowerCase();
  }

  /**
   * Convert amount to Stripe format (smallest currency unit)
   */
  toStripeAmount(amount: number, currencyCode: string): number {
    const currency = SUPPORTED_CURRENCIES[currencyCode.toUpperCase()];
    const decimalPlaces = currency?.decimal_places ?? 2;
    
    // Stripe expects amounts in smallest unit (cents for most currencies)
    // KWD has 3 decimal places, so multiply by 1000
    return Math.round(amount * Math.pow(10, decimalPlaces));
  }

  /**
   * Convert Stripe amount to regular amount
   */
  fromStripeAmount(stripeAmount: number, currencyCode: string): number {
    const currency = SUPPORTED_CURRENCIES[currencyCode.toUpperCase()];
    const decimalPlaces = currency?.decimal_places ?? 2;
    
    return stripeAmount / Math.pow(10, decimalPlaces);
  }

  /**
   * Check if currency is supported by Stripe
   */
  isStripeSupportedCurrency(currencyCode: string): boolean {
    // Stripe supports all major currencies
    const stripeSupported = [
      'EUR', 'USD', 'GBP', 'AED', 'SAR', 'QAR', 'KWD', 'CHF',
      'AUD', 'CAD', 'JPY', 'SGD', 'HKD', 'INR', 'BRL', 'MXN'
    ];
    return stripeSupported.includes(currencyCode.toUpperCase());
  }

  /**
   * Create multi-currency price for display
   */
  async getMultiCurrencyPrices(
    baseAmount: number,
    baseCurrency: string,
    targetCurrencies?: string[]
  ): Promise<Record<string, { amount: number; formatted: string }>> {
    const currencies = targetCurrencies || Object.keys(SUPPORTED_CURRENCIES);
    const prices: Record<string, { amount: number; formatted: string }> = {};

    for (const currency of currencies) {
      const conversion = await this.convert(baseAmount, baseCurrency, currency);
      prices[currency] = {
        amount: conversion.converted_amount,
        formatted: this.formatAmount(conversion.converted_amount, currency),
      };
    }

    return prices;
  }

  /**
   * Initialize default currencies in database
   */
  async initializeCurrencies(): Promise<void> {
    const defaultRates: Record<string, number> = {
      EUR: 1,
      USD: 1.08,
      GBP: 0.86,
      AED: 3.97,
      SAR: 4.05,
      QAR: 3.93,
      KWD: 0.33,
      CHF: 0.95,
    };

    for (const [code, info] of Object.entries(SUPPORTED_CURRENCIES)) {
      const { data: existing } = await supabase
        .from('currencies')
        .select('code')
        .eq('code', code)
        .single();

      if (!existing) {
        await supabase.from('currencies').insert({
          ...info,
          exchange_rate: defaultRates[code] || 1,
          is_active: true,
          is_default: code === 'EUR',
          last_updated: new Date().toISOString(),
        });
      }
    }

    logger.info('[CurrencyService] Currencies initialized');
  }
}

export const currencyService = new CurrencyService();

/**
 * V2 Resort - Email Analytics Service
 * Tracks email metrics and provides insights
 */

import { supabase } from "../lib/supabase.js";

export interface EmailMetrics {
  sent: number;
  delivered: number;
  opened: number;
  clicked: number;
  bounced: number;
  complained: number;
  unsubscribed: number;
  deliveryRate: number;
  openRate: number;
  clickRate: number;
  bounceRate: number;
  complaintRate: number;
  unsubscribeRate: number;
}

export interface EmailEvent {
  id?: string;
  message_id: string;
  event_type: 'sent' | 'delivered' | 'opened' | 'clicked' | 'bounced' | 'complained' | 'unsubscribed' | 'dropped';
  timestamp: string;
  email?: string;
  user_id?: string;
  template_id?: string;
  campaign_id?: string;
  link_url?: string;
  user_agent?: string;
