  subject_line: string;
  sent_at: string;
  unique_opens: number;
  unique_clicks: number;
  total_revenue?: number;
  conversions?: number;
}

export interface TemplatePerformance {
  template_id: string;
  template_name: string;
  total_sent: number;
  metrics: EmailMetrics;
  average_open_time?: number; // seconds after delivery
  top_clicked_links: Array<{ url: string; clicks: number }>;
}

class EmailAnalyticsService {
  /**
   * Record an email event
   */
  async recordEvent(event: Omit<EmailEvent, 'id'>): Promise<void> {
    const { error } = await supabase.from('email_events').insert({
      ...event,
      timestamp: event.timestamp || new Date().toISOString(),
    });

    if (error) {
      console.error('[EmailAnalytics] Failed to record event:', error);
    }

    // Update email record with latest status
    if (['delivered', 'opened', 'clicked', 'bounced', 'complained'].includes(event.event_type)) {
      await supabase
        .from('emails')
        .update({
          [`${event.event_type}_at`]: event.timestamp || new Date().toISOString(),
          status: event.event_type,
        })
        .eq('message_id', event.message_id);
    }
  }

  /**
   * Process SendGrid webhook events
   */
  async processSendGridWebhook(events: any[]): Promise<void> {
    for (const event of events) {
      const mappedEvent: Omit<EmailEvent, 'id'> = {
        message_id: event.sg_message_id?.split('.')[0] || event['smtp-id'],
        event_type: this.mapSendGridEventType(event.event),
        timestamp: new Date(event.timestamp * 1000).toISOString(),
        email: event.email,
        metadata: {
          sg_event_id: event.sg_event_id,
          category: event.category,
          response: event.response,
          reason: event.reason,
        },
      };

      if (event.url) {
        mappedEvent.link_url = event.url;
      }

      if (event.useragent) {
        mappedEvent.user_agent = event.useragent;
      }

      if (event.ip) {
        mappedEvent.ip_address = event.ip;
      }

      await this.recordEvent(mappedEvent);
    }
  }

  /**
   * Map SendGrid event types to our types
   */
  private mapSendGridEventType(sgEvent: string): EmailEvent['event_type'] {
    const mapping: Record<string, EmailEvent['event_type']> = {
      processed: 'sent',
      delivered: 'delivered',
      open: 'opened',
      click: 'clicked',
      bounce: 'bounced',
      spamreport: 'complained',
      unsubscribe: 'unsubscribed',
      dropped: 'dropped',
      deferred: 'sent', // Treat deferred as still in-flight
    };

    return mapping[sgEvent] || 'sent';
  }

  /**
   * Get overall email metrics for a period
   */
  async getMetrics(
    period: 'day' | 'week' | 'month' | 'year',
    startDate?: string
  ): Promise<EmailMetrics> {
    const periodMs = {
      day: 24 * 60 * 60 * 1000,
      week: 7 * 24 * 60 * 60 * 1000,
      month: 30 * 24 * 60 * 60 * 1000,
      year: 365 * 24 * 60 * 60 * 1000,
    };

    const fromDate = startDate || new Date(Date.now() - periodMs[period]).toISOString();

    const { data: events, error } = await supabase
      .from('email_events')
      .select('event_type')
      .gte('timestamp', fromDate);

    if (error) {
      throw error;
    }

    return this.calculateMetrics(events || []);
  }

  /**
   * Calculate metrics from events
   */
  private calculateMetrics(events: Array<{ event_type: string }>): EmailMetrics {
    const counts = {
      sent: 0,
      delivered: 0,
      opened: 0,
      clicked: 0,
      bounced: 0,
      complained: 0,
      unsubscribed: 0,
    };

    for (const event of events) {
      if (event.event_type in counts) {
        counts[event.event_type as keyof typeof counts]++;
      }
    }

    const sent = counts.sent + counts.delivered; // sent includes delivered
    const delivered = counts.delivered;

    return {
      ...counts,
      sent,
      deliveryRate: sent > 0 ? (delivered / sent) * 100 : 0,
      openRate: delivered > 0 ? (counts.opened / delivered) * 100 : 0,
      clickRate: counts.opened > 0 ? (counts.clicked / counts.opened) * 100 : 0,
      bounceRate: sent > 0 ? (counts.bounced / sent) * 100 : 0,
      complaintRate: delivered > 0 ? (counts.complained / delivered) * 100 : 0,
      unsubscribeRate: delivered > 0 ? (counts.unsubscribed / delivered) * 100 : 0,
    };
  }

  /**
   * Get metrics by template
   */
  async getTemplatePerformance(
    templateId?: string,
    period: 'week' | 'month' = 'month'
  ): Promise<TemplatePerformance[]> {
    const periodMs = {
      week: 7 * 24 * 60 * 60 * 1000,
      month: 30 * 24 * 60 * 60 * 1000,
    };

    const fromDate = new Date(Date.now() - periodMs[period]).toISOString();

    let query = supabase
      .from('email_events')
      .select('template_id, event_type, link_url')
      .gte('timestamp', fromDate);

    if (templateId) {
      query = query.eq('template_id', templateId);
    }

    const { data: events, error } = await query;

    if (error) {
      throw error;
    }

    // Group by template
    const templateMap = new Map<string, Array<{ event_type: string; link_url?: string }>>();

    for (const event of events || []) {
      if (!event.template_id) continue;

      if (!templateMap.has(event.template_id)) {
        templateMap.set(event.template_id, []);
      }
      templateMap.get(event.template_id)!.push(event);
    }

    // Calculate metrics per template
    const results: TemplatePerformance[] = [];

    for (const [tid, templateEvents] of templateMap) {
      const metrics = this.calculateMetrics(templateEvents);
      
      // Count link clicks
      const linkClicks = new Map<string, number>();
      for (const event of templateEvents) {
        if (event.event_type === 'clicked' && event.link_url) {
          linkClicks.set(event.link_url, (linkClicks.get(event.link_url) || 0) + 1);
        }
      }

      const topClickedLinks = Array.from(linkClicks.entries())
        .map(([url, clicks]) => ({ url, clicks }))
        .sort((a, b) => b.clicks - a.clicks)
        .slice(0, 5);

      results.push({
        template_id: tid,
        template_name: tid, // Would need to join with templates table
        total_sent: metrics.sent,
        metrics,
        top_clicked_links: topClickedLinks,
      });
    }

    return results.sort((a, b) => b.total_sent - a.total_sent);
  }

  /**
   * Get campaign metrics
   */
  async getCampaignMetrics(campaignId: string): Promise<CampaignMetrics | null> {
    const { data: events, error } = await supabase
      .from('email_events')
      .select('event_type, email')
      .eq('campaign_id', campaignId);

    if (error || !events) {
      return null;
    }

    const metrics = this.calculateMetrics(events);

    // Count unique opens and clicks
    const openedEmails = new Set<string>();
    const clickedEmails = new Set<string>();

    for (const event of events) {
      if (event.event_type === 'opened' && event.email) {
        openedEmails.add(event.email);
      }
      if (event.event_type === 'clicked' && event.email) {
        clickedEmails.add(event.email);
      }
    }

    // Get campaign details
    const { data: campaign } = await supabase
      .from('email_campaigns')
      .select('name, subject, sent_at')
      .eq('id', campaignId)
      .single();

    return {
      campaign_id: campaignId,
      campaign_name: campaign?.name || campaignId,
      subject_line: campaign?.subject || '',
      sent_at: campaign?.sent_at || '',
      ...metrics,
      unique_opens: openedEmails.size,
      unique_clicks: clickedEmails.size,
    };
  }

  /**
   * Get time-series metrics for charts
   */
  async getTimeSeriesMetrics(
    period: 'day' | 'week' | 'month',
    granularity: 'hour' | 'day' | 'week'
  ): Promise<Array<{
    timestamp: string;
    sent: number;
    delivered: number;
    opened: number;
    clicked: number;
    bounced: number;
  }>> {
    const periodMs = {
      day: 24 * 60 * 60 * 1000,
      week: 7 * 24 * 60 * 60 * 1000,
      month: 30 * 24 * 60 * 60 * 1000,
    };

    const fromDate = new Date(Date.now() - periodMs[period]).toISOString();

    const { data: events, error } = await supabase
      .from('email_events')
      .select('event_type, timestamp')
      .gte('timestamp', fromDate)
      .order('timestamp');

    if (error) {
      throw error;
    }

    // Group by time bucket
    const granularityMs = {
      hour: 60 * 60 * 1000,
      day: 24 * 60 * 60 * 1000,
      week: 7 * 24 * 60 * 60 * 1000,
    };

    const bucketSize = granularityMs[granularity];
    const buckets = new Map<number, {
      sent: number;
      delivered: number;
      opened: number;
      clicked: number;
      bounced: number;
    }>();

    for (const event of events || []) {
      const eventTime = new Date(event.timestamp).getTime();
      const bucketTime = Math.floor(eventTime / bucketSize) * bucketSize;

      if (!buckets.has(bucketTime)) {
        buckets.set(bucketTime, {
          sent: 0,
          delivered: 0,
          opened: 0,
          clicked: 0,
          bounced: 0,
        });
      }

      const bucket = buckets.get(bucketTime)!;
      const type = event.event_type as keyof typeof bucket;
      if (type in bucket) {
        bucket[type]++;
      }
    }

    return Array.from(buckets.entries())
      .map(([timestamp, data]) => ({
        timestamp: new Date(timestamp).toISOString(),
        ...data,
      }))
      .sort((a, b) => a.timestamp.localeCompare(b.timestamp));
  }

  /**
   * Get deliverability insights
   */
  async getDeliverabilityInsights(): Promise<{
    overall_health: 'good' | 'warning' | 'critical';
    bounce_rate: number;
    complaint_rate: number;
    recommendations: string[];
    domain_stats: Array<{
      domain: string;
      sent: number;
      delivered: number;
      bounced: number;
      deliveryRate: number;
    }>;
  }> {
    const metrics = await this.getMetrics('week');

    // Determine health status
    let health: 'good' | 'warning' | 'critical' = 'good';
    const recommendations: string[] = [];

    if (metrics.bounceRate > 5 || metrics.complaintRate > 0.1) {
      health = 'critical';
      if (metrics.bounceRate > 5) {
        recommendations.push('Your bounce rate is critically high. Clean your email list immediately.');
      }
      if (metrics.complaintRate > 0.1) {
        recommendations.push('Your complaint rate is critically high. Review your email content and targeting.');
      }
    } else if (metrics.bounceRate > 2 || metrics.complaintRate > 0.05) {
      health = 'warning';
      if (metrics.bounceRate > 2) {
        recommendations.push('Your bounce rate is above industry standards. Consider validating email addresses.');
      }
      if (metrics.complaintRate > 0.05) {
        recommendations.push('Your complaint rate is elevated. Review unsubscribe options and email frequency.');
      }
    }

    if (metrics.openRate < 15) {
      recommendations.push('Your open rate is below average. Test different subject lines and send times.');
    }

    if (metrics.unsubscribeRate > 1) {
      recommendations.push('Your unsubscribe rate is high. Review your email frequency and content relevance.');
    }

    // Get domain-level stats
    const { data: domainEvents } = await supabase
      .from('email_events')
      .select('email, event_type')
      .gte('timestamp', new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString());

    const domainMap = new Map<string, {
      sent: number;
      delivered: number;
      bounced: number;
    }>();

    for (const event of domainEvents || []) {
      if (!event.email) continue;

      const domain = event.email.split('@')[1]?.toLowerCase();
      if (!domain) continue;

      if (!domainMap.has(domain)) {
        domainMap.set(domain, { sent: 0, delivered: 0, bounced: 0 });
      }

      const stats = domainMap.get(domain)!;
      if (event.event_type === 'sent' || event.event_type === 'delivered') {
        stats.sent++;
      }
      if (event.event_type === 'delivered') {
        stats.delivered++;
      }
      if (event.event_type === 'bounced') {
        stats.bounced++;
      }
    }

    const domain_stats = Array.from(domainMap.entries())
      .map(([domain, stats]) => ({
        domain,
        ...stats,
        deliveryRate: stats.sent > 0 ? (stats.delivered / stats.sent) * 100 : 0,
      }))
      .sort((a, b) => b.sent - a.sent)
      .slice(0, 10);

    return {
      overall_health: health,
      bounce_rate: metrics.bounceRate,
      complaint_rate: metrics.complaintRate,
      recommendations,
      domain_stats,
    };
  }

  /**
   * Generate pixel tracking URL
   */
  generateTrackingPixel(messageId: string): string {
    const baseUrl = process.env.BACKEND_URL || 'https://api.ironparadisegym.com';
    return `${baseUrl}/email/track/open/${messageId}`;
  }

  /**
   * Generate click tracking URL
   */
  generateClickTrackingUrl(messageId: string, originalUrl: string): string {
    const baseUrl = process.env.BACKEND_URL || 'https://api.ironparadisegym.com';
    const encoded = encodeURIComponent(originalUrl);
    return `${baseUrl}/email/track/click/${messageId}?url=${encoded}`;
  }
}

export const emailAnalyticsService = new EmailAnalyticsService();

/**
 * V2 Resort - Email Rate Limiter
 * Prevents email flooding and ensures deliverability
 */

import Redis from 'ioredis';
import { supabase } from "../lib/supabase.js";
import { Request, Response, NextFunction } from 'express';

// Redis client for rate limiting
let redis: Redis | null = null;

const getRedis = (): Redis | null => {
  if (process.env.REDIS_ENABLED === 'false') return null;
  if (!redis) {
    redis = new Redis(process.env.REDIS_URL || 'redis://localhost:6379', {
      maxRetriesPerRequest: 3,
      retryStrategy: (times) => Math.min(times * 50, 2000),
    });
  }
  return redis;
};

export interface RateLimitConfig {
  maxPerMinute: number;
  maxPerHour: number;
  maxPerDay: number;
  burstLimit: number; // Max emails in 10 seconds
}

// Default rate limits by sender type
const DEFAULT_LIMITS: Record<string, RateLimitConfig> = {
  transactional: {
    maxPerMinute: 30,
    maxPerHour: 500,
    maxPerDay: 5000,
    burstLimit: 10,
  },
  marketing: {
    maxPerMinute: 10,
    maxPerHour: 100,
    maxPerDay: 1000,
    burstLimit: 5,
  },
  system: {
    maxPerMinute: 50,
    maxPerHour: 1000,
    maxPerDay: 10000,
    burstLimit: 20,
  },
};

// Per-user rate limits
const USER_LIMITS: RateLimitConfig = {
  maxPerMinute: 3,
  maxPerHour: 20,
  maxPerDay: 50,
  burstLimit: 3,
};

export type EmailCategory = 'transactional' | 'marketing' | 'system';

class EmailRateLimiter {
  private readonly prefix = 'email_ratelimit';

  /**
   * Check if email can be sent (global rate limit)
   */
  async canSendGlobal(category: EmailCategory): Promise<{
    allowed: boolean;
    reason?: string;
    retryAfter?: number;
  }> {
    const limits = DEFAULT_LIMITS[category];
    const redis = getRedis();
    if (!redis) return { allowed: true };
    const now = Math.floor(Date.now() / 1000);

    // Check burst limit (10 second window)
    const burstKey = `${this.prefix}:global:${category}:burst`;
    const burstCount = await redis.incr(burstKey);
    if (burstCount === 1) {
      await redis.expire(burstKey, 10);
    }
    if (burstCount > limits.burstLimit) {
      const ttl = await redis.ttl(burstKey);
      return {
        allowed: false,
        reason: 'Burst limit exceeded',
        retryAfter: ttl,
      };
    }

    // Check minute limit
    const minuteKey = `${this.prefix}:global:${category}:minute:${Math.floor(now / 60)}`;
    const minuteCount = await redis.incr(minuteKey);
    if (minuteCount === 1) {
      await redis.expire(minuteKey, 120);
    }
    if (minuteCount > limits.maxPerMinute) {
      return {
        allowed: false,
        reason: 'Per-minute limit exceeded',
        retryAfter: 60 - (now % 60),
      };
    }

    // Check hour limit
    const hourKey = `${this.prefix}:global:${category}:hour:${Math.floor(now / 3600)}`;
    const hourCount = await redis.incr(hourKey);
    if (hourCount === 1) {
      await redis.expire(hourKey, 7200);
    }
    if (hourCount > limits.maxPerHour) {
      return {
        allowed: false,
        reason: 'Per-hour limit exceeded',
        retryAfter: 3600 - (now % 3600),
      };
    }

    // Check day limit
    const dayKey = `${this.prefix}:global:${category}:day:${Math.floor(now / 86400)}`;
    const dayCount = await redis.incr(dayKey);
    if (dayCount === 1) {
      await redis.expire(dayKey, 172800);
    }
    if (dayCount > limits.maxPerDay) {
      return {
        allowed: false,
        reason: 'Daily limit exceeded',
        retryAfter: 86400 - (now % 86400),
      };
    }

    return { allowed: true };
  }

  /**
   * Check if email can be sent to specific user
   */
  async canSendToUser(
    userId: string,
    category: EmailCategory = 'transactional'
  ): Promise<{
    allowed: boolean;
    reason?: string;
    retryAfter?: number;
  }> {
    // Marketing emails have stricter per-user limits
    const limits = category === 'marketing'
      ? { ...USER_LIMITS, maxPerDay: 3 }
      : USER_LIMITS;

    const redis = getRedis();
    if (!redis) return { allowed: true };
    const now = Math.floor(Date.now() / 1000);

    // Check minute limit
    const minuteKey = `${this.prefix}:user:${userId}:minute:${Math.floor(now / 60)}`;
    const minuteCount = await redis.incr(minuteKey);
    if (minuteCount === 1) {
      await redis.expire(minuteKey, 120);
    }
    if (minuteCount > limits.maxPerMinute) {
      return {
        allowed: false,
        reason: 'Too many emails sent to this user',
        retryAfter: 60 - (now % 60),
      };
    }

    // Check hour limit
    const hourKey = `${this.prefix}:user:${userId}:hour:${Math.floor(now / 3600)}`;
    const hourCount = await redis.incr(hourKey);
    if (hourCount === 1) {
      await redis.expire(hourKey, 7200);
    }
    if (hourCount > limits.maxPerHour) {
      return {
        allowed: false,
        reason: 'Too many emails sent to this user (hourly limit)',
        retryAfter: 3600 - (now % 3600),
      };
    }

    // Check day limit
    const dayKey = `${this.prefix}:user:${userId}:day:${Math.floor(now / 86400)}`;
    const dayCount = await redis.incr(dayKey);
    if (dayCount === 1) {
      await redis.expire(dayKey, 172800);
    }
    if (dayCount > limits.maxPerDay) {
      return {
        allowed: false,
        reason: 'Too many emails sent to this user (daily limit)',
        retryAfter: 86400 - (now % 86400),
      };
    }

    return { allowed: true };
  }

  /**
   * Check if email can be sent to specific address (for non-logged-in users)
   */
  async canSendToEmail(
    email: string,
    category: EmailCategory = 'transactional'
  ): Promise<{
    allowed: boolean;
    reason?: string;
    retryAfter?: number;
  }> {
    const emailHash = Buffer.from(email.toLowerCase()).toString('base64');
    const limits = USER_LIMITS;
    const redis = getRedis();
    if (!redis) return { allowed: true };
    const now = Math.floor(Date.now() / 1000);

    // Check hour limit for this email
    const hourKey = `${this.prefix}:email:${emailHash}:hour:${Math.floor(now / 3600)}`;
    const hourCount = await redis.incr(hourKey);
    if (hourCount === 1) {
      await redis.expire(hourKey, 7200);
    }
    if (hourCount > limits.maxPerHour) {
      return {
        allowed: false,
        reason: 'Too many emails sent to this address',
        retryAfter: 3600 - (now % 3600),
      };
    }

    // Check day limit for this email
    const dayKey = `${this.prefix}:email:${emailHash}:day:${Math.floor(now / 86400)}`;
    const dayCount = await redis.incr(dayKey);
    if (dayCount === 1) {
      await redis.expire(dayKey, 172800);
    }
    if (dayCount > limits.maxPerDay) {
      return {
        allowed: false,
        reason: 'Too many emails sent to this address (daily limit)',
        retryAfter: 86400 - (now % 86400),
      };
    }

    return { allowed: true };
  }

  /**
   * Combined check for all rate limits
   */
  async checkRateLimit(
    email: string,
    userId: string | null,
    category: EmailCategory
  ): Promise<{
    allowed: boolean;
    reason?: string;
    retryAfter?: number;
  }> {
    // Check global rate limit
    const globalCheck = await this.canSendGlobal(category);
    if (!globalCheck.allowed) {
      return globalCheck;
    }

    // Check user-specific rate limit
    if (userId) {
      const userCheck = await this.canSendToUser(userId, category);
      if (!userCheck.allowed) {
        return userCheck;
      }
    } else {
      // Check email-specific rate limit
      const emailCheck = await this.canSendToEmail(email, category);
      if (!emailCheck.allowed) {
        return emailCheck;
      }
    }

    return { allowed: true };
  }

  /**
   * Record an email send attempt (for tracking without blocking)
   */
  async recordSend(
    email: string,
    userId: string | null,
    category: EmailCategory,
    templateId?: string
  ): Promise<void> {
    // Store in database for analytics
    await supabase.from('email_rate_limit_log').insert({
      email_hash: Buffer.from(email.toLowerCase()).toString('base64'),
      user_id: userId,
      category,
      template_id: templateId,
    });
  }

  /**
   * Get current usage statistics
   */
  async getUsageStats(category: EmailCategory): Promise<{
    minute: { used: number; limit: number };
    hour: { used: number; limit: number };
    day: { used: number; limit: number };
  }> {
    const limits = DEFAULT_LIMITS[category];
    const redis = getRedis();
    if (!redis) {
      return {
        minute: { used: 0, limit: limits.maxPerMinute },
        hour: { used: 0, limit: limits.maxPerHour },
        day: { used: 0, limit: limits.maxPerDay },
      };
    }
    const now = Math.floor(Date.now() / 1000);

    const minuteKey = `${this.prefix}:global:${category}:minute:${Math.floor(now / 60)}`;
    const hourKey = `${this.prefix}:global:${category}:hour:${Math.floor(now / 3600)}`;
    const dayKey = `${this.prefix}:global:${category}:day:${Math.floor(now / 86400)}`;

    const [minuteCount, hourCount, dayCount] = await Promise.all([
      redis.get(minuteKey),
      redis.get(hourKey),
      redis.get(dayKey),
    ]);

    return {
      minute: { used: parseInt(minuteCount || '0'), limit: limits.maxPerMinute },
      hour: { used: parseInt(hourCount || '0'), limit: limits.maxPerHour },
      day: { used: parseInt(dayCount || '0'), limit: limits.maxPerDay },
    };
  }

  /**
   * Get user-specific usage
   */
  async getUserUsageStats(userId: string): Promise<{
    minute: number;
    hour: number;
    day: number;
    limits: RateLimitConfig;
  }> {
    const redis = getRedis();
    if (!redis) {
      return { minute: 0, hour: 0, day: 0, limits: USER_LIMITS };
    }
    const now = Math.floor(Date.now() / 1000);

    const minuteKey = `${this.prefix}:user:${userId}:minute:${Math.floor(now / 60)}`;
    const hourKey = `${this.prefix}:user:${userId}:hour:${Math.floor(now / 3600)}`;
    const dayKey = `${this.prefix}:user:${userId}:day:${Math.floor(now / 86400)}`;

    const [minuteCount, hourCount, dayCount] = await Promise.all([
      redis.get(minuteKey),
      redis.get(hourKey),
      redis.get(dayKey),
    ]);

    return {
      minute: parseInt(minuteCount || '0'),
      hour: parseInt(hourCount || '0'),
      day: parseInt(dayCount || '0'),
      limits: USER_LIMITS,
    };
  }

  /**
   * Reset rate limits for testing/admin purposes
   */
  async resetLimits(target: 'global' | 'user', identifier?: string): Promise<void> {
    const redis = getRedis();

    if (target === 'global') {
      const redis = getRedis();
      if (!redis) return;
      const keys = await redis.keys(`${this.prefix}:global:*`);
      if (keys.length > 0) {
        await redis.del(...keys);
      }
    } else if (target === 'user' && identifier) {
      const redis = getRedis();
      if (!redis) return;
      const keys = await redis.keys(`${this.prefix}:user:${identifier}:*`);
      if (keys.length > 0) {
        await redis.del(...keys);
      }
    }
  }

  /**
   * Close Redis connection
   */
  async close(): Promise<void> {
    if (redis) {
      await redis.quit();
      redis = null;
    }
  }
}

export const emailRateLimiter = new EmailRateLimiter();

// Middleware factory for Express routes
interface AuthenticatedRequest {
  body?: { email?: string; to?: string };
  user?: { id: string };
}

export function emailRateLimitMiddleware(category: EmailCategory = 'transactional') {
  return async (req: AuthenticatedRequest, res: Response, next: NextFunction) => {
    const email = req.body?.email || req.body?.to;
    const userId = req.user?.id || null;

    if (!email) {
      return next();
    }

    const result = await emailRateLimiter.checkRateLimit(email, userId, category);

    if (!result.allowed) {
      res.set('Retry-After', String(result.retryAfter || 60));
      return res.status(429).json({
        error: 'Too Many Requests',
        message: result.reason,
        retryAfter: result.retryAfter,
      });
    }

    next();
  };
}

import nodemailer from 'nodemailer';
import { getSupabase } from '../database/connection.js';
import { config } from '../config/index.js';
import { logger } from '../utils/logger.js';

interface EmailOptions {
  to: string;
  subject: string;
  html?: string;
  text?: string;
  template?: string;
  context?: any;
  data?: any;
  attachments?: Array<{
    filename: string;
    content: string | Buffer;
    encoding?: string;
    contentType?: string;
  }>;
}

interface TemplateVariables {
  [key: string]: string | number | undefined;
}

class EmailService {
  private transporter: nodemailer.Transporter | null = null;
  private isConfigured: boolean = false;

  constructor() {
    this.initialize();
  }

  private initialize() {
    const host = process.env.SMTP_HOST;
    const port = parseInt(process.env.SMTP_PORT || '587', 10);
    const user = process.env.SMTP_USER;
    const pass = process.env.SMTP_PASS;

    if (!host || !user || !pass) {
      logger.warn('Email service not configured. Set SMTP_HOST, SMTP_USER, SMTP_PASS environment variables.');
      this.isConfigured = false;
      return;
    }

    try {
      this.transporter = nodemailer.createTransport({
        host,
        port,
        secure: port === 465,
        auth: { user, pass },
      });
      this.isConfigured = true;
      logger.info('Email service initialized successfully');
    } catch (error: unknown) {
      const err = error as Error;
      logger.error('Failed to initialize email service:', err.message);
      this.isConfigured = false;
    }
  }

  private async getTemplate(templateName: string): Promise<{ subject: string; html_body: string; variables: string[] } | null> {
    try {
      const supabase = getSupabase();
      const { data, error } = await supabase
        .from('email_templates')
        .select('subject, html_body, variables')
        .eq('template_name', templateName)
        .eq('is_active', true)
        .single();

      if (error) {
        logger.error(`Failed to fetch email template '${templateName}':`, error.message);
        return null;
      }
      return data;
    } catch (error: unknown) {
      const err = error as Error;
      logger.error(`Error fetching template '${templateName}':`, err.message);
      return null;
    }
  }

  private async getSiteSettings(): Promise<Record<string, string>> {
    try {
      const supabase = getSupabase();
      // Existing site_settings table uses 'key' and 'value' (JSONB) columns
      const { data, error } = await supabase
        .from('site_settings')
        .select('key, value');

      if (error) {
        logger.warn('Failed to fetch site settings for email:', error.message);
        return this.getDefaultSettings();
      }

      // Extract relevant fields from JSONB values
      const settings: Record<string, string> = {};
      (data || []).forEach((s: { key: string; value: Record<string, unknown> | null }) => {
        if (s.key === 'general' && s.value) {
          settings.company_name = String(s.value.resortName || 'Iron Paradise Gym');
          settings.companyName = String(s.value.resortName || 'Iron Paradise Gym');
        }
        if (s.key === 'contact' && s.value) {
          settings.contact_email = String(s.value.email || 'info@ironparadisegym.com');
          settings.contactEmail = String(s.value.email || 'info@ironparadisegym.com');
          settings.contact_phone = String(s.value.phone || 'Not configured');
          settings.contactPhone = String(s.value.phone || 'Not configured');
          settings.contact_address = String(s.value.address || 'Iron Paradise Gym');
          settings.companyAddress = String(s.value.address || 'Iron Paradise Gym');
        }
        if (s.key === 'chalets' && s.value) {
          settings.chalet_check_in = String(s.value.checkIn || s.value.check_in_time || '3:00 PM');
          settings.chalet_check_out = String(s.value.checkOut || s.value.check_out_time || '12:00 PM');
        }
      });
      return { ...this.getDefaultSettings(), ...settings };
    } catch {
      return this.getDefaultSettings();
    }
  }

  private getDefaultSettings(): Record<string, string> {
    return {
      company_name: 'Iron Paradise Gym',
      contact_email: 'info@ironparadisegym.com',
      contact_phone: 'Not configured',
      contact_address: 'Iron Paradise Gym',
      companyName: 'Iron Paradise Gym',
      contactEmail: 'info@ironparadisegym.com',
      contactPhone: 'Not configured',
      companyAddress: 'Iron Paradise Gym',
    };
  }

  private replaceVariables(template: string, variables: TemplateVariables): string {
    let result = template;
    for (const [key, value] of Object.entries(variables)) {
      const regex = new RegExp(`{{${key}}}`, 'g');
      result = result.replace(regex, String(value ?? ''));
    }
    // Remove any unreplaced variables
    result = result.replace(/{{[^}]+}}/g, '');
    return result;
  }

  async sendEmail(options: EmailOptions): Promise<boolean> {
    if (!this.isConfigured || !this.transporter) {
      logger.warn('Email not sent - service not configured');
      return false;
    }

    // Handle template if provided
    if (options.template && !options.html) {
      const templateData = await this.getTemplate(options.template);
      if (templateData) {
        const variables = {
          ...(await this.getSiteSettings()),
          ...(options.data || options.context || {})
        };
        options.html = this.replaceVariables(templateData.html_body, variables as TemplateVariables);

        // Use template subject if not provided in options
        if (!options.subject || options.subject === '') {
          options.subject = this.replaceVariables(templateData.subject, variables as TemplateVariables);
        }
      } else {
        logger.warn(`Template '${options.template}' not found, utilizing provided options`);
      }
    }

    if (!options.html) {
      logger.error('Email not sent - missing content (HTML or valid template)');
      return false;
    }

    const fromAddress = process.env.SMTP_FROM || process.env.SMTP_USER || 'noreply@ironparadisegym.com';
    const fromName = process.env.SMTP_FROM_NAME || 'Iron Paradise Gym';

    try {
      const info = await this.transporter.sendMail({
        from: `"${fromName}" <${fromAddress}>`,
        to: options.to,
        subject: options.subject,
        html: options.html,
        text: options.text,
        attachments: options.attachments,
      });

      logger.info(`Email sent successfully: ${info.messageId}`);
      return true;
    } catch (error: unknown) {
      const err = error as Error;
      logger.error('Failed to send email:', err.message);
      return false;
    }
  }

  /**
   * Send email using a template name with variables
   */
  async sendTemplatedEmail(templateName: string, to: string, variables: Record<string, unknown>): Promise<boolean> {
    const template = await this.getTemplate(templateName);
    if (!template) {
      logger.warn(`Template '${templateName}' not found`);
      return false;
    }

    const html = this.replaceVariables(template.html_body, variables as TemplateVariables);
    const subject = this.replaceVariables(template.subject, variables as TemplateVariables);

    return this.sendEmail({ to, subject, html });
  }

