interface MembershipResult {
  success: boolean;
  message: string;
  membership?: any;
  subscriptionId?: string;
  clientSecret?: string;
  statusCode?: number;
  code?: string;
}

function isStripeConfigured(): boolean {
  return Boolean(process.env.STRIPE_SECRET_KEY && process.env.STRIPE_SECRET_KEY.trim());
}

function isStripeAuthError(error: unknown): boolean {
  if (!error || typeof error !== 'object') {
    return false;
  }

  const stripeError = error as { type?: string; message?: string };
  return (
    stripeError.type === 'StripeAuthenticationError' ||
    (typeof stripeError.message === 'string' && /api key|authentication/i.test(stripeError.message))
  );
}

function billingUnavailableResult(message = 'Membership billing is currently unavailable. Please try again later.'): MembershipResult {
  return {
    success: false,
    message,
    statusCode: 503,
    code: 'BILLING_UNAVAILABLE',
  };
}

/**
 * Get membership pricing
 */
export function getMembershipPricing(
  type: MembershipType,
  billingCycle: BillingCycle
): MembershipPricing | null {
  return MEMBERSHIP_PRICING.find(
    p => p.type === type && p.billingCycle === billingCycle
  ) || null;
}

/**
 * Get all available membership plans
 */
export function getAllMembershipPlans(): MembershipPricing[] {
  return MEMBERSHIP_PRICING;
}

/**
 * Create a new membership
 */
export async function createMembership(
  input: CreateMembershipInput
): Promise<MembershipResult> {
  try {
    if (!isStripeConfigured()) {
      logger.warn('Membership creation blocked: Stripe secret key is not configured');
      return billingUnavailableResult();
    }

    const pricing = getMembershipPricing(input.type, input.billingCycle);
    
    if (!pricing) {
      return {
        success: false,
        message: 'Invalid membership type or billing cycle',
      };
    }

    // Check if user already has an active membership
    const supabase = getSupabase();
    const { data: existingMembership, error: existingError } = await supabase
      .from('pool_memberships')
      .select('id')
      .eq('user_id', input.userId)
      .eq('status', MembershipStatus.ACTIVE)
      .limit(1)
      .maybeSingle();
    if (existingError) throw existingError;

    if (existingMembership) {
      return {
        success: false,
        message: 'User already has an active membership',
      };
    }

    // Validate member count for family/corporate
    if (input.memberEmails && input.memberEmails.length > pricing.maxMembers - 1) {
      return {
        success: false,
        message: `Maximum ${pricing.maxMembers} members allowed for this plan`,
      };
    }

    // Get or create Stripe customer
    const { data: user, error: userError } = await supabase
      .from('users')
      .select('*')
      .eq('id', input.userId)
      .maybeSingle();
    if (userError) throw userError;

    if (!user) {
      return { success: false, message: 'User not found' };
    }

    let stripeCustomerId = user.stripe_customer_id;
    
    if (!stripeCustomerId) {
      const customer = await stripeClient.customers.create({
        email: user.email,
        name: `${user.first_name} ${user.last_name}`,
        metadata: { userId: input.userId },
      });
      
      stripeCustomerId = customer.id;
      
      const { error: updateUserError } = await supabase
        .from('users')
        .update({ stripe_customer_id: stripeCustomerId })
        .eq('id', input.userId);
      if (updateUserError) throw updateUserError;
    }

    // Create or get Stripe price
    const stripePriceId = await getOrCreateStripePrice(pricing);

    // Create Stripe subscription
    const subscriptionParams: Stripe.SubscriptionCreateParams = {
      customer: stripeCustomerId,
      items: [{ price: stripePriceId }],
      payment_behavior: 'default_incomplete',
      payment_settings: { save_default_payment_method: 'on_subscription' },
      expand: ['latest_invoice.payment_intent'],
    };

    if (input.paymentMethodId) {
      subscriptionParams.default_payment_method = input.paymentMethodId;
    }

    const subscription = await stripeClient.subscriptions.create(subscriptionParams);

    // Calculate membership dates
    const startDate = new Date();
    const endDate = calculateEndDate(startDate, input.billingCycle);

    // Create membership in database
    const { data: membership, error: membershipError } = await supabase
      .from('pool_memberships')
      .insert({
        user_id: input.userId,
        type: input.type,
        billing_cycle: input.billingCycle,
        status: MembershipStatus.PENDING_PAYMENT,
        start_date: startDate.toISOString(),
        end_date: endDate.toISOString(),
        price: pricing.basePrice,
        stripe_subscription_id: subscription.id,
        corporate_name: input.corporateName,
        max_members: pricing.maxMembers,
        remaining_guest_passes: pricing.guestPasses,
        discount_percentage: pricing.discountPercentage,
      })
      .select()
      .single();
    if (membershipError) throw membershipError;

    // Add additional members if provided
    if (input.memberEmails && input.memberEmails.length > 0) {
      for (const email of input.memberEmails) {
        const { error: memberError } = await supabase
          .from('membership_members')
          .insert({
            membership_id: membership.id,
            email,
            status: 'PENDING_INVITATION',
          });
        if (memberError) throw memberError;
        
        // Send invitation email
        await sendMemberInvitation(email, membership, user);
      }
    }

    // Get client secret for payment
    const invoice = subscription.latest_invoice as Stripe.Invoice;
    const paymentIntent = invoice.payment_intent as Stripe.PaymentIntent;

    logger.info('Pool membership created', {
      userId: input.userId,
      membershipId: membership.id,
      type: input.type,
    });

    return {
      success: true,
      message: 'Membership created. Please complete payment.',
      membership,
      subscriptionId: subscription.id,
      clientSecret: paymentIntent?.client_secret || undefined,
    };
  } catch (error: any) {
    if (isStripeAuthError(error)) {
      logger.error('Failed to create membership due to Stripe authentication error', {
        error: error?.message,
      });
      return billingUnavailableResult();
    }

    logger.error('Failed to create membership', { error: error.message });
    throw error;
  }
}

/**
 * Cancel membership
 */
export async function cancelMembership(
  membershipId: string,
  userId: string,
  reason?: string,
  immediate: boolean = false
): Promise<MembershipResult> {
  try {
    const supabase = getSupabase();
    const { data: membership, error: membershipError } = await supabase
      .from('pool_memberships')
      .select('*')
      .eq('id', membershipId)
      .maybeSingle();
    if (membershipError) throw membershipError;

    if (!membership) {
      return { success: false, message: 'Membership not found' };
    }

    if (membership.user_id !== userId) {
      return { success: false, message: 'Unauthorized' };
    }

    if (membership.status !== MembershipStatus.ACTIVE) {
      return { success: false, message: 'Membership is not active' };
    }

    // Cancel Stripe subscription
    if (membership.stripe_subscription_id) {
      if (!isStripeConfigured()) {
        logger.warn('Membership cancellation blocked: Stripe secret key is not configured', {
          membershipId,
          userId,
        });
        return billingUnavailableResult('Membership billing is currently unavailable. Unable to cancel subscription right now.');
      }

      await stripeClient.subscriptions.update(membership.stripe_subscription_id, {
        cancel_at_period_end: !immediate,
      });

      if (immediate) {
        await stripeClient.subscriptions.cancel(membership.stripe_subscription_id);
      }
    }

    // Update membership status
    const { error: updateError } = await supabase
      .from('pool_memberships')
      .update({
        status: immediate ? MembershipStatus.CANCELLED : MembershipStatus.ACTIVE,
        cancelled_at: new Date().toISOString(),
        cancellation_reason: reason,
        auto_renew: false,
      })
      .eq('id', membershipId);
    if (updateError) throw updateError;

    logger.info('Pool membership cancelled', {
      membershipId,
      userId,
      immediate,
    });

    return {
      success: true,
      message: immediate 
        ? 'Membership cancelled immediately' 
        : 'Membership will be cancelled at the end of the billing period',
    };
  } catch (error: any) {
    if (isStripeAuthError(error)) {
      logger.error('Failed to cancel membership due to Stripe authentication error', {
        membershipId,
        userId,
        error: error?.message,
      });
      return billingUnavailableResult('Membership billing is currently unavailable. Unable to cancel subscription right now.');
    }

    logger.error('Failed to cancel membership', { error: error.message });
    throw error;
  }
}

/**
 * Validate membership access
 */
export async function validateMembershipAccess(
  userId: string
): Promise<{
  hasAccess: boolean;
  membership?: any;
  remainingGuestPasses?: number;
  discountPercentage?: number;
}> {
  const supabase = getSupabase();
  const now = new Date().toISOString();

  // Check direct membership
  const { data: directMembership, error: directError } = await supabase
    .from('pool_memberships')
    .select('*, members:membership_members(*)')
    .eq('user_id', userId)
    .eq('status', MembershipStatus.ACTIVE)
    .gte('end_date', now)
    .limit(1)
    .maybeSingle();
  if (directError) throw directError;

  let membership = directMembership;

  // If no direct membership, check via membership_members
  if (!membership) {
    const { data: memberRecord, error: memberError } = await supabase
      .from('membership_members')
      .select('membership_id')
      .eq('user_id', userId)
      .eq('status', 'ACTIVE')
      .limit(1)
      .maybeSingle();
    if (memberError) throw memberError;

    if (memberRecord) {
      const { data: parentMembership, error: parentError } = await supabase
        .from('pool_memberships')
        .select('*, members:membership_members(*)')
        .eq('id', memberRecord.membership_id)
        .eq('status', MembershipStatus.ACTIVE)
        .gte('end_date', now)
        .maybeSingle();
      if (parentError) throw parentError;
      membership = parentMembership;
    }
  }

  if (!membership) {
    return { hasAccess: false };
  }

  return {
    hasAccess: true,
    membership,
    remainingGuestPasses: membership.remaining_guest_passes,
    discountPercentage: membership.discount_percentage ? Number(membership.discount_percentage) : 0,
  };
}

/**
 * Use a guest pass
 */
export async function useGuestPass(
  membershipId: string,
  guestName: string,
  guestEmail?: string
): Promise<{ success: boolean; message: string; remainingPasses?: number }> {
  const supabase = getSupabase();
  const { data: membership, error: membershipError } = await supabase
    .from('pool_memberships')
    .select('*')
    .eq('id', membershipId)
    .maybeSingle();
  if (membershipError) throw membershipError;

  if (!membership) {
    return { success: false, message: 'Membership not found' };
  }

  if (membership.status !== MembershipStatus.ACTIVE) {
    return { success: false, message: 'Membership is not active' };
  }

  // VIP has unlimited passes
  if (membership.type !== MembershipType.VIP && membership.remaining_guest_passes <= 0) {
    return { success: false, message: 'No guest passes remaining' };
  }

  // Record guest pass usage
  const { error: usageError } = await supabase
    .from('guest_pass_usage')
    .insert({
      membership_id: membershipId,
      guest_name: guestName,
      guest_email: guestEmail,
      used_at: new Date().toISOString(),
    });
  if (usageError) throw usageError;

  // Decrement remaining passes (except for VIP)
  if (membership.type !== MembershipType.VIP) {
    const { error: updateError } = await supabase
      .from('pool_memberships')
      .update({ remaining_guest_passes: membership.remaining_guest_passes - 1 })
      .eq('id', membershipId);
    if (updateError) throw updateError;
  }

  return {
    success: true,
    message: 'Guest pass used successfully',
    remainingPasses: membership.type === MembershipType.VIP 
      ? -1 // Unlimited
      : membership.remaining_guest_passes - 1,
  };
}

/**
 * Process membership renewal (called by webhook)
 */
export async function processRenewal(
  subscriptionId: string
): Promise<void> {
  const supabase = getSupabase();
  const { data: membership, error: membershipError } = await supabase
    .from('pool_memberships')
    .select('*, user:users(*)')
    .eq('stripe_subscription_id', subscriptionId)
    .limit(1)
    .maybeSingle();
  if (membershipError) throw membershipError;

  if (!membership) {
    logger.warn('Membership not found for renewal', { subscriptionId });
    return;
  }

  const pricing = getMembershipPricing(
    membership.type as MembershipType,
    membership.billing_cycle as BillingCycle
  );

  const newEndDate = calculateEndDate(
    new Date(membership.end_date || new Date()),
    membership.billing_cycle as BillingCycle
  );

  const { error: updateError } = await supabase
    .from('pool_memberships')
    .update({
      end_date: newEndDate.toISOString(),
      remaining_guest_passes: pricing?.guestPasses || membership.remaining_guest_passes,
      renewed_at: new Date().toISOString(),
    })
    .eq('id', membership.id);
  if (updateError) throw updateError;

  // Send renewal confirmation
  await emailService.sendEmail({
    to: membership.user.email,
    subject: 'Pool Membership Renewed',
    html: `
      <h2>Membership Renewal Confirmation</h2>
      <p>Your ${membership.type} pool membership has been renewed.</p>
      <p><strong>New expiration date:</strong> ${newEndDate.toLocaleDateString()}</p>
      <p><strong>Guest passes refreshed:</strong> ${pricing?.guestPasses || 0}</p>
    `,
  });

  logger.info('Membership renewed', { membershipId: membership.id, newEndDate });
}

/**
 * Handle failed payment (called by webhook)
 */
export async function handleFailedPayment(
  subscriptionId: string
): Promise<void> {
  const supabase = getSupabase();
  const { data: membership, error: membershipError } = await supabase
    .from('pool_memberships')
    .select('*, user:users(*)')
    .eq('stripe_subscription_id', subscriptionId)
    .limit(1)
    .maybeSingle();
  if (membershipError) throw membershipError;

  if (!membership) return;

  const { error: updateError } = await supabase
    .from('pool_memberships')
    .update({ status: MembershipStatus.SUSPENDED })
    .eq('id', membership.id);
  if (updateError) throw updateError;

  // Send notification
  await emailService.sendEmail({
    to: membership.user.email,
    subject: 'Pool Membership Payment Failed',
    html: `
      <h2>Payment Failed</h2>
      <p>We were unable to process your membership payment.</p>
      <p>Your membership has been suspended. Please update your payment method to restore access.</p>
    `,
  });

  logger.warn('Membership suspended due to failed payment', {
    membershipId: membership.id,
  });
}

// Helper functions
function calculateEndDate(startDate: Date, billingCycle: BillingCycle): Date {
  const endDate = new Date(startDate);
  
  switch (billingCycle) {
    case BillingCycle.MONTHLY:
      endDate.setMonth(endDate.getMonth() + 1);
      break;
    case BillingCycle.QUARTERLY:
      endDate.setMonth(endDate.getMonth() + 3);
      break;
    case BillingCycle.ANNUALLY:
      endDate.setFullYear(endDate.getFullYear() + 1);
      break;
  }
  
  return endDate;
}

async function getOrCreateStripePrice(pricing: MembershipPricing): Promise<string> {
  const priceKey = `pool_${pricing.type.toLowerCase()}_${pricing.billingCycle.toLowerCase()}`;
  
  // Check if price exists in settings
  const supabase = getSupabase();
  const { data: existingPrice, error: priceError } = await supabase
    .from('system_settings')
    .select('value')
    .eq('key', `stripe.price.${priceKey}`)
    .maybeSingle();
  if (priceError) throw priceError;

  if (existingPrice) {
    return existingPrice.value;
  }

  // Create Stripe product and price
  const product = await stripeClient.products.create({
    name: `Pool Membership - ${pricing.type}`,
    metadata: { type: pricing.type, billingCycle: pricing.billingCycle },
  });

  const intervalMap: Record<BillingCycle, Stripe.PriceCreateParams.Recurring.Interval> = {
    [BillingCycle.MONTHLY]: 'month',
    [BillingCycle.QUARTERLY]: 'month',
    [BillingCycle.ANNUALLY]: 'year',
  };

  const price = await stripeClient.prices.create({
    product: product.id,
    unit_amount: Math.round(pricing.basePrice * 100),
    currency: 'usd',
    recurring: {
      interval: intervalMap[pricing.billingCycle],
      interval_count: pricing.billingCycle === BillingCycle.QUARTERLY ? 3 : 1,
    },
  });

  // Store price ID
  const { error: storeError } = await supabase
    .from('system_settings')
    .insert({
      key: `stripe.price.${priceKey}`,
      value: price.id,
      category: 'stripe',
    });
  if (storeError) throw storeError;

  return price.id;
}

async function sendMemberInvitation(
  email: string,
  membership: any,
  owner: any
): Promise<void> {
  await emailService.sendEmail({
    to: email,
    subject: 'Pool Membership Invitation',
    html: `
      <h2>You've Been Invited!</h2>
      <p>${owner.firstName} ${owner.lastName} has added you to their ${membership.type} pool membership.</p>
      <p>Click the link below to activate your membership access.</p>
      <a href="${process.env.FRONTEND_URL}/membership/accept?token=${membership.id}">
        Activate Membership
      </a>
    `,
  });
}

export default {
  getMembershipPricing,
  getAllMembershipPlans,
  createMembership,
  cancelMembership,
  validateMembershipAccess,
  useGuestPass,
  processRenewal,
  handleFailedPayment,
  MembershipType,
  MembershipStatus,
  BillingCycle,
};

/**
 * Enhanced Rate Limiter Service
 * Implements token bucket algorithm with Redis support and endpoint-specific limits
 */
import { Request, Response, NextFunction } from 'express';

interface RateLimitConfig {
  windowMs: number;
  maxRequests: number;
  message?: string;
  skipSuccessfulRequests?: boolean;
  skipFailedRequests?: boolean;
  keyGenerator?: (req: Request) => string;
  handler?: (req: Request, res: Response, next: NextFunction) => void;
}

interface TokenBucket {
  tokens: number;
  lastRefill: number;
}

interface RateLimitStore {
  get(key: string): Promise<TokenBucket | null>;
  set(key: string, bucket: TokenBucket, ttlMs: number): Promise<void>;
  increment(key: string): Promise<number>;
}

// In-memory store (for single instance)
class MemoryStore implements RateLimitStore {
  private buckets: Map<string, TokenBucket> = new Map();
  private counters: Map<string, number> = new Map();

  async get(key: string): Promise<TokenBucket | null> {
    return this.buckets.get(key) || null;
  }

  async set(key: string, bucket: TokenBucket, ttlMs: number): Promise<void> {
    this.buckets.set(key, bucket);
    setTimeout(() => this.buckets.delete(key), ttlMs);
  }

  async increment(key: string): Promise<number> {
    const current = this.counters.get(key) || 0;
    this.counters.set(key, current + 1);
    return current + 1;
  }
}

// Endpoint-specific configurations
const ENDPOINT_LIMITS: Record<string, Partial<RateLimitConfig>> = {
  // Auth endpoints - stricter limits
  '/api/auth/login': { windowMs: 60000, maxRequests: 5 },
  '/api/auth/register': { windowMs: 60000, maxRequests: 3 },
  '/api/auth/forgot-password': { windowMs: 300000, maxRequests: 3 },
  '/api/auth/reset-password': { windowMs: 300000, maxRequests: 3 },
  '/api/auth/2fa/authenticate': { windowMs: 60000, maxRequests: 5 },
  
  // Payment endpoints - moderate limits
  '/api/payments': { windowMs: 60000, maxRequests: 10 },
  '/api/bookings/chalets': { windowMs: 60000, maxRequests: 20 },
  
  // Admin endpoints - higher limits
  '/api/admin': { windowMs: 60000, maxRequests: 200 },
  
  // API default
  '/api': { windowMs: 60000, maxRequests: 100 },
};

// User tier multipliers
const TIER_MULTIPLIERS: Record<string, number> = {
  anonymous: 1.0,
  customer: 1.5,
  premium: 2.0,
  staff: 3.0,
  admin: 5.0,
};

export class RateLimiterService {
  private store: RateLimitStore;
  private defaultConfig: RateLimitConfig;

  constructor(store?: RateLimitStore, defaultConfig?: Partial<RateLimitConfig>) {
    this.store = store || new MemoryStore();
    this.defaultConfig = {
      windowMs: 60000,
      maxRequests: 100,
      message: 'Too many requests, please try again later.',
      skipSuccessfulRequests: false,
      skipFailedRequests: false,
      ...defaultConfig,
    };
  }

  /**
   * Get configuration for a specific endpoint
   */
  private getEndpointConfig(path: string): RateLimitConfig {
    // Find matching endpoint config (longest match wins)
    let matchedConfig: Partial<RateLimitConfig> = {};
    let matchLength = 0;

    for (const [endpoint, config] of Object.entries(ENDPOINT_LIMITS)) {
      if (path.startsWith(endpoint) && endpoint.length > matchLength) {
        matchedConfig = config;
        matchLength = endpoint.length;
      }
    }

    return { ...this.defaultConfig, ...matchedConfig };
  }

  /**
   * Get user tier from request
   */
  private getUserTier(req: Request): string {
    const user = req.user;
    if (!user) return 'anonymous';
    return user.roles?.[0] || 'customer';
  }

  /**
   * Generate rate limit key
   */
  private generateKey(req: Request, config: RateLimitConfig): string {
    if (config.keyGenerator) {
      return config.keyGenerator(req);
    }

    // Default: IP + user ID (if authenticated)
    const ip = req.ip || req.socket.remoteAddress || 'unknown';
    const userId = req.user?.id || 'anon';
    const path = this.normalizePath(req.path);

    return `ratelimit:${ip}:${userId}:${path}`;
  }

  private normalizePath(path: string): string {
    // Group similar paths
    return path
      .replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi, ':id')
      .replace(/\/\d+/g, '/:id');
  }

  /**
   * Check if request should be rate limited
   */
  async checkLimit(req: Request): Promise<{
    allowed: boolean;
    remaining: number;
    resetTime: number;
    limit: number;
  }> {
    const config = this.getEndpointConfig(req.path);
    const key = this.generateKey(req, config);
    const userTier = this.getUserTier(req);
    const multiplier = TIER_MULTIPLIERS[userTier] || 1.0;
    
    const effectiveLimit = Math.floor(config.maxRequests * multiplier);
    const now = Date.now();

    // Get or create bucket
    let bucket = await this.store.get(key);
    
    if (!bucket) {
      bucket = {
        tokens: effectiveLimit,
        lastRefill: now,
      };
    }

    // Refill tokens based on time elapsed
    const elapsed = now - bucket.lastRefill;
    const refillRate = effectiveLimit / config.windowMs;
    const tokensToAdd = elapsed * refillRate;
    
    bucket.tokens = Math.min(effectiveLimit, bucket.tokens + tokensToAdd);
    bucket.lastRefill = now;

    // Check if we can consume a token
    const allowed = bucket.tokens >= 1;
    
    if (allowed) {
      bucket.tokens -= 1;
    }

    // Save updated bucket
    await this.store.set(key, bucket, config.windowMs);

    // Calculate reset time
    const tokensNeeded = allowed ? 0 : 1 - bucket.tokens;
    const resetTime = now + (tokensNeeded / refillRate);

    return {
      allowed,
      remaining: Math.floor(bucket.tokens),
      resetTime: Math.ceil(resetTime),
      limit: effectiveLimit,
    };
  }

  /**
   * Express middleware
   */
  middleware() {
    return async (req: Request, res: Response, next: NextFunction) => {
      const result = await this.checkLimit(req);

      // Set rate limit headers
      res.setHeader('X-RateLimit-Limit', result.limit);
      res.setHeader('X-RateLimit-Remaining', result.remaining);
      res.setHeader('X-RateLimit-Reset', result.resetTime);

      if (!result.allowed) {
        res.setHeader('Retry-After', Math.ceil((result.resetTime - Date.now()) / 1000));
        
        const config = this.getEndpointConfig(req.path);
        
        if (config.handler) {
          return config.handler(req, res, next);
        }

        return res.status(429).json({
          error: config.message,
          retryAfter: Math.ceil((result.resetTime - Date.now()) / 1000),
        });
      }

      next();
    };
  }

  /**
   * Sliding window counter for more accurate limiting
   */
  async checkSlidingWindow(
    key: string,
    windowMs: number,
    maxRequests: number
  ): Promise<{ allowed: boolean; count: number }> {
    const now = Date.now();
    const windowStart = now - windowMs;
    
    // This would ideally use Redis sorted sets
    // For in-memory, we'll use a simplified approach
    const count = await this.store.increment(`sliding:${key}:${Math.floor(now / windowMs)}`);

    return {
      allowed: count <= maxRequests,
      count,
    };
  }

  /**
   * IP-based blocking for repeated violations
   */
  private blockedIPs: Map<string, number> = new Map();
  private violationCounts: Map<string, number> = new Map();

  async recordViolation(ip: string): Promise<void> {
    const count = (this.violationCounts.get(ip) || 0) + 1;
    this.violationCounts.set(ip, count);

    // Block IP after 10 violations within 1 hour
    if (count >= 10) {
      const blockUntil = Date.now() + 3600000; // 1 hour
      this.blockedIPs.set(ip, blockUntil);
      this.violationCounts.delete(ip);
    }
  }

  isIPBlocked(ip: string): boolean {
    const blockUntil = this.blockedIPs.get(ip);
    if (!blockUntil) return false;
    
    if (Date.now() > blockUntil) {
      this.blockedIPs.delete(ip);
      return false;
    }
    
    return true;
  }

  /**
   * DDoS protection middleware
   */
  ddosProtection() {
    const requestCounts: Map<string, number[]> = new Map();
    const WINDOW_SIZE = 1000; // 1 second
    const MAX_REQUESTS_PER_SECOND = 50;

    return (req: Request, res: Response, next: NextFunction) => {
      const ip = req.ip || req.socket.remoteAddress || 'unknown';
      
      // Check if IP is blocked
      if (this.isIPBlocked(ip)) {
        return res.status(403).json({
          error: 'Access temporarily blocked due to suspicious activity',
        });
      }

      const now = Date.now();
      const requests = requestCounts.get(ip) || [];
      
      // Remove old requests
      const recentRequests = requests.filter(t => now - t < WINDOW_SIZE);
      recentRequests.push(now);
      requestCounts.set(ip, recentRequests);

      if (recentRequests.length > MAX_REQUESTS_PER_SECOND) {
        this.recordViolation(ip);
        return res.status(429).json({
          error: 'Request rate too high',
        });
      }

      next();
    };
  }
}

// Create and export default rate limiter
export const rateLimiter = new RateLimiterService();

// Convenience middleware functions
export const apiRateLimiter = rateLimiter.middleware();
export const ddosProtection = rateLimiter.ddosProtection();

// Specific limiters for different endpoint types
export const authRateLimiter = new RateLimiterService(undefined, {
  windowMs: 60000,
  maxRequests: 5,
  message: 'Too many authentication attempts. Please try again later.',
}).middleware();

export const paymentRateLimiter = new RateLimiterService(undefined, {
  windowMs: 60000,
  maxRequests: 10,
  message: 'Too many payment requests. Please try again later.',
}).middleware();

export const adminRateLimiter = new RateLimiterService(undefined, {
  windowMs: 60000,
  maxRequests: 200,
}).middleware();

/**
 * Restaurant Table Management Service
 * 
 * Handles table reservations, visual floor plan, and kitchen display integration.
 */

import { getSupabase } from '../database/connection.js';
import { logger } from '../utils/logger.js';
import { io } from '../config/socket.js';

export enum TableStatus {
  AVAILABLE = 'AVAILABLE',
  OCCUPIED = 'OCCUPIED',
  RESERVED = 'RESERVED',
  CLEANING = 'CLEANING',
  OUT_OF_SERVICE = 'OUT_OF_SERVICE',
}

export enum ReservationStatus {
  PENDING = 'PENDING',
  CONFIRMED = 'CONFIRMED',
  SEATED = 'SEATED',
  COMPLETED = 'COMPLETED',
  CANCELLED = 'CANCELLED',
  NO_SHOW = 'NO_SHOW',
}

interface TablePosition {
  x: number;
  y: number;
  rotation: number;
  width: number;
  height: number;
  shape: 'rectangle' | 'circle' | 'square';
}

interface TableReservation {
  id: string;
  guestName: string;
  partySize: number;
  time: string;
  status: ReservationStatus;
}

interface TableOrder {
  id: string;
  status: string;
  total: number;
}

interface TableInfo {
  id: string;
  number: number;
  name: string;
  capacity: number;
  minCapacity: number;
  status: TableStatus;
  position: TablePosition;
  section: string | null;
  features: string[];
  currentReservation?: TableReservation;
  currentOrder?: TableOrder;
}

interface CreateReservationInput {
  tableId?: string;
  date: Date;
  time: string;
  partySize: number;
  guestName: string;
  guestPhone: string;
  guestEmail?: string;
  specialRequests?: string;
  userId?: string;
}

interface ReservationResult {
  success: boolean;
  message: string;
  reservation?: TableReservation;
}

interface TableFilterOptions {
  status?: TableStatus | { not: TableStatus };
  section?: string;
  minCapacity?: number;
  maxCapacity?: number;
}

interface RestaurantTable {
  id: string;
  number: number;
  name: string;
  capacity: number;
  min_capacity: number;
  status: string;
  position: TablePosition | unknown;
  section: string | null;
  features: unknown;
  currentReservation?: TableReservation[];
  currentOrder?: TableOrder[];
}

interface SystemSetting {
  key: string;
  value?: string;
}

interface ReservationRecord {
  table_id: string;
}

/**
 * Get all tables with current status
 */
export async function getAllTables(
  includeOutOfService: boolean = false
): Promise<TableInfo[]> {
  const supabase = getSupabase();
  const today = new Date().toISOString().split('T')[0];

  let query = supabase
    .from('restaurant_tables')
    .select('*')
    .order('number', { ascending: true });

  if (!includeOutOfService) {
    query = query.neq('status', TableStatus.OUT_OF_SERVICE);
  }

  const { data: tables, error } = await query;
  if (error) throw error;

  // Fetch current reservations for today
  const tableIds = (tables || []).map((t: any) => t.id);
  const { data: reservations } = await supabase
    .from('table_reservations')
    .select('*')
    .in('table_id', tableIds)
    .in('status', [ReservationStatus.CONFIRMED, ReservationStatus.SEATED])
    .eq('date', today);

  // Fetch current orders
  const { data: orders } = await supabase
    .from('orders')
    .select('*')
    .in('table_id', tableIds)
    .in('status', ['PENDING', 'IN_PROGRESS']);

  return (tables || []).map((table: any) => {
    const tableReservations = (reservations || []).filter((r: any) => r.table_id === table.id);
    const tableOrders = (orders || []).filter((o: any) => o.table_id === table.id);
    return {
      id: table.id,
      number: table.number,
      name: table.name,
      capacity: table.capacity,
      minCapacity: table.min_capacity,
      status: table.status as TableStatus,
      position: (table.position as unknown as TablePosition) || { x: 0, y: 0, rotation: 0, width: 60, height: 60, shape: 'rectangle' },
      section: table.section || 'main',
      features: (table.features as unknown as string[]) || [],
      currentReservation: tableReservations[0] ? {
          ...tableReservations[0],
          status: tableReservations[0].status as ReservationStatus
      } : undefined,
      currentOrder: tableOrders[0],
    };
  });
}

/**
 * Get available tables for a specific date/time and party size
 */
export async function getAvailableTables(
  date: string,
  time: string,
  partySize: number
): Promise<TableInfo[]> {
  const supabase = getSupabase();

  // Get all tables that can accommodate the party
  const { data: tables, error: tablesError } = await supabase
    .from('restaurant_tables')
    .select('*')
    .neq('status', TableStatus.OUT_OF_SERVICE)
    .gte('capacity', partySize)
    .lte('min_capacity', partySize);
  if (tablesError) throw tablesError;

  // Calculate time window (2 hours for reservation)
  const reservationStart = new Date(`${date}T${time}`);
  const reservationEnd = new Date(reservationStart.getTime() + 2 * 60 * 60 * 1000);

  // Find tables with conflicting reservations
  const { data: conflictingReservations, error: conflictError } = await supabase
    .from('table_reservations')
    .select('table_id')
    .eq('date', date)
    .in('status', [ReservationStatus.PENDING, ReservationStatus.CONFIRMED])
    .gte('time', time)
    .lte('end_time', new Date(reservationEnd).toTimeString().slice(0, 5));
  if (conflictError) throw conflictError;

  const bookedTableIds = new Set((conflictingReservations || []).map((r: ReservationRecord) => r.table_id));

  return (tables || [])
    .filter((table: RestaurantTable) => !bookedTableIds.has(table.id))
    .map((table: RestaurantTable) => ({
      id: table.id,
      number: table.number,
      name: table.name,
      capacity: table.capacity,
      minCapacity: table.min_capacity,
      status: TableStatus.AVAILABLE,
      position: table.position as TablePosition,
      section: table.section,
      features: table.features as string[],
    }));
}

/**
 * Create a table reservation
 */
export async function createReservation(
  input: CreateReservationInput
): Promise<ReservationResult> {
  try {
    // Find available table if not specified
    let tableId = input.tableId;
    
    if (!tableId) {
      const availableTables = await getAvailableTables(
        input.date.toISOString().split('T')[0],
        input.time,
        input.partySize
      );

      if (availableTables.length === 0) {
        return {
          success: false,
          message: 'No tables available for the requested time and party size',
        };
      }

      // Select the smallest table that fits
      const sortedTables = availableTables.sort((a, b) => a.capacity - b.capacity);
      tableId = sortedTables[0].id;
    }

    // Verify table availability
    const supabase = getSupabase();
    const { data: existingReservation, error: existingError } = await supabase
      .from('table_reservations')
      .select('id')
      .eq('table_id', tableId)
      .eq('date', input.date.toISOString().split('T')[0])
      .eq('time', input.time)
      .in('status', [ReservationStatus.PENDING, ReservationStatus.CONFIRMED])
      .limit(1)
      .maybeSingle();
    if (existingError) throw existingError;

    if (existingReservation) {
      return {
        success: false,
        message: 'Table is already reserved for this time',
      };
    }

    // Calculate end time (2 hours default)
    const startTime = new Date(`${input.date.toISOString().split('T')[0]}T${input.time}`);
    const endTime = new Date(startTime.getTime() + 2 * 60 * 60 * 1000);

    // Create reservation
    const { data: reservation, error: createError } = await supabase
      .from('table_reservations')
      .insert({
        table_id: tableId,
        date: input.date.toISOString().split('T')[0],
        time: input.time,
        end_time: endTime.toTimeString().slice(0, 5),
        party_size: input.partySize,
        guest_name: input.guestName,
        guest_phone: input.guestPhone,
        guest_email: input.guestEmail,
        special_requests: input.specialRequests,
        user_id: input.userId,
        status: ReservationStatus.PENDING,
      })
      .select('*, table:restaurant_tables(*)')
      .single();
    if (createError) throw createError;

    // Notify staff via WebSocket
    io.to('restaurant-staff').emit('new-reservation', {
      id: reservation.id,
      table: reservation.table.name,
      time: reservation.time,
      partySize: reservation.party_size,
      guestName: reservation.guest_name,
    });

    logger.info('Reservation created', {
      reservationId: reservation.id,
      tableId,
      date: input.date,
      time: input.time,
    });

    return {
      success: true,
      message: 'Reservation created successfully',
      reservation: {
        ...reservation,
        status: reservation.status as ReservationStatus
      },
    };
  } catch (error: any) {
    logger.error('Failed to create reservation', { error: error.message });
    throw error;
  }
}

/**
 * Update table status
 */
export async function updateTableStatus(
  tableId: string,
  status: TableStatus,
  staffId?: string
): Promise<void> {
  const supabase = getSupabase();
  const { error } = await supabase
    .from('restaurant_tables')
    .update({
      status,
      last_status_change: new Date().toISOString(),
      last_status_changed_by: staffId,
    })
    .eq('id', tableId);
  if (error) throw error;

  // Notify via WebSocket
  io.to('restaurant-staff').emit('table-status-changed', {
    tableId,
    status,
    timestamp: new Date(),
  });

  logger.info('Table status updated', { tableId, status, staffId });
}

/**
 * Seat guests (mark reservation as seated)
 */
export async function seatGuests(
  reservationId: string,
  staffId: string
): Promise<ReservationResult> {
  const supabase = getSupabase();
  const { data: reservation, error: reservationError } = await supabase
    .from('table_reservations')
    .select('*, table:restaurant_tables(*)')
    .eq('id', reservationId)
    .maybeSingle();
  if (reservationError) throw reservationError;

  if (!reservation) {
    return { success: false, message: 'Reservation not found' };
  }

  if (reservation.status !== ReservationStatus.CONFIRMED) {
    return { success: false, message: 'Reservation is not confirmed' };
  }

  // Update reservation and table (sequential calls replacing $transaction)
  const { error: updateReservationError } = await supabase
    .from('table_reservations')
    .update({
      status: ReservationStatus.SEATED,
      seated_at: new Date().toISOString(),
      seated_by: staffId,
    })
    .eq('id', reservationId);
  if (updateReservationError) throw updateReservationError;

  const { error: updateTableError } = await supabase
    .from('restaurant_tables')
    .update({ status: TableStatus.OCCUPIED })
    .eq('id', reservation.table_id);
  if (updateTableError) throw updateTableError;

  // Notify kitchen
  io.to('kitchen').emit('table-seated', {
    tableId: reservation.table_id,
    tableName: reservation.table.name,
    partySize: reservation.party_size,
  });

  logger.info('Guests seated', { reservationId, tableId: reservation.table_id });

  return { success: true, message: 'Guests seated successfully' };
}

/**
 * Complete a table session (guests leaving)
 */
export async function completeTable(
  tableId: string,
  staffId: string
): Promise<void> {
  const supabase = getSupabase();
  const { data: table, error: tableError } = await supabase
    .from('restaurant_tables')
    .select('*')
    .eq('id', tableId)
    .maybeSingle();
  if (tableError) throw tableError;

  if (!table) {
    throw new Error('Table not found');
  }

  // Get seated reservations for this table
  const { data: seatedReservations, error: resError } = await supabase
    .from('table_reservations')
    .select('*')
    .eq('table_id', tableId)
    .eq('status', ReservationStatus.SEATED);
  if (resError) throw resError;

  // Complete reservation if exists (sequential calls replacing $transaction)
  if (seatedReservations && seatedReservations.length > 0) {
    const { error: completeResError } = await supabase
      .from('table_reservations')
      .update({
        status: ReservationStatus.COMPLETED,
        completed_at: new Date().toISOString(),
      })
      .eq('id', seatedReservations[0].id);
    if (completeResError) throw completeResError;
  }

  // Set table to cleaning
  const { error: updateTableError } = await supabase
    .from('restaurant_tables')
    .update({ status: TableStatus.CLEANING })
    .eq('id', tableId);
  if (updateTableError) throw updateTableError;

  // Notify staff
  io.to('restaurant-staff').emit('table-needs-cleaning', {
    tableId,
    tableName: table.name,
  });

  logger.info('Table completed', { tableId, staffId });
}

/**
 * Get floor plan configuration
 */
export async function getFloorPlan(): Promise<{
  tables: TableInfo[];
  sections: string[];
  dimensions: { width: number; height: number };
}> {
  const tables = await getAllTables(true);
  const sections = [...new Set(tables.map(t => t.section))].filter((s): s is string => s !== null);
  
  // Get floor plan dimensions from settings
  const supabase = getSupabase();
  const { data: settings, error } = await supabase
    .from('system_settings')
    .select('*')
    .like('key', 'restaurant.floorPlan.%');
  if (error) throw error;

  const dimensions = {
    width: parseInt((settings || []).find((s: SystemSetting) => s.key === 'restaurant.floorPlan.width')?.value || '800'),
    height: parseInt((settings || []).find((s: SystemSetting) => s.key === 'restaurant.floorPlan.height')?.value || '600'),
  };

  return { tables, sections, dimensions };
}

/**
 * Update table position (for floor plan editor)
 */
export async function updateTablePosition(
  tableId: string,
  position: Partial<TablePosition>,
  staffId: string
): Promise<void> {
  const supabase = getSupabase();
  const { data: table, error: tableError } = await supabase
    .from('restaurant_tables')
    .select('*')
    .eq('id', tableId)
    .maybeSingle();
  if (tableError) throw tableError;

  if (!table) {
    throw new Error('Table not found');
  }

  const currentPosition = (table.position as unknown as TablePosition) || {
    x: 0,
    y: 0,
    rotation: 0,
    width: 60,
    height: 60,
    shape: 'rectangle',
  };

  const { error: updateError } = await supabase
    .from('restaurant_tables')
    .update({
      position: { ...currentPosition, ...position },
    })
    .eq('id', tableId);
  if (updateError) throw updateError;

  // Broadcast update
  io.to('restaurant-staff').emit('table-position-updated', {
    tableId,
    position: { ...currentPosition, ...position },
  });

  logger.info('Table position updated', { tableId, position, staffId });
}

/**
 * Get today's reservations
 */
export async function getTodaysReservations(): Promise<any[]> {
  const today = new Date().toISOString().split('T')[0];
  const supabase = getSupabase();

  const { data, error } = await supabase
    .from('table_reservations')
    .select('*, table:restaurant_tables(id, name, number)')
    .eq('date', today)
    .not('status', 'in', `(${ReservationStatus.CANCELLED},${ReservationStatus.NO_SHOW})`)
    .order('time', { ascending: true });
  if (error) throw error;

  return data || [];
}

/**
 * Cancel a reservation
 */
export async function cancelReservation(
  reservationId: string,
  reason?: string
): Promise<ReservationResult> {
  const supabase = getSupabase();
  const { data: reservation, error: resError } = await supabase
    .from('table_reservations')
    .select('*')
    .eq('id', reservationId)
    .maybeSingle();
  if (resError) throw resError;

  if (!reservation) {
    return { success: false, message: 'Reservation not found' };
  }

  if (reservation.status === ReservationStatus.CANCELLED) {
    return { success: false, message: 'Reservation is already cancelled' };
  }

  const { error: updateError } = await supabase
    .from('table_reservations')
    .update({
      status: ReservationStatus.CANCELLED,
      cancelled_at: new Date().toISOString(),
      cancellation_reason: reason,
    })
    .eq('id', reservationId);
  if (updateError) throw updateError;

  logger.info('Reservation cancelled', { reservationId, reason });

  return { success: true, message: 'Reservation cancelled' };
}

/**
 * Mark reservation as no-show
 */
export async function markNoShow(
  reservationId: string,
  staffId: string
): Promise<void> {
  const supabase = getSupabase();
  const { error } = await supabase
    .from('table_reservations')
    .update({
      status: ReservationStatus.NO_SHOW,
      no_show_marked_at: new Date().toISOString(),
      no_show_marked_by: staffId,
    })
    .eq('id', reservationId);
  if (error) throw error;

  logger.info('Reservation marked as no-show', { reservationId, staffId });
}

/**
 * Confirm a pending reservation
 */
export async function confirmReservation(
  reservationId: string,
  staffId: string
): Promise<ReservationResult> {
  const supabase = getSupabase();
  const { data: reservation, error: resError } = await supabase
    .from('table_reservations')
    .select('*')
    .eq('id', reservationId)
    .maybeSingle();
  if (resError) throw resError;

  if (!reservation) {
    return { success: false, message: 'Reservation not found' };
  }

  if (reservation.status !== ReservationStatus.PENDING) {
    return { success: false, message: 'Reservation is not pending' };
  }

  const { error: updateError } = await supabase
    .from('table_reservations')
    .update({
      status: ReservationStatus.CONFIRMED,
      confirmed_at: new Date().toISOString(),
      confirmed_by: staffId,
    })
    .eq('id', reservationId);
  if (updateError) throw updateError;

  logger.info('Reservation confirmed', { reservationId, staffId });

  return { success: true, message: 'Reservation confirmed' };
}

