const SERVICE_VERSION = process.env.SERVICE_VERSION || '1.0.0';
const OTEL_EXPORTER_URL = process.env.OTEL_EXPORTER_OTLP_ENDPOINT || 'http://localhost:4318/v1/traces';
const ENVIRONMENT = process.env.NODE_ENV || 'development';

let tracerProvider: NodeTracerProvider | null = null;
let tracer: Tracer | null = null;

/**
 * Initialize distributed tracing
 */
export function initializeTracing(): void {
  if (tracerProvider) {
    console.log('[Tracing] Already initialized');
    return;
  }

  // Create resource describing this service
  const resource = resourceFromAttributes({
    [SemanticResourceAttributes.SERVICE_NAME]: SERVICE_NAME,
    [SemanticResourceAttributes.SERVICE_VERSION]: SERVICE_VERSION,
    [SemanticResourceAttributes.DEPLOYMENT_ENVIRONMENT]: ENVIRONMENT,
  });

  // Create tracer provider
  tracerProvider = new NodeTracerProvider({ resource: resource as any });

  // Configure exporter
  const exporter = new OTLPTraceExporter({
    url: OTEL_EXPORTER_URL,
    headers: {
      'x-api-key': process.env.OTEL_API_KEY || '',
    },
  });

  // Use batch processor in production, simple in development
  const spanProcessor = ENVIRONMENT === 'production'
    ? new BatchSpanProcessor(exporter as any, {
        maxQueueSize: 1000,
        maxExportBatchSize: 100,
        scheduledDelayMillis: 5000,
      })
    : new SimpleSpanProcessor(exporter as any);

  (tracerProvider as any).addSpanProcessor(spanProcessor);

  // Set up propagation (W3C Trace Context)
  propagation.setGlobalPropagator(new W3CTraceContextPropagator());

  // Register the provider globally
  tracerProvider.register();

  // Register automatic instrumentations
  registerInstrumentations({
    tracerProvider,
    instrumentations: [
      new HttpInstrumentation({
        ignoreIncomingRequestHook: (request) => {
          // Ignore health checks and static files
          const url = request.url || '';
          return url.includes('/health') || url.includes('/static/');
        },
        requestHook: (span, request) => {
          // Add custom attributes
          span.setAttribute('http.request_id', (request as any).headers?.['x-request-id'] || '');
          span.setAttribute('http.correlation_id', (request as any).headers?.['x-correlation-id'] || '');
        },
      }),
      new ExpressInstrumentation({
        ignoreLayers: ['/health', '/metrics'],
        requestHook: (span, info) => {
          span.setAttribute('express.route', info.route || 'unknown');
        },
      }),
      new PgInstrumentation({
        enhancedDatabaseReporting: true,
      }),
      new RedisInstrumentation({
        dbStatementSerializer: (cmdName, cmdArgs) => {
          // Don't log full Redis commands with sensitive data
          return `${cmdName} [${cmdArgs.length} args]`;
        },
      }),
    ],
  });

  tracer = trace.getTracer(SERVICE_NAME, SERVICE_VERSION);

  console.log(`[Tracing] Initialized for ${SERVICE_NAME} v${SERVICE_VERSION}`);
  console.log(`[Tracing] Exporting to ${OTEL_EXPORTER_URL}`);
}

/**
 * Get the tracer instance
 */
export function getTracer(): Tracer {
  if (!tracer) {
    initializeTracing();
  }
  return tracer || trace.getTracer(SERVICE_NAME);
}

/**
 * Create a new span for a custom operation
 */
export function createSpan(
  name: string,
  options: {
    kind?: SpanKind;
    attributes?: Record<string, string | number | boolean>;
    parent?: Span;
  } = {}
): Span {
  const t = getTracer();
  
  const spanOptions: any = {
    kind: options.kind || SpanKind.INTERNAL,
    attributes: options.attributes,
  };

  if (options.parent) {
    const ctx = trace.setSpan(context.active(), options.parent);
    return t.startSpan(name, spanOptions, ctx);
  }

  return t.startSpan(name, spanOptions);
}

/**
 * Wrap an async function with tracing
 */
export async function withSpan<T>(
  name: string,
  fn: (span: Span) => Promise<T>,
  options: {
    kind?: SpanKind;
    attributes?: Record<string, string | number | boolean>;
  } = {}
): Promise<T> {
  const span = createSpan(name, options);

  try {
    const result = await context.with(
      trace.setSpan(context.active(), span),
      () => fn(span)
    );
    span.setStatus({ code: SpanStatusCode.OK });
    return result;
  } catch (error: any) {
    span.setStatus({
      code: SpanStatusCode.ERROR,
      message: error.message,
    });
    span.recordException(error);
    throw error;
  } finally {
    span.end();
  }
}

/**
 * Wrap a sync function with tracing
 */
export function withSpanSync<T>(
  name: string,
  fn: (span: Span) => T,
  options: {
    kind?: SpanKind;
    attributes?: Record<string, string | number | boolean>;
  } = {}
): T {
  const span = createSpan(name, options);

  try {
    const result = fn(span);
    span.setStatus({ code: SpanStatusCode.OK });
    return result;
  } catch (error: any) {
    span.setStatus({
      code: SpanStatusCode.ERROR,
      message: error.message,
    });
    span.recordException(error);
    throw error;
  } finally {
    span.end();
  }
}

/**
 * Add event to current span
 */
export function addSpanEvent(
  name: string,
  attributes?: Record<string, string | number | boolean>
): void {
  const currentSpan = trace.getSpan(context.active());
  if (currentSpan) {
    currentSpan.addEvent(name, attributes);
  }
}

/**
 * Add attributes to current span
 */
export function addSpanAttributes(
  attributes: Record<string, string | number | boolean>
): void {
  const currentSpan = trace.getSpan(context.active());
  if (currentSpan) {
    currentSpan.setAttributes(attributes);
  }
}

/**
 * Get current trace ID
 */
export function getCurrentTraceId(): string | null {
  const currentSpan = trace.getSpan(context.active());
  if (!currentSpan) return null;

  const spanContext = currentSpan.spanContext();
  return spanContext.traceId;
}

/**
 * Get current span ID
 */
export function getCurrentSpanId(): string | null {
  const currentSpan = trace.getSpan(context.active());
  if (!currentSpan) return null;

  const spanContext = currentSpan.spanContext();
  return spanContext.spanId;
}

/**
 * Express middleware for manual span management
 */
export function tracingMiddleware() {
  return (req: any, res: any, next: any) => {
    const t = getTracer();

    const span = t.startSpan(`HTTP ${req.method} ${req.path}`, {
      kind: SpanKind.SERVER,
      attributes: {
        'http.method': req.method,
        'http.url': req.originalUrl,
        'http.target': req.path,
        'http.host': req.hostname,
        'http.user_agent': req.headers['user-agent'] || 'unknown',
        'user.id': req.user?.id || 'anonymous',
      },
    });

    // Store span and trace IDs on request
    req.span = span;
    req.traceId = span.spanContext().traceId;
    req.spanId = span.spanContext().spanId;

    // Add trace ID to response headers
    res.setHeader('X-Trace-Id', req.traceId);

    // Run in span context
    context.with(trace.setSpan(context.active(), span), () => {
      // Capture response
      const originalEnd = res.end;
      res.end = function (...args: any[]) {
        span.setAttribute('http.status_code', res.statusCode);

        if (res.statusCode >= 400) {
          span.setStatus({
            code: SpanStatusCode.ERROR,
            message: `HTTP ${res.statusCode}`,
          });
        } else {
          span.setStatus({ code: SpanStatusCode.OK });
        }

        span.end();
        return originalEnd.apply(this, args);
      };

      next();
    });
  };
}

/**
 * Create traces for specific operations
 */
export const traces = {
  /**
   * Trace a database query
   */
  async dbQuery<T>(
    operation: string,
    table: string,
    fn: () => Promise<T>
  ): Promise<T> {
    return withSpan(`db.${operation}`, async (span) => {
      span.setAttribute('db.system', 'postgresql');
      span.setAttribute('db.operation', operation);
      span.setAttribute('db.table', table);
      return fn();
    }, { kind: SpanKind.CLIENT });
  },

  /**
   * Trace an external API call
   */
  async externalApi<T>(
    service: string,
    operation: string,
    fn: () => Promise<T>
  ): Promise<T> {
    return withSpan(`external.${service}.${operation}`, async (span) => {
      span.setAttribute('peer.service', service);
      span.setAttribute('rpc.method', operation);
      return fn();
    }, { kind: SpanKind.CLIENT });
  },

  /**
   * Trace a cache operation
   */
  async cache<T>(
    operation: 'get' | 'set' | 'delete',
    key: string,
    fn: () => Promise<T>
  ): Promise<T> {
    return withSpan(`cache.${operation}`, async (span) => {
      span.setAttribute('db.system', 'redis');
      span.setAttribute('db.operation', operation);
      span.setAttribute('cache.key', key.split(':')[0]); // Only log key prefix
      return fn();
    }, { kind: SpanKind.CLIENT });
  },

  /**
   * Trace business logic
   */
  async business<T>(
    domain: string,
    operation: string,
    fn: (span: Span) => Promise<T>
  ): Promise<T> {
    return withSpan(`${domain}.${operation}`, fn, {
      kind: SpanKind.INTERNAL,
      attributes: {
        'business.domain': domain,
        'business.operation': operation,
      },
    });
  },
};

/**
 * Shutdown tracing
 */
export async function shutdownTracing(): Promise<void> {
  if (tracerProvider) {
    await tracerProvider.shutdown();
    tracerProvider = null;
    tracer = null;
    console.log('[Tracing] Shutdown complete');
  }
}

// Auto-initialize in production
if (process.env.NODE_ENV === 'production' && process.env.OTEL_ENABLED === 'true') {
  initializeTracing();
}

/**
 * Auto-translation service supporting multiple providers:
 * 
 * 1. GOOGLE TRANSLATE (Recommended - Most Reliable)
 *    - Set GOOGLE_TRANSLATE_API_KEY in your .env
 *    - Get an API key from: https://console.cloud.google.com/apis/credentials
 *    - Enable "Cloud Translation API" in your Google Cloud project
 *    - Cost: ~$20 per 1 million characters
 * 
 * 2. LIBRE TRANSLATE (Free / Self-Hosted)
 *    - Set LIBRE_TRANSLATE_URL and optionally LIBRE_TRANSLATE_KEY
 *    - Public API: https://libretranslate.com (rate limited, may require key)
 *    - Self-hosted: https://github.com/LibreTranslate/LibreTranslate
 * 
 * 3. FALLBACK (No API Required)
 *    - Uses built-in dictionary for common hospitality terms
 *    - Limited vocabulary, returns original text for unknown phrases
 */

import { logger } from '../utils/logger.js';

// Provider configuration
const TRANSLATION_PROVIDER = process.env.TRANSLATION_PROVIDER || 'auto'; // 'google', 'libre', 'fallback', 'auto'
const GOOGLE_TRANSLATE_API_KEY = process.env.GOOGLE_TRANSLATE_API_KEY || '';
const LIBRE_TRANSLATE_URL = process.env.LIBRE_TRANSLATE_URL || 'https://libretranslate.com/translate';
const LIBRE_TRANSLATE_KEY = process.env.LIBRE_TRANSLATE_KEY || '';

interface TranslationResult {
  en: string;
  ar: string;
  fr: string;
}

// Basic translation cache to avoid repeated API calls
const translationCache = new Map<string, TranslationResult>();

// Common words/phrases translation mapping for fallback
const fallbackTranslations: Record<string, { ar: string; fr: string }> = {
  // Food items
  'hummus': { ar: 'حمص', fr: 'houmous' },
  'falafel': { ar: 'فلافل', fr: 'falafel' },
  'shawarma': { ar: 'شاورما', fr: 'shawarma' },
  'kebab': { ar: 'كباب', fr: 'kebab' },
  'tabbouleh': { ar: 'تبولة', fr: 'taboulé' },
  'fattoush': { ar: 'فتوش', fr: 'fatouche' },
  'kibbeh': { ar: 'كبة', fr: 'kebbé' },
  'baklava': { ar: 'بقلاوة', fr: 'baklava' },
  'coffee': { ar: 'قهوة', fr: 'café' },
  'tea': { ar: 'شاي', fr: 'thé' },
  'juice': { ar: 'عصير', fr: 'jus' },
  'water': { ar: 'ماء', fr: 'eau' },
  'sandwich': { ar: 'ساندويتش', fr: 'sandwich' },
  'salad': { ar: 'سلطة', fr: 'salade' },
  'soup': { ar: 'شوربة', fr: 'soupe' },
  'grilled': { ar: 'مشوي', fr: 'grillé' },
  'fresh': { ar: 'طازج', fr: 'frais' },
  'traditional': { ar: 'تقليدي', fr: 'traditionnel' },
  'delicious': { ar: 'لذيذ', fr: 'délicieux' },
  // Common descriptions
  'served with': { ar: 'يقدم مع', fr: 'servi avec' },
  'fresh vegetables': { ar: 'خضروات طازجة', fr: 'légumes frais' },
  'homemade': { ar: 'منزلي', fr: 'fait maison' },
  'chef special': { ar: 'خاص الشيف', fr: 'spécial du chef' },
  // Sizes
  'small': { ar: 'صغير', fr: 'petit' },
  'medium': { ar: 'وسط', fr: 'moyen' },
  'large': { ar: 'كبير', fr: 'grand' },
  // Categories
  'appetizers': { ar: 'المقبلات', fr: 'entrées' },
  'main courses': { ar: 'الأطباق الرئيسية', fr: 'plats principaux' },
  'desserts': { ar: 'الحلويات', fr: 'desserts' },
  'beverages': { ar: 'المشروبات', fr: 'boissons' },
  'drinks': { ar: 'مشروبات', fr: 'boissons' },
  'snacks': { ar: 'وجبات خفيفة', fr: 'collations' },
};

export async function translateText(text: string, sourceLang: string = 'en'): Promise<TranslationResult> {
  // Check cache first
  const cacheKey = `${text}-${sourceLang}`;
  if (translationCache.has(cacheKey)) {
    return translationCache.get(cacheKey)!;
  }

  const result: TranslationResult = {
    en: sourceLang === 'en' ? text : text,
    ar: '',
    fr: '',
  };

  // Try API translation
  try {
    if (sourceLang !== 'ar') {
      result.ar = await callTranslateAPI(text, sourceLang, 'ar');
    } else {
      result.ar = text;
    }

    if (sourceLang !== 'fr') {
      result.fr = await callTranslateAPI(text, sourceLang, 'fr');
    } else {
      result.fr = text;
    }

    if (sourceLang !== 'en') {
      result.en = await callTranslateAPI(text, sourceLang, 'en');
    }
  } catch (error) {
    logger.warn('[TRANSLATION] API failed, using fallback:', error);
    // Fallback to basic translation
    const fallback = fallbackTranslations[text.toLowerCase()];
    if (fallback) {
      result.ar = fallback.ar;
      result.fr = fallback.fr;
    } else {
      // Return original text with language indicators
      result.ar = result.ar || text;
      result.fr = result.fr || text;
    }
  }

  // Cache the result
  translationCache.set(cacheKey, result);
  return result;
}

/**
 * Determine which translation provider to use
 */
function getActiveProvider(): 'google' | 'libre' | 'fallback' {
  if (TRANSLATION_PROVIDER === 'google' && GOOGLE_TRANSLATE_API_KEY) {
    return 'google';
  }
  if (TRANSLATION_PROVIDER === 'libre') {
    return 'libre';
  }
  if (TRANSLATION_PROVIDER === 'fallback') {
    return 'fallback';
  }
  // Auto-detect: prefer Google if key exists, then Libre, then fallback
  if (GOOGLE_TRANSLATE_API_KEY) {
    return 'google';
  }
  if (LIBRE_TRANSLATE_KEY || LIBRE_TRANSLATE_URL !== 'https://libretranslate.com/translate') {
    return 'libre';
  }
  return 'fallback';
}

/**
 * Call the appropriate translation API based on configuration
 */
async function callTranslateAPI(text: string, source: string, target: string): Promise<string> {
  // Skip if text is empty or very short
  if (!text || text.length < 2) return text;

  const provider = getActiveProvider();
  
  if (provider === 'fallback') {
    // Use fallback dictionary
    const fallback = fallbackTranslations[text.toLowerCase()];
    if (fallback) {
      return target === 'ar' ? fallback.ar : fallback.fr;
    }
    logger.debug(`[TRANSLATION] No fallback for "${text}", returning original`);
    return text;
  }

  if (provider === 'google') {
    return callGoogleTranslateAPI(text, source, target);
  }

  return callLibreTranslateAPI(text, source, target);
}

/**
 * Google Cloud Translation API v2
 */
async function callGoogleTranslateAPI(text: string, source: string, target: string): Promise<string> {
  const url = `https://translation.googleapis.com/language/translate/v2?key=${GOOGLE_TRANSLATE_API_KEY}`;
  
  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      q: text,
      source,
      target,
      format: 'text',
    }),
  });

  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    const errorMsg = (errorData as { error?: { message?: string } })?.error?.message || response.statusText;
    throw new Error(`Google Translate API error: ${response.status} - ${errorMsg}`);
  }

  const data = await response.json() as { 
    data?: { translations?: Array<{ translatedText?: string }> } 
  };
  
  return data?.data?.translations?.[0]?.translatedText || text;
}

/**
 * LibreTranslate API (free / self-hosted)
 */
async function callLibreTranslateAPI(text: string, source: string, target: string): Promise<string> {
  const response = await fetch(LIBRE_TRANSLATE_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      q: text,
      source,
      target,
      api_key: LIBRE_TRANSLATE_KEY || undefined,
    }),
  });

  if (!response.ok) {
    let bodyText = '';
    try {
      bodyText = await response.text();
    } catch {
      // Ignore - bodyText will remain empty if response body can't be read
    }
    throw new Error(`LibreTranslate API error: ${response.status} ${bodyText}`);
  }

  const data = await response.json() as { translatedText?: string };
  return data.translatedText || text;
}

// Batch translate multiple texts at once
export async function batchTranslate(texts: string[], sourceLang: string = 'en'): Promise<TranslationResult[]> {
  return Promise.all(texts.map(text => translateText(text, sourceLang)));
}

// Helper to create a translatable item (for menu items, chalets, etc.)
export function createTranslatableFields<T extends Record<string, any>>(
  item: T,
  translations: TranslationResult,
  fieldName: string
): T {
  return {
    ...item,
    [fieldName]: translations.en,
    [`${fieldName}_ar`]: translations.ar,
    [`${fieldName}_fr`]: translations.fr,
  };
}

/**
 * Get the current translation service status
 */
export function getTranslationStatus(): {
  provider: string;
  configured: boolean;
  apiKeySet: boolean;
  message: string;
} {
  const provider = getActiveProvider();
  
  if (provider === 'google') {
    return {
      provider: 'Google Translate',
      configured: true,
      apiKeySet: true,
      message: 'Google Translate API is configured and ready',
    };
  }
  
  if (provider === 'libre') {
    const hasKey = !!LIBRE_TRANSLATE_KEY;
    const isCustomUrl = LIBRE_TRANSLATE_URL !== 'https://libretranslate.com/translate';
    return {
      provider: 'LibreTranslate',
      configured: true,
      apiKeySet: hasKey || isCustomUrl,
      message: isCustomUrl 
        ? `Using custom LibreTranslate at ${LIBRE_TRANSLATE_URL}`
        : hasKey 
          ? 'LibreTranslate API key configured'
          : 'Using public LibreTranslate (may be rate limited)',
    };
  }
  
  return {
    provider: 'Fallback Dictionary',
    configured: false,
    apiKeySet: false,
    message: 'No translation API configured. Using built-in dictionary (limited vocabulary). Set GOOGLE_TRANSLATE_API_KEY or LIBRE_TRANSLATE_KEY in your .env file for full auto-translation.',
  };
}

export default {
  translateText,
  batchTranslate,
  createTranslatableFields,
  getTranslationStatus,
};

/**
 * Two-Factor Authentication Service
 * TOTP-based 2FA using authenticator apps (Google Authenticator, Authy, etc.)
 */

import { generate, verify, generateSecret, generateURI } from 'otplib';
import QRCode from 'qrcode';
import { getSupabase } from '../database/connection.js';
import { logger } from '../utils/logger.js';
import crypto from 'crypto';

// TOTP configuration
const TOTP_OPTIONS = {
  digits: 6 as const,
  period: 30, // 30 second window
  algorithm: 'sha1' as const,
};

interface TwoFactorSetup {
  secret: string;
  qrCodeDataUrl: string;
  backupCodes: string[];
}

interface TwoFactorStatus {
  enabled: boolean;
  enabledAt?: string;
  backupCodesRemaining?: number;
}

class TwoFactorService {
  private readonly APP_NAME = 'V2 Resort';
  
  /**
   * Generate a new 2FA secret and QR code for setup
   */
  async generateSetup(userId: string, userEmail: string): Promise<TwoFactorSetup> {
    // Generate secret (v13 functional API)
    const secret = generateSecret({ length: 20 });
    
    // Generate OTP Auth URL for QR code (v13 functional API)
    const otpAuthUrl = generateURI({
      secret,
      issuer: this.APP_NAME,
      label: userEmail,
      ...TOTP_OPTIONS,
    });
    
    // Generate QR code as data URL
    const qrCodeDataUrl = await QRCode.toDataURL(otpAuthUrl, {
      width: 256,
      margin: 2,
      color: {
        dark: '#0891b2',
        light: '#ffffff',
      },
    });
    
    // Generate backup codes
    const backupCodes = this.generateBackupCodes(8);
    
    // Store pending setup in database (not yet verified)
    const supabase = getSupabase();
    await supabase
      .from('two_factor_pending')
      .upsert({
        user_id: userId,
        secret: this.encryptSecret(secret),
        backup_codes: backupCodes.map(code => this.hashBackupCode(code)),
        created_at: new Date().toISOString(),
        expires_at: new Date(Date.now() + 10 * 60 * 1000).toISOString(), // 10 min expiry
      }, {
        onConflict: 'user_id',
      });
    
    logger.info(`2FA setup initiated for user: ${userId}`);
    
    return {
      secret, // Only shown once during setup
      qrCodeDataUrl,
      backupCodes, // Only shown once
    };
  }
  
  /**
   * Verify a TOTP code and enable 2FA
   */
  async verifyAndEnable(userId: string, code: string): Promise<boolean> {
    const supabase = getSupabase();
    
    // Get pending setup
    const { data: pending, error } = await supabase
      .from('two_factor_pending')
      .select('*')
      .eq('user_id', userId)
      .single();
    
    if (error || !pending) {
      logger.warn(`No pending 2FA setup found for user: ${userId}`);
      return false;
    }
    
    // Check expiry
    if (new Date(pending.expires_at) < new Date()) {
      await supabase.from('two_factor_pending').delete().eq('user_id', userId);
      logger.warn(`2FA setup expired for user: ${userId}`);
      return false;
    }
    
    // Decrypt secret and verify code (v13 functional API)
    const secret = this.decryptSecret(pending.secret);
    const result = await verify({ token: code, secret, ...TOTP_OPTIONS });
    
    if (!result.valid) {
      logger.warn(`Invalid 2FA code during setup for user: ${userId}`);
      return false;
    }
    
    // Move to active 2FA
    await supabase.from('two_factor_auth').upsert({
      user_id: userId,
      secret: pending.secret,
      backup_codes: pending.backup_codes,
      enabled_at: new Date().toISOString(),
    }, {
      onConflict: 'user_id',
    });
    
    // Update user record
    await supabase
      .from('users')
      .update({ two_factor_enabled: true })
      .eq('id', userId);
    
    // Delete pending setup
    await supabase.from('two_factor_pending').delete().eq('user_id', userId);
    
    logger.info(`2FA enabled for user: ${userId}`);
    return true;
  }
  
  /**
   * Verify a TOTP code during login
   */
  async verifyCode(userId: string, code: string): Promise<boolean> {
    const supabase = getSupabase();
    
    // Get active 2FA
    const { data: twoFactor, error } = await supabase
      .from('two_factor_auth')
      .select('secret, backup_codes')
      .eq('user_id', userId)
      .single();
    
    if (error || !twoFactor) {
      logger.warn(`No active 2FA found for user: ${userId}`);
      return false;
    }
    
    const secret = this.decryptSecret(twoFactor.secret);
    
    // Try TOTP verification first (v13 functional API)
    const result = await verify({ token: code, secret, ...TOTP_OPTIONS });
    if (result.valid) {
      logger.info(`2FA code verified for user: ${userId}`);
      return true;
    }
    
    // Try backup codes
    const hashedCode = this.hashBackupCode(code);
    const backupCodes = twoFactor.backup_codes as string[];
    const codeIndex = backupCodes.indexOf(hashedCode);
    
    if (codeIndex !== -1) {
      // Remove used backup code
      backupCodes.splice(codeIndex, 1);
      await supabase
        .from('two_factor_auth')
        .update({ backup_codes: backupCodes })
        .eq('user_id', userId);
      
      logger.info(`Backup code used for user: ${userId}. Remaining: ${backupCodes.length}`);
      return true;
    }
    
    logger.warn(`Invalid 2FA code for user: ${userId}`);
    return false;
  }
  
  /**
   * Disable 2FA for a user
   */
  async disable(userId: string, code: string): Promise<boolean> {
    // Verify code first
    const isValid = await this.verifyCode(userId, code);
    if (!isValid) {
      return false;
    }
    
    const supabase = getSupabase();
    
    // Delete 2FA record
    await supabase.from('two_factor_auth').delete().eq('user_id', userId);
    
    // Update user record
    await supabase
      .from('users')
      .update({ two_factor_enabled: false })
      .eq('id', userId);
    
    logger.info(`2FA disabled for user: ${userId}`);
    return true;
  }
  
  /**
   * Get 2FA status for a user
   */
  async getStatus(userId: string): Promise<TwoFactorStatus> {
    const supabase = getSupabase();
    
    const { data, error } = await supabase
      .from('two_factor_auth')
      .select('enabled_at, backup_codes')
      .eq('user_id', userId)
      .single();
    
    if (error || !data) {
      return { enabled: false };
    }
    
    return {
      enabled: true,
      enabledAt: data.enabled_at,
      backupCodesRemaining: (data.backup_codes as string[])?.length || 0,
    };
  }
  
  /**
   * Regenerate backup codes
   */
  async regenerateBackupCodes(userId: string, code: string): Promise<string[] | null> {
    // Verify current code first
    const isValid = await this.verifyCode(userId, code);
    if (!isValid) {
      return null;
    }
    
    const backupCodes = this.generateBackupCodes(8);
    
    const supabase = getSupabase();
    await supabase
      .from('two_factor_auth')
      .update({
        backup_codes: backupCodes.map(c => this.hashBackupCode(c)),
      })
      .eq('user_id', userId);
    
    logger.info(`Backup codes regenerated for user: ${userId}`);
    return backupCodes;
  }
  
  /**
   * Check if user has 2FA enabled
   */
  async isEnabled(userId: string): Promise<boolean> {
    const supabase = getSupabase();
    
    const { data } = await supabase
      .from('users')
      .select('two_factor_enabled')
      .eq('id', userId)
      .single();
    
    return data?.two_factor_enabled || false;
  }
  
  // ============================================
  // Private Helper Methods
  // ============================================
  
  /**
   * Generate random backup codes
   */
  private generateBackupCodes(count: number): string[] {
    const codes: string[] = [];
    for (let i = 0; i < count; i++) {
      // Generate 8 character alphanumeric codes
      const code = crypto.randomBytes(4).toString('hex').toUpperCase();
      codes.push(`${code.slice(0, 4)}-${code.slice(4)}`);
    }
    return codes;
  }
  
  /**
   * Hash a backup code for storage
   */
  private hashBackupCode(code: string): string {
    const normalized = code.replace(/-/g, '').toUpperCase();
    return crypto.createHash('sha256').update(normalized).digest('hex');
  }
  
  /**
   * Encrypt 2FA secret for storage
   */
  private encryptSecret(secret: string): string {
    const key = process.env.JWT_SECRET;
    if (!key) {
      throw new Error('JWT_SECRET environment variable is required for 2FA encryption');
    }
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv(
      'aes-256-cbc',
      crypto.createHash('sha256').update(key).digest(),
      iv
    );
    let encrypted = cipher.update(secret, 'utf8', 'hex');
    encrypted += cipher.final('hex');
    return iv.toString('hex') + ':' + encrypted;
  }

  /**
   * Decrypt 2FA secret from storage
   */
  private decryptSecret(encrypted: string): string {
    const key = process.env.JWT_SECRET;
    if (!key) {
      throw new Error('JWT_SECRET environment variable is required for 2FA decryption');
    }
    const [ivHex, encryptedData] = encrypted.split(':');
    const iv = Buffer.from(ivHex, 'hex');
    const decipher = crypto.createDecipheriv(
      'aes-256-cbc',
      crypto.createHash('sha256').update(key).digest(),
      iv
    );
    let decrypted = decipher.update(encryptedData, 'hex', 'utf8');
    decrypted += decipher.final('utf8');
    return decrypted;
  }
}

export const twoFactorService = new TwoFactorService();

/**
 * V2 Resort - Webhook Retry Service
 * Handles failed webhook processing with exponential backoff
 */

import { supabase } from '../lib/supabase.js';
import { activityLogger } from '../utils/activityLogger.js';
import { logger } from '../utils/logger.js';

export interface WebhookFailure {
  id: string;
  event_type: string;
  event_id: string;
  source: 'stripe' | 'twilio' | 'sendgrid' | 'other';
  payload: Record<string, any>;
  error_message: string;
  error_stack?: string;
  retry_count: number;
  max_retries: number;
  next_retry_at: string | null;
  status: WebhookStatus;
  processed_at: string | null;
  created_at: string;
  updated_at: string;
}

export type WebhookStatus =
  | 'pending'
  | 'retrying'
  | 'resolved'
  | 'failed'
  | 'manual_review';

// Retry delays in milliseconds (exponential backoff)
const RETRY_DELAYS = [
  60 * 1000,       // 1 minute
  5 * 60 * 1000,   // 5 minutes
  30 * 60 * 1000,  // 30 minutes
  2 * 60 * 60 * 1000,  // 2 hours
  24 * 60 * 60 * 1000, // 24 hours
];

type WebhookHandler = (payload: any) => Promise<void>;

class WebhookRetryService {
  private handlers: Map<string, WebhookHandler> = new Map();
  private processingInterval: NodeJS.Timeout | null = null;
  private isProcessing = false;

  /**
   * Register a handler for a specific event type
   */
  registerHandler(eventType: string, handler: WebhookHandler): void {
    this.handlers.set(eventType, handler);
    logger.info(`[WebhookRetry] Handler registered for: ${eventType}`);
  }

  /**
   * Record a failed webhook for retry
   */
  async recordFailure(
    source: WebhookFailure['source'],
    eventType: string,
    eventId: string,
    payload: Record<string, any>,
    error: Error
  ): Promise<WebhookFailure> {
    logger.info(`[WebhookRetry] Recording failure for ${eventType} (${eventId})`);

    const failureData = {
      event_type: eventType,
      event_id: eventId,
      source,
      payload,
      error_message: error.message,
      error_stack: error.stack,
      retry_count: 0,
      max_retries: RETRY_DELAYS.length,
      next_retry_at: new Date(Date.now() + RETRY_DELAYS[0]).toISOString(),
      status: 'pending' as WebhookStatus,
    };

    const { data, error: insertError } = await supabase
      .from('webhook_failures')
      .insert(failureData)
      .select()
      .single();

    if (insertError) {
      logger.error('[WebhookRetry] Failed to record webhook failure:', insertError);
      throw insertError;
    }

    // Log activity
    await activityLogger.log({
      action: 'webhook_failed',
      entity_type: 'webhook',
      entity_id: data.id,
      details: {
        event_type: eventType,
        event_id: eventId,
        source,
        error: error.message,
      },
    });

    return data;
  }

  /**
   * Process a single failed webhook
   */
  async processFailure(failure: WebhookFailure): Promise<boolean> {
    logger.info(`[WebhookRetry] Processing failure: ${failure.id}`);

    // Update status to retrying
    await supabase
      .from('webhook_failures')
      .update({
        status: 'retrying',
        updated_at: new Date().toISOString(),
      })
      .eq('id', failure.id);

    // Get handler
    const handler = this.handlers.get(failure.event_type);
    if (!handler) {
      logger.error(`[WebhookRetry] No handler for event type: ${failure.event_type}`);
      await this.markForManualReview(failure.id, 'No handler registered');
      return false;
    }

    try {
      // Attempt to process
      await handler(failure.payload);

      // Success!
      await supabase
        .from('webhook_failures')
        .update({
          status: 'resolved',
          processed_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        })
        .eq('id', failure.id);

      logger.info(`[WebhookRetry] Successfully processed: ${failure.id}`);

      // Log success
      await activityLogger.log({
        action: 'webhook_retry_success',
        entity_type: 'webhook',
        entity_id: failure.id,
        details: {
          event_type: failure.event_type,
          retry_count: failure.retry_count + 1,
        },
      });

      return true;
    } catch (error: any) {
      logger.error(`[WebhookRetry] Retry failed: ${failure.id} - ${error.message}`);

      const newRetryCount = failure.retry_count + 1;

      if (newRetryCount >= failure.max_retries) {
        // Max retries exceeded
        await this.markAsFailed(failure.id, error.message);
        await this.alertMaxRetriesExceeded(failure);
        return false;
      }

      // Schedule next retry
      const nextDelay = RETRY_DELAYS[newRetryCount] || RETRY_DELAYS[RETRY_DELAYS.length - 1];

      await supabase
        .from('webhook_failures')
        .update({
          status: 'pending',
          retry_count: newRetryCount,
          next_retry_at: new Date(Date.now() + nextDelay).toISOString(),
          error_message: error.message,
          error_stack: error.stack,
          updated_at: new Date().toISOString(),
        })
        .eq('id', failure.id);

      logger.info(`[WebhookRetry] Scheduled retry ${newRetryCount + 1} for: ${failure.id}`);
      return false;
    }
  }

  /**
   * Process all pending webhook retries
   */
  async processPendingRetries(): Promise<{ processed: number; succeeded: number }> {
    if (this.isProcessing) {
      logger.debug('[WebhookRetry] Already processing, skipping');
      return { processed: 0, succeeded: 0 };
    }

    this.isProcessing = true;
    let processed = 0;
    let succeeded = 0;

    try {
      // Get all pending retries that are due
      const { data: failures, error } = await supabase
        .from('webhook_failures')
        .select('*')
        .eq('status', 'pending')
        .lte('next_retry_at', new Date().toISOString())
        .order('next_retry_at', { ascending: true })
        .limit(10); // Process 10 at a time

      if (error) {
        throw error;
      }

      if (!failures || failures.length === 0) {
        return { processed: 0, succeeded: 0 };
      }

      logger.info(`[WebhookRetry] Found ${failures.length} pending retries`);

      for (const failure of failures) {
        const success = await this.processFailure(failure);
        processed++;
        if (success) succeeded++;
      }
    } finally {
      this.isProcessing = false;
    }

    return { processed, succeeded };
  }

  /**
   * Manual retry of a specific failure
   */
  async manualRetry(failureId: string, adminUserId: string): Promise<boolean> {
    const { data: failure, error } = await supabase
      .from('webhook_failures')
      .select('*')
      .eq('id', failureId)
      .single();

    if (error || !failure) {
      throw new Error('Webhook failure not found');
    }

    if (failure.status === 'resolved') {
      throw new Error('This webhook has already been processed');
    }

    // Log manual retry
    await activityLogger.log({
      action: 'webhook_manual_retry',
      entity_type: 'webhook',
      entity_id: failureId,
      user_id: adminUserId,
    });

    // Reset retry count for manual retry
    await supabase
      .from('webhook_failures')
      .update({
        retry_count: failure.retry_count, // Keep current count but reset status
        status: 'pending',
        next_retry_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      .eq('id', failureId);

    return this.processFailure(failure);
  }

  /**
   * Mark failure as requiring manual review
   */
  private async markForManualReview(failureId: string, reason: string): Promise<void> {
    await supabase
      .from('webhook_failures')
      .update({
        status: 'manual_review',
        error_message: reason,
        updated_at: new Date().toISOString(),
      })
      .eq('id', failureId);
  }

  /**
   * Mark failure as permanently failed
   */
  private async markAsFailed(failureId: string, lastError: string): Promise<void> {
    await supabase
      .from('webhook_failures')
      .update({
        status: 'failed',
        error_message: `Max retries exceeded. Last error: ${lastError}`,
        updated_at: new Date().toISOString(),
      })
      .eq('id', failureId);
  }

  /**
   * Alert admin when max retries exceeded
   */
  private async alertMaxRetriesExceeded(failure: WebhookFailure): Promise<void> {
    // Import email service dynamically to avoid circular dependency
    const { emailService } = await import('./email.service.js');

    await emailService.sendEmail({
      to: process.env.ADMIN_EMAIL || 'admin@v2resort.com',
      subject: `[Alert] Webhook Failed After ${failure.max_retries} Retries`,
      template: 'admin-webhook-failure',
      data: {
        failure_id: failure.id,
        event_type: failure.event_type,
        event_id: failure.event_id,
        source: failure.source,
        error_message: failure.error_message,
        retry_count: failure.retry_count,
        admin_url: `${process.env.FRONTEND_URL}/admin/payments/webhooks/${failure.id}`,
      },
    });
  }

  /**
   * Get failure statistics
   */
  async getStats(): Promise<{
    pending: number;
    retrying: number;
    resolved: number;
    failed: number;
    manual_review: number;
    by_source: Record<string, number>;
    by_event_type: Record<string, number>;
  }> {
    const { data: failures, error } = await supabase
      .from('webhook_failures')
      .select('status, source, event_type');

    if (error) {
      throw error;
    }

    const stats = {
      pending: 0,
      retrying: 0,
      resolved: 0,
      failed: 0,
      manual_review: 0,
      by_source: {} as Record<string, number>,
      by_event_type: {} as Record<string, number>,
    };

    for (const failure of failures || []) {
      // Count by status
      stats[failure.status as keyof typeof stats]++;

      // Count by source
      stats.by_source[failure.source] = (stats.by_source[failure.source] || 0) + 1;

      // Count by event type (only for non-resolved)
      if (failure.status !== 'resolved') {
        stats.by_event_type[failure.event_type] =
          (stats.by_event_type[failure.event_type] || 0) + 1;
      }
    }

    return stats;
  }

  /**
   * List failures with filters
   */
  async list(filters: {
    status?: WebhookStatus;
    source?: string;
    event_type?: string;
    from_date?: string;
    to_date?: string;
    limit?: number;
    offset?: number;
  }): Promise<{ data: WebhookFailure[]; total: number }> {
    let query = supabase
      .from('webhook_failures')
      .select('*', { count: 'exact' });

    if (filters.status) {
      query = query.eq('status', filters.status);
    }
    if (filters.source) {
      query = query.eq('source', filters.source);
    }
    if (filters.event_type) {
      query = query.eq('event_type', filters.event_type);
    }
    if (filters.from_date) {
      query = query.gte('created_at', filters.from_date);
    }
    if (filters.to_date) {
      query = query.lte('created_at', filters.to_date);
    }

    query = query
      .order('created_at', { ascending: false })
      .range(
        filters.offset || 0,
        (filters.offset || 0) + (filters.limit || 20) - 1
      );

    const { data, count, error } = await query;

    if (error) {
      throw error;
    }

    return {
      data: data || [],
      total: count || 0,
    };
  }

  /**
   * Start background processing
   */
  startBackgroundProcessing(intervalMs: number = 60000): void {
    if (this.processingInterval) {
      return;
    }

    logger.info('[WebhookRetry] Starting background processing');

    // Initial run
    this.processPendingRetries();

    // Schedule periodic runs
    this.processingInterval = setInterval(() => {
      this.processPendingRetries();
    }, intervalMs);
  }

  /**
   * Stop background processing
   */
  stopBackgroundProcessing(): void {
    if (this.processingInterval) {
      clearInterval(this.processingInterval);
      this.processingInterval = null;
      logger.info('[WebhookRetry] Stopped background processing');
    }
  }
}

export const webhookRetryService = new WebhookRetryService();

/**
 * Webhook Idempotency Service
 * 
 * Prevents duplicate processing of webhook events using database-backed tracking.
 */

import crypto from 'crypto';
import { getSupabase } from '../database/supabase.js';
import { logger } from '../utils/logger.js';

interface ProcessedEvent {
  id: string;
  event_id: string;
  event_type: string;
  processed_at: Date;
  payload_hash: string | null;
  result: Record<string, unknown> | null;
}

/**
 * Check if a webhook event has already been processed
 */
export async function isEventProcessed(eventId: string): Promise<boolean> {
  const { data, error } = await getSupabase()
    .from('processed_webhook_events')
    .select('id')
    .eq('event_id', eventId)
    .single();

  if (error && error.code !== 'PGRST116') { // PGRST116 = no rows returned
    logger.error('Error checking webhook event:', error);
    throw error;
  }

  return !!data;
}

/**
 * Mark a webhook event as processed
 * Returns true if the event was newly marked, false if it already existed
 */
export async function markEventProcessed(
  eventId: string,
  eventType: string,
  result?: Record<string, unknown>
): Promise<boolean> {
  const { data, error } = await getSupabase()
    .from('processed_webhook_events')
    .insert({
      event_id: eventId,
      event_type: eventType,
      result: result || null,
    })
    .select()
    .single();

  if (error) {
    // Unique constraint violation = already processed
    if (error.code === '23505') {
      return false;
    }
    logger.error('Error marking webhook event as processed:', error);
    throw error;
  }

  return !!data;
}

/**
 * Process a webhook event with idempotency protection
 * Returns the result of the handler, or null if already processed
 */
export async function processWithIdempotency<T>(
  eventId: string,
  eventType: string,
  handler: () => Promise<T>
): Promise<{ processed: boolean; result: T | null; alreadyProcessed: boolean }> {
  // Check if already processed
  const alreadyProcessed = await isEventProcessed(eventId);
  if (alreadyProcessed) {
    logger.debug(`Webhook event ${eventId} already processed, skipping`);
    return { processed: false, result: null, alreadyProcessed: true };
  }

  try {
    // Process the event
    const result = await handler();

    // Mark as processed (with race condition protection)
    // Convert result to Record<string, unknown> if it's an object
    const resultRecord = result && typeof result === 'object'
      ? (result as Record<string, unknown>)
      : undefined;
    const wasMarked = await markEventProcessed(eventId, eventType, resultRecord);

    if (!wasMarked) {
      // Another process beat us to it
      logger.debug(`Webhook event ${eventId} was processed by another worker`);
      return { processed: false, result: null, alreadyProcessed: true };
    }

    return { processed: true, result, alreadyProcessed: false };
  } catch (error) {
    // Don't mark as processed on error - allow retry
    logger.error(`Error processing webhook event ${eventId}:`, error);
    throw error;
  }
}

/**
 * Generate a hash of the webhook payload for verification
 */
export function hashPayload(payload: object): string {
  const json = JSON.stringify(payload, Object.keys(payload).sort());
  return crypto.createHash('sha256').update(json).digest('hex');
}

/**
 * Clean up old processed events
 */
export async function cleanupOldEvents(daysToKeep: number = 30): Promise<number> {
  const cutoffDate = new Date();
  cutoffDate.setDate(cutoffDate.getDate() - daysToKeep);

  const { data, error } = await getSupabase()
    .from('processed_webhook_events')
    .delete()
    .lt('processed_at', cutoffDate.toISOString())
    .select();

  if (error) {
    logger.error('Error cleaning up old webhook events:', error);
    throw error;
  }

  return data?.length || 0;
}

/**
 * Get processing statistics for webhook events
 */
export async function getWebhookStats(): Promise<{
  totalProcessed: number;
  byType: Record<string, number>;
  last24Hours: number;
}> {
  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);

  // Get all events
  const { data: allEvents, error: allError } = await getSupabase()
    .from('processed_webhook_events')
    .select('event_type, processed_at');

  if (allError) {
    throw allError;
  }

  const byType: Record<string, number> = {};
  let last24Hours = 0;

  for (const event of allEvents || []) {
    byType[event.event_type] = (byType[event.event_type] || 0) + 1;
    if (new Date(event.processed_at) >= yesterday) {
      last24Hours++;
    }
  }

  return {
    totalProcessed: allEvents?.length || 0,
    byType,
    last24Hours,
  };
}

/**
 * V2 Resort - Socket.io Redis Adapter for Horizontal Scaling
 * Enables WebSocket communication across multiple backend instances
 */

import { Server as SocketIOServer } from 'socket.io';
import { createAdapter } from '@socket.io/redis-adapter';
import { createClient, RedisClientType } from 'redis';
import { Server as HttpServer } from 'http';
import { logger } from "../utils/logger.js";

// Environment variables
const REDIS_URL = process.env.REDIS_URL || 'redis://localhost:6379';
const NODE_ENV = process.env.NODE_ENV || 'development';

// Redis clients for pub/sub
let pubClient: RedisClientType;
let subClient: RedisClientType;

/**
 * Configure Socket.io with Redis adapter for horizontal scaling
 */
export const configureSocketRedisAdapter = async (
  io: SocketIOServer
): Promise<void> => {
  // Create Redis clients for pub/sub
  pubClient = createClient({ url: REDIS_URL });
  subClient = pubClient.duplicate();

  // Error handling
  pubClient.on('error', (err: Error) => {
    logger.error(`[Socket.io Redis] Pub client error: ${err.message}`);
  });

  subClient.on('error', (err: Error) => {
    logger.error(`[Socket.io Redis] Sub client error: ${err.message}`);
  });

  // Connect clients
  await Promise.all([
    pubClient.connect(),
    subClient.connect(),
  ]);

  logger.info('[Socket.io Redis] Connected to Redis for pub/sub');

  // Configure adapter
  io.adapter(createAdapter(pubClient, subClient));
  
  logger.info('[Socket.io Redis] Adapter configured successfully');
};

/**
 * Initialize Socket.io server with all configurations
 */
export const initializeSocketServer = async (
  httpServer: HttpServer
): Promise<SocketIOServer> => {
  const io = new SocketIOServer(httpServer, {
    cors: {
      origin: process.env.FRONTEND_URL || 'http://localhost:3000',
      methods: ['GET', 'POST'],
      credentials: true,
    },
    transports: ['websocket', 'polling'],
    pingInterval: 25000,
    pingTimeout: 60000,
    connectTimeout: 45000,
    allowEIO3: true,
    path: '/socket.io',
  });

  // Configure Redis adapter if not in development without Redis
  if (NODE_ENV === 'production' || process.env.REDIS_URL) {
    await configureSocketRedisAdapter(io);
  } else {
    logger.info('[Socket.io] Running without Redis adapter (development mode)');
  }

  // Connection handling
  io.on('connection', (socket) => {
    logger.debug(`[Socket.io] Client connected: ${socket.id}`);

    // Join user to their personal room
    socket.on('join:user', (userId: string) => {
      socket.join(`user:${userId}`);
      logger.debug(`[Socket.io] User ${userId} joined personal room`);
    });

    // Join user to role-based rooms
    socket.on('join:role', (role: string) => {
      socket.join(`role:${role}`);
      logger.debug(`[Socket.io] Socket joined role room: ${role}`);
    });

    // Kitchen namespace rooms
    socket.on('join:kitchen', () => {
      socket.join('kitchen');
      logger.debug('[Socket.io] Socket joined kitchen room');
    });

    // Admin namespace rooms
    socket.on('join:admin', () => {
      socket.join('admin');
      logger.debug('[Socket.io] Socket joined admin room');
    });

    // Pool monitoring room
    socket.on('join:pool-monitor', () => {
      socket.join('pool-monitor');
      logger.debug('[Socket.io] Socket joined pool monitor room');
    });

    // Handle disconnection
    socket.on('disconnect', (reason) => {
      logger.debug(`[Socket.io] Client disconnected: ${socket.id}, reason: ${reason}`);
    });

    // Handle errors
    socket.on('error', (error) => {
      logger.error(`[Socket.io] Socket error: ${socket.id}`, error);
    });
  });

  // Middleware for authentication
  io.use((socket, next) => {
    const token = socket.handshake.auth.token;
    if (!token && NODE_ENV === 'production') {
      return next(new Error('Authentication required'));
    }
    // In production, verify JWT token here
    // const decoded = verifyJWT(token);
    // socket.data.user = decoded;
    next();
  });

  return io;
};

