interface AuditLogEntry {
  user_id: string;
  action: string;
  resource: string;
  resource_id?: string;
  entity_id?: string; // Alias for resource_id
  entity_type?: string;
  details?: unknown;
  old_value?: unknown;
  new_value?: unknown;
  ip_address?: string;
  user_agent?: string;
}

export async function logActivity(entry: AuditLogEntry) {
  try {
    const supabase = getSupabase();

    // Convert objects to strings if needed
    const safePayload = {
      ...entry,
      old_value: entry.old_value ? (typeof entry.old_value === 'string' ? entry.old_value : JSON.stringify(entry.old_value)) : null,
      new_value: entry.new_value ? (typeof entry.new_value === 'string' ? entry.new_value : JSON.stringify(entry.new_value)) : null,
    };

    const { error } = await supabase
      .from('audit_logs')
      .insert(safePayload);

    if (error) {
      logger.error('Failed to write audit log:', error);
    }
  } catch (err) {
    logger.error('Error logging activity:', err);
  }
}

export const activityLogger = {
  log: async (arg1: string | Partial<AuditLogEntry>, arg2?: any) => {
    let entry: AuditLogEntry;

    if (typeof arg1 === 'string') {
      entry = {
        action: arg1,
        user_id: arg2?.userId || arg2?.user_id || 'system',
        resource: arg2?.resource || 'system',
        details: arg2,
        ...arg2
      } as AuditLogEntry;
    } else {
      entry = {
        user_id: 'system',
        action: 'unknown',
        resource: 'system',
        ...arg1
      } as AuditLogEntry;
    }

    return logActivity(entry);
  }
};

/**
 * Redis Cache Service
 * 
 * Provides caching functionality using Redis for:
 * - Menu items
 * - User sessions
 * - Settings
 * - Rate limiting
 * 
 * Falls back gracefully if Redis is unavailable.
 */

import Redis from 'ioredis';
import { logger } from './logger.js';
import { config } from '../config/index.js';

// Cache key prefixes for organization
export const CacheKeys = {
  MENU: 'menu:',
  MENU_ITEM: 'menu:item:',
  MENU_CATEGORY: 'menu:category:',
  SETTINGS: 'settings:',
  SESSION: 'session:',
  USER: 'user:',
  RATE_LIMIT: 'rate:',
  CHALET: 'chalet:',
  AVAILABILITY: 'availability:'
} as const;

// Default TTLs in seconds
export const CacheTTL = {
  SHORT: 60,           // 1 minute
  MEDIUM: 300,         // 5 minutes
  LONG: 3600,          // 1 hour
  VERY_LONG: 86400,    // 24 hours
  SESSION: 604800      // 7 days
} as const;

class RedisCache {
  private client: Redis | null = null;
  private isConnected = false;
  private connectionAttempts = 0;
  private maxRetries = 3;

  /**
   * Initialize Redis connection
   */
  async connect(): Promise<void> {
    const redisUrl = process.env.REDIS_URL;
    
    if (!redisUrl) {
      logger.warn('REDIS_URL not configured. Caching will be disabled.');
      return;
    }

    try {
      this.client = new Redis(redisUrl, {
        maxRetriesPerRequest: 3,
        lazyConnect: true,
        enableReadyCheck: true,
        connectTimeout: 5000,
        retryStrategy: (times: number) => Math.min(times * 1000, 5000)
      });

      this.client.on('connect', () => {
        this.isConnected = true;
        this.connectionAttempts = 0;
        logger.info('Redis connected successfully');
      });

      this.client.on('error', (err: Error) => {
        this.isConnected = false;
        logger.error('Redis connection error:', err.message);
      });

      this.client.on('close', () => {
        this.isConnected = false;
        logger.warn('Redis connection closed');
      });

      this.client.on('reconnecting', () => {
        this.connectionAttempts++;
        logger.info(`Redis reconnecting (attempt ${this.connectionAttempts})`);
      });

      await this.client.connect();
    } catch (error) {
      logger.error('Failed to connect to Redis:', error);
      this.client = null;
    }
  }

  /**
   * Check if cache is available
   */
  isAvailable(): boolean {
    return this.isConnected && this.client !== null;
  }

  /**
   * Get a value from cache
   */
  async get<T>(key: string): Promise<T | null> {
    if (!this.isAvailable()) return null;

    try {
      const value = await this.client!.get(key);
      if (!value) return null;
      return JSON.parse(value) as T;
    } catch (error) {
      logger.error(`Cache get error for key ${key}:`, error);
      return null;
    }
  }

  /**
   * Set a value in cache with optional TTL
   */
  async set(key: string, value: unknown, ttlSeconds: number = CacheTTL.MEDIUM): Promise<boolean> {
    if (!this.isAvailable()) return false;

    try {
      const serialized = JSON.stringify(value);
      await this.client!.set(key, serialized, 'EX', ttlSeconds);
      return true;
    } catch (error) {
      logger.error(`Cache set error for key ${key}:`, error);
      return false;
    }
  }

  /**
   * Delete a key from cache
   */
  async del(key: string): Promise<boolean> {
    if (!this.isAvailable()) return false;

    try {
      await this.client!.del(key);
      return true;
    } catch (error) {
      logger.error(`Cache delete error for key ${key}:`, error);
      return false;
    }
  }

  /**
   * Delete multiple keys matching a pattern
   */
  async delPattern(pattern: string): Promise<number> {
    if (!this.isAvailable()) return 0;

    try {
      const keys = await this.client!.keys(pattern);
      if (keys.length === 0) return 0;
      return await this.client!.del(...keys);
    } catch (error) {
      logger.error(`Cache delete pattern error for ${pattern}:`, error);
      return 0;
    }
  }

  /**
   * Get or set a value (cache-aside pattern)
   */
  async getOrSet<T>(
    key: string, 
    fetcher: () => Promise<T>, 
    ttlSeconds: number = CacheTTL.MEDIUM
  ): Promise<T> {
    // Try to get from cache
    const cached = await this.get<T>(key);
    if (cached !== null) {
      return cached;
    }

    // Fetch fresh data
    const fresh = await fetcher();
    
    // Store in cache (don't await, fire and forget)
    this.set(key, fresh, ttlSeconds).catch(() => {});
    
    return fresh;
  }

  /**
   * Acquire a distributed lock
   * @param key Lock key
   * @param ttlSeconds Lock duration in seconds
   * @returns true if lock acquired, false otherwise
   */
  async acquireLock(key: string, ttlSeconds: number = 10): Promise<boolean> {
    if (!this.client || !this.isConnected) return true; // Fail open if no Redis (risk, but keeps system alive)

    try {
      // Correct argument order: key, value, 'EX', ttl, 'NX'
      const result = await this.client.set(key, 'locked', 'EX', ttlSeconds, 'NX');
      return result === 'OK';
    } catch (error) {
      logger.error('Redis lock error:', error);
      return false;
    }
  }

  /**
   * Release a distributed lock
   * @param key Lock key
   */
  async releaseLock(key: string): Promise<void> {
    if (!this.client || !this.isConnected) return;
    try {
      await this.client.del(key);
    } catch (error) {
      logger.error('Redis unlock error:', error);
    }
  }

  /**
   * Increment a counter (useful for rate limiting)
   */
  async incr(key: string, ttlSeconds?: number): Promise<number> {
    if (!this.isAvailable()) return 0;

    try {
      const count = await this.client!.incr(key);
      if (ttlSeconds && count === 1) {
        await this.client!.expire(key, ttlSeconds);
      }
      return count;
    } catch (error) {
      logger.error(`Cache incr error for key ${key}:`, error);
      return 0;
    }
  }

  /**
   * Check if key exists
   */
  async exists(key: string): Promise<boolean> {
    if (!this.isAvailable()) return false;

    try {
      const result = await this.client!.exists(key);
      return result === 1;
    } catch (error) {
      return false;
    }
  }

  /**
   * Set expiration on a key
   */
  async expire(key: string, ttlSeconds: number): Promise<boolean> {
    if (!this.isAvailable()) return false;

    try {
      await this.client!.expire(key, ttlSeconds);
      return true;
    } catch (error) {
      return false;
    }
  }

  /**
   * Get TTL remaining on a key
   */
  async ttl(key: string): Promise<number> {
    if (!this.isAvailable()) return -1;

    try {
      return await this.client!.ttl(key);
    } catch (error) {
      return -1;
    }
  }

  /**
   * Close the Redis connection
   */
  async disconnect(): Promise<void> {
    if (this.client) {
      await this.client.quit();
      this.client = null;
      this.isConnected = false;
      logger.info('Redis disconnected');
    }
  }
}

