/**
 * Encryption Utility
 * 
 * Provides AES-256-GCM encryption for sensitive data storage.
 */

import crypto from 'crypto';
import { env } from '../config/env.js';

const ALGORITHM = 'aes-256-gcm';
const IV_LENGTH = 16;
const TAG_LENGTH = 16;
const SALT_LENGTH = 32;

/**
 * Get encryption key from environment
 */
function getEncryptionKey(): Buffer {
  const key = env.ENCRYPTION_KEY || env.JWT_SECRET;
  if (!key) {
    throw new Error('ENCRYPTION_KEY or JWT_SECRET must be configured');
  }
  
  // Derive a consistent 32-byte key using SHA-256
  return crypto.createHash('sha256').update(key).digest();
}

/**
 * Encrypt a string value
 * Returns base64-encoded string containing: salt + iv + authTag + encrypted data
 */
export function encrypt(plaintext: string): string {
  if (!plaintext) return '';
  
  const key = getEncryptionKey();
  const iv = crypto.randomBytes(IV_LENGTH);
  const salt = crypto.randomBytes(SALT_LENGTH);
  
  // Derive key with salt for added security
  const derivedKey = crypto.pbkdf2Sync(key, salt, 100000, 32, 'sha256');
  
  const cipher = crypto.createCipheriv(ALGORITHM, derivedKey, iv);
  
  let encrypted = cipher.update(plaintext, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  
  const authTag = cipher.getAuthTag();
  
  // Combine all parts: salt + iv + authTag + encrypted
  const combined = Buffer.concat([
    salt,
    iv,
    authTag,
    Buffer.from(encrypted, 'hex')
  ]);
  
  return combined.toString('base64');
}

/**
 * Decrypt an encrypted string
 */
export function decrypt(encryptedText: string): string {
  if (!encryptedText) return '';
  
  try {
    const key = getEncryptionKey();
    const combined = Buffer.from(encryptedText, 'base64');
    
    // Extract parts
    const salt = combined.subarray(0, SALT_LENGTH);
    const iv = combined.subarray(SALT_LENGTH, SALT_LENGTH + IV_LENGTH);
    const authTag = combined.subarray(
      SALT_LENGTH + IV_LENGTH,
      SALT_LENGTH + IV_LENGTH + TAG_LENGTH
    );
    const encrypted = combined.subarray(SALT_LENGTH + IV_LENGTH + TAG_LENGTH);
    
    // Derive key with same salt
    const derivedKey = crypto.pbkdf2Sync(key, salt, 100000, 32, 'sha256');
    
    const decipher = crypto.createDecipheriv(ALGORITHM, derivedKey, iv);
    decipher.setAuthTag(authTag);
    
    let decrypted = decipher.update(encrypted.toString('hex'), 'hex', 'utf8');
    decrypted += decipher.final('utf8');
    
    return decrypted;
  } catch (error) {
    throw new Error('Failed to decrypt value - data may be corrupted or key may have changed');
  }
}

/**
 * Hash a value (one-way, for comparison)
 */
export function hash(value: string, salt?: string): string {
  const useSalt = salt || crypto.randomBytes(16).toString('hex');
  const hash = crypto
    .pbkdf2Sync(value, useSalt, 100000, 64, 'sha512')
    .toString('hex');
  
  return `${useSalt}:${hash}`;
}

/**
 * Verify a value against a hash
 */
export function verifyHash(value: string, hashedValue: string): boolean {
  const [salt, originalHash] = hashedValue.split(':');
  const hash = crypto
    .pbkdf2Sync(value, salt, 100000, 64, 'sha512')
    .toString('hex');
  
  return crypto.timingSafeEqual(
    Buffer.from(hash),
    Buffer.from(originalHash)
  );
}

/**
 * Generate a random token
 */
export function generateToken(length: number = 32): string {
  return crypto.randomBytes(length).toString('hex');
}

/**
 * Generate a secure random string (URL-safe)
 */
export function generateSecureId(length: number = 16): string {
  return crypto.randomBytes(length).toString('base64url');
}

export default {
  encrypt,
  decrypt,
  hash,
  verifyHash,
  generateToken,
  generateSecureId
};

import fs from 'fs';
import os from 'os';
import path from 'path';
import winston from 'winston';
import { config } from '../config/index.js';

const levels = {
  error: 0,
  warn: 1,
  info: 2,
  http: 3,
  debug: 4,
};

const colors = {
  error: 'red',
  warn: 'yellow',
  info: 'green',
  http: 'magenta',
  debug: 'white',
};

winston.addColors(colors);

const format = winston.format.combine(
  winston.format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
  winston.format.colorize({ all: true }),
  winston.format.printf(
    (info) => `${info.timestamp} ${info.level}: ${info.message}`
  )
);

// Determine a safe log directory. Priority:
// 1. LOG_DIR environment variable (if provided)
// 2. ./logs relative to project root (if writable)
// 3. OS temp directory (always writable in most environments)
const preferred = process.env.LOG_DIR;
const defaultTmp = path.join(os.tmpdir(), 'v2-resort-logs');
let logDir: string | null = null;

try {
  if (preferred) {
    fs.mkdirSync(preferred, { recursive: true });
    logDir = preferred;
  } else {
    // Try to use ./logs first for local dev convenience
    try {
      const localLogs = path.join(process.cwd(), 'logs');
      fs.mkdirSync(localLogs, { recursive: true });
      logDir = localLogs;
    } catch (e) {
      // fallback to OS temp directory
      fs.mkdirSync(defaultTmp, { recursive: true });
      logDir = defaultTmp;
    }
  }
} catch (err) {
  // If we cannot create any directory, disable file transports and continue
  // This prevents the app from crashing during startup in restrictive environments
  // and will log to console only.
  // eslint-disable-next-line no-console
  console.error('Warning: Unable to create log directory for file transports, file logging disabled.', err);
  logDir = null;
}

const transports: winston.transport[] = [new winston.transports.Console()];

if (logDir) {
  try {
    transports.push(
      new winston.transports.File({
        filename: path.join(logDir, 'error.log'),
        level: 'error',
      })
    );

    transports.push(
      new winston.transports.File({ filename: path.join(logDir, 'all.log') })
    );
  } catch (err) {
    // If file transports fail for any reason, keep console transport and warn
    // eslint-disable-next-line no-console
    console.error('Warning: Failed to initialize file transports for logging. Falling back to console only.', err);
  }
}

export const logger = winston.createLogger({
  level: config.env === 'development' ? 'debug' : 'warn',
  levels,
  format,
  transports,
});

/**
 * QR Code Security Utility
 * 
 * Provides secure QR code generation and validation with HMAC signatures.
 * Prevents tampering and replay attacks on QR code-based access (pool, chalets, etc.)
 */

import crypto from 'crypto';
import QRCode from 'qrcode';
import { env } from '../config/env.js';
import { logger } from './logger.js';

// Configuration
const QR_CONFIG = {
  algorithm: 'sha256',
  expirationMs: 24 * 60 * 60 * 1000, // 24 hours default
  shortExpirationMs: 5 * 60 * 1000, // 5 minutes for one-time codes
};

interface QRPayload {
  type: 'pool_ticket' | 'chalet_access' | 'restaurant_order' | 'module_content';
  id: string;
  timestamp: number;
  expiresAt: number;
  data?: Record<string, unknown>;
  nonce: string;
}

interface SignedQRPayload extends QRPayload {
  signature: string;
}

interface QRValidationResult {
  valid: boolean;
  payload?: QRPayload;
  error?: string;
  expired?: boolean;
  tampered?: boolean;
}

/**
 * Get the HMAC secret key
 */
function getSecretKey(): string {
  const secret = env.QR_SECRET_KEY || env.JWT_SECRET;
  if (!secret) {
    throw new Error('QR_SECRET_KEY or JWT_SECRET must be configured');
  }
  return secret;
}

/**
 * Generate a cryptographic nonce
 */
function generateNonce(): string {
  return crypto.randomBytes(16).toString('hex');
}

/**
 * Create HMAC signature for payload
 */
function signPayload(payload: QRPayload): string {
  const dataToSign = JSON.stringify({
    type: payload.type,
    id: payload.id,
    timestamp: payload.timestamp,
    expiresAt: payload.expiresAt,
    data: payload.data,
    nonce: payload.nonce
  });
  
  return crypto
    .createHmac(QR_CONFIG.algorithm, getSecretKey())
    .update(dataToSign)
    .digest('hex');
}

/**
 * Verify HMAC signature
 */
function verifySignature(payload: SignedQRPayload): boolean {
  const expectedSignature = signPayload(payload);
  return crypto.timingSafeEqual(
    Buffer.from(payload.signature),
    Buffer.from(expectedSignature)
  );
}

/**
 * Generate a secure QR code payload
 */
export function generateSecurePayload(
  type: QRPayload['type'],
  id: string,
  data?: Record<string, unknown>,
  expirationMs: number = QR_CONFIG.expirationMs
): SignedQRPayload {
  const now = Date.now();
  
  const payload: QRPayload = {
    type,
    id,
    timestamp: now,
    expiresAt: now + expirationMs,
    data,
    nonce: generateNonce()
  };
  
  const signature = signPayload(payload);
  
  return {
    ...payload,
    signature
  };
}

/**
 * Generate a short-lived one-time QR code payload
 */
export function generateOneTimePayload(
  type: QRPayload['type'],
  id: string,
  data?: Record<string, unknown>
): SignedQRPayload {
  return generateSecurePayload(type, id, data, QR_CONFIG.shortExpirationMs);
}

/**
 * Encode payload as base64 string for QR code
 */
export function encodePayload(payload: SignedQRPayload): string {
  const json = JSON.stringify(payload);
  return Buffer.from(json).toString('base64url');
}

/**
 * Decode base64 string back to payload
 */
export function decodePayload(encoded: string): SignedQRPayload | null {
  try {
    const json = Buffer.from(encoded, 'base64url').toString('utf-8');
    return JSON.parse(json) as SignedQRPayload;
  } catch (error) {
    logger.warn('Failed to decode QR payload', { error });
    return null;
  }
}

/**
 * Validate a QR code payload
 */
export function validatePayload(encoded: string): QRValidationResult {
  // Decode the payload
  const payload = decodePayload(encoded);
  
  if (!payload) {
    return {
      valid: false,
      error: 'Invalid QR code format',
      tampered: true
    };
  }
  
  // Verify signature (prevents tampering)
  try {
    if (!verifySignature(payload)) {
      logger.warn('QR code signature verification failed', { 
        type: payload.type, 
        id: payload.id 
      });
      return {
        valid: false,
        error: 'QR code has been tampered with',
        tampered: true
      };
    }
  } catch (error) {
    return {
      valid: false,
      error: 'Signature verification failed',
      tampered: true
    };
  }
  
  // Check expiration
  if (Date.now() > payload.expiresAt) {
    return {
      valid: false,
      payload,
      error: 'QR code has expired',
      expired: true
    };
  }
  
  // Remove signature from returned payload for safety
  const { signature, ...cleanPayload } = payload;
  
  return {
    valid: true,
    payload: cleanPayload
  };
}

/**
 * Generate QR code image as data URL
 */
export async function generateQRCodeImage(
  type: QRPayload['type'],
  id: string,
  data?: Record<string, unknown>,
  options?: {
    width?: number;
    margin?: number;
    color?: { dark?: string; light?: string };
    expirationMs?: number;
  }
): Promise<{ dataUrl: string; payload: SignedQRPayload; expiresAt: Date }> {
  const payload = generateSecurePayload(type, id, data, options?.expirationMs);
  const encoded = encodePayload(payload);
  
  const qrOptions = {
    width: options?.width || 256,
    margin: options?.margin || 2,
    color: {
      dark: options?.color?.dark || '#000000',
      light: options?.color?.light || '#ffffff'
    },
    errorCorrectionLevel: 'M' as const
  };
  
  const dataUrl = await QRCode.toDataURL(encoded, qrOptions);
  
  return {
    dataUrl,
    payload,
    expiresAt: new Date(payload.expiresAt)
  };
}

/**
 * Generate QR code as SVG string
 */
export async function generateQRCodeSVG(
  type: QRPayload['type'],
  id: string,
  data?: Record<string, unknown>,
  options?: {
    width?: number;
    margin?: number;
    color?: { dark?: string; light?: string };
    expirationMs?: number;
  }
): Promise<{ svg: string; payload: SignedQRPayload; expiresAt: Date }> {
  const payload = generateSecurePayload(type, id, data, options?.expirationMs);
  const encoded = encodePayload(payload);
  
  const qrOptions = {
    width: options?.width || 256,
    margin: options?.margin || 2,
    color: {
      dark: options?.color?.dark || '#000000',
      light: options?.color?.light || '#ffffff'
    },
    type: 'svg' as const
  };
  
  const svg = await QRCode.toString(encoded, qrOptions);
  
  return {
    svg,
    payload,
    expiresAt: new Date(payload.expiresAt)
  };
}

/**
 * Pool Ticket QR Code Generator
 */
export async function generatePoolTicketQR(
  ticketId: string,
  ticketData: {
    guestName: string;
    date: string;
    ticketType: string;
    quantity: number;
  }
): Promise<{ dataUrl: string; expiresAt: Date }> {
  const result = await generateQRCodeImage('pool_ticket', ticketId, ticketData, {
    expirationMs: QR_CONFIG.expirationMs
  });
  
  logger.info('Generated pool ticket QR code', { ticketId, expiresAt: result.expiresAt });
  
  return {
    dataUrl: result.dataUrl,
    expiresAt: result.expiresAt
  };
}

/**
 * Chalet Access QR Code Generator
 */
export async function generateChaletAccessQR(
  bookingId: string,
  accessData: {
    chaletName: string;
    guestName: string;
    checkIn: string;
    checkOut: string;
  }
): Promise<{ dataUrl: string; expiresAt: Date }> {
  // Calculate expiration based on checkout date + 1 day buffer
  const checkoutDate = new Date(accessData.checkOut);
  checkoutDate.setDate(checkoutDate.getDate() + 1);
  const expirationMs = checkoutDate.getTime() - Date.now();
  
  const result = await generateQRCodeImage('chalet_access', bookingId, accessData, {
    expirationMs: Math.max(expirationMs, QR_CONFIG.expirationMs)
  });
  
  logger.info('Generated chalet access QR code', { bookingId, expiresAt: result.expiresAt });
  
  return {
    dataUrl: result.dataUrl,
    expiresAt: result.expiresAt
  };
}

/**
 * Restaurant Order QR Code Generator (for table-side ordering)
 */
export async function generateRestaurantOrderQR(
  tableId: string,
  sessionData: {
    tableName: string;
    startTime: string;
    serverName?: string;
  }
): Promise<{ dataUrl: string; expiresAt: Date }> {
  // Short-lived for active dining session
  const result = await generateQRCodeImage('restaurant_order', tableId, sessionData, {
    expirationMs: 4 * 60 * 60 * 1000 // 4 hours for dining session
  });
  
  logger.info('Generated restaurant order QR code', { tableId, expiresAt: result.expiresAt });
  
  return {
    dataUrl: result.dataUrl,
    expiresAt: result.expiresAt
  };
}

/**
 * Module Content QR Code Generator (for educational content sharing)
 */
export async function generateModuleContentQR(
  moduleId: string,
  contentData: {
    moduleName: string;
    contentType: string;
    accessLevel?: string;
  }
): Promise<{ dataUrl: string; expiresAt: Date }> {
  const result = await generateQRCodeImage('module_content', moduleId, contentData);
  
  logger.info('Generated module content QR code', { moduleId, expiresAt: result.expiresAt });
  
  return {
    dataUrl: result.dataUrl,
    expiresAt: result.expiresAt
  };
}

/**
 * Validate a scanned QR code (generic)
 */
export function validateScannedQR(
  scannedData: string,
  expectedType?: QRPayload['type']
): QRValidationResult {
  const result = validatePayload(scannedData);
  
  if (!result.valid) {
    return result;
  }
  
  // Optionally check if type matches expected
  if (expectedType && result.payload?.type !== expectedType) {
    return {
      valid: false,
      payload: result.payload,
      error: `Expected QR code type '${expectedType}' but got '${result.payload?.type}'`
    };
  }
  
  return result;
}

export default {
  generateSecurePayload,
  generateOneTimePayload,
  encodePayload,
  decodePayload,
  validatePayload,
  generateQRCodeImage,
  generateQRCodeSVG,
  generatePoolTicketQR,
  generateChaletAccessQR,
  generateRestaurantOrderQR,
  generateModuleContentQR,
  validateScannedQR
};

/**
 * Common Validation Schemas
 * 
 * Provides reusable Zod schemas for input validation across the application.
 * These schemas protect against:
 * - SQL injection (via type validation)
 * - XSS attacks (via sanitization transforms)
 * - Type coercion errors
 * - Invalid data formats
 */

import { z } from 'zod';

// ============ COMMON PATTERNS ============

/**
 * UUID validation schema
 */
export const uuidSchema = z.string().uuid('Invalid ID format');

/**
 * Phone number validation (international format)
 */
export const phoneSchema = z.string()
  .regex(/^\+?[0-9\s\-()]{7,20}$/, 'Invalid phone number format')
  .optional()
  .nullable();

/**
 * Sanitized string that strips HTML tags to prevent XSS
 */
export function sanitizedString(maxLength: number = 255) {
  return z.string()
    .max(maxLength, `Text must be ${maxLength} characters or less`)
    .transform(s => s.replace(/<[^>]*>/g, '').trim());
}

/**
 * Safe name field (letters, spaces, hyphens, apostrophes only)
 */
export const nameSchema = z.string()
  .min(2, 'Name must be at least 2 characters')
  .max(100, 'Name must be 100 characters or less')
  .regex(/^[\p{L}\s'-]+$/u, 'Name contains invalid characters')
  .transform(s => s.replace(/<[^>]*>/g, '').trim());

/**
 * Email validation
 */
export const emailSchema = z.string()
  .email('Invalid email format')
  .max(255, 'Email must be 255 characters or less')
  .toLowerCase()
  .trim();

/**
 * Date string validation (ISO format)
 */
export const dateSchema = z.string()
  .refine((d) => !isNaN(Date.parse(d)), 'Invalid date format');

/**
 * Positive number validation
 */
export const positiveNumberSchema = z.number()
  .positive('Value must be positive')
  .finite('Value must be a valid number');

/**
 * Positive integer validation
 */
export const positiveIntSchema = z.number()
  .int('Value must be a whole number')
  .positive('Value must be positive');

/**
 * Pagination parameters
 */
export const paginationSchema = z.object({
  page: z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(20),
});

